trait UserAuthAndCompanyTrait
{
public function checkAdmin($post)
    {
        global $callConfig;
        $value = $post['chrUserName'];
        if (strpos($value, ',') !== false || strpos($value, "'") !== false || strpos($value, '"') !== false) {
            $return['error'] = '6002';
            return $return;
        }
        $where = "(user_email='" . $post['chrUserName'] . "' OR user_name='" . $post['chrUserName'] . "')  and is_active ='0'";
        $fail_data = array('email_id' => $post['chrUserName'], 'password' => $post['chrPassword'], 'device_source' => 'Web', 'domain_name' => $post['subdomain']);
        $query = $callConfig->selectQuery(MAINDB . '.' . TBL_USER_REGISTIRED_GROUPS, '*', $where, '', '', '');

        $row = $callConfig->getRow($query);
        if ($row->id != "" && $row->email_active == 1) {
            $fail_data['zqr_connect'] = $row->zqr_connect;
            $whr = " id='" . $row->zqr_connect . "' and  is_active='0'";
            $query_db = $callConfig->selectQuery(MAINDB . '.' . TBL_DATABASE_ALLOCATIONS, '*', $whr, '', '', '');
            $row_db = $callConfig->getRow($query_db);
            $row->db = $row_db->db_name;
            $fail_data['db_name'] = $row_db->db_name;
            $wheres = "(user_email='" . $post['chrUserName'] . "' OR user_name='" . $post['chrUserName'] . "' ) and (user_password='" . $callConfig->passwordEncrypt($post['chrPassword']) . self::USER_LIT_OR . $post['passcheck'] . "'='N') and is_active ='0'";
            $query_user = $callConfig->selectQuery($row_db->db_name . self::USER_LIT_APPLICATION_USERS, '*', $wheres, '', '', '');

            $user = $callConfig->getRow($query_user);
            if ($user->id != '') {
                $login_type = 'U';
                $user->db = $row_db->db_name;
                $query_last = self::USER_SQL_SELECT_FROM . $row_db->db_name . ".application_user_logins where user_id =" . $user->id . " ORDER BY id DESC LIMIT 0,1";
                $last = $callConfig->getRow($query_last);
                $user->lastlogin = $last->login_from;
                $user->reset_password = $row->reset_password;
                unset($user->user_password);

                $user->data_name = $row_db->db_name;
                $query_employee = self::USER_SQL_SELECT_ID_FROM . $row_db->db_name . ".employees where user_id =" . $user->id . self::USER_SQL_AND_IS_ACTIVE_0_4;
                $employee = $callConfig->getRow($query_employee);
                $user->emp_id = $employee->id;

                if ($post['mobile'] == 'Y') {
                    $fail_data['device_source'] = 'Mobile';
                    $query_mobile = self::USER_SQL_SELECT_ID_FROM . $row_db->db_name . ".user_otp_authentication where user_id =" . $user->id . " AND current_status =199 AND is_active=0 ";
                    $mobile = $callConfig->getRow($query_mobile);
                    $user->base_url = "https://dev.infistaq.in/";
                    $user->user_toke = '';
                    $user->mobile_verification = 1;
                    if ($mobile->id != '') {
                        $user->mobile_verification = 0;
                    }

                    $user->login_type = $login_type;
                }
                $retun_token = '';
                $user->user_token = $retun_token;
                $return = $user;
            } else {
                $return['error'] = '6002';
            }
        } else {

            if ($row->email_active === '0') {
                $return['error'] = '6004';
            } else {
                if ($post['mobile'] == 'Y') {
                    $wheres = self::USER_LIT_USER_EMAIL . $post['chrUserName'] . "' and user_password='" . $callConfig->passwordEncrypt($post['chrPassword']) . "' and is_active ='0'";
                    $query_user = $callConfig->selectQuery(MAINDB . '.mobile_user_registrations', '*', $wheres, '', '', '');
                    $user = $callConfig->getRow($query_user);
                    if ($user->id != '') {
                        $login_type = 'M';
                        $user->login_type = $login_type;
                        $return = $user;
                    } else {
                        $return['error'] = '6005';
                    }

                } else {
                    $return['error'] = '6005';
                }

            }
        }

        return $return;

    }
    public function toadddatauserfaillogin($insert_array)
    {
        global $callConfig;
        $callConfig->insertRecord(MAINDB . '.user_failed_login_attempts', $insert_array);
    }
    public function tocreateusertoken($get)
    {
        global $callConfig;
        $dateTimePart = date('YmdHis'); // e.g., 20250613123045
        $randomPart = strtoupper(bin2hex(random_bytes(4))); // 8 chars hex, uppercase
        $token = "Infisuite#" . $get['user_id'] . "$" . $dateTimePart . "@" . $randomPart;
        $retun_token = base64_encode($token);
        $insert_array = array('company_id' => $get['company_id'], 'user_id' => $get['user_id'], 'login_type' => $get['login_type'], 'user_token' => $retun_token, 'is_active' => 0, 'current_status' => 0, 'created_by' => $get['user_id']);
        $callConfig->insertRecord($get['db_name'] . '.appliccation_user_login_tokens', $insert_array);
        return $retun_token;
    }
    public function togetbaseurlcreate($get)
    {
        global $callConfig;
        $user_email = $get['chrUserName'];
        $query = self::USER_SQL_SELECT_FROM . MAINDB . ".registered_groups WHERE id in (SELECT group_id FROM " . MAINDB . ".user_registered_groups WHERE user_email = '" . $user_email . "' AND is_active=0)";
        $data = $callConfig->getRow($query);

        $subdomain = '';
        $host = $_SERVER['HTTP_HOST'];
        $parts = explode('.', $host);
        if (count($parts) > 2) {
            $subdomain = $parts[0];
            if ($subdomain == "www") {
                $subdomain = $parts[1];
            }
        }
        $httpshttp = isset($_SERVER['HTTPS']) ? 'https' : 'http';
        return $httpshttp . "://" . str_replace($subdomain, $data->domain_name, $host);
    }
