        $default_application_languages = "english";
        foreach ($langres as $lng) {
            $languagefieldname[] = $lng->language_field_name;
            if ($lng->is_default == 1) {
                $default_application_languages = $lng->language_field_name;
            }
        }
        $return['application_languages'] = $langres;
        if (count((array) $languagefieldname) != 0) {
            $implodedfieldnamestr = implode(",", $languagefieldname);
            $langtranquery = self::USER_SQL_SELECT . $implodedfieldnamestr . " FROM application_language_translations WHERE is_active = 0";
            $langtranres = $callConfig->getAllRows($langtranquery);
            foreach ($langtranres as $langtr) {
                $translation_key = $langtr->$default_application_languages;
                if (isset($application_language_translations[$translation_key])) {
                    // duplicate English word: fill only the cells that are still empty
                    foreach ($langtr as $translation_field => $translation_value) {
                        if (trim((string) ($application_language_translations[$translation_key]->$translation_field ?? '')) === '' && trim((string) $translation_value) !== '') {
                            $application_language_translations[$translation_key]->$translation_field = $translation_value;
                        }
                    }
                } else {
                    $application_language_translations[$translation_key] = $langtr;
                }
            }
        }
        $return['default_application_languages'] = $default_application_languages;
        $return['application_language_translations'] = $application_language_translations;

        return $return;
    }
    public function getMainDomainName()
    {
        $url = SITEURL;
        $host = parse_url($url, PHP_URL_HOST);
        $parts = explode('.', $host);
        return $parts[count((array) $parts) - 2] . '.' . $parts[count((array) $parts) - 1];
    }
    public function confrimbutton($id)
    {
        global $callConfig;

        $emailcheckalreadyactivesql = "SELECT urg.id, urg.user_email, da.db_name FROM " . MAINDB . "." . TBL_USER_REGISTIRED_GROUPS . " urg, " . MAINDB . ".database_allocations da WHERE urg.id ='" . $id . "' AND urg.zqr_connect = da.id  AND urg.email_active = 0";
        $returnarray['emailcheckalreadyactivesql'] = $emailcheckalreadyactivesql;
        $emailcheckalreadyactiveres = $callConfig->getRow($emailcheckalreadyactivesql);
        $returnarray['emailcheckalreadyactiveres'] = $emailcheckalreadyactiveres;
        if (isset($emailcheckalreadyactiveres->id)) {

            $domainregister = "SELECT id, default_module_id FROM " . MAINDB . ".domain_registrations WHERE user_email ='" . $emailcheckalreadyactiveres->user_email . self::USER_LIT_AND_IS_ACTIVE_0;
            $domainregisres = $callConfig->getRow($domainregister);
            $returnarray['domainregisres'] = $domainregisres;


            $dbname = $emailcheckalreadyactiveres->db_name;
            $time = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
            $fied = array('email_active' => 1, 'email_active_date' => $time);
            $res = $callConfig->updateRecord(MAINDB . '.' . TBL_USER_REGISTIRED_GROUPS, $fied, 'id', $id);
            $returnarray['res'] = $res;

            $application_userssql = "SELECT id, company_id, display_name, user_email, user_mobile, role_id FROM " . $dbname . ".application_users WHERE user_email ='" . $emailcheckalreadyactiveres->user_email . self::USER_LIT_AND_IS_ACTIVE_0;
            $application_usersres = $callConfig->getRow($application_userssql);
            $returnarray['application_userssql'] = $application_userssql;
            $returnarray['application_usersres'] = $application_usersres;
            $rolelist = json_decode($application_usersres->role_id, 1);
            $returnarray['role_id'] = $rolelist;

            $emailarray['databasename'] = $dbname;
            $emailarray['session_company_id'] = $application_usersres->company_id;
            $emailarray['user_display_name'] = $application_usersres->display_name;
            $emailarray['user_email_id'] = $application_usersres->user_email;
            $emailarray['user_phone_number'] = $application_usersres->user_mobile;
            $emailarray['created_by'] = $application_usersres->id;
            $emailarray['default_module_id'] = $domainregisres->default_module_id;
            if (in_array(ADMIN_ROLES, (array) $rolelist)) {
                $emailsend = $this->sendNotificationAndEmails('', $emailarray, 2);
            } else {
                $emailsend = $this->sendNotificationAndEmails('', $emailarray, 4);
            }
            $returnarray['emailsend'] = $emailsend;
        }
        return $returnarray;
    }


