    {
        global $callConfig;
        $timm = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
        $fieldnames = array('login_to' => $timm);
        return $callConfig->updateRecord('application_user_logins', $fieldnames, 'user_id', $data);
