    public function genrateRandomString($n)
    {
        $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
        $randomString = '';
        for ($i = 0; $i < $n; $i++) {
            $index = random_int(0, strlen($characters) - 1);
            $randomString .= $characters[$index];
        }
        return $randomString;
    }
    public function forgotpassword($email)
    {
        global $callConfig;
        $whrs = "user_email= '" . $email . "'";
        $querys = $callConfig->selectQuery(MAINDB . '.' . TBL_USER_REGISTIRED_GROUPS, 'id,zqr_connect', $whrs, '', '', '');
        $rowg = $callConfig->getRow($querys);
        if ($rowg->id != '') {
            $whr = self::USER_LIT_ID . $rowg->zqr_connect . "'";
            $query = $callConfig->selectQuery(MAINDB . '.' . TBL_DATABASE_ALLOCATIONS, '*', $whr, '', '', '');
            $row = $callConfig->getRow($query);
            $db_name = $row->db_name;
            $gen_password = $this->genrateRandomString(7);
            $password = $callConfig->passwordEncrypt($gen_password);
            $fied = array('reset_password' => '0');
            $callConfig->updateRecord(MAINDB . '.' . TBL_USER_REGISTIRED_GROUPS, $fied, 'id', $rowg->id);
            $fied = array('user_password' => $password);
            $whrcon = self::USER_LIT_USER_EMAIL . $email . "'";
            $callConfig->updateRecord($db_name . self::USER_LIT_APPLICATION_USERS, $fied, '', '', $whrcon);
            $ausql = "SELECT id, company_id, display_name, user_email, user_mobile, role_id FROM " . $db_name . ".application_users WHERE user_email ='" . $email . self::USER_LIT_AND_IS_ACTIVE_0;
            $aures = $callConfig->getRow($ausql);

            $apmql = "SELECT id, application_module_id FROM " . $db_name . ".application_user_module_roles WHERE user_id ='" . $aures->id . self::USER_LIT_AND_IS_ACTIVE_0;
