    public function toGetblancebill($get)
    {
        global $callConfig;
        $return = $returnpaymets = $pttrans = $pttransdue = array();
        $partyids = json_decode(urldecode($get['party_id']), 1);
        $partyid = implode(',', (array) $partyids);

        if ($get['transaction_type'] == 'customers') {
            if ($get['payment_process'] == "AP") {
                $gettransactionarray[] = array('sales_orders' => array());
            } else {
                $gettransactionarray[] = array('sales_invoices' => array('debit_notes', 'credit_notes'), 'rental_invoices' => array('debit_notes', 'credit_notes'), 'utility_rental_invoices' => array('debit_notes', 'credit_notes'));
            }
        } elseif ($get['transaction_type'] == 'vendors') {
            if ($get['payment_process'] == "AP") {
                $gettransactionarray[] = array('purchase_orders' => array());
            } else {
                $gettransactionarray[] = array('supplier_bills' => array('debit_notes', 'credit_notes'), 'purchase_invoices' => array('debit_notes', 'credit_notes'));
            }
        }
        if ($get['transaction_type'] == 'employees') {

            $query = "SELECT *, expense_code as transaction_number FROM emp_expenses WHERE company_id = '" . $get['company_id'] . "' AND emp_id IN (" . $partyid . ") AND pending_amount > 0 AND is_active = 0 AND current_status = '" . ST_APPROVED . "'";
            $data = $callConfig->getAllRows($query);
            $masterid = array();
            if (count((array) $data) != 0) {
                foreach ($data as $ddt) {
                    $masterid[$ddt->id] = $ddt->id;
                }
                $return['emp_expenses'] = $data;
            }
            if (count((array) $masterid) != "0") {
                $masterids = implode(',', (array) $masterid);
                $alreadypaysql = "SELECT pay.id, pay.transaction_no, pay.payment_date, pay.current_status, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM payments pay, payment_allocations paya WHERE pay.company_id = '" . $get['company_id'] . "' AND pay.company_id = paya.company_id AND pay.id = paya.payment_id AND paya.transaction_table = 'emp_expenses' AND paya.transaction_id IN(" . $masterids . self::USER_LIT_AND_PAY_IS_ACTIVE_PAYA_IS_ACTI;
                $alreadypayres = $callConfig->getAllRows($alreadypaysql);
                foreach ($alreadypayres as $ddt) {
                    $returnpaymets['emp_expenses'][$ddt->id][] = $ddt;
                }
                $query22 = self::USER_SQL_SELECT_FROM_PAYMENT_TERM_TRANS . $get['company_id'] . "' AND transaction_id IN (" . $masterids . ") AND transaction_table = 'emp_expenses' AND pending_amount > 0 AND is_active = 0";
                $data22 = $callConfig->getAllRows($query22);
                foreach ($data22 as $ptt) {
                    if ($ptt->due_date <= $this->dateconvertdbformat($get['due_date'])) {
                        $pttransdue['emp_expenses'][$ptt->transaction_id] += $ptt->pending_amount;
                    }
                    $pttrans['emp_expenses'][$ptt->transaction_id][] = $ptt;
                }
            }

        } else {
            foreach ($gettransactionarray as $masttable) {
                foreach ($masttable as $mastertable => $transtable) {
                    $query = self::USER_SQL_SELECT_FROM . $mastertable . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . "' AND party_id IN (" . $partyid . ") AND due_date <= '" . $this->dateconvertdbformat($get['due_date']) . "' AND pending_amount > 0 AND is_active = 0 AND current_status = '" . ST_APPROVED . "'";
                    $data = $callConfig->getAllRows($query);
                    $masterid = array();
                    if (count((array) $data) != 0) {
                        foreach ($data as $ddt) {
                            $masterid[$ddt->id] = $ddt->id;
                        }
                        $return[$mastertable] = $data;
                    }
                    if (count((array) $masterid) != "0") {
                        $masterids = implode(',', (array) $masterid);

                        if ($get['transaction_type'] == 'customers') {
                            $alreadypaysql = "SELECT pay.id, pay.transaction_no, pay.payment_date, pay.current_status, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM receipts pay, receipt_allocations paya WHERE pay.company_id = '" . $get['company_id'] . "' AND pay.company_id = paya.company_id AND pay.id = paya.receipt_id AND paya.transaction_table = '" . $mastertable . self::USER_LIT_AND_PAYA_TRANSACTION_ID_IN . $masterids . self::USER_LIT_AND_PAY_IS_ACTIVE_PAYA_IS_ACTI;
                        } else {
                            $alreadypaysql = "SELECT pay.id, pay.transaction_no, pay.payment_date, pay.current_status, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM payments pay, payment_allocations paya WHERE pay.company_id = '" . $get['company_id'] . "' AND pay.company_id = paya.company_id AND pay.id = paya.payment_id AND paya.transaction_table = '" . $mastertable . self::USER_LIT_AND_PAYA_TRANSACTION_ID_IN . $masterids . self::USER_LIT_AND_PAY_IS_ACTIVE_PAYA_IS_ACTI;
                        }
                        $alreadypayres = $callConfig->getAllRows($alreadypaysql);
                        foreach ($alreadypayres as $ddt) {
                            $returnpaymets[$mastertable][$ddt->id][] = $ddt;
                        }


                        $query22 = self::USER_SQL_SELECT_FROM_PAYMENT_TERM_TRANS . $get['company_id'] . "' AND transaction_id IN (" . $masterids . ") AND transaction_table = '" . $mastertable . "' AND pending_amount > 0 AND is_active = 0";
                        $data22 = $callConfig->getAllRows($query22);
                        foreach ($data22 as $ptt) {
                            if ($ptt->due_date <= $this->dateconvertdbformat($get['due_date'])) {
                                $pttransdue[$mastertable][$ptt->transaction_id] += $ptt->pending_amount;
                            }
                            $pttrans[$mastertable][$ptt->transaction_id][] = $ptt;
                        }
                    }
                    foreach ($transtable as $subtranstable) {

                        $query = self::USER_SQL_SELECT_FROM . $subtranstable . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . "' AND party_id IN (" . $partyid . ") AND ref_type = '" . $mastertable . "' AND pending_amount > 0 AND is_active = 0 AND current_status = '" . ST_APPROVED . "'";
                        $data = $callConfig->getAllRows($query);
                        $subtabid = array();
                        if (count((array) $data) != 0) {
                            foreach ($data as $ddt) {
                                $subtabid[$ddt->id] = $ddt->id;
                            }
                            $return[$subtranstable] = $data;
                        }
                        if (count((array) $subtabid) != "0") {
                            $subtabids = implode(',', (array) $subtabid);
                            if ($get['transaction_type'] == 'customers') {
                                $alreadypaysql1 = "SELECT pay.id, pay.transaction_no, pay.payment_date, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM receipts pay, receipt_allocations paya WHERE pay.company_id = '" . $get['company_id'] . "' AND pay.company_id = paya.company_id AND pay.id = paya.receipt_id AND paya.transaction_table = '" . $subtranstable . self::USER_LIT_AND_PAYA_TRANSACTION_ID_IN . $subtabids . self::USER_LIT_AND_PAY_IS_ACTIVE_PAYA_IS_ACTI;
                            } else {
                                $alreadypaysql1 = "SELECT pay.id, pay.transaction_no, pay.payment_date, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM payments pay, payment_allocations paya WHERE pay.company_id = '" . $get['company_id'] . "' AND pay.company_id = paya.company_id AND pay.id = paya.payment_id AND paya.transaction_table = '" . $subtranstable . self::USER_LIT_AND_PAYA_TRANSACTION_ID_IN . $subtabids . self::USER_LIT_AND_PAY_IS_ACTIVE_PAYA_IS_ACTI;

                            }
                            $alreadypayres1 = $callConfig->getAllRows($alreadypaysql1);
                            foreach ($alreadypayres1 as $ddt) {
                                $returnpaymets[$subtranstable][$ddt->id][] = $ddt;
                            }

                        }
                    }
                }
            }
        }
        $returnres['transactions'] = $return;
        $returnres['transaction_payment_allocations'] = $returnpaymets;
        $returnres['payment_term_transactions'] = $pttrans;
        $returnres['payment_term_transactions_due'] = $pttransdue;
        return $returnres;
    }

    public function toInsertandupateinvoice($post)
    {
        global $callConfig;
        $fieldnames = array('company_id' => $post['company_id'], 'amount' => $post['total_amount'], 'payment_method' => $post['paytype'], 'reference' => $post['ref_number']);
        $receiptid = $callConfig->insertRecord(TBL_INVOICE_PAYMENTS, $fieldnames);
        foreach ($post['details'] as $item) {
            $invoice_number = $item['invoice_number'] == 'unallocated' ? 0 : $item['invoice_number'];
            $itemfieldnames = array('receipt_id' => $receiptid, 'invoice_id' => $invoice_number, 'paid_amount' => $item['paid']);
            $callConfig->insertRecord(TBL_INVOICE_ALLOCATED, $itemfieldnames);
            if ($item['invoice_number'] != 'unallocated') {
                $field = array('paid_amount' => $item['paid'], 'due_amount' => $item['due']);
                $callConfig->updateRecord(TBL_INVOICE, $field, 'invoice_number', $item['invoice_number']);
            }
        }

    }
