trait UserSystemPreferencesTrait
{
    public function togetitemvalues($item_d, $post = array())
    {
        global $callConfig;
        if ($item_d != "") {
            $whr = "id='" . $item_d . "'";
            $query = $callConfig->selectQuery(TBL_ITEMS, '*', $whr, '', '', '');
            $data = $callConfig->getRow($query);
            if ($data->company_id != "") {
                $sosql = "SELECT sum(si.pending_qty) as pending_qty FROM sales_orders so, so_items si WHERE so.company_id = '" . $data->company_id . "' AND so.company_id = si.company_id AND so.id = si.transaction_id AND so.current_status ='" . ST_APPROVED . "' AND si.item_id = '" . $item_d . "' AND so.is_active = si.is_active AND so.is_active = 0";
                $sores = $callConfig->getRow($sosql);

                $data->sales_order_qty = $sores->pending_qty != "" ? $sores->pending_qty : 0;

                $posql = "SELECT sum(si.pending_qty) as pending_qty FROM purchase_orders so, po_items si WHERE so.company_id = '" . $data->company_id . "' AND so.company_id = si.company_id AND so.id = si.transaction_id AND so.current_status ='" . ST_APPROVED . "' AND si.item_id = '" . $item_d . "' AND so.is_active = si.is_active AND so.is_active = 0";
                $pores = $callConfig->getRow($posql);

                $configsql = "SELECT id , default_inventory_account FROM config where company_id = '" . $data->company_id . "'";
                $configres = $callConfig->getRow($configsql);
                if (isset($configres->default_inventory_account)) {
                    $data->config_inventory_asset_account = $configres->default_inventory_account;
                }
                $isbsql = "SELECT closing_qty,balance_date FROM `item_st_balances` WHERE company_id = '" . $callConfig->company_id . self::USER_LIT_AND_ITEM_ID . $item_d . "' ORDER BY balance_date DESC limit 1";
                $isbres = $callConfig->getRow($isbsql);
                if ($isbres->closing_qty != "") {
                    $data->stock_in_hand = $isbres->closing_qty != "" ? $isbres->closing_qty : 0;
                }
                if ($isbres->balance_date != "") {
                    $data->balance_date = $isbres->balance_date != "" ? $isbres->balance_date : 0;
                }
                if ($isbres->pending_qty != "") {
                    $data->purchase_order_qty = $pores->pending_qty != "" ? $pores->pending_qty : 0;
                    if ($isbres->pending_qty != "") {
                        $available_qty = ($isbres->closing_qty + $pores->pending_qty) - $sores->pending_qty;
                    }
                } else {
                    $data->purchase_order_qty = 0;
                }

                $data->available_qty = $available_qty != "" ? $available_qty : 0;


                if ($data->category_id != "") {
                    $icsql = "SELECT id , inventory_asset_account, inventory_adjustment_account, inventory_cost_variance_account, cogs_account, purchase_expense_account, sales_revenue_account, sales_discount_account, sales_return_account, purchase_price_variance_account, freight_expense_account, packaging_expense_account, sales_tax_payable_account, purchase_tax_payable_account, promotions_and_discounts_account, sales_allowances_account, deferred_revenue_account, ap_account, ar_account, accrued_expenses_account, prepaid_expenses_account, wip_asset_account, goods_received_not_invoiced_account, invoiced_not_received_account FROM item_categories where id = '" . $data->category_id . self::USER_LIT_AND_COMPANY_ID . $data->company_id . self::USER_LIT_AND_IS_ACTIVE_0;
                    $icategory = $callConfig->getRow($icsql);
                    $data->item_cat_inventory_asset_account = $icategory->inventory_asset_account;
                    $data->item_cat_goods_received_not_invoiced_accountt = $icategory->goods_received_not_invoiced_account;
                    if ($data->hsn_and_sac_code_id == "" || $data->hsn_and_sac_code_id == "0") {
                        $data->hsn_and_sac_code_id = $icategory->hsn_and_sac_code_id;
                    }
                }
            }
            if ($data->hsn_and_sac_code_id != "") {
                if ($post['date'] != "") {
                    $hsnwhere = " AND from_date <= '" . $this->dateconvertdbformat($post['date']) . "' AND (to_date >= '" . $this->dateconvertdbformat($post['date']) . "' OR to_date IS NULL)";
                }
                $sql = "SELECT id , code, gst, code_description FROM `hsn_and_sac_codes` where code = '" . $data->hsn_and_sac_code_id . "' " . $hsnwhere . self::USER_SQL_AND_IS_ACTIVE_0;
                $data2 = $callConfig->getRow($sql);
                $data->hsn_code_id = $data2->id;
                $data->hsn_code = $data2->code;
                $data->hsn_code_description = $data2->code_description;
                $data->igst = $data2->gst;
            }
            $data->party_sku_number = '-';
            $data->party_sku_name = '-';
            $data->party_sku_concat = '-';
            if ($post['party_id'] != "") {
                $display_attribute_typessql = self::USER_SQL_SELECT_CONTENT_FROM_DISPLAY_AT . $post['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $post['table'] . self::USER_LIT_AND_FIELD_NAME_PARTY_ID;
                $parttable_name = $callConfig->getRow($display_attribute_typessql);
                $qquery = urldecode($parttable_name->content);
                $explosql = explode("FROM", $qquery); // splite from to get table name and other part get
                if (isset($explosql[1])) {
                    $explosql = explode(" ", trim($explosql[1])); //splite to space only get table name
                }
                $partytable = trim($explosql[0]); //get Table name
                if ($partytable != "") {
                    if ($partytable == "customers") {
                        $itemskusql = "SELECT id, item_id, customer_id, customer_part_no, customer_part_name FROM customer_items WHERE company_id = '" . $post['company_id'] . "' AND customer_id = '" . $post['party_id'] . self::USER_LIT_AND_ITEM_ID . $item_d . self::USER_LIT_AND_IS_ACTIVE_0;
                        $itemskures = $callConfig->getRow($itemskusql);
                        $data->party_sku_number = $itemskures->customer_part_no != "" ? $itemskures->customer_part_no : '-';
                        $data->party_sku_name = $itemskures->customer_part_name != "" ? $itemskures->customer_part_name : '-';
                        $data->party_sku_concat = $itemskures->customer_part_no . " - " . $itemskures->customer_part_name;

                    } elseif ($partytable == "vendors") {
                        $itemskusql = "SELECT id, item_id, vendor_id, vendor_part_no, vendor_part_name FROM vendor_items WHERE company_id = '" . $post['company_id'] . self::USER_LIT_AND_VENDOR_ID . $post['party_id'] . self::USER_LIT_AND_ITEM_ID . $item_d . self::USER_LIT_AND_IS_ACTIVE_0;
                        $itemskures = $callConfig->getRow($itemskusql);
                        $data->party_sku_number = $itemskures->vendor_part_no != "" ? $itemskures->vendor_part_no : '-';
                        $data->party_sku_name = $itemskures->vendor_part_name != "" ? $itemskures->vendor_part_name : '-';
                        $data->party_sku_concat = $itemskures->vendor_part_no . " - " . $itemskures->vendor_part_name;
                    }
                }
            }

        }
        return $data;
    }
