        global $callConfig;
        $transdate = $get['transaction_date'] != "" ? $this->dateconvertdbformat($get['transaction_date']) : date('Y-m-d');
        $finyaer = date("m", strtotime($transdate)) >= 4 ? date("Y", strtotime($transdate)) . '-' . (date("y", strtotime($transdate)) + 1) : (date("Y", strtotime($transdate)) - 1) . '-' . date("y", strtotime($transdate));
        $numLength = !empty($res->doc_no_length) ? (int) $res->doc_no_length : 3;
        $serial = str_pad((string) $res->serial_number, $numLength, '0', STR_PAD_LEFT);
        $parts = [];
        for ($m = 1; $m <= 4; $m++) {
            if ($res->pre_fix_check == "Y" && $res->pre_fix_position == $m) {
                if ($res->pre_fix_type == "STATIC" && !empty($res->pre_fix)) {
                    $parts[] = $res->pre_fix;
                } elseif ($res->pre_fix_type == "DYNAMIC") {
                    $parts[] = 'FIELDVALUE';
                }
            }
            if (!empty($res->serial_number) && $res->serial_number_position == $m) {
                $parts[] = $serial;
            }
            if ($res->post_fix_check == "Y" && $res->post_fix_position == $m) {
                if ($res->post_fix_type == "STATIC" && !empty($res->post_fix)) {
                    $parts[] = $res->post_fix;
                } elseif ($res->post_fix_type == "DYNAMIC") {
                    $parts[] = 'FIELDVALUE';
                }
            }
            if (!empty($finyaer) && $res->financial_year_check == "Y" && $res->financial_year_position == $m) {
                $parts[] = $finyaer;
            }
        }
        return $parts;

    }
    public function toGetApplicationSerialNumber($table_name, $get)
    {
        global $callConfig;
        $company_id = $get['company_id'] != "" ? $get['company_id'] : 1;
        $transdate = $get['transaction_date'] != "" ? $this->dateconvertdbformat($get['transaction_date']) : date('Y-m-d');
        $query = "SELECT * FROM `application_serial_numbers` WHERE company_id = '" . $company_id . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $table_name . "' AND from_date <= '" . $this->dateconvertdbformat($transdate) . "' AND to_date >= '" . $this->dateconvertdbformat($transdate) . self::USER_LIT_AND_IS_ACTIVE_0_3;
        $return['query_1'] = $query;
        $res = $callConfig->getRow($query);
        $return['query_1_res'] = $res;

        if ($res->id != "") {
            $parts = $this->dynamicCreateSerialNumber($table_name, $get, $res);
            if (isset($res->id)) {
                $callConfig->updateRecord('application_serial_numbers', array('serial_number' => $res->serial_number + 1), 'id', $res->id);
            }
        } else {

            $query = "SELECT * FROM `application_serial_numbers` WHERE company_id = '" . $company_id . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $table_name . "' AND is_active = 0 ORDER BY to_date DESC limit 1";
            $return['query_2_res'] = $query;
            $res = $callConfig->getRow($query);

            if (isset($res->id)) {
                if (date("m", strtotime($transdate)) >= 4) {
                    $startyear = date("Y", strtotime($transdate));
                    $endyear = (date("Y", strtotime($transdate)) + 1);
                    $startdate = $startyear . self::USER_LIT_04_01;
                    $enddate = $endyear . self::USER_LIT_03_31;
                } else {
                    $startyear = (date("Y", strtotime($transdate)) - 1);
                    $endyear = date("Y", strtotime($transdate));
                    $startdate = $startyear . self::USER_LIT_04_01;
                    $enddate = $endyear . self::USER_LIT_03_31;
                }
                $financial_year = date("Y", strtotime($startdate));
                $serial_number = $res->reset_every_financial_year == "Y" ? 1 : $res->serial_number + 1;
                $insertsql = "INSERT INTO `application_serial_numbers`(company_id, `application_table_name`, `serial_number`, `serial_number_position`, `pre_fix`, `pre_fix_position`, `post_fix`, `post_fix_position`, `doc_no_length`, `financial_year`, `financial_year_position`, `reset_every_financial_year`, `separator_symbols`, `pre_fix_check`, `post_fix_check`, `financial_year_check`, `pre_fix_type`, `post_fix_type`, `pre_fix_field`, `post_fix_field`, `is_active`, `current_status`, `from_date`, `to_date`, `created_date`, `created_by`) SELECT company_id, `application_table_name`, '" . ($serial_number + 1) . "', `serial_number_position`, `pre_fix`, `pre_fix_position`, `post_fix`, `post_fix_position`, `doc_no_length`, '" . $financial_year . "', `financial_year_position`, `reset_every_financial_year`, `separator_symbols`, `pre_fix_check`, `post_fix_check`, `financial_year_check`, `pre_fix_type`, `post_fix_type`, `pre_fix_field`, `post_fix_field`, `is_active`, `current_status`, '" . $startdate . "', '" . $enddate . "', '" . date(self::USER_DATE_FORMAT_Y_M_D_H_I_S) . "', '" . $get['user_id'] . "' FROM `application_serial_numbers` WHERE id = '" . $res->id . "'";
                $callConfig->executeQueryString($insertsql);
                $res->serial_number = $serial_number;
                $parts = $this->dynamicCreateSerialNumber($table_name, $get, $res);
            } else {
                $parts = array(1);
            }
        }
        return trim(implode($res->separator_symbols, (array) $parts));
    }
