                if ($table == 'goods_receipt_notes' || $table == 'delivery_orders' || $table == 'rgp_delivery_orders' || $table == 'rgp_sales_returns' || $table == 'nrgp_delivery_orders' || $table == 'stock_transfers' || $table == 'stock_transfer_receipts' || $table == 'stock_transfer_returns' || $table == 'subcontract_work_order_transfers' || $table == 'subcontract_work_order_receipts') {
                    $itemfieldnames['invoice_item_quantity'] = $post['invoiced_quantity'][$key];
                }
                if ($table == 'requisitions') {
                    $itemfieldnames['customer_description'] = $post['customer_description'][$key];
                }
                if ($table == 'stock_adjustments') {
                    $reason = explode('$', $post['respon'][$key]);
                    $itemfieldnames['reason_id'] = $reason[0];
                }
                if (in_array($table, array('enquiries', 'estimates', 'sales_orders'))) {
                    $itemfieldnames['pending_order_qty'] = $post['quantity'][$key];
                }
                if (in_array($table, array('purchase_orders', 'sales_orders'))) {
                    $itemfieldnames['ref_pending_qty_1'] = $post['quantity'][$key];
                }
                $item_detaileeee = array();
                foreach ($post['item_details'] as $qkey => $qkem) {
                    $item_detaileeee[$qkey] = $qkem[$key];
                }
                $item_details = json_encode($item_detaileeee);
                $itemfieldnames['item_details'] = $item_details;


                $taxfield = array('company_id' => $post['company_id'], 'transaction_id' => $insert_id, 'transaction_item_id' => $item, 'tax_id' => $post['taxid'][$key], 'tax_name' => $post['tax_name'][$key], 'amount' => $post['p_amount'][$key], 'tax_amount' => $post['ptax_amount'][$key], 'total_amount' => $post['amount'][$key], 'tax_type' => $tax_flag, 'tax_value' => $post['tax'][$key], 'is_active' => '0', 'current_status' => '0');
                if ($post['tax'][$key] != '0' && $post['tax'][$key] != '') {
                    if ($tax_flag == "S") {
                        $txper1 = $post['tax'][$key] * $split_1;
                        $txval1 = $post['ptax_amount'][$key] * $split_1;
                        $txper2 = $post['tax'][$key] * $split_2;
                        $txval2 = $post['ptax_amount'][$key] * $split_2;
                        $tax_split_details = array(array('tax_name' => $split_1_name, 'tax_percentage' => $txper1, 'tax_amount' => $txval1, 'account_code' => $split_1_gl_account_code), array('tax_name' => $split_2_name, 'tax_percentage' => $txper2, 'tax_amount' => $txval2, 'account_code' => $split_2_gl_account_code));
                        $taxfield['tax_split_details'] = json_encode($tax_split_details);
                    } else {
                        $txper1 = $post['tax'][$key] * $split_1;
                        $txval1 = $post['ptax_amount'][$key] * $split_1;
                        $tax_split_details = array(array('tax_name' => $split_1_name, 'tax_percentage' => $txper1, 'tax_amount' => $txval1, 'account_code' => $split_1_gl_account_code));
                        $taxfield['tax_split_details'] = json_encode($tax_split_details);
                    }
                }
                $insert_data['taxsss'][] = $taxfield;
                //replace ' symbol
                foreach ($itemfieldnames as $fieldkey => $fieldval) {
                    if ($fieldkey != "item_details") {
                        $itemfieldnames[$fieldkey] = str_replace(["'", '"'], "", $fieldval);
                    }
                }
                foreach ($taxfield as $fieldkey1 => $fieldval1) {
                    if ($fieldkey1 != "tax_split_details") {
                        $taxfield[$fieldkey1] = str_replace(["'", '"'], "", $fieldval1);
                    }
                }

                $item_id = '';
                if ($type == 'update') {
                    //Item table Insert data Start
                    $transaction_item_row_id = $post['transaction_item_row_id'][$key];
                    $where = self::USER_LIT_ID . $transaction_item_row_id . "'";
                    $itemquery = $callConfig->selectQuery($fieldarray[$table]['item'], '*', $where, '', '', '');
                    $data = $callConfig->getRow($itemquery);

                    $itemfieldnames['approved_quantity'] = $post['quantity'][$key];
                    $itemfieldnames['pending_qty'] = $post['quantity'][$key];
                    if ($data->id != '') {
                        $itemfieldnames['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1);
                        $itemfieldnames['updated_by'] = $get['user_id'];
                        $res = $callConfig->updateRecord($fieldarray[$table]['item'], $itemfieldnames, 'id', $data->id);
                        $insert_data['item'][] = $res;
                        $return['item_id'][] = $res;
                    } else {
                        $itemfieldnames['created_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1);
                        $itemfieldnames['created_by'] = $get['user_id'];
                        $item_transaction = $callConfig->insertRecord($fieldarray[$table]['item'], $itemfieldnames);
                        $insert_data['item'][] = $item_transaction;
                        $transaction_item_row_id = $item_transaction['LASTID'];
                        $return['item_id'][] = $item_id;
                    }



                    if ($post['tax'][$key] != '0' && $post['tax'][$key] != '') {
                        $where = self::USER_LIT_TRANSACTION_ID . $insert_id . "' AND transaction_item_row_id    = '" . $transaction_item_row_id . "'";
                        $itemquery = $callConfig->selectQuery($fieldarray[$table]['tax'], '*', $where, '', '', '');
                        $data_tax = $callConfig->getRow($itemquery);
                        if ($data_tax->id != '') {
                            $taxfield['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1);
                            $taxfield['updated_by'] = $get['user_id'];
                            $where = self::USER_LIT_ID . $data_tax->id . "'";
                            $callConfig->updateRecord($fieldarray[$table]['tax'], $taxfield, '', '', $where);
                            $insert_data['tax'][] = $itax_id;

                        } else {
                            $taxfield['created_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1);
                            $taxfield['created_by'] = $get['user_id'];
                            $taxfield['transaction_item_row_id'] = $transaction_item_row_id;
                            $itax_id = $callConfig->insertRecord($fieldarray[$table]['tax'], $taxfield);
                            $insert_data['tax'][] = $itax_id;
                        }
                    }
                    //Tax table Insert data End
                } else {
                    //Item table Insert data Start
                    $itemfieldnames['created_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1);
                    $itemfieldnames['created_by'] = $get['user_id'];
                    $item_transaction = $callConfig->insertRecord($fieldarray[$table]['item'], $itemfieldnames);
                    $insert_data['item'][] = $item_transaction;
                    $transaction_item_row_id = $item_transaction['LASTID'];
                    //Item table Insert data End
                    //Tax table Insert data Start
                    if ($post['tax'][$key] != '0' && $post['tax'][$key] != '') {
                        $taxfield['created_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1);
                        $taxfield['created_by'] = $get['user_id'];
                        $taxfield['transaction_item_row_id'] = $transaction_item_row_id;
                        $itax_id = $callConfig->insertRecord($fieldarray[$table]['tax'], $taxfield);
                        $insert_data['tax'][] = $itax_id;
                    }
                    //Tax table Insert data Start
                }
            }   // Product loop close
        }

        $insert_data['table'] = $table;
        //TCS Part In Sales Invoice Only
        if ($post['amendment'] == "Y") {
            $insert_data['insert_amendment'] = $this->InsertAmendment($table, $insert_id, $post);
        }
        $return['insert_data'] = $insert_data;
        return $insert_data;
    }


    public function invoiceUpdates($table, $len)
    {
        if (isset($table)) { /* noop */ }
        global $callConfig;

        if (count((array) $len) > 1) {
            $request_warehouse_id = $len['request_warehouse_id'] ?? 1;
            unset($len['request_warehouse_id']);
            $this->insertoupdatelocitemwabalances($len);
            $this->insertoupdatelocitemstbalances($len);

            $reverseentry = array('stock_transfers', 'stock_transfer_receipts', 'subcontract_work_order_transfers', 'subcontract_work_order_receipts');

            if (in_array($len['document_type'], $reverseentry)) {
                $len['transaction_warehouse_id'] = $request_warehouse_id;
                if ($len['document_type'] == "stock_transfers" || $len['document_type'] == "subcontract_work_order_transfers") {
                    $len['in_qty'] = $len['out_qty'];
                    $len['in_value'] = $len['out_value'];
                    $len['out_qty'] = 0;
                    $len['out_value'] = 0;
                } else {
                    $len['out_qty'] = $len['in_qty'];
                    $len['out_value'] = $len['in_value'];
                    $len['in_qty'] = 0;
                    $len['in_value'] = 0;
                }
                $this->insertoupdatelocitemwabalances($len);
                $this->insertoupdatelocitemstbalances($len);
            }
            $this->insertorupdateitem_ledgerst($len);
            $this->insertorupdateitem_ledgerwa($len);

            $this->insertoupdateitemwabalances($len);

            $this->insertoupdateitemstbalances($len);
            $this->insertorupdateitemfifo($len);
        }
    }





