    public function itemlifoupdateledge($post)
    {
        global $callConfig;
        $count = $post['out_qty'];
        $itemcount = $post['out_qty'];
        if ($count > 0) {
            $locquery = "SELECT * FROM loc_item_lifo_balances WHERE item_id =" . $post['item_id'] . self::USER_SQL_AND_COMPANY_ID_1 . $post['company_id'] . self::USER_SQL_AND_LOCATION_ID . $post['location_id'] . " AND closing_qty >0 ORDER By balance_date DESC,id DESC";
            $query = "SELECT * FROM item_lifo_balances WHERE item_id =" . $post['item_id'] . self::USER_SQL_AND_COMPANY_ID_1 . $post['company_id'] . " AND closing_qty >0 ORDER By balance_date DESC,id DESC";
        } else {
            $locquery = "SELECT * FROM loc_item_lifo_balances WHERE item_id =" . $post['item_id'] . self::USER_SQL_AND_LOCATION_ID . $post['location_id'] . self::USER_SQL_AND_COMPANY_ID_1 . $post['company_id'] . " AND AND (closing_qty = 0 OR closing_qty!=in_qty) ORDER By balance_date,id DESC";
            $query = "SELECT * FROM item_lifo_balances WHERE item_id =" . $post['item_id'] . self::USER_SQL_AND_COMPANY_ID_1 . $post['company_id'] . " AND  (closing_qty = 0 OR closing_qty!=in_qty) ORDER By balance_date DESC,id DESC";
        }
        $rows = $callConfig->getAllRows($locquery);
        $itemrows = $callConfig->getAllRows($query);
        foreach ($itemrows as $itemdata) {
            if ($itemcount > 0) {
                if ($itemdata->closing_qty < $itemcount) {
                    $itemremaning_count = $itemcount - $itemdata->closing_qty;
                    $count = $itemdata->closing_qty;
                } else {
                    $itemremaning_count = 0;
                }
            } else {
                if ($itemdata->closing_qty < $itemcount) {
                    $itemcount = "-" . $itemdata->closing_qty;
                } else {
                    $itemremaning_count = 0;
                }
            }
            $cc = $itemdata->out_qty + $itemcount;
            $ccc = $itemdata->closing_qty - $itemcount;
            $updatequery121 = "UPDATE item_lifo_balances SET out_qty = " . $cc . self::USER_LIT_CLOSING_QTY . $ccc . self::USER_SQL_WHERE_ID . $itemdata->id . "'";
            $callConfig->executeQuery($updatequery121);
            if ($itemremaning_count == 0) {
                break;
            }
            $itemcount = $itemremaning_count;
        }
        foreach ($rows as $row) {
            if ($count > 0) {
                if ($row->closing_qty < $count) {
                    $remaning_count = $count - $row->closing_qty;
                    $count = $row->closing_qty;
                } else {
                    $remaning_count = 0;
                }
            } else {
                if ($row->closing_qty < $count) {
                    $remaning_count = $count + $row->closing_qty;
                    $count = "-" . $row->closing_qty;
                } else {
                    $remaning_count = 0;
                }
            }
            $cc = $row->out_qty + $count;
            $ccc = $row->closing_qty - $count;
            $updatequery = "UPDATE loc_item_lifo_balances SET out_qty = " . $cc . self::USER_LIT_CLOSING_QTY . $ccc . self::USER_SQL_WHERE_ID . $row->id . "'";
            $callConfig->executeQuery($updatequery);
            $insert = array('company_id' => $post['company_id'], 'location_id' => $post['location_id'], 'item_id' => $post['item_id'], 'document_no' => $post['document_no'], 'document_type' => $post['document_type'], 'document_ref_no' => $post['document_ref_no'], 'document_date' => $post['transaction_date'], 'in_qty' => $post['in_qty'], 'in_value' => $post['in_value'], 'item_cost' => $row->day_rate, 'total_cost' => $row->day_rate * $count, 'out_qty' => $count, 'out_value' => ($post['out_value'] / $post['out_qty']) * $count, 'is_active' => 0);
            $res = $callConfig->insertRecord('item_ledger_lifo', $insert);
            if ($remaning_count == 0) {
                break;
            }
            $count = $remaning_count;
        }
        return $res;
    }
