    public function toCheckStatusApprovalLog($post)
    {
        global $callConfig;
        $data['transaction_type'] = $post['table'];
        $data['total_amount'] = $post['amount'];
        $data['status'] = $post['response_type'];
        $data['status_old_value'] = $post['status_old'];
        $post['transaction_type'] = $post['table'];
        $post['Rid'] = $post['hid'];
        $post['updated_by'] = $post['user_id'];
        $workflow = $this->checkhierarchicallevel($post);
        if ($workflow['doa'] == 1) {
            $res = $this->tocheckDAOValues($data);
            $return = $post['status_old'];
            if ($res->doa_condition == 1) {
                $where = self::USER_LIT_TRANSACTION_TABLE . $post['table'] . self::USER_LIT_AND_TRANSACTION_ID_1 . $post['hid'] . "' AND send_back_flag=0 AND doa_id != 0 ";
                $query = $callConfig->selectQuery(TBL_TRANSACTION_APPROVAL_LOGS, '*', $where, '', '', '');
                $maindata = $callConfig->getAllRows($query);
                $count = count((array) $maindata);
                $doaval = $res->approval_type;
                $doanum = $res->approval_number;
                foreach ($maindata as $mvalue) {

                    if ($mvalue->response_type == ST_REJECTED) {
                        $val['reject'][] = $mvalue->id;
                    } elseif ($mvalue->response_type == 0) {
                        $val['pending'][] = $mvalue->id;
                    } else {
                        $val['approve'][] = $mvalue->id;
                    }
                }
                if ($doaval == 'A') {
                    if ($count == count((array) $val['approve'])) {
                        $return = ST_APPROVED;
                    }
                    if (count((array) $val['reject']) > 0) {
                        $return = ST_REJECTED;
                    }
                }
                if ($doaval == 'M') {

                    if ($doanum <= count((array) $val['approve'])) {
                        $return = ST_APPROVED;
                    } elseif (count((array) $val['reject']) <= 0) {
                        $return = $post['status_old'];
                    } else {
                        $check = count((array) $val['approve']) + count((array) $val['pending']);
                        if ($check < $doanum) {
                            $return = ST_REJECTED;
                        }
                    }
                }
                if ($doaval == 'L') {
                    $return = $post['response_type'];
                }
            } else {
                $return = $post['response_type'];
            }
        }
        if ($res->doa_condition == 0) {
            $return = $post['response_type'];
        }
        if ($res->doa_condition == 2) {
            $return = ST_APPROVED;
        }
        return $return;
    }

