            $stax_amount = $stax_amount + (($item_data->tax_amount / $fqty) * $pqty);
            $discount_amount = $discount_amount + $inlinediscount;

            foreach ($item_tax[$item_data->id] as $tax_data) {
                $itemtaxenty = array('company_id' => $tax_data->company_id, 'transaction_id' => $insert_id, 'transaction_item_id' => $tax_data->transaction_item_id, 'tax_name' => $tax_data->tax_name, 'tax_value' => ($tax_data->tax_value / $fqty) * $pqty, 'tax_id' => $tax_data->tax_id, 'amount' => ($tax_data->amount / $fqty) * $pqty, 'tax_amount' => ($tax_data->tax_amount / $fqty) * $pqty, 'total_amount' => ($tax_data->total_amount / $fqty) * $pqty, 'is_active' => 0, 'created_by' => $data['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));

