            $fieldnames['transaction_number'] = $transaction_number_details['main_transaction_number'];
            $fieldnames['monthly_transaction_number'] = $transaction_number_details['monthly_transaction_number'];
            $fieldnames['yearly_transaction_number'] = $transaction_number_details['yearly_transaction_number'];
            $fieldnames['lifetime_transaction_number'] = $transaction_number_details['lifetime_transaction_number'];
            //End - Serial Number Masters

            $where2 = "id =" . $vendor;
            if ($party_type == "customers") {
                $query2 = $callConfig->selectQuery('customers', '*', $where2, '', '', '');
            } else {
                $query2 = $callConfig->selectQuery(TBL_VENDOR, '*', $where2, '', '', '');
            }
            $vendor_data = $callConfig->getRow($query2);

            $fieldnames['party_id'] = $vendor;
            $fieldnames['party_name'] = $vendor_data->company;
            $fieldnames['party_email'] = $vendor_data->email;
            $fieldnames['party_tax_number'] = $vendor_data->vendor_tax_reg_no;
            $fieldnames['party_phone'] = $vendor_data->phone;
            $fieldnames['party_address'] = $vendor_data->billing_address;
