                    }

                    $item_id = $callConfig->insertRecord($fieldarray[$insert_table]['item'], $item_data);
                    $transaction_item_row_id = $item_id['LASTID'];
                    $res['item'][] = $item_data;
                    $res['item_res'][] = $item_id;
                    foreach ($itemtaxfieldnames[$key] as $taxfield) {
