                $taxfield = array('company_id' => $post['company_id'], 'transaction_id' => $insert_id, 'transaction_item_id' => $item, 'tax_id' => $post['tax'][$key], 'amount' => $post['p_amount'][$key], 'tax_amount' => $post['ptax_amount'][$key], 'total_amount' => $post['amount'][$key], 'tax_type' => $tax_flag, 'tax_value' => $post['tax'][$key]);
                if ($type == 'update') {
                    $where = self::USER_LIT_TRANSACTION_ID . $insert_id . self::USER_LIT_AND_ITEM_ID . $item . self::USER_LIT_AND_IS_ACTIVE_0;
                    $itemquery = $callConfig->selectQuery($bill_items, '*', $where, '', '', '');
                    $data = $callConfig->getRow($itemquery);
                    if ($data->description != $itemfieldnames['description'] || $data->purchase_uom != $itemfieldnames['purchase_uom'] || $data->item_quantity != $itemfieldnames['item_quantity'] || $data->item_price != $itemfieldnames['item_price']) {
                        if ($data->id != '') {
                            $callConfig->updateRecord($bill_items, $itemfieldnames, 'id', $data->id);
                        } else {
                            $callConfig->insertRecord($bill_items, $itemfieldnames);
                        }
                    }
                    $where = self::USER_LIT_TRANSACTION_ID . $insert_id . self::USER_LIT_AND_TRANSACTION_ITEM_ID_1 . $item . self::USER_LIT_AND_IS_ACTIVE_0;
                    $itemquery = $callConfig->selectQuery($bill_item_taxes, '*', $where, '', '', '');
                    $data_tax = $callConfig->getRow($itemquery);
                    if (count((array) $data_tax) > 0) {
                        if ($data->tax_amount != $itemfieldnames['tax_amount']) {
                            $where = self::USER_LIT_TRANSACTION_ID . $insert_id . self::USER_LIT_AND_TRANSACTION_ITEM_ID . $item . self::USER_LIT_AND_IS_ACTIVE_0;
                            $callConfig->updateRecord($bill_item_taxes, $taxfield, '', '', $where);
                        }
                    } else {
                        $callConfig->insertRecord($bill_item_taxes, $taxfield);
                    }

                } else {
                    $callConfig->insertRecord($bill_items, $itemfieldnames);
                    if ($post['tax'][$key] != 0) {
                        $callConfig->insertRecord($bill_item_taxes, $taxfield);
                    }
                }
            }
            if ($type == 'update') {
                $diffid = array_diff($itemids, $litemids);
                if (count((array) $diffid) > 0) {
                    foreach ($diffid as $value_id) {
                        $taxfieldde = array('is_active' => 1);
                        $wheredd = self::USER_LIT_TRANSACTION_ID . $insert_id . self::USER_LIT_AND_ITEM_ID . $value_id . self::USER_LIT_AND_IS_ACTIVE_0;
                        $wheredd1 = self::USER_LIT_TRANSACTION_ID . $insert_id . self::USER_LIT_AND_TRANSACTION_ITEM_ID . $value_id . self::USER_LIT_AND_IS_ACTIVE_0;
                        $callConfig->updateRecord($bill_items, $taxfieldde, '', '', $wheredd);
                        $callConfig->updateRecord($bill_item_taxes, $taxfieldde, '', '', $wheredd1);
                    }
                }
                if ($status > ST_DRAFT) {
                    $this->toSendEmailNotificationsBaseDAO($email_data);
                }
                if ($status != ST_CANCEL && $status != ST_DRAFT) {
                    $this->insertandupdatedataapplicationtag($fieldnames, $insert_id, 'COM_INSERT_PETTY_CASH');
                }
            }
        }
        return $insert_data;
    }



