    public function candidateautoregistation($post, $get)
    {
        global $callConfig;
        $allreadycreatesql = self::USER_SQL_SELECT_ID_FROM . MAINDB . ".user_registered_groups WHERE user_email ='" . $post['user_email'] . "'";
        $allreadycreateres = $callConfig->getAllRows($allreadycreatesql);
        if (count((array) $allreadycreateres) > 0) {
            return array('status' => "fail", 'type' => 'email');
        } else {
            $whre = "user_mobile='" . $post['user_mobile'] . self::USER_LIT_AND_IS_ACTIVE_0_9;
            $querym = $callConfig->selectQuery('application_users', '*', $whre, '', '', '');
            $empmrow = $callConfig->getAllRows($querym);
            if (count((array) $empmrow) > 0) {
                return array('status' => "fail", 'type' => 'mobile');
            } else {
                $role = json_encode(array(CANDIDATE_ROLE));
                $insert_array = array('company_id' => $get['company_id'], 'user_email' => $post['user_email'], 'user_mobile' => $post['user_mobile'], 'display_name' => $post['display_name'], 'user_type' => '4', 'role_id' => $role, 'current_status' => '0', 'is_active' => '0', "created_date" => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), "created_by" => $post['user_id']);

                $insert = $callConfig->insertRecord('application_users', $insert_array);
                $userid = $insert['LASTID'];

