                        $leaves = $this->togetemployeeleavecalucate($emp->id, $date1, $date2);
                        $total_no_of_leaves = $leaves['total_no_of_leaves'];
                        $total_lop_days = $leaves['total_lop_days'];
                    } else {
                        $total_no_of_leaves = 0;
                        $total_lop_days = 0;
                    }
                }
                $total_month_working_days = $leaves['total_month_working_days'];
                $date_of_leaving = $emp->date_of_leaving != "" ? $emp->date_of_leaving : $emp_termination_data->releive_date;

                $insert_array = array('company_id' => $get['company_id'], 'revision_no' => $version, 'pay_year' => $post['pay_year'], 'pay_month' => $post['pay_month'], 'location_id' => $emp->location_id, 'employee_id' => $emp->id, 'designation_id' => $emp->designation_id, 'father_name' => $emp->father_name, 'date_of_birth' => $emp->date_of_birth, 'date_of_leaving' => $date_of_leaving, 'date_of_joining' => $emp->joining_date, 'contact_details' => $emp->phone, 'bank_id' => $emp->bank_id, 'bank_link' => $emp->bank_link, 'bank_account_no' => $emp->bank_account_no, 'cover_under_pf' => $emp->cover_under_pf, 'cover_under_esi' => $emp->cover_under_esi, 'total_no_of_leaves' => $total_no_of_leaves, 'total_no_of_days' => $total_working_days, 'total_lop_days' => $total_lop_days, 'total_no_of_working_days' => $total_month_working_days, 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1));
                $insert = $callConfig->insertRecord('pay_run_summary', $insert_array);

