    public function movefileonedirtoanotherdir($source, $destination, $file, $other = '')
    {
        if (isset($other)) { /* noop */ }
        $path = $destination;
        if (!is_dir($path)) {
            $dual_path = trim($path, '/');
            $dual_path = explode('/', $dual_path);
            $epath = "";
            foreach ($dual_path as $dpath) {
                $epath = $epath . $dpath . "/";
                if (!is_dir($epath)) {
                    mkdir($epath);
                }
            }
        }
        return copy($source . "/" . $file, $destination . "/" . $file);
    }
