        $cadndidata = $callConfig->getRow($candiquery);





        $tasquery = self::USER_SQL_SELECT_TASK_ID_ASSIGNED_TO_FRO . $post['company_id'] . "' AND transaction_table = 'candidates' AND transaction_id = '" . $post['candidate_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
