    public function payrollfromtodates($get)
    {
        global $callConfig;
        if ($get['pay_area_id'] != "") {
            $cfquery = "SELECT pay_run_period FROM pay_areas WHERE company_id =" . $get['company_id'] . self::USER_SQL_AND_ID_2 . $get['pay_area_id'] . self::USER_SQL_AND_IS_ACTIVE_0;
            $cfdata = $callConfig->getRow($cfquery);
            $payday = $cfdata->pay_run_period;
        }
        if ($payday == "" || !isset($get['pay_area_id']) || $get['pay_area_id'] == "") {
            $cfquery = $callConfig->selectQuery('config', 'default_payroll_day', 'id=1', '', '', '');
            $cfdata = $callConfig->getRow($cfquery);
            $payday = $cfdata->default_payroll_day;
        }

        $date2 = $get['pay_year'] . "-" . $get['pay_month'] . "-" . $payday;
        if ($payday > 28) {
            $date2 = $get['pay_year'] . "-" . $get['pay_month'] . "-28";
            $month = $get['pay_month'] - 1;
            $date1 = $get['pay_year'] . "-" . $month . "-28";
            $date1 = date("Y-m-d", strtotime('last day of', strtotime($date1)));
            $date2 = date("Y-m-d", strtotime('last day of', strtotime($date2)));
        } else {
            $date1 = date("Y-m-d", strtotime(self::USER_LIT_1_MONTHS, strtotime($date2)));
        }

        $date1 = date("Y-m-d", strtotime(self::USER_LIT_1_DAY, strtotime($date1)));
        return array('date1' => $date1, 'date2' => $date2);
    }

