                    $assspquery = "SELECT sum(if(category_id =3, 1,0)) addition, sum(if(category_id =4, 1,0)) separation, sum(if(category_id = 1, 1,0)) exclusion, sum(if(category_id = 5, 1,0)) settlements FROM `payroll_exclusions` WHERE  company_id = " . $get['company_id'] . self::USER_SQL_AND_IS_ACTIVE_0_AND_PAY_YEAR . $get['pay_year'] . self::USER_LIT_AND_PAY_MONTH_1 . $get['pay_month'] . "'";
