            $post_array = array("module_setup_id" => $module_id, "task_name" => $post['task_name'], "assigned_to" => $post['assigned_to'], "approval_type" => $post['approval_type'], "process_id" => $post['process_id'], "email_content_id" => $post['email_content_id'], "process_type" => $post['process_type'], "no_action" => $post['no_action'], "on_the_day" => $post['on_the_day'], "action_no" => $post['action_no'], "action_frequency" => $post['action_frequency'], "before_or_after" => $post['before_or_after'], "description" => $post['description'], "files" => $post['files'], "display_color" => $post['display_color'], "display_background_color" => $post['display_background_color'], "remarks" => $post['remarks'], "task_for" => $post['task_for'], "link_page" => $link_page, "page_url" => $post['page_url'], "updated_date" => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), "updated_by" => $post['created_by'], "user_id" => $post['other_id'], "company_id" => $get['company_id'], "is_active" => '0', "check_list" => $post['check_list'], 'planned_day' => $post['planned_day'], 'trigger_date' => $post['trigger_date']);
            $res = $callConfig->updateRecord(TBL_PROCESS_TASK_SETTINGS, $post_array, 'id', $rowid);
