    public function gettotalemployeesbyfilter($post, $get)
    {
        global $callConfig;
        $company_id = $get['company_id'];
        $table_name = $post['table'];
        $cond = "";
        $count = 0;
        foreach ($post as $key => $value) {
            $explode = explode(",", $value);  // rohan added (1,2,3) NEW ('1','2','3')
            $vall = "'" . implode("', '", (array) $explode) . "'";
            if ($key != 'page' && $value != '' && $key != 'table') {
                $cond .= self::USER_SQL_AND . $key . " IN (" . $vall . ")";
            }
        }
        if ($cond != '') {
            $display_data = self::USER_SQL_SELECT_FROM_1 . $table_name . self::USER_SQL_WHERE_IS_ACTIVE_0_AND_COMPANY__1 . $company_id . "'" . $cond;
            $display_details = $callConfig->getAllRows($display_data);
