    public function getsalaryreportinggroupsdata($get)
    {
        global $callConfig;
        $finiancial_year_start_month = 4;
        $total_months_in_year = 12;
        $project_date = $get['projected_date'];
        $project_month = date("m", strtotime($project_date));
        $project_day = date("d", strtotime($project_date));
        $report_header = "select * from config where company_id='" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_5;
        $report_header_data = $callConfig->getRow($report_header);
        $salary_reports['report_header'] = $report_header_data;
        $payroll_day = $report_header_data->default_payroll_day;
        $assessment_year = $report_header_data->assessment_year == "" ? "0" : $report_header_data->assessment_year;
        $in_assessment_year = explode("-", $assessment_year);
        $old_regime_year = ($in_assessment_year[0] - 1) . $in_assessment_year[0];
        $assessment_date = $in_assessment_year[0] . "-" . $finiancial_year_start_month . "-01";
        for ($m = 1; $m < $total_months_in_year + 1; $m++) {
            $finiancial_year_start_month = ($finiancial_year_start_month > 12) ? ($finiancial_year_start_month - 12) : $finiancial_year_start_month;
            $monthly_wise_taxyear[$finiancial_year_start_month] = $m;
            $finiancial_year_start_month = $finiancial_year_start_month + 1;
        }
        if ($project_day > $payroll_day) {
            $month_wise_key = $project_month;
        } else {
            $month_wise_key = $project_month - 1;
        }
        $month_wise_key = $month_wise_key != 0 ? $month_wise_key : 12;
        $salary_reports['actual_months'] = $monthly_wise_taxyear[$month_wise_key];
        $salary_reports['projected_months'] = $total_months_in_year - $salary_reports['actual_months'];

        $employeequery1 = "SELECT * FROM `employees` WHERE id = " . $get['employee_id'] . self::USER_SQL_AND_IS_ACTIVE_0_AND_COMPANY_ID . $get['company_id'];
        $empdata = $callConfig->getRow($employeequery1);
        $designationquery1 = "SELECT * FROM `designations` WHERE id = " . $empdata->designation_id . self::USER_SQL_AND_IS_ACTIVE_0_AND_COMPANY_ID . $get['company_id'];
        $designationquerydata = $callConfig->getRow($designationquery1);
        $salary_reports['employee_designation'] = $designationquerydata->designation_name;
        $salary_reports['employee_details'] = $empdata;

        $reporting_data = "select * from salary_reporting_groups where company_id='" . $get['company_id'] . "' and is_active='0'  order by display_seq";
        $reporting_details = $callConfig->getAllRows($reporting_data);
        $salary_reports['parent_group'] = $reporting_details;

        $fetchdate = $assessment_date;
        for ($k = 0; $k < $salary_reports['actual_months']; $k++) {
            $fetch_month = date('m', strtotime($fetchdate));
            $fetch_year = date('Y', strtotime($fetchdate));
            $pay_run_summary_query = "select * from pay_run_summary where employee_id='" . $get['employee_id'] . self::USER_LIT_AND_PAY_MONTH_2 . $fetch_month . self::USER_LIT_AND_PAY_YEAR . $fetch_year . "' and is_active='0' and company_id=" . $get['company_id'];
            $prsde = $callConfig->getRow($pay_run_summary_query);
            $payrunsum = "select * from pay_summary_components where pay_summary_id='" . $prsde->id . self::USER_LIT_AND_PAY_MONTH_2 . $fetch_month . self::USER_LIT_AND_PAY_YEAR . $fetch_year . "' and is_active='0' and company_id=" . $get['company_id'];
            echo $payrunsum;
            exit;
            $payrunsum_details = $callConfig->getAllRows($payrunsum);
            foreach ($payrunsum_details as $pdetails) {
                $payrunsum_idlist[$fetch_month . "-" . $fetch_month][$pdetails->component_id] = $pdetails;
                $totalcomponent[$pdetails->component_id] = $totalcomponent[$pdetails->component_id] != "" ? $totalcomponent[$pdetails->component_id] : 0;
                $totalcomponent[$pdetails->component_id] = $totalcomponent[$pdetails->component_id] + $pdetails->salary_component_actual;
            }
            $fetchdate = date("Y-m-d", strtotime($fetchdate . self::USER_LIT_1_MONTH));
        }
        $salary_reports['payrunsummer_totalcomponets'] = $totalcomponent;

        $salary_reports['payrunsummer_monthlycomponet'] = $payrunsum_idlist;
        foreach ($salary_reports['parent_group'] as $mapped_data) {
            $group_id = $mapped_data->id;
            $reporting_group = "select * from earnings where company_id='" . $get['company_id'] . "' and is_active='0' and report_group_id='" . $group_id . "'";
            $reporting_group_data = $callConfig->getAllRows($reporting_group);
            $salary_dtails[$group_id] = $reporting_group_data;
        }
        $salary_reports['child_group'] = $salary_dtails;

        $salarytempquery = "SELECT max(st.affected_date) max_affected_date, stc.component_id as component_id, stc.monthly_amount as projected, salary_template_id ,FROM `salary_template` st, salary_template_components stc where st.id = stc.salary_template_id and st.company_id = stc.company_id  and st.employee_id ='" . $get['employee_id'] . "' and  st.company_id='" . $get['company_id'] . "' AND st.is_active = 0 and stc.is_active=0";
        $salarytempquery_projected = $callConfig->getAllRows($salarytempquery);
        foreach ($salarytempquery_projected as $projected) {
            $salay_template[$projected->component_id] = $projected;
        }
        $salary_reports['salary_monthlycomponet'] = $salay_template;

        $old_regime = str_replace('-', '', $old_regime_year);
        $assessment = str_replace('-', '', $assessment_year);
        $salary_tax_components_pquery = "SELECT  * from salary_tax_components where company_id=" . $get['company_id'] . " AND is_active=0 AND assesment_year in('" . $old_regime . "','" . $assessment . "')";
        $salary_tax_components_datas = $callConfig->getAllRows($salary_tax_components_pquery);
        foreach ($salary_tax_components_datas as $salary_tax_components_data) {
            if ($salary_tax_components_data->assesment_year == $old_regime) {
                $salary_tax_components['old_regime'][$salary_tax_components_data->salary_component_id] = $salary_tax_components_data->taxable != '' ? $salary_tax_components_data->taxable : 0;

            } else {
                $salary_tax_components['new_regime'][$salary_tax_components_data->salary_component_id] = $salary_tax_components_data->taxable != '' ? $salary_tax_components_data->taxable : 0;
            }
        }
        $salary_reports['salary_tax_components'] = $salary_tax_components;
        return $salary_reports;

    }
    public function saveusersettings($post, $get)
    {
        global $callConfig;
        $rowid = $post['rowid'];
        if ($rowid != '') {
            $post_array = array("setting" => $post['jsonsetting'], "updated_date" => $post['load_date'], "updated_by" => $post['user_id']);
            $callConfig->updateRecord(TBL_USER_SETTINGS, $post_array, 'id', $rowid);
            $inserted_rowid = $rowid;
        } else {
            $post_array = array("company_id" => $get['company_id'], "emp_id" => $post['emp_id'], "fieldname" => $post['fieldname'], "setting" => $post['jsonsetting'], "created_date" => $post['load_date'], "created_by" => $post['user_id'], "is_active" => '0');
            $res = $callConfig->insertRecord(TBL_USER_SETTINGS, $post_array);
            $inserted_rowid = $res['LASTID'];
        }
        return $inserted_rowid;
    }

    public function toimportthedataintosalarytables($get)
    {
        global $callConfig;
        $whre = self::USER_LIT_IS_IMPLODE_0_AND_FILE_NAME . $get['file_name'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
        $pequery = $callConfig->selectQuery('import_mappings', '*', $whre, '', '', '');
        $pedata = $callConfig->getRow($pequery);
        if ($pedata->id != "") {
            $maps = json_decode($pedata->filed_mapping);
            $maps = (array) $maps;
            $eraningquery = $callConfig->selectQuery('earnings', '*', self::USER_LIT_IS_ACTIVE_0, '', '', '');
            $earnings = $callConfig->getAllRows($eraningquery);
            foreach ($earnings as $earns) {
                $earname = strtolower($earns->name);
                $earn[$earname] = (array) $earns;
            }
            $whre = "name ='" . $get['file_name'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
            $edquery = $callConfig->selectQuery('edi_dump', '*', $whre, '', '', '');
            $edddata = $callConfig->getRow($edquery);
            $edi_dump_data = json_decode($edddata->field_data, 1);
            foreach ($maps as $fkey => $map) {
                if ($map == 'employee_id') {
                    $employee_code_id = $fkey;
                }
                if ($map == 'ctc_monthly') {
                    $monthly_ctc_id = $fkey;
                }
                if ($map == 'ctc_yearly') {
                    $annual_ctc_id = $fkey;
                }
                if ($map == 'affected_date') {
                    $affected_date_id = $fkey;
                }

            }
            $remove = array('employee_code', 'ctc_monthly', 'ctc_yearly', 'affected_date', 'yearly_gross_salary', 'EMPLOYEE_CODE', 'BASIC_NUMBER', 'HRA_NUMBER', 'OTHER ALLOWANCE_NUMBER', 'MONTHLY_CTC', 'ANNUAL_CTC');
            $whre = self::USER_LIT_FILE_NAME . $get['file_name'] . "'";
            $dquery = $callConfig->selectQuery('edi_data', '*', $whre, '', '', '');
            $ddata = $callConfig->getAllRows($dquery);
            $whre = self::USER_LIT_FILE_NAME . $get['file_name'] . "'";
            $dqquery = $callConfig->selectQuery('edi_read', '*', $whre, '', '', '');
            $edi_reads = $callConfig->getRow($dqquery);
            $gmaps = json_decode($edi_reads->header, 1);
            foreach ($ddata as $edata) {
                $edata = (array) $edata;
                $sal_array = array('company_id' => $get['company_id'], 'employee_id' => $edata[$employee_code_id], 'ctc_yearly' => $edata[$annual_ctc_id], 'ctc_monthly' => $edata[$monthly_ctc_id], 'yearly_gross_salary' => $edata[$annual_ctc_id], 'is_active' => '0', 'current_status' => 0, 'created_by' => $get['user_id'], 'description' => $edata['description'], 'note' => $edata['note'], 'affected_date' => $edata[$affected_date_id]);
                $salary_template = $callConfig->insertRecord('salary_template', $sal_array);
                $salary_template_id = $salary_template['LASTID'];

                $ids[] = $salary_template_id;


                foreach ($gmaps as $fkey => $map) {
                    if (!in_array($map, (array) $remove) && !strpos('NUMBER')) {
                        $lfkey = "field" . ($fkey + 1);
                        $lmap = strtolower($map);
                        $month_sal = str_replace(',', '', $edata[$lfkey]);
                        $name_comp = strtoupper($map . "_NUMBER");
                        $component_number_key = array_search($name_comp, $edi_dump_data);
                        $component_number = ($component_number_key != "" ? $edata[$component_number_key] : "0.00");

                        $saltemp_array = array('company_id' => $get['company_id'], 'salary_template_id' => $salary_template_id, 'component_id' => $earn[$lmap]['id'], 'component_name' => $map, 'component_category' => $earn[$lmap]['category_id'], 'component_number' => $component_number, 'component_type' => $earn[$lmap]['calculation_type'], 'monthly_amount' => $month_sal, 'yearly_amount' => $month_sal * 12, 'is_active' => '0', 'current_status' => 0, 'created_by' => $get['user_id']);
                        $callConfig->insertRecord('salary_template_components', $saltemp_array);
                    }
                }
            }
            $storedata['insert_ids'] = json_encode($ids);
            $storedata['is_implode'] = 1;
            $callConfig->updateRecord('import_mappings', $storedata, 'id', $pedata->id);
        }
        return $ids;
    }
    public function toimportthedataintotablesold($get)
    {
        global $callConfig;

        if ($get['table'] == 'salary_template') {
            $ids = $this->toimportthedataintosalarytables($get);
        } else {
            $whre = self::USER_LIT_IS_IMPLODE_0_AND_FILE_NAME . $get['file_name'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
            $pequery = $callConfig->selectQuery('import_mappings', '*', $whre, '', '', '');
            $pedata = $callConfig->getRow($pequery);
            if ($pedata->id != "") {
                $maps = json_decode($pedata->filed_mapping);
                $maps = (array) $maps;
                $table = $pedata->application_table;
                if ($table == 'employees') {
                    foreach ($maps as $filed => $aps) {
                        if (strpos($aps, 'ARN_')) {
                            $salmap[$filed] = $aps;
                        } else {
                            $empmap[$filed] = $aps;
                        }
                    }
                    $maps = $empmap;
                }
                $distyquery = $callConfig->selectQuery('display_attribute_types', '*', self::USER_LIT_APPLICATION_TABLE_NAME . $table . "'", '', '', '');
                $distydata = $callConfig->getAllRows($distyquery);
                foreach ($distydata as $std) {
                    $distypjson = json_decode(urldecode($std->content_details), 1);
                    $distype[$std->field_name]['display_field'] = $std->display_field;
                    $distype[$std->field_name]['value_field'] = $std->value_field;
                    $distype[$std->field_name]['table_name'] = $distypjson['table_name'];
                }
                $wh = self::USER_LIT_APPLICATION_TABLE_NAME . $table . "'";
                $disquery = $callConfig->selectQuery('display_attributes', '*', $wh, '', '', '');
                $disdata = $callConfig->getRow($disquery);
                $list_attributes = json_decode($disdata->list_attributes, 1);
                $check = array('select', 'radio', 'switch', 'checkbox', 'multi_select', 'disable_select');
                foreach ($maps as $fkey => $map) {
                    $fieldsdata[$map]['type'] = $list_attributes[$map]['type'];
                    if (in_array($list_attributes[$map]['type'], (array) $check)) {
                        $condata = $this->getDyanamicSelectData($table, $map);
                        $fieldsdata[$map]['data'] = $condata['res'];
                        $fieldsdata[$map]['fileds'] = $distype[$map];
                    }
                }
                $whre = self::USER_LIT_FILE_NAME . $get['file_name'] . "'";
                $dquery = $callConfig->selectQuery('edi_data', '*', $whre, '', '', '');
                $ddata = $callConfig->getAllRows($dquery);
                foreach ($ddata as $edata) {
                    $edata = (array) $edata;
                    $insert_array = array();
                    foreach ($maps as $fkey => $map) {
                        if (in_array($list_attributes[$map]['type'], (array) $check) && $edata[$fkey] != "") {
                            $return = $this->togetidorinsertrow($fieldsdata[$map], $edata[$fkey], $get);
                            $insert_array[$map] = $return['return_id'];
                            if (count((array) $return['return_array']) > 0) {
                                $appen = $return['return_array'];
                                $fieldsdata[$map]['data'][$appen['id']] = $appen['value'];
                            }
                        } else {
                            $insert_array[$map] = $edata[$fkey];
                        }
                    }
                    $insert_array['company_id'] = $get['company_id'];
                    $insert_array['current_status'] = '0';
                    $insert_array['is_active'] = '0';
                    $insert_array['created_by'] = $get['user_id'];
                    $mainres = $callConfig->insertRecord($table, $insert_array);
                    $ids[] = $mainres['LASTID'];

                }
            }

        }
        return $ids;
    }
