                $ddata = $callConfig->getAllRows($dquery);
                foreach ($ddata as $edata) {
                    $edata = (array) $edata;
                    $insert_array = array();
                    foreach ($maps as $fkey => $map) {
                        if (in_array($list_attributes[$map]['type'], (array) $check) && $edata[$fkey] != "") {
                            $return = $this->togetidorinsertrow($fieldsdata[$map], $edata[$fkey], $get);
                            $insert_array[$map] = $return['return_id'];
                            if (count((array) $return['return_array']) > 0) {
                                $appen = $return['return_array'];
                                $fieldsdata[$map]['data'][$appen['id']] = $appen['value'];
                            }
                        } else {

                            if ($list_attributes[$map]['type'] == 'date_pick') {


                                $insert_array[$map] = $this->convertToYYYYMMDD($edata[$fkey]);

                            } else {
                                $insert_array[$map] = $edata[$fkey];
                            }

                        }

                    }
                    $insert_array['company_id'] = $get['company_id'];
                    $insert_array['current_status'] = '0';
                    $insert_array['is_active'] = '0';
                    $insert_array['created_by'] = $get['user_id'];
                    $mainres = $callConfig->insertRecord($table, $insert_array);
                    $ids[] = $mainres['LASTID'];

                }
            }

        }
        return $ids;
    }

    public function convertToYYYYMMDD($dateString)
    {
        $dateTime = date_create_from_format('Y-m-d', $dateString);
        if (!$dateTime) {
            $dateTime = date_create_from_format('d/M/y', $dateString);
        }
        if (!$dateTime) {
            $dateTime = date_create_from_format('d-M-y', $dateString);
        }
        if (!$dateTime) {
            $dateTime = date_create_from_format('d/m/y', $dateString);
        }
        if (!$dateTime) {
            $dateTime = date_create_from_format('d-m-y', $dateString);
        }
        if (!$dateTime) {
            $dateTime = date_create_from_format('m/d/Y', $dateString);
        }
        if (!$dateTime) {
            $dateTime = date_create_from_format('m-d-Y', $dateString);
        }
        if (!$dateTime) {
            $dateTime = date_create($dateString);
        }
        if ($dateTime) {
            return $dateTime->format('Y-m-d');
        } else {
            return false; // Invalid date format
        }
    }

