    public function setuppayroll($post, $get)
    {
        if (isset($get['company_id']) && empty($post['company_id'])) { $post['company_id'] = $get['company_id']; }
        global $callConfig;
        $common_field = array('created_by' => $_SESSION['user_id'], 'is_active' => '0', 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
        $address = $post['address'] . ', ' . $post['city'] . ', ' . $post['state'] . ' ,' . $post['pincode'];

        $companies_setup = array('name' => $post['company_name'], 'gstno' => $post['gst_number'], 'telephone' => $post['phone_number'], 'email' => $post['admin_email'], 'created_by' => $_SESSION['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'is_active' => '0');
        $res = $callConfig->insertRecord(TBL_COMPANIES, $companies_setup);
        $common_field['company_id'] = $res['LASTID'];

        $config_setup = array('name' => $post['company_name'], 'contact_address' => $address, 'pan_number' => $post['pan_number'], 'tax_number' => $post['tan_number'], 'gst_number' => $post['gst_number'], 'cin_number' => $post['cin_number'], 'default_payroll_day' => $post['default_payroll_day'], 'liscense_number' => $post['license_number'], 'phone_number' => $post['phone_number'], 'admin_email' => $post['admin_email'], 'industry' => $post['industry'], 'location' => $post['location'], 'CreatedBy' => $_SESSION['user_id'], 'created_at' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'company_id' => $res['LASTID'], 'is_active' => '0');
        $callConfig->insertRecord(TBL_CONFIG, $config_setup);

        $attendance_setup = array('working_days' => json_encode($post['working_days'], 1), 'minimum_hours_required' => $post['minimum_hours_required'], 'half_day_hours' => $post['half_day_hours'], 'grace_perieod' => $post['grace_perieod']);
        $attendance_setup_full = array_merge($attendance_setup, $common_field);
        $res = $callConfig->insertRecord(TBL_ATTENDANCE_SETTINGS, $attendance_setup_full);

        if ($post['esi_checked']) {
            $esi_setup = array('esi_no' => $post['esi_no'], 'deduction_cycle' => $post['esi_deduction_cycle'], 'employee_contribution' => $post['esi_employee_contribution'], 'employer_contribution' => $post['esi_employer_contribution'], 'employer_contribution_in_ctc' => $post['esi_employer_contribution_in_ctc']);
            $esi_setup_full = array_merge($esi_setup, $common_field);
            $res = $callConfig->insertRecord(TBL_ESI, $esi_setup_full);
        }
        if ($post['pt_checked']) {
            foreach ($post['start_range'] as $slabkey => $slabsvalue) {
                $post_slabs['start_range'] = $slabsvalue;
                $post_slabs['end_range'] = $post['end_range'][$slabkey];
                $post_slabs['tax_amount'] = $post['tax_amount'][$slabkey];
                $postdata_slabs[] = $post_slabs;
            }
            $pt_setup = array('work_location_id' => $post['work_location_id'], 'state_id' => $post['pt_state_id'], 'pt_number' => $post['pt_number'], 'deduction_cycle' => $post['pt_deduction_cycle'], 'slabs' => json_encode($postdata_slabs, 1));
            $pt_setup_full = array_merge($pt_setup, $common_field);
            $res = $callConfig->insertRecord(TBL_PROFESSIONAL_TAX, $pt_setup_full);
        }
        if ($post['pf_checked']) {
            $pf_setup = array('epf_number' => $post['epf_number'], 'deduction_cycle' => $post['epf_deduction_cycle'], 'employee_contribution' => $post['epf_employee_contribution'], 'employer_contribution' => $post['epf_employer_contribution'], 'employer_contribution_in_ctc' => $post['epf_employer_contribution_in_ctc']);
            $pf_setup_full = array_merge($pf_setup, $common_field);
            $res = $callConfig->insertRecord(TBL_PROVIDENT_FUNDS, $pf_setup_full);
