trait UserBankingAndReconciliationTrait
{
    public function addeployeeshifts($post, $get)
    {
        global $callConfig;
        foreach ($post['check_employee'] as $emp) {
            $inserts_array = array('company_id' => $get['company_id'], 'emp_id' => $emp, 'shift_id' => $post['shift_id'], 'shift_from' => date('Y-m-d', strtotime($post['from'])), 'shift_to' => date('Y-m-d', strtotime($post['to'])), 'is_active' => '0', 'current_status' => 0, 'created_by' => $get['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));

            $callConfig->insertRecord('emp_shifts', $inserts_array);
        }

    }
    public function tosearchempleavesbydate($get)
    {
        global $callConfig;
        $condition = "";
        if ($get['emp_id'] != "") {
            $condition = " AND employee_id = '" . $get['emp_id'] . "'";
        }
        if ($get['type'] == 'REPORTTO') {
            $condition = " AND employee_id IN(SELECT id FROM employees WHERE user_id IN(SELECT id FROM `application_users` WHERE reports_to = '" . $get['user_id'] . self::USER_LIT_AND_COMPANY_ID . $get['company_id'] . "' AND is_active ='0')) AND current_status NOT IN(" . ST_ACTIVE . "," . ST_DRAFT . "," . ST_INACTIVE . ")";
        }
        $query6 = "SELECT * FROM `employee_leaves` WHERE company_id = '" . $get['company_id'] . "' AND  `leave_from`>= '" . $get['start'] . "' and  `leave_from`<= '" . $get['end'] . self::USER_LIT_AND_IS_ACTIVE_0_1 . $condition;
        return $callConfig->getAllRows($query6);
    }
    public function tosearchemployee($get)
    {
        global $callConfig;
        $employe = implode(",", (array) json_decode($get['employee'], 1));
        $department = $get['department'];
        $designation = $get['designation'];
        $whr = " where is_active = 0";
        if ($department != "") {
            $whr .= " and department_id=" . $department;
        }
        if ($designation != "") {
            $whr .= " and designation_id=" . $designation;
        }
        if ($employe != "") {
            $whr .= " and id in (" . $employe . ")";
        }
        $query = "SELECT * From employees " . $whr;
        return $callConfig->getAllRows($query);
    }



    public function setupvendor($post, $get)
    {
        global $callConfig;
        unset($post['document_id']);
        $returnddd['post'] = $post;
        $user_idd = $post['user_idd'];
        unset($post['user_idd']);
        if ($get['rid'] == '') {
            $post['current_status'] = "0";
            $res = $callConfig->insertRecord(TBL_VENDOR_REGISTERS, $post);
            $returnddd['upinsertvr'] = $res;
            $attachlist = json_decode($post['attachments'], 1);
            foreach ($attachlist as $dvalue) {
                $filename = $dvalue['filename'];
                $doctype = $dvalue['document_id'];
                if ($filename != "" && $dvalue['categoryid'] != "") {
                    $fields = array('company_id' => $get['company_id'], 'vendor_user_id' => $user_idd, 'document_id' => $dvalue['categoryid'], 'filename' => $filename, 'category_id' => $doctype, 'created_by' => $get['user_id'], 'is_active' => '0', 'current_status' => ST_APPROVAL_PENDING, 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
