    public function getvendorsettings($get)
    {
        global $callConfig;

        $vendor_registerssql = "SELECT * FROM `vendor_registers` WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_USER_ID . $get['user_id'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
        $vendor_registersres = $callConfig->getRow($vendor_registerssql);
        $details['vendor_registers'] = $vendor_registersres;

        $application_user_invitationssql = "SELECT connect_users, company_name FROM `application_user_invitations` WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_USER_ID . $get['user_id'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
        $application_user_invitationsres = $callConfig->getRow($application_user_invitationssql);
        $details['application_user_invitations'] = $application_user_invitationsres;

        $display_data = self::USER_SQL_SELECT_GENC_DETAIL_CODE_GENC_D_3 . $get['company_id'] . "'  and genc_code='BANKACCTTYPE'";
        $display_details = $callConfig->getAllRows($display_data);
        $details['bankactype'] = $display_details;

        $vendor_documents = "SELECT * FROM vendor_documents WHERE company_id='" . $get['company_id'] . "'  AND vendor_user_id = '" . $get['user_id'] . self::USER_LIT_AND_IS_ACTIVE_0_4;
        $display_details = $callConfig->getAllRows($vendor_documents);
        $details['vendor_documents'] = $display_details;


        $whrcat = self::USER_LIT_COMPANY_ID_1 . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
        $query = $callConfig->selectQuery('countries', 'id,country_name', $whrcat, '', '', '');
        $components6 = (array) $callConfig->getAllRows($query);
        $details['countries'] = (array) $components6;

        $statessql = self::USER_SQL_SELECT_ID_STATE_NAME_FROM_STAT . $get['company_id'] . "' AND (country_id = '" . $vendor_registersres->billing_country . "' || country_id = '" . $vendor_registersres->shipping_country . self::USER_LIT_AND_IS_ACTIVE_0_17;
        $statesres = $callConfig->getAllRows($statessql);
        $details['states'] = $statesres;

        $citiessql = self::USER_SQL_SELECT_ID_CITY_NAME_FROM_CITIE . $get['company_id'] . "' AND (state_id = '" . $vendor_registersres->billing_state . "' || state_id = '" . $vendor_registersres->shipping_state . self::USER_LIT_AND_IS_ACTIVE_0_17;
        $citiesres = $callConfig->getAllRows($citiessql);
        $details['cities'] = $citiesres;






        $query = "SELECT id,document_name,document_list_types  FROM `document_lists` WHERE company_id = '" . $get['company_id'] . "' and is_active =0 and category_id in (select id from document_categories where id='" . ST_VENDOR_REGISTRATION . "' and is_active ='0')";
        $components6 = $callConfig->getAllRows($query);
        foreach ($components6 as $cmp) {
            $document_lists[$cmp->id] = $cmp;
        }
        $details['document_lists'] = $document_lists;
        $query1 = "SELECT id,document_list_id,document_type  FROM `document_list_types` WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
        $components7 = $callConfig->getAllRows($query1);
        foreach ($components7 as $cmplist) {
            $document_list_types[$cmplist->document_list_id][] = $cmplist;
        }
        $details['document_list_types'] = $document_list_types;
