    public function getannouncements($get)
    {
        global $callConfig;
        $whrconfig = self::USER_LIT_IS_ACTIVE_0_AND_COMPANY_ID . $get['company_id'];
        $queryconfig = $callConfig->selectQuery('config', 'name,display_logo,location', $whrconfig, '', '', '');
