            $empdata = $callConfig->getRow($queryemp);
            $announceslist[$announcesvalue->id]['created_by_image'] = $empdata->image;
            $announceslist[$announcesvalue->id]['display_name'] = $empdata->display_name;
            $querysumm = self::USER_SQL_SELECT_SUM_IF_COMMENTS_1_0_AS_ . $get['company_id'] . self::USER_SQL_AND_ANNOUNCEMENT_ID . $announcesvalue->id;
            $announcessummary = $callConfig->getRow($querysumm);
            $announceslist[$announcesvalue->id]['totallikes'] = $announcessummary->totallikes == null ? '0' : $announcessummary->totallikes;
            $announceslist[$announcesvalue->id]['totaldislikes'] = $announcessummary->totaldislikes == null ? '0' : $announcessummary->totaldislikes;
            $announceslist[$announcesvalue->id]['totalcomments'] = $announcessummary->totalcomments == null ? '0' : $announcessummary->totalcomments;
            $querysumm = "SELECT count(id) as liked FROM summary_announcements WHERE is_active=0 and company_id=" . $get['company_id'] . self::USER_SQL_AND_ANNOUNCEMENT_ID . $announcesvalue->id . self::USER_SQL_AND_USERID . $get['userid'] . "' and msg_type='2' and like_type='1'";
            $announcessummary = $callConfig->getRow($querysumm);
            $announceslist[$announcesvalue->id]['highlight_like'] = $announcessummary->liked == 0 ? '0' : '1';
            $querysumm = "SELECT count(id) as disliked FROM summary_announcements WHERE is_active=0 and company_id=" . $get['company_id'] . self::USER_SQL_AND_ANNOUNCEMENT_ID . $announcesvalue->id . self::USER_SQL_AND_USERID . $get['userid'] . "' and msg_type='2' and like_type='2'";
            $announcessummary = $callConfig->getRow($querysumm);
            $announceslist[$announcesvalue->id]['highlight_dislike'] = $announcessummary->disliked == 0 ? '0' : '1';
            $querysumm = "SELECT count(id) as commented FROM summary_announcements WHERE is_active=0 and company_id=" . $get['company_id'] . self::USER_SQL_AND_ANNOUNCEMENT_ID . $announcesvalue->id . self::USER_SQL_AND_USERID . $get['userid'] . "' and msg_type='1' and like_type='0'";
            $announcessummary = $callConfig->getRow($querysumm);
            $announceslist[$announcesvalue->id]['highlight_comment'] = $announcessummary->commented == 0 ? '0' : '1';
            $querysumm = "SELECT like_type FROM summary_announcements WHERE is_active=0 and company_id=" . $get['company_id'] . self::USER_SQL_AND_ANNOUNCEMENT_ID . $announcesvalue->id . self::USER_SQL_AND_USERID . $get['userid'] . "' and msg_type='3' AND is_active = 0 ";
            $survey_result = $callConfig->getRow($querysumm);
            $announceslist[$announcesvalue->id]['survey_result'] = "0";
            if (count((array) $survey_result) > 0) {
                $announceslist[$announcesvalue->id]['survey_result'] = $survey_result->like_type;
            }

        }
        $details['announcements'] = $announceslist;
        $queryannounceshistory = self::USER_SQL_SELECT_FROM_COMPANY_ANNOUNCEME . $get['company_id'] . " and MONTH(expiry_date)=MONTH('" . date("Y-m-d") . "') order by start_date desc";
        $announceshistory = $callConfig->getAllRows($queryannounceshistory);
        foreach ($announceshistory as $announcesvalue) {
            $historyannouncesmonth[$announcesvalue->id] = (array) $announcesvalue;
            $querysumm = self::USER_SQL_SELECT_SUM_IF_COMMENTS_1_0_AS_ . $get['company_id'] . self::USER_SQL_AND_ANNOUNCEMENT_ID . $announcesvalue->id;
            $announcessummary = $callConfig->getRow($querysumm);
            $historyannouncesmonth[$announcesvalue->id]['totallikes'] = $announcessummary->totallikes == null ? '0' : $announcessummary->totallikes;
            $historyannouncesmonth[$announcesvalue->id]['totaldislikes'] = $announcessummary->totaldislikes == null ? '0' : $announcessummary->totaldislikes;
            $historyannouncesmonth[$announcesvalue->id]['totalcomments'] = $announcessummary->totalcomments == null ? '0' : $announcessummary->totalcomments;
        }
        $details['current_month_announcements'] = $historyannouncesmonth;
        $queryannounceshistory = self::USER_SQL_SELECT_FROM_COMPANY_ANNOUNCEME . $get['company_id'] . " and YEAR(expiry_date)=YEAR('" . date("Y-m-d") . "') order by start_date desc";
        $announceshistory = $callConfig->getAllRows($queryannounceshistory);
        foreach ($announceshistory as $announcesvalue) {
