    /* Dynamic employee Graphs Page Start */
    public function getheadcountreport($get)
    {
        global $callConfig;
        $year = $get['year'];
        $monthNo = $get['month'];
        $prev_year = $year - 1;
        $appendcondtion = '';
        $filterdata = urldecode($get['filterby']);
        $filters = json_decode($filterdata, 1);
        $curentyear_totalheadcount = 0;
        $prevyear_totalheadcount = 0;
        if ($filters != '') {
            $appendcondtion = self::USER_SQL_AND_1;
            foreach ($filters as $filterkey => $filtervalue) {
                $appendcondtion .= $filterkey . self::USER_LIT_IN;
                $appendcondtion .= implode(',', array_keys((array) $filtervalue));
                $appendcondtion .= self::USER_LIT_AND_2;
            }
            $appendcondtion = substr($appendcondtion, 0, -4);
        }
        for ($i = 1; $i <= 12; $i++) {
            $fdate = $prev_year . "-" . sprintf('%02s', $i) . "-01";
            $ldate = $prev_year . "-" . sprintf('%02s', $i) . "-31";
            $query = self::USER_SQL_SELECT_COUNT_ID_AS_HEADCOUNT_F . $ldate . self::USER_LIT_AS_DATE_OF_LEAVING_FROM_EMPLOY . $ldate . "' and td.date_of_leaving >='" . $fdate . "'";
            $empdatas = $callConfig->getRow($query);
            $query_emp = "SELECT id,display_name,designation_id,department_id,joining_date,employment_category_id,location_id  FROM `employees`  WHERE MONTH(joining_date)='" . $i . "' and YEAR(joining_date)='" . $prev_year . self::USER_LIT_AND_COMPANY_ID_1 . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2 . $appendcondtion;
            $emp_id_query = $callConfig->getAllRows($query_emp);
            foreach ($emp_id_query as $eidvalue) {
                $selected_employees[$eidvalue->id] = $eidvalue;
            }
            $prevyear_monthwise_headcount[$i] = $empdatas->headcount;
        }
        for ($i = 1; $i <= 12; $i++) {
            if ($i > $monthNo) {
                $curyear_monthwise_headcount[$i] = 0;
            } else {
                $fdate = $year . "-" . sprintf('%02s', $i) . "-01";
                $ldate = $year . "-" . sprintf('%02s', $i) . "-31";
                $query = self::USER_SQL_SELECT_COUNT_ID_AS_HEADCOUNT_F . $ldate . self::USER_LIT_AS_DATE_OF_LEAVING_FROM_EMPLOY . $ldate . "' and td.date_of_leaving >='" . $fdate . "'";
                $empdatas = $callConfig->getRow($query);
                $query_emp = "SELECT id,display_name,designation_id,department_id,joining_date,employment_category_id,location_id  FROM `employees` WHERE MONTH(joining_date)='" . $i . "' and YEAR(joining_date)='" . $year . self::USER_LIT_AND_COMPANY_ID_1 . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2 . $appendcondtion;
                $emp_id_query = $callConfig->getAllRows($query_emp);
                foreach ($emp_id_query as $eidvalue) {
                    $selected_employees[$eidvalue->id] = $eidvalue;
                }
                $curyear_monthwise_headcount[$i] = $empdatas->headcount;
            }
        }
