    public function updatebulktransferhistory($post, $get)
    {
        if (isset($get['company_id']) && empty($post['company_id'])) { $post['company_id'] = $get['company_id']; }
        global $callConfig;
        $fieldname = $post['update_fieldname'];
        $updatevalue = $post['update_fieldvalue'];
        $emplist = $post['transfer_list'];
        $update_previous_record = array('to_date' => date('Y-m-d', strtotime(self::USER_LIT_1_DAY_1, strtotime($post['effective_from']))), 'is_active' => '0', 'updated_by' => $post['created_by'], 'updated_date' => $post['created_date']);
        foreach ($emplist as $evalue) {
            $insertdata = array('company_id' => $post['company_id'], 'emp_id' => $evalue['emp_id'], 'previous_data' => $evalue['old_value'], 'new_data' => $updatevalue, 'application_fieldname' => $fieldname, 'from_date' => $post['effective_from'], 'to_date' => $post['effective_to'], 'created_by' => $post['created_by'], 'created_date' => $post['created_date']);

            $callConfig->updateRecord(TBL_TRANSFER_HISTORY_EMPLOYEES, $update_previous_record, 'id', $evalue['previous_record_rowid']);
            $res = $callConfig->insertRecord(TBL_TRANSFER_HISTORY_EMPLOYEES, $insertdata);
        }
        return $res;
    }

    public function updatebulktransferemployees($get)
    {
        global $callConfig;
        $display_data = self::USER_SQL_SELECT_FROM_1 . TBL_TRANSFER_HISTORY_EMPLOYEES . " where is_active is null and company_id='" . $get['company_id'] . "'";
        $empdata = $callConfig->getAllRows($display_data);
        foreach ($empdata as $avalue) {
            $fieldname = $avalue->application_fieldname;
            $updatevalue = $avalue->new_data;
            $callConfig->updateRecord(TBL_EMPLOYEES, array($fieldname => $updatevalue), 'id', $avalue->emp_id);
            $res = $callConfig->updateRecord(TBL_TRANSFER_HISTORY_EMPLOYEES, array('is_active' => '0'), 'id', $avalue->id);
        }
        return $res;
    }
