        foreach ($empdatas1 as $value1) {
            $query1 = "SELECT count(id) as headcount from (SELECT id,joining_date,display_name,designation_id,department_id,vendor_id,location_id,company_id, if(date_of_leaving!='0000-00-00',date_of_leaving,'" . $ldate . self::USER_LIT_AS_DATE_OF_LEAVING_FROM_EMPLOY . $ldate . "' and td.date_of_leaving >='" . $fdate . "' and td.vendor_id=" . $value1->id . self::USER_SQL_AND_TD_COMPANY_ID . $get['company_id'] . "'";
            $empresult = $callConfig->getRow($query1);
