        $fieldnames['effective_to_date'] = $post['effective_to_date'] !== "" ? date('Y-m-d', strtotime($post['effective_to_date'])) : "";
        if ($table == 'esgin_budget_approvals') {
            $fieldnames['po_date'] = $post['po_date'] != "" ? date('Y-m-d', strtotime(str_replace('/"', '-', $post['po_date']))) : "";
            $fieldnames['po_no'] = $post['po_no'];
        }
        if ($type == 'update') {
            $fieldnames['updated_date'] = $post['updated_date'];
            $fieldnames['updated_by'] = $post['updated_by'];
            $insert_data = $callConfig->updateRecord($table, $fieldnames, 'id', $post['hid']);
            $insert_id = $post['hid'];
        } else {
            $fieldnames['created_by'] = $post['created_by'];
            $fieldnames['created_date'] = $post['created_date'];
            $insert_data = $callConfig->insertRecord($table, $fieldnames);
            $insert_id = $insert_data['LASTID'];
        }
        $inum = 1;
        if ($insert_id > 0) {
            $update_query = self::USER_SQL_UPDATE . $fieldarray[$table]['item'] . " SET is_active = 1 WHERE transaction_id=" . $insert_id;
            $callConfig->executeQuery($update_query);
            $manreq = (object) array('job_title_id' => '');
            foreach ($post['productCode'] as $key => $item) {
                $where = self::USER_LIT_TRANSACTION_ID . $insert_id . self::USER_LIT_AND_ITEM_ID . $item . "' AND is_active = 1";
                $itemquery = $callConfig->selectQuery($fieldarray[$table]['item'], '*', $where, '', '', '');
                $iitem_data = $callConfig->getRow($itemquery);
                $query = "select * from job_titles where id=" . $manreq->job_title_id;
                $mainitem = $callConfig->getRow($query);
                $allow_overtime = $post['allow_overtime'][$inum] == 'on' ? '0' : '1';
                $experience_base = $post['experience_base'][$inum] == 'on' ? '0' : '1';
                if ($table == "vendor_rate_cards") {
                    $itemfieldnames = array('company_id' => $post['company_id'], 'transaction_id' => $insert_id, 'item_id' => $item, 'manpower_requisition_id' => $item, 'item_name' => $mainitem->job_title, 'description' => $post['productName'][$key], 'allow_overtime' => $allow_overtime, 'purchase_uom' => $post['uom'][$key], 'item_quantity' => $post['quantity'][$key], 'item_price' => $post['price'][$key], 'item_amount' => $post['amount'][$key], 'total_amount' => $post['amount'][$key], 'max_leave' => $post['min_leave'][$key], 'min_exp' => $post['min_exp'][$key], 'max_exp' => $post['max_exp'][$key], 'is_active' => '0', 'experience_base' => $experience_base);
                } else {
                    $effective_date = $post['effective_date'][$key] != "" ? date('Y-m-d', strtotime(str_replace('/"', '-', $post['effective_date'][$key]))) : "";
                    $expire_date = $post['expire_date'][$key] != "" ? date('Y-m-d', strtotime(str_replace('/"', '-', $post['expire_date'][$key]))) : "";
                    $itemfieldnames = array('company_id' => $post['company_id'], 'transaction_id' => $insert_id, 'item_id' => $item, 'manpower_requisition_id' => $item, 'item_name' => $mainitem->job_title, 'description' => $post['productName'][$key], 'allow_overtime' => $allow_overtime, 'ref_rate' => $post['ref_rate'][$key], 'purchase_uom' => $post['uom'][$key], 'item_quantity' => $post['quantity'][$key], 'item_price' => $post['price'][$key], 'item_amount' => $post['amount'][$key], 'total_amount' => $post['amount'][$key], 'effective_date' => $effective_date, 'expire_date' => $expire_date, 'billable' => $post['billable'][$key], 'is_active' => '0');
                    if ($table == "manpower_contracts") {
                        $itemfieldnames['min_exp'] = $post['min_exp'][$key];
                        $itemfieldnames['max_exp'] = $post['max_exp'][$key];
                    }
                }
                if ($post['table_name'] == 'milestone_contracts') {
                    $itemfieldnames['account_code'] = $item;
                }
                if ($iitem_data->id != "") {
                    $itemfieldnames['current_status'] = $post['current_status'];
                    $itemfieldnames['updated_date'] = $post['updated_date'];
                    $itemfieldnames['updated_by'] = $post['updated_by'];
                    $callConfig->updateRecord($fieldarray[$table]['item'], $itemfieldnames, 'id', $iitem_data->id);
                } else {
                    $itemfieldnames['current_status'] = $post['current_status'];
                    $itemfieldnames['created_by'] = $post['created_by'];
                    $itemfieldnames['created_date'] = $post['created_date'];
                    $callConfig->insertRecord($fieldarray[$table]['item'], $itemfieldnames);
                }
                $inum++;
            }
        }
        $attachmentarray = array('table_name' => $post['table_name'], 'transaction_number' => $post['transaction_number'], 'id' => $insert_id);
        $this->updatefillAttachments($attachmentarray);
        if ($post['table_name'] == 'esgin_budget_approvals' && $fieldnames['current_status'] == ST_APPROVED && $type != 'update') {
            $array = array('trn_id' => $insert_id, 'user_id' => $fieldnames['created_by'], 'company_id' => $fieldnames['company_id']);
            $this->updateesignconsumedata($array);
        }
        return $insert_data;
    }
