    public function saveperformanceresponse($post, $get)
    {
        if (isset($get['company_id']) && empty($post['company_id'])) { $post['company_id'] = $get['company_id']; }
        global $callConfig;
        $response_details = $post['response_detail_array'];

        $rowid = $post['response_array']['rowid'];
        unset($post['response_array']['rowid']);
        if ($rowid == "") {
            $callConfig->insertRecord(TBL_PERFORMANCE_RESPONSES, $post['response_array']);
        } else {
            $callConfig->updateRecord(TBL_PERFORMANCE_RESPONSES, $post['response_array'], 'id', $rowid);
        }
        for ($i = 0; $i < count((array) $response_details['performance_response_details']); $i++) {
            $response_row = $response_details['performance_response_details'][$i]['rowid'];
            unset($response_details['performance_response_details'][$i]['rowid']);
            if ($response_row == "") {
                unset($response_details['performance_response_details'][$i]['updated_by']);
                unset($response_details['performance_response_details'][$i]['updated_date']);
                $callConfig->insertRecord(TBL_PERFORMANCE_RESPONSE_DETAILS, $response_details['performance_response_details'][$i]);
            } else {
                unset($response_details['performance_response_details'][$i]['created_by']);
                unset($response_details['performance_response_details'][$i]['created_date']);
                unset($response_details['performance_response_details'][$i]['current_status']);
                $callConfig->updateRecord(TBL_PERFORMANCE_RESPONSE_DETAILS, $response_details['performance_response_details'][$i], 'id', $response_row);
            }
        }
    }


