        foreach ($empdatas5 as $value5) {
            $designation[$value5->id] = $value5->designation_name;
        }
        $details['designations'] = $designation;

        $options = self::USER_SQL_SELECT_FROM_1 . TBL_PERFORMANCE_RESPONSE_DETAILS . self::USER_SQL_WHERE_COMPANY_ID_2 . $get['company_id'] . "' and is_active='0' and assessment_id=" . $get['assessment_id'];
        $responsedata = $callConfig->getAllRows($options);
        foreach ($responsedata as $valueresp) {
            if ($valueresp->employee_id == $get['emp_id']) {
                $response_count = count((array) json_decode($valueresp->response_option, 1));
                if ($response_count == 1) {
                    $respdata = json_decode($valueresp->response_option, 1);
                    $valueresp->selected_option_index = 0;
                    $valueresp->selected_option_value = $respdata[0];
                } else {
                    $respdata = json_decode($valueresp->response_option, 1);
                    $valueresp->selected_option_index = $respdata[0];
                    $valueresp->selected_option_value = $respdata[1];
                }
                $empresponses[$valueresp->question_id] = $valueresp;
            }

            if ($valueresp->employee_id == $get['reports_to']) {
                $response_count = count((array) json_decode($valueresp->response_option, 1));
                if ($response_count == 1) {
                    $respdata = json_decode($valueresp->response_option, 1);
                    $valueresp->selected_option_index = 0;
                    $valueresp->selected_option_value = $respdata[0];
                } else {
                    $respdata = json_decode($valueresp->response_option, 1);
                    $valueresp->selected_option_index = $respdata[0];
                    $valueresp->selected_option_value = $respdata[1];
                }
                $mgrresponses[$valueresp->question_id] = $valueresp;
            }

            if ($valueresp->employee_id == $get['reviewer']) {
                $response_count = count((array) json_decode($valueresp->response_option, 1));
                if ($response_count == 1) {
                    $respdata = json_decode($valueresp->response_option, 1);
                    $valueresp->selected_option_index = 0;
                    $valueresp->selected_option_value = $respdata[0];
                } else {
                    $respdata = json_decode($valueresp->response_option, 1);
                    $valueresp->selected_option_index = $respdata[0];
                    $valueresp->selected_option_value = $respdata[1];
                }
                $reviewresponses[$valueresp->question_id] = $valueresp;
            }
        }

        $details['employee_responses'] = $empresponses;
        $details['manager_responses'] = $mgrresponses;
        $details['reviewer_responses'] = $reviewresponses;

        return $details;
    }

