    public function savepeerfeedbackquestions($post, $get)
    {
        if (isset($get['company_id']) && empty($post['company_id'])) { $post['company_id'] = $get['company_id']; }
        global $callConfig;
        for ($i = 0; $i < count((array) $post); $i++) {
            $qresponse = $callConfig->insertRecord(TBL_EMP_PERFORMANCE_PEER_FEEDBACK, $post[$i]);
        }
        return $qresponse;
    }


    public function getperformanceassessment($get)
    {
        global $callConfig;
        $month = $get['month'];
        $year = $get['year'];
        $assessment_date = $year . "-" . $month . "-01";
        $query = "SELECT id from performance_setup where assessment_start_date>='" . $assessment_date . "'";
        $assess = $callConfig->getRow($query);
        $assessment_id = $assess->id;
        $details['assessment_id'] = $assessment_id;

        $filterdata = urldecode($get['filterby']);
        $filters = json_decode($filterdata, 1);
        if ($filters != '') {
            $appendcondtion = self::USER_SQL_AND_1;
            foreach ($filters as $filterkey => $filtervalue) {
                $appendcondtion .= "emp." . $filterkey . self::USER_LIT_IN;
                $appendcondtion .= implode(',', array_keys((array) $filtervalue));
                $appendcondtion .= self::USER_LIT_AND_2;
            }
            $appendcondtion = substr($appendcondtion, 0, -4);
        }

        $query = "SELECT pr.* from performance_responses pr,employees emp where pr.assessment_id=" . $assessment_id . " and pr.employee_id=emp.id" . $appendcondtion;
        $assess_resp = $callConfig->getAllRows($query);
        foreach ($assess_resp as $resp) {
            $rating[$resp->employee_id] = $resp;
        }
        $details['rating'] = $rating;
        return $details;
    }


    public function employeedashboard($get)
    {
        global $callConfig;
        $thisyearfirstmonthlastdate = date('Y') . "-01-01";
        $thisyearfirstmonth = date('Y') . "-01";
        $endate = date('Y') . "-12-31";
        //new
        $today_date = date("Y-m-d");

        $thismonthstartdate = date("Y-m-d", strtotime('first day of this month', time()));
        $thismonthenddate = date("Y-m-d", strtotime('last day of this month', time()));

        $lastthree = date("Y-m-d", strtotime('-3 months', strtotime($today_date)));
        $joinquery = "SELECT id, emp_code, display_name, image, joining_date, user_id FROM employees WHERE company_id =" . $get['company_id'] . " AND joining_date <= '" . $today_date . "' AND joining_date >= '" . $lastthree . "'";
        $data['join_emp_data_query'] = $joinquery;
        $data['join_emp_data'] = $callConfig->getAllRows($joinquery);
        $resignquery = "SELECT emp.id, emp.emp_code, emp.display_name, emp.image, emp.joining_date, emp.user_id, emp.date_of_leaving, au.is_active FROM employees emp, application_users au WHERE emp.company_id = au.company_id AND emp.company_id =" . $get['company_id'] . " AND emp.user_id = au.id AND emp.date_of_leaving <= '" . $today_date . "' AND emp.date_of_leaving >= '" . $lastthree . "'";
        $data['resign_emp_data_query'] = $resignquery;
        $data['resign_emp_data'] = $callConfig->getAllRows($resignquery);





        $sql = "SELECT id, display_name, employee_type FROM `employees` emp WHERE company_id = '" . $get['company_id'] . "' AND is_active = 0 AND ( CASE WHEN ( emp.date_of_leaving IS NOT NULL AND emp.date_of_leaving >= '" . $endate . self::USER_LIT_THEN_1_WHEN_EMP_DATE_OF_LEAVIN . $get['admin_type'] . self::USER_LIT_OR_EMP_REPORTING_MANAGER_ID . $get['user_id'] . self::USER_LIT_OR_EMP_HR_BUDDY . $get['emp_id'] . self::USER_LIT_OR_EMP_FINANCE_BUDDY . $get['emp_id'] . self::USER_LIT_ELSE_EMP_VENDOR_ID_SELECT_ID_F . $get['user_email'] . "' ) ) END )";

        $empdatas = $callConfig->getAllRows($sql);
        $allemplist = array();
        $data['todayattendants']['total_emp'] = count((array) $empdatas);
        foreach ($empdatas as $empdatas1) {
            $data['todayattendants']['total_emp_ids'][$empdatas1->id] = $empdatas1->id;
            $allemplist[$empdatas1->id] = $empdatas1->id;
            if ($empdatas1->employee_type == '1') {
                $data['todayattendants']['regular_emp_ids'][$empdatas1->id] = $empdatas1->id;
            } elseif ($empdatas1->employee_type == '2') {
                $data['todayattendants']['contract_emp_ids'][$empdatas1->id] = $empdatas1->id;
            }

        }
        //Get Today Attendance Eployeees
        $attendancequery = "SELECT emp.id from employees emp, employee_daily_attendances eda WHERE emp.company_id = '" . $get['company_id'] . self::USER_LIT_AND_EMP_IS_ACTIVE_0_AND_CASE_W . $endate . self::USER_LIT_THEN_1_WHEN_EMP_DATE_OF_LEAVIN . $get['admin_type'] . self::USER_LIT_OR_EMP_REPORTING_MANAGER_ID . $get['user_id'] . self::USER_LIT_OR_EMP_HR_BUDDY . $get['emp_id'] . self::USER_LIT_OR_EMP_FINANCE_BUDDY . $get['emp_id'] . self::USER_LIT_ELSE_EMP_VENDOR_ID_SELECT_ID_F . $get['user_email'] . "' ) ) END ) AND eda.company_id = emp.company_id AND eda.employee_id = emp.id AND eda.attendace_date = '" . $today_date . "' AND eda.is_active = emp.is_active group by emp.id";
        $attendata = $callConfig->getAllRows($attendancequery);
        $data['todayattendants']['present'] = count((array) $attendata);
        foreach ($attendata as $empdatas2) {
            $data['todayattendants']['present_ids'][$empdatas2->id] = $empdatas2->id;
            unset($allemplist[$empdatas2->id]);
        }
        $data['totalpressent'] = count((array) $attendata);
        $data['todayattendants']['absent_ids'] = $allemplist;
        //Get Today Planed Leaves Eployeees
        $leaves = "SELECT emp.id FROM `employees` emp, employee_leaves el WHERE emp.company_id = '" . $get['company_id'] . self::USER_LIT_AND_EMP_IS_ACTIVE_0_AND_CASE_W . $endate . self::USER_LIT_THEN_1_WHEN_EMP_DATE_OF_LEAVIN . $get['admin_type'] . self::USER_LIT_OR_EMP_REPORTING_MANAGER_ID . $get['user_id'] . self::USER_LIT_OR_EMP_HR_BUDDY . $get['emp_id'] . self::USER_LIT_OR_EMP_FINANCE_BUDDY . $get['emp_id'] . "') )ELSE( emp.vendor_id = ( SELECT id FROM vendors ven2 WHERE ven2.email = '" . $get['user_email'] . "' ) ) END ) AND emp.company_id = el.company_id AND emp.id = el.employee_id AND (el.leave_from <= '" . $today_date . "' AND el.leave_to >= '" . $today_date . "') AND el.current_status = '" . ST_APPROVED . "' AND el.is_active = 0";

        $leavesdata = $callConfig->getAllRows($leaves);
        foreach ($leavesdata as $empdatas3) {
            $data['todayattendants']['planned_leave_ids'][$empdatas3->id] = $empdatas3->id;
        }
        $empcnt = count((array) $leavesdata) != "0" ? count((array) $leavesdata) : 0;
        $attendataempcnt = count((array) $attendata) != "0" ? count((array) $attendata) : 0;
        $data['todayattendants']['planned_leave'] = $empcnt;
        $data['todayattendants']['absent'] = count((array) $empdatas) - ($empcnt + $attendataempcnt);
        $data['totalabsent'] = count((array) $empdatas) - ($empcnt + $attendataempcnt);
        //Get regular,contact,male,female,manger_count,employees Count Eployeees
        $query = "SELECT SUM(if(emp.employee_type='1',1,0))as regular, SUM(if(emp.employee_type='2',1,0))as contact, COUNT(emp.id) as em_count FROM employees emp WHERE emp.company_id = '" . $get['company_id'] . self::USER_LIT_AND_EMP_IS_ACTIVE_0_AND_CASE_W . $endate . self::USER_LIT_THEN_1_WHEN_EMP_DATE_OF_LEAVIN . $get['admin_type'] . self::USER_LIT_OR_EMP_REPORTING_MANAGER_ID . $get['user_id'] . self::USER_LIT_OR_EMP_HR_BUDDY . $get['emp_id'] . self::USER_LIT_OR_EMP_FINANCE_BUDDY . $get['emp_id'] . self::USER_LIT_ELSE_EMP_VENDOR_ID_SELECT_ID_F . $get['user_email'] . "' ) ) END )";
        $nempdata = $callConfig->getRow($query);
        $data['nemp'] = $nempdata;

        //Get Joing Employees
        $mequery = "SELECT count(emp.id) as joinn FROM employees emp WHERE emp.company_id = '" . $get['company_id'] . "' AND ( CASE WHEN (emp.date_of_leaving IS NULL AND emp.is_active = 0 ) THEN 1 ELSE 2 END)= 1 AND ( CASE WHEN '3' <> '1' THEN ( ('1' = '" . $get['admin_type'] . self::USER_LIT_OR_EMP_REPORTING_MANAGER_ID . $get['user_id'] . "') OR (emp.hr_buddy) = '" . $get['emp_id'] . self::USER_LIT_OR_EMP_FINANCE_BUDDY . $get['emp_id'] . "') ELSE( emp.vendor_id = ( SELECT id FROM vendors ven2 WHERE ven2.email = '" . $get['user_email'] . "' ) ) END ) AND emp.joining_date >= '" . $thismonthstartdate . self::USER_LIT_AND_EMP_JOINING_DATE . $thismonthenddate . self::USER_LIT_AND_IS_ACTIVE_0_1;
        $medata = $callConfig->getRow($mequery);
        $data['joining'] = $medata->joinn;

        //Get leaving Employees
        $mequery = "SELECT count(emp.id) as realving FROM employees emp WHERE emp.date_of_leaving >= '" . $thismonthstartdate . self::USER_LIT_AND_EMP_DATE_OF_LEAVING . $thismonthenddate . "' AND emp.date_of_leaving IS NOT NULL AND emp.company_id = '" . $get['company_id'] . "' AND ( CASE WHEN '3' <> '1' THEN ( ('1' = '" . $get['admin_type'] . self::USER_LIT_OR_EMP_REPORTING_MANAGER_ID . $get['user_id'] . self::USER_LIT_OR_EMP_HR_BUDDY . $get['emp_id'] . self::USER_LIT_OR_EMP_FINANCE_BUDDY . $get['emp_id'] . self::USER_LIT_ELSE_EMP_VENDOR_ID_SELECT_ID_F . $get['user_email'] . "' ) ) END ) AND  is_active=0";
        $medata1 = $callConfig->getRow($mequery);
        $data['relive'] = $medata1->realving;

        $query = "SELECT SUM(if(emp.gender='M',1,0)) as male, SUM(if(emp.gender='F',1,0))as female, count(DISTINCT(emp.reporting_manager_id)) as manger_count, COUNT(emp.id) as em_count FROM employees emp WHERE emp.company_id = '" . $get['company_id'] . self::USER_LIT_AND_EMP_IS_ACTIVE_0_AND_CASE_W . $endate . self::USER_LIT_THEN_1_WHEN_EMP_DATE_OF_LEAVIN . $get['admin_type'] . self::USER_LIT_OR_EMP_REPORTING_MANAGER_ID . $get['user_id'] . self::USER_LIT_OR_EMP_HR_BUDDY . $get['emp_id'] . self::USER_LIT_OR_EMP_FINANCE_BUDDY . $get['emp_id'] . self::USER_LIT_ELSE_EMP_VENDOR_ID_SELECT_ID_F . $get['user_email'] . "' ) ) END) ";


        $nempdata = $callConfig->getRow($query);
        $data['daterangenemp'] = $nempdata;
        $sqqlgraph = "SELECT sum(m12) as j12,
         sum(m11) as j11,
         sum(m10) as j10,
         sum(m9) as j9,
         sum(m8) as j8,
         sum(m7) as j7,
         sum(m6) as j6,
         sum(m5) as j5,
         sum(m4) as j4,
         sum(m3) as j3,
         sum(m2) as j2,
         sum(m1) as j1,
         sum(lm12) as r12,
         sum(lm11) as r11,
         sum(lm10) as r10,
         sum(lm9) as r9,
         sum(lm8) as r8,
         sum(lm7) as r7,
         sum(lm6) as r6,
         sum(lm5) as r5,
         sum(lm4) as r4,
         sum(lm3) as r3,
         sum(lm2) as r2,
         sum(lm1) as r1
         FROM    (
         SELECT    DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 12 MONTH), '%Y-%m' )curdt,
         DATE_FORMAT(emp.joining_date, '%Y-%m')dojm,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 11 MONTH), '%Y-%m' )
         THEN 1
         END M12,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 10 MONTH), '%Y-%m' )
         THEN 1
         END M11,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 9 MONTH), '%Y-%m' )
         THEN 1
         END M10,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 8 MONTH), '%Y-%m' )
         THEN 1
         END M9,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 7 MONTH), '%Y-%m' )
         THEN 1
         END M8,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 6 MONTH), '%Y-%m' )
         THEN 1
         END M7,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 5 MONTH), '%Y-%m' )
         THEN 1
         END M6,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 4 MONTH), '%Y-%m' )
         THEN 1
         END M5,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 3 MONTH), '%Y-%m' )
         THEN 1
         END M4,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 2 MONTH), '%Y-%m' )
         THEN 1
         END M3,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 1 MONTH), '%Y-%m' )
         THEN 1
         END M2,
         CASE WHEN DATE_FORMAT(emp.joining_date, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 0 MONTH), '%Y-%m' )
         THEN 1
         END M1,
         DATE_FORMAT(emp.joining_date, '%Y-%m') monyr,
         DATE_FORMAT(emp.date_of_leaving, '%Y-%m')dolm,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 11 MONTH), '%Y-%m' )
         THEN 1
         END LM12,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 10 MONTH), '%Y-%m' )
         THEN 1
         END LM11,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 9 MONTH), '%Y-%m' )
         THEN 1
         END LM10,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 8 MONTH), '%Y-%m' )
         THEN 1
         END LM9,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 7 MONTH), '%Y-%m' )
         THEN 1
         END LM8,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 6 MONTH), '%Y-%m' )
         THEN 1
         END LM7,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 5 MONTH), '%Y-%m' )
         THEN 1
         END LM6,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 4 MONTH), '%Y-%m' )
         THEN 1
         END LM5,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 3 MONTH), '%Y-%m' )
         THEN 1
         END LM4,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 2 MONTH), '%Y-%m' )
         THEN 1
         END LM3,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 1 MONTH), '%Y-%m' )
         THEN 1
         END LM2,
         CASE WHEN DATE_FORMAT(emp.date_of_leaving, '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 0 MONTH), '%Y-%m' )
         THEN 1
         END LM1,
         DATE_FORMAT(emp.date_of_leaving, '%Y-%m') lmonyrl
         FROM     employees emp
         WHERE    emp.company_id = 1
         AND       (
         (emp.joining_date >= '" . $thisyearfirstmonthlastdate . self::USER_LIT_AND_EMP_JOINING_DATE . $endate . "')
         OR (emp.date_of_leaving >= '" . $thisyearfirstmonthlastdate . self::USER_LIT_AND_EMP_DATE_OF_LEAVING . $endate . "')
         )
         AND emp.is_active = 0 AND ( CASE WHEN '3' <> '1' THEN ( ('1' = '" . $get['admin_type'] . self::USER_LIT_OR_EMP_REPORTING_MANAGER_ID . $get['user_id'] . self::USER_LIT_OR_EMP_HR_BUDDY . $get['emp_id'] . self::USER_LIT_OR_EMP_FINANCE_BUDDY . $get['emp_id'] . "') ) ELSE( emp.vendor_id = (SELECT id FROM vendors ven2 WHERE ven2.email = '" . $get['user_email'] . "'))END))a";

        $sqqlgraphres = $callConfig->getRow($sqqlgraph);
        $data['graphjoinandleave'] = $sqqlgraphres;
        $salarygraph = "SELECT sum(m12) as j12, sum(m11) as j11, sum(m10) as j10, sum(m9) as j9, sum(m8) as j8, sum(m7) as j7, sum(m6) as j6, sum(m5) as j5, sum(m4) as j4, sum(m3) as j3, sum(m2) as j2, sum(m1) as j1 FROM ( SELECT DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 12 MONTH), '%Y-%m' )curdt, DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m')dojm, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 11 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M12, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 10 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M11, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 9 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M10, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 8 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M9, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 7 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M8, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 6 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M7, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 5 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M6, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 4 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M5, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 3 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M4, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 2 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M3, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 1 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M2, CASE WHEN DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') = DATE_FORMAT( ('" . $thisyearfirstmonthlastdate . "' - INTERVAL 0 MONTH), '%Y-%m' ) THEN prsc.salary_component_actual END M1, DATE_FORMAT(emp.joining_date, '%Y-%m') monyr FROM employees emp, pay_run_summary prs, pay_run_summary_components prsc WHERE emp.company_id = 1 AND emp.id = prs.employee_id AND emp.company_id = prs.company_id AND prsc.company_id = prs.company_id AND prsc.pay_run_summary_id = prs.id AND prsc.employee_id = emp.id AND prsc.component_id = 1 AND (( DATE_FORMAT(CONCAT(prs.pay_year, '-', prs.pay_month, '-','01'), '%Y-%m') >= '" . $thisyearfirstmonth . "') AND ( DATE_FORMAT(CONCAT(prs.pay_year, '-',prs.pay_month, '-','01'), '%Y-%m') <= '" . $thisyearfirstmonth . "')) AND prsc.is_active = 0 AND ( CASE WHEN '3' <> '1' THEN ( ('1' = '" . $get['admin_type'] . self::USER_LIT_OR_EMP_REPORTING_MANAGER_ID . $get['user_id'] . self::USER_LIT_OR_EMP_HR_BUDDY . $get['emp_id'] . self::USER_LIT_OR_EMP_FINANCE_BUDDY . $get['emp_id'] . "') )ELSE ( emp.vendor_id = ( SELECT id FROM vendors ven2 WHERE ven2.email = '" . $get['user_email'] . "' ) ) END ) ) a";
        $salarygraphres = $callConfig->getRow($salarygraph);

        $data['salarygraphres'] = $salarygraphres;
        return $data;
    }


    public function togetVendorAgreementexpirelist($get)
    {
        if (isset($get)) { /* noop */ }
        global $callConfig;
        $query = "SELECT ven.`company_id`, ven.`id`, ven.image, ven.display_name, venag.`agreement_name`, venag.`agreement_ref_no`, venag.`signed_date`, venag.`expiry_date`, venag.`file_url`, DATEDIFF(venag.`expiry_date`, NOW()) as diff_days FROM vendors ven, vendor_agreements venag WHERE ven.id = venag.vendor_id AND ven.company_id = venag.company_id AND ven.company_id = 1 AND ven.is_active = '0' AND venag.`expiry_date` < (NOW() + INTERVAL 120 day)";
        $exdata = $callConfig->getAllRows($query);
        foreach ($exdata as $ex) {
            if ($ex->diff_days > 0 && $ex->diff_days < 8) {
                $return['week'][] = $ex;
            }
            if ($ex->diff_days > 0 && $ex->diff_days < 31) {
                $return['month'][] = $ex;
            }
            if ($ex->diff_days > 0 && $ex->diff_days < 120) {
                $return['qtr'][] = $ex;
            }
        }
        return $return;
    }
    public function getemprequests($get)
    {
        global $callConfig;
        $sql = "select * from food_options where company_id='" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_5;
        $foodoptions = $callConfig->getAllRows($sql);
        $sql = self::USER_SQL_SELECT_FROM_LOCATIONS_WHERE_CO . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_5;
        $location = $callConfig->getAllRows($sql);

        $datecondition = "AND (efo.stop_date is null or (current_date() between efo.start_date and efo.stop_date))";
        if ($get['fromdate'] != '' || $get['todate']) {
            $datecondition = "AND (efo.stop_date<='" . $get['todate'] . "') and efo.start_date >='" . $get['fromdate'] . "'";
        }
        $queryresponse = "SELECT efo.location_id as location_id,
         efo.emp_id,
         emp.display_name,
         efo.food_options option_value,
         fo.food_option option_name
         FROM     employees emp, employee_food_requests efo, food_options fo
         WHERE     emp.id = efo.emp_id
         AND        emp.company_id = efo.company_id
         AND        emp.is_active = 0
         AND        efo.is_active = 0
         AND        fo.company_id = emp.company_id
         AND        fo.id = efo.food_options
         AND        fo.is_active = 0
         " . $datecondition . " order by 1, 2";
        $allresponse = $callConfig->getAllRows($queryresponse);

        foreach ($allresponse as $data) {
            foreach ($foodoptions as $foodtype) {
                $foodoptiondata[$foodtype->id] = $foodtype->food_option;
                if ($foodtype->id == $data->option_value) {
                    $food_option_array[$foodtype->id][] = $data;
                    foreach ($location as $loc) {
                        if ($loc->id == $data->location_id) {
                            $loc_food_option[$foodtype->id][$loc->id][$data->emp_id] = $data;
                        }
                    }
                }
            }

        }
        $details['summary'] = $food_option_array;
        $details['foodoptiondata'] = $foodoptiondata;
        $details['locfooddata'] = $loc_food_option;

        $transport_datecondition = "AND (current_date() <= efo.created_date)";
        if ($get['fromdate'] != '' || $get['todate']) {
            $transport_datecondition = "AND (efo.created_date between '" . $get['fromdate'] . self::USER_LIT_AND . $get['todate'] . "')";
        }

        $queryresponse = "SELECT efo.location_id as location_id,
         efo.employee_id,emp.display_name FROM employees emp, employee_transport_requests efo
         WHERE     emp.id = efo.employee_id
         AND        emp.company_id = efo.company_id
         AND        emp.is_active = 0
         AND        efo.is_active = 0
         " . $transport_datecondition . " order by 1, 2";
        $allresponse = $callConfig->getAllRows($queryresponse);
        foreach ($allresponse as $data) {
            $total_transport_req[] = $data;
            foreach ($location as $loc) {
                if ($loc->id == $data->location_id) {
                    $transport_option[$loc->id][$data->employee_id] = $data;
                }
            }
        }

        $details['transport'] = $transport_option;
        $details['transport_req'] = count((array) $total_transport_req) == '' ? '0' : count((array) $total_transport_req);
        return $details;
    }


    public function getempreport($get)
    {
        global $callConfig;
        $filterdata = urldecode($get['filterby']);
        $filters = json_decode($filterdata, 1);
        if ($filters != '') {
            $appendcondtion = self::USER_SQL_AND_1;
            foreach ($filters as $filterkey => $filtervalue) {
                $appendcondtion .= $filterkey . self::USER_LIT_IN;
                $appendcondtion .= implode(',', array_keys((array) $filtervalue));
                $appendcondtion .= self::USER_LIT_AND_2;
            }
            $appendcondtion = substr($appendcondtion, 0, -4);
        }

        if ($get['empidlist'] != '') {
            $empids = json_decode($get['empidlist'], 1);
            $emplistfilter = implode(',', (array) $empids);
            $appendcondtion .= ' and id in (' . $emplistfilter . ')';
        }

        $query = "SELECT * from employees where company_id=" . $get['company_id'] . self::USER_SQL_AND_IS_ACTIVE_0_8 . $appendcondtion;
        $empdata = $callConfig->getAllRows($query);
        foreach ($empdata as $emp) {
            $empdetails[$emp->id] = $emp;
        }
        $details['emp_data'] = $empdetails;
        return $details;

    }


    // Priya lastest
    public function getjobpostingsreport($get)
    {
        global $callConfig;
        $jobstypes = array('0' => 'Open', '2' => 'In-Progress', '1' => 'Close', '3' => 'Total');
        $sql = "select * from vendors where company_id='" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_5;
        $vendors = $callConfig->getAllRows($sql);

        $datecondition = "AND (current_date() >= jp.requested_date)";
        if ($get['fromdate'] != '' || $get['todate']) {
            $datecondition = "AND jp.requested_date between '" . $get['fromdate'] . self::USER_LIT_AND . $get['todate'] . "'";
        }
        $queryresponse = "SELECT jpd.vendor_id, jp.current_status, jp.job_status, COUNT(jp.id) as totalcount FROM job_posting_distribute jpd, job_postings jp, job_posting_candidates jpc WHERE jp.id = jpd.job_posting_id AND jp.company_id = jpd.company_id AND jp.is_active = '0' AND jpd.is_active = '0' " . $datecondition . " AND jpc.job_posting_id = jp.id AND jpc.company_id = jp.company_id AND jpc.is_active = '0' GROUP BY jpd.vendor_id, jp.current_status,jp.job_status";
        $allresponse = $callConfig->getAllRows($queryresponse);
        $total = 0;
        foreach ($jobstypes as $jobkey => $jobtype) {
            $job_type_total = 0;
            foreach ($allresponse as $data) {
                if ($data->job_status == $jobkey) {
                    $job_type_total += $data->totalcount;
                    $total += $data->totalcount;
                }
            }
            $job_type_array[$jobkey] = $job_type_total;
        }
        $job_type_array[3] = $total;
        foreach ($allresponse as $data) {
            foreach ($jobstypes as $jobkey => $jobtype) {
                foreach ($vendors as $ven) {
                    if ($ven->id == $data->vendor_id && $jobkey == $data->job_status) {
                        $vendor_jobs[$ven->id][$jobkey] = $data->totalcount;
                    }
                }

            }
        }
        foreach ($vendor_jobs as $vid => $vjobs) {
            $totalj = 0;
            foreach ($vjobs as $jobcount) {
                $totalj += $jobcount;
            }
            $vendor_jobs[$vid][3] = $totalj;
        }
        $details['summary'] = $job_type_array;
        $details['job_type_data'] = $jobstypes;
        $details['vendor_jobs'] = $vendor_jobs;
        return $details;
    }

    public function insertseriallot($post, $get)
    {
        global $callConfig;
        echo "ravi";
        print_r($post);
        if ($post['type'] == 1) {
            if ($post['tranid'] != "" && $post['tranid'] != 0) {
                $query = "UPDATE item_serial_nos SET is_active='1' WHERE transaction_id =" . $post['tranid'] . " AND transaction_table='" . $post['table'] . self::USER_LIT_AND_ITEM_ID_3 . $post['item_id'];
                $callConfig->executeQuery($query);
            } else {
                $random = $post['random'];
            }
            for ($i = 1; $i < $post['count'] + 1; $i++) {
                $serial = 'serial_' . $i;
                $notdataa = array('company_id' => $get['company_id'], 'transaction_id' => $post['tranid'], 'transaction_table' => $post['table'], 'random_no' => $random, 'item_id' => $post['item_id'], 'serial_no' => $post[$serial], 'is_active' => '0', 'current_status' => 0, 'created_by' => $get['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
                $insert[] = $callConfig->insertRecord('item_serial_nos', $notdataa);
            }
        }
        if ($post['type'] == 2) {
            if ($post['tranid'] != "" && $post['tranid'] != 0) {
                $query = "UPDATE item_lot_nos SET is_active='1' WHERE transaction_id =" . $post['tranid'] . " AND transaction_table='" . $post['table'] . self::USER_LIT_AND_ITEM_ID_3 . $post['item_id'];
                $callConfig->executeQuery($query);
            } else {
                $random = $post['random'];
            }
            for ($i = 1; $i < $post['count'] + 1; $i++) {
                $lot = 'lot_' . $i;
                $lotvalue = 'lotvalue_' . $i;
                $notdataa = array('company_id' => $get['company_id'], 'transaction_id' => $post['tranid'], 'transaction_table' => $post['table'], 'random_no' => $random, 'item_id' => $post['item_id'], 'lot_no' => $post[$lot], 'lot_quantity' => $post[$lotvalue], 'is_active' => '0', 'current_status' => 0, 'created_by' => $get['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
                $insert[] = $callConfig->insertRecord('item_lot_nos', $notdataa);
            }
        }
        return array('query' => $notdataa, 'res' => $insert);
    }
}

