    public function togetmyreporserach($post, $get)
    {
        if (isset($get['company_id']) && empty($post['company_id'])) { $post['company_id'] = $get['company_id']; }
        global $callConfig;
        $data = $post;
        $filt = json_decode(urldecode($post['lists']), 1);
        $notarry = array('table', 'report_id', 'lists', 'submit');
        foreach ($post as $field => $pos) {
            if (!in_array($field, (array) $notarry) && $data[$field] != "") {
                if ($filt[$field] == 'text') {
                    $str[] = $field . "  LIKE '%" . $data[$field] . "%'";
                }
                if ($filt[$field] == 'select') {
                    $str[] = $field . "  = '" . $data[$field] . "'";
                }
                if ($filt[$field] == 'date_pick') {
                    $str[] = $field . "  < '" . date("Y-m-d", strtotime($data[$field])) . "'";
                }
            }
        }
        $strs = '';
        if (count((array) $str) > 0) {
            $strs = self::USER_SQL_WHERE . implode(self::USER_SQL_AND, (array) $str);
        }
        $cus_query = self::USER_SQL_SELECT_FROM . $post['table'] . " " . $strs;
        return $callConfig->getAllRows($cus_query);
    }
