    public function exitprocesssteps($data)
    {
        global $callConfig;
        $offer_post = array('reporting_date' => '');
        $whr1 = "is_active = 0 AND  trn_id='" . $data['trn_id'] . "'";
        $cd_query = $callConfig->selectQuery('employee_terminations', '*', $whr1, '', '', '');
        $estdata = $callConfig->getRow($cd_query);

        $whr1 = "is_active = 0 AND  process_type='E'";
        $task_query = $callConfig->selectQuery('process_task_settings', '*', $whr1, '', '', '');
        $task_data = $callConfig->getAllRows($task_query);
        if ($task_data->no_action != 1) {
            foreach ($task_data as $tasks) {
                $days_ago = $estdata['employee_leaving_date'];
                if ($task_data->on_the_day != 1) {
                    if ($tasks->action_frequency == 'DY') {
                        $day = $tasks->on_the_day;
                    }
                    if ($tasks->action_frequency == 'WK') {
                        $day = 7;
                    }
                    if ($tasks->action_frequency == 'MON') {
                        $day = 30;
                    }
                    if ($tasks->before_or_after == 'BF') {
                        $day = "-" . $day;
                    } else {
                        $day = "+" . $day;
                    }
                    $days_ago = date('Y-m-d', strtotime($day . self::USER_LIT_DAYS, strtotime($offer_post['reporting_date'])));
                }

                if ($tasks->assigned_to == 'HB') {
                    /* unused */
                }
                if ($tasks->assigned_to == 'AB') {
                    /* unused */
                }
                if ($tasks->assigned_to == 'FB') {
                    /* unused */
                }
                if ($tasks->assigned_to == 'PB') {
                    /* unused */
                }
                if ($tasks->assigned_to == 'OB') {
                    $asssdata = $estdata;
                } else {
                    $asssdata = $callConfig->getRow($cd_query);
                }
                $event_array = array('company_id' => $data['company_id'], 'event_category_id' => '4', 'user_id' => $asssdata->user_id, 'event_name' => $tasks->task_name, 'event_short_name' => $tasks->task_short_name, 'event_description' => $tasks->description, 'start_date' => $days_ago, 'is_active' => '0', 'current_status' => '0', 'created_by' => $data['user_id']);
                $callConfig->insertRecord('employee_events', $event_array);

                $notiarray = array('notification_message' => 'Schedule Event ' . $tasks->task_name, 'notification_users' => array('0' => $estdata->user_id), 'id' => $data['trn_id'], 'application_table_name' => 'employee_terminations', 'company_id' => $data['company_id'], 'option' => 'COM_INSERT_EMPLOYEE_TERMINATIONS', 'notification_datetime' => $days_ago, 'notification_users' => array($asssdata->user_id));
                $this->tosendnotifiations($notiarray);
            }
        }
    }
