    public function createjobfeedback($post, $get)
    {
        global $callConfig;
        $rowid = $get['rowid'];
        $table_setup = $get['table_setup'];
        $table_questions = $get['table_questions'];
        $table_options = $get['table_options'];
        $main = $post['main'];
        $quesion_data = $post['qustion'];
        if ($rowid == "") {
            $array = array('company_id' => $main['company_id'], 'is_active' => '0', 'created_by' => $main['created_by'], 'created_date' => $main['created_date']);
            $res = $callConfig->insertRecord($table_setup, $main);
            $s_id = $res['LASTID'];
            foreach ($quesion_data as $value) {
                $value['job_feedback_setup_id'] = $s_id;
                $survey_question_option['feedback_question_option'] = $value['feedback_question_option'];
                $survey_question_option['job_feedback_setup_id'] = $s_id;
                unset($value['feedback_question_option']);
                $quesion_array = array_merge((array) $value, (array) $array);
                $qres = $callConfig->insertRecord($table_questions, $quesion_array);
                $survey_question_option['question_id'] = $qres['LASTID'];
                $answer_array = array_merge((array) $survey_question_option, (array) $array);
                $callConfig->insertRecord($table_options, $answer_array);
            }
            $retunn_survey_id = $s_id;
        } else {
            $array = array('company_id' => $main['company_id'], 'is_active' => '0', 'updated_by' => $main['updated_by'], 'updated_date' => $main['updated_date']);
            $callConfig->updateRecord($table_setup, $main, 'id', $rowid);
            // two update querys - qustiontable and option table is_aactive=1
            $s_id = $rowid;
            foreach ($quesion_data as $value) {
                $value['job_feedback_setup_id'] = $s_id;
                $question_id = $value['question_id'];
                $survey_question_option['feedback_question_option'] = $value['feedback_question_option'];
                $survey_question_option['job_feedback_setup_id'] = $s_id;

                unset($value['feedback_question_option']);
                unset($value['question_id']);
                unset($value['rid']);
                $quesion_array = array_merge((array) $value, (array) $array);
                if ($question_id != '') {
                    $callConfig->updateRecord($table_questions, $quesion_array, 'id', $question_id);
                    $answer_array = array_merge((array) $survey_question_option, (array) $array);
                    $callConfig->updateRecord($table_options, $answer_array, 'question_id', $question_id);
                } else {
                    $qres = $callConfig->insertRecord($table_questions, $quesion_array);
                    $survey_question_option['question_id'] = $qres['LASTID'];
                    $answer_array = array_merge((array) $survey_question_option, (array) $array);
                    $callConfig->insertRecord($table_options, $answer_array);
                }
            }
            $retunn_survey_id = $rowid;
        }
        return $retunn_survey_id;
    }
    public function getcandidatefeedbackresult($get)
    {

        global $callConfig;
        $whr2 = self::USER_LIT_COMPANY_ID . $get['company_id'] . " and is_active='0' and genc_code='SURVEY_QTYPE'";
        $query = $callConfig->selectQuery('general_code_details', 'genc_detail_code,genc_detail_name', $whr2, '', '', '');
        $deta['qustion_types'] = $callConfig->getAllRows($query);

        $query = "SELECT jfs.id, jfs.job_title_id, jfs.name, jfs.description, jpc.job_posting_id FROM job_feedback_setup jfs, job_posting_candidates jpc, job_postings jp WHERE jfs.company_id = " . $get['company_id'] . " AND jfs.company_id = jpc.company_id AND jfs.company_id = jp.company_id AND jpc.id = '" . $get['job_candidate_id'] . "' AND jpc.job_posting_id = jp.id AND jp.job_code= jfs.job_title_id AND jfs.is_active = jpc.is_active AND jfs.is_active = jp.is_active AND jfs.is_active = 0";
        $details = $callConfig->getAllRows($query);
        foreach ($details as $detail) {
            $detail_id = $detail->id;
            $whr = self::USER_LIT_COMPANY_ID . $get['company_id'] . " and is_active='0' and job_feedback_setup_id=" . $detail_id;
            $query = $callConfig->selectQuery('job_feedback_questions', '*', $whr, '', '', '');
            $survey_qustion_details = $callConfig->getAllRows($query);
            $disp_question = array();
            foreach ($survey_qustion_details as $value) {
                $whr = self::USER_LIT_COMPANY_ID . $get['company_id'] . " and is_active='0' and job_feedback_setup_id=" . $detail_id . self::USER_SQL_AND_QUESTION_ID . $value->id;
                $query_ans = $callConfig->selectQuery('job_feedback_question_options', '*', $whr, '', '', '');
                $survey_answer_details = $callConfig->getRow($query_ans);
                $disp_question[$value->id]['survey_question'] = $value->feedback_question;
                $disp_question[$value->id]['job_feedback_setup_id'] = $value->job_feedback_setup_id;
                $disp_question[$value->id]['options_display_type'] = $value->options_display_type;
                $disp_question[$value->id]['require_response'] = $value->require_response;
                $disp_question[$value->id]['allow_multiple_selections'] = $value->allow_multiple_selections;
                $disp_question[$value->id]['survey_question_option'] = $survey_answer_details->feedback_question_option;
            }
            $question[$detail_id] = $disp_question;
        }

        $query = "SELECT * FROM `job_feedback_responses_details` WHERE job_feedback_response_id IN ( SELECT id FROM `job_feedback_responses` WHERE `job_candidate_id`=" . $get['job_candidate_id'] . " AND `job_selection_process_step_id`=" . $get['job_selection_process_step_id'] . " AND is_active =0) And is_active=0";
        $respon = $callConfig->getAllRows($query);
        $deta['survey_details'] = $details;
        $deta['question'] = $question;
        $deta['response'] = $respon;
        return $deta;
    }

    public function getListJobPostingsList($data)
    {
        global $callConfig;
        $return = array();
        $condition = "";
        if ($data['start_date'] != "" && $data['end_date'] != "") {
            $condition .= " AND jp.requested_date >='" . $data['start_date'] . "' and jp.requested_date <='" . $data['end_date'] . "'";
        } else {
            $condition .= " AND jp.requested_date >='" . date('Y-m-d', strtotime('first day of this month')) . "' and jp.requested_date <='" . date('Y-m-d', strtotime('last day of this month')) . "'";
        }
        if ($data['department'] != "") {
            $condition .= " AND jp.department_id ='" . $data['department'] . "'";
        }
        if ($data['location'] != "") {
            $condition .= " AND jp.location_id ='" . $data['location'] . "'";

        }
        $sql = "SELECT *, jp.id as jpid FROM `job_postings` jp LEFT JOIN job_titles jt on jp.job_code = jt.id where jp.is_active = '0' AND jp.company_id = '" . $data['company_id'] . "' " . $condition;
        $datas = $callConfig->getAllRows($sql);
        $notshortlistcnt = 0;
        $totalcandidet = 0;
        foreach ($datas as $list) {
            $sql1 = "SELECT count(id) as cnt FROM `job_posting_candidates` WHERE is_active = '0' and company_id = '" . $data['company_id'] . self::USER_LIT_AND_JOB_POSTING_ID . $list->jpid;
            $row = $callConfig->getRow($sql1);
            $sql33 = self::USER_SQL_SELECT_COUNT_ID_AS_CNT_FROM_JO . $data['company_id'] . self::USER_LIT_AND_JOB_POSTING_ID . $list->jpid . " and shortlisted = '0'";
            $shortlisted = $callConfig->getRow($sql33);
            $sql45 = self::USER_SQL_SELECT_COUNT_ID_AS_CNT_FROM_JO . $data['company_id'] . self::USER_LIT_AND_JOB_POSTING_ID . $list->jpid . " and current_status in('58','59') and shortlisted = '0'";
            $offerrelised = $callConfig->getRow($sql45);
            $sql45 = self::USER_SQL_SELECT_COUNT_ID_AS_CNT_FROM_JO . $data['company_id'] . self::USER_LIT_AND_JOB_POSTING_ID . $list->jpid . " and current_status = '59' and shortlisted = '0'";
            $offeraccept = $callConfig->getRow($sql45);
            $in_porccess_array = array();
            $sql55 = "SELECT * FROM `job_posting_candidates` WHERE is_active = '0' and company_id = '" . $data['company_id'] . self::USER_LIT_AND_JOB_POSTING_ID . $list->jpid . " AND shortlisted = '0' AND current_status NOT IN('58','59')";
            $rowss = $callConfig->getAllRows($sql55);
            foreach ($rowss as $value) {
                $sql88 = "SELECT jsps.select_name, count(jc.id) as cnt FROM job_posting_candidates jc left JOIN `job_selection_process_steps` jsps on jc.job_selection_process_step_id = jsps.id WHERE jsps.id ='" . $value->job_selection_process_step_id . "' and jc.shortlisted =0 and jc.job_posting_id ='" . $list->jpid . "'";
                $row88 = $callConfig->getRow($sql88);
                $in_porccess_array[] = array("name" => $row88->select_name, 'cnt' => $row88->cnt);
            }
            $totalcandidet = $totalcandidet + $row->cnt;
            $return['list'][] = array(
                'id' => $list->jpid,
                'title' => $list->job_title,
                'requested_date' => $list->requested_date,
                'job_desc' => $list->job_desc
                ,
                'total_candidate' => $row->cnt,
                'shortlistcnt' => $shortlisted->cnt,
                'notshortlistcnt' => $notshortlistcnt,
                'offeraccepted' => $offeraccept->cnt,
                'offerrelesed' => $offerrelised->cnt,
                'in_preccess' => count((array) $rowss),
                'in_procees_list' => $in_porccess_array
            );
        }
        $return['totaljob'] = count((array) $datas);
        $return['totalcndided'] = $totalcandidet;
        return $return;
    }
