        $cntcnadidatestotal = $callConfig->getRow($sql253)->cnt;
        $sql33 = self::USER_SQL_SELECT_COUNT_ID_AS_CNT_FROM_JO . $data['company_id'] . self::USER_LIT_AND_JOB_POSTING_ID_1 . $data['id'] . " and shortlisted = '0'";
        $shortlisted = $callConfig->getRow($sql33);
        $sql45 = self::USER_SQL_SELECT_COUNT_ID_AS_CNT_FROM_JO . $data['company_id'] . self::USER_LIT_AND_JOB_POSTING_ID_1 . $data['id'] . " and current_status = '59' and shortlisted = '0'";
        $aprovecnt = $callConfig->getRow($sql45);
        $sql2 = "SELECT * FROM `job_selection_process_steps` WHERE process_id = '" . $datas->job_selection_process . "' and is_active = '0' ORDER BY `selection_seq` DESC";
        $processlists = $callConfig->getAllRows($sql2);
        $totalcandidateshortliststatus = 0;
        foreach ($processlists as $processlist) {
            $sql1 = self::USER_SQL_SELECT_COUNT_ID_AS_CNT_FROM_JO . $data['company_id'] . self::USER_LIT_AND_JOB_POSTING_ID_1 . $data['id'] . " and shortlisted = '0' AND job_selection_process_step_id = " . $processlist->id;
            $cntcandidate = $callConfig->getRow($sql1);
            $totalcandidateshortliststatus = $totalcandidateshortliststatus + $cntcandidate->cnt;
            $return['list'][] = array('id' => $processlist->id, 'name' => $processlist->select_name, 'cnt' => $totalcandidateshortliststatus);
        }
        $return[cntcandidate] = $cntcnadidatestotal;
        $return[aprovecnt] = $aprovecnt->cnt;
        $return[title] = $datas->job_title;
        $return[shortlisted] = $shortlisted->cnt;
        return $return;
    }
