            $item_categoriesres = $callConfig->getAllRows($item_categoriessql);
            $return['item_categories'] = $item_categoriesres;

            $transactiontypesql = "SELECT genc_detail_name, genc_detail_code FROM general_code_details WHERE genc_code = 'TRANSACTIONTYPEself::USER_SQL_AND_COMPANY_ID" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
