trait UserPurchasingAndVendorsTrait
{

    public function getRiviewsData($data)
    {
        global $callConfig;
        $pendingapprove = array();
        $approve = array();
        $sendarray = $data;
        $sql = "SELECT tal.id,tal.transaction_table,tal.transaction_id,tal.request_date,tal.response_type,tal.response_date,tal.workflow_id  FROM transaction_approval_logs tal WHERE tal.company_id = '" . $data['company_id'] . "'  AND tal.user_id = '" . $data['user_id'] . "'";
        $reviewdata = $callConfig->getAllRows($sql);
        $workflowid = array();
        $logtableandid = array();
        $logtabledetails = array();
        $statusres = array();
        foreach ($reviewdata as $reviewda) {  // only store table name and id
            $logtableandid[$reviewda->transaction_table][] = $reviewda->transaction_id;
        }

        foreach ($logtableandid as $tablename => $logtableandidres) {  // only store table name and id
            $idlist = implode(",", (array) $logtableandidres);

            $sqldyntable = self::USER_SQL_SELECT_FROM . $tablename . self::USER_SQL_WHERE_COMPANY_ID . $data['company_id'] . self::USER_LIT_AND_ID_IN . $idlist . ") AND is_active = '0'";
            $dyntableres = $callConfig->getAllRows($sqldyntable);
            foreach ($dyntableres as $dyntablere) {
                $logtabledetails[$tablename][$dyntablere->id] = $dyntablere;
            }

            $statussql = "SELECT id,name,status,action_label FROM status_progress WHERE company_id = '" . $data['company_id'] . self::USER_LIT_AND_TABLE_NAME . $tablename . "'  AND is_active = '0' ORDER BY `id` ASC";
            $statusress = $callConfig->getAllRows($statussql);
            if (!isset($statusress[0]->id)) {
                $statusres[$tablename][] = array('status' => '0');
            } else {
                $statusres[$tablename] = $statusress;
            }
            $query = "SELECT id,display_field,value_field,attribute_type,content,company_id,field_name FROM display_attribute_types WHERE company_id = '" . $data['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $tablename . "' ";
            $datares = $callConfig->getAllRows($query);

            foreach ($datares as $datadd) {
                $attributes = array();
                $display = $datadd->display_field;
                $value = $datadd->value_field;
                if ($datadd->attribute_type == 'custom_sql') {
                    $qquery = urldecode($datadd->content);
                    if (strpos($qquery, 'WHERE')) {
                        $cwhr = self::USER_SQL_AND_COMPANY_ID_3 . $datadd->company_id . self::USER_SQL_ORDER_BY;
                    } else {
                        $cwhr = self::USER_SQL_WHERE_COMPANY_ID_6 . $datadd->company_id . self::USER_SQL_ORDER_BY;
                    }
                    $qquery = str_replace(self::USER_SQL_ORDER_BY_1, $cwhr, $qquery);
                    $custom_sql = $callConfig->getAllRows($qquery);
                    foreach ($custom_sql as $custom) {
                        $array1[$custom->$value] = $custom->$display;
                    }
                    $attributes = $array1;
                } else {
                    $attributes = json_decode($datadd->content, 1);
                }
                $arrayattributes[$tablename][$datadd->field_name] = $attributes;
            }
        }
        $return["attributes"] = $arrayattributes;
        foreach ($reviewdata as $reviewda) {

            $tabledetails = array();
            $workflowid[$reviewda->workflow_id] = $reviewda->workflow_id;
            $tabledetails = $logtabledetails[$reviewda->transaction_table][$reviewda->transaction_id];
            $return["table_details"][$reviewda->transaction_table][$reviewda->transaction_id] = $tabledetails;
            if (count((array) $statusename[$reviewda->transaction_table]) == '0') {
                $getstatuslistname = $statusres[$reviewda->transaction_table];
                foreach ($getstatuslistname as $getstatuse) {
                    $statusename[$reviewda->transaction_table][$getstatuse->status] = $getstatuse->name;
                    $statusaction_label[$reviewda->transaction_table][$getstatuse->status] = $getstatuse->name;
                }
            }

            if ($reviewda->response_type == "0") {

                $pendingapprove = array();
                $sendarray['transaction_id'] = $reviewda->transaction_id;
                $sendarray['table'] = $reviewda->transaction_table;
                $sendarray['currnet_status'] = $tabledetails->current_status;
                $pendingapprove['created_by'] = $tabledetails->created_by;
                $pendingapprove['workflow_id'] = $reviewda->workflow_id;
                $pendingapprove['request_date'] = $reviewda->request_date;
                $pendingapprove['table'] = $reviewda->transaction_table;
                $pendingapprove['transaction_id'] = $reviewda->transaction_id;
                $pendingapprove['status'] = $this->getUserStatusStep($sendarray); //get next steps stauts
                $pendingapprove['status']['approve']['action_label'] = $statusename[$reviewda->transaction_table][$pendingapprove['status']['approve']['status']]; //get next steps stauts
                $pendingapprove['status']['reject']['action_label'] = $statusaction_label[$reviewda->transaction_table][$pendingapprove['status']['reject']['status']];
                $return["pending"][] = $pendingapprove;

            } else {
                $approve['table'] = $reviewda->transaction_table;
                $approve['transaction_id'] = $reviewda->transaction_id;
                $approve['created_by'] = $tabledetails->created_by;
                $approve['workflow_id'] = $reviewda->workflow_id;
                $approve['currnet_status'] = $tabledetails->current_status;
                $approve['request_date'] = $reviewda->request_date;
                $approve['status'] = $tabledetails->current_status;
                $approve['status_name'] = $statusename[$reviewda->transaction_table][$tabledetails->current_status];
                $return["approve"][] = $approve;
            }
        }
        $implodeworkflowid = implode(",", (array) $workflowid);
        $workfsql = "SELECT wf.id,wf.approve_field FROM workflow_configuration wf WHERE wf.company_id = '" . $data['company_id'] . "' AND wf.is_active = '0' AND wf.id IN(" . $implodeworkflowid . ")";
        $workfres = $callConfig->getAllRows($workfsql);
        foreach ($workfres as $workfres) {
            $return["workflow_details"][$workfres->id] = $workfres;
        }

        $query = "SELECT em.id as id , em.display_name as name, em.user_id, em.image FROM `employee_terminations` et  JOIN employees em ON em.id = et.emp_id AND em.is_active = 0  WHERE em.id NOT IN(select emp_id from user_assets ua where company_id=" . $data['company_id'] . " AND is_active =0 ) AND et.company_id=" . $data['company_id'] . " AND et.is_active=0";
        $return['reg_emp_query'] = $query;
        $return['reg_emp_data'] = $callConfig->getAllRows($query);

        $query = "SELECT em.id as id , em.display_name as name, em.user_id, em.image FROM `employee_terminations` et  JOIN employees em ON em.id = et.emp_id AND em.is_active = 0  WHERE em.id  IN(select emp_id from user_assets ua where company_id=" . $data['company_id'] . " AND is_active =0 ) AND et.company_id=" . $data['company_id'] . " AND et.is_active=0";
        $return['reg_emp_com_query'] = $query;
        $return['reg_emp_com_data'] = $callConfig->getAllRows($query);

        $query = "SELECT id , display_name as name, user_id, image FROM `employees`  WHERE id  IN( SELECT  ua.emp_id from user_assets ua WHERE company_id=" . $data['company_id'] . " AND emp_id NOT IN (SELECT emp_id FROM employee_terminations WHERE company_id=" . $data['company_id'] . " AND is_active = 0 ) AND  is_active =0 ) AND company_id=" . $data['company_id'] . self::USER_SQL_AND_IS_ACTIVE_0_1;
        $return['reg_emp_wo_query'] = $query;
        $return['reg_emp_wo_data'] = $callConfig->getAllRows($query);

        $yesterday = date('Y-m-d', strtotime(self::USER_LIT_1_DAY_1));

        $sql = "
            SELECT eda.id,eda.company_id,eda.employee_id,CONCAT(emp.emp_code, ' - ', emp.display_name) AS employee_name, eda.attendace_date,eda.clock_in,eda.clock_out,eda.leave_type_id,eda.attendance_key_short_code
            FROM employee_daily_attendances AS eda
            LEFT JOIN employees AS emp ON emp.id = eda.employee_id AND emp.company_id=eda.company_id AND emp.is_active=0
            WHERE eda.company_id = '" . intval($data['company_id']) . "'
              AND eda.attendace_date = '" . $yesterday . "'
              AND (eda.clock_in IS NULL OR eda.clock_in = '' OR eda.clock_in = '00:00:00'
                    OR
                    eda.clock_out IS NULL OR eda.clock_out = '' OR eda.clock_out = '00:00:00')
              AND eda.is_active = 0 AND eda.employee_id !='' ORDER BY eda.employee_id ASC";
        $return['emp_miss_punch_list'] = $callConfig->getAllRows($sql);

        return $return;
    }







    public function serchforpos($post)
    {
        global $callConfig;
        if ($post['get_table'] == "requisitions") {
            $post['transaction_table'] = $post['clone_table'];
        } elseif ($post['get_table'] == "quotations") {
            $post['transaction_table'] = 'purchase_orders';
        }
        $post['transaction_date_check'] = date('Y-m-d');
        $getdocaccesssetup = array('document_access_setupsres' => array(), 'document_access_setups_user' => array(), 'allowcostcenter' => array());
        $return = $getdocaccesssetup;
        $return['post'] = $post;
        $conditionbuild = "";
        $document_access_setupsres = $getdocaccesssetup['document_access_setupsres'];
        $docaccesssetupsuser = $getdocaccesssetup['document_access_setups_user'];
        if (count((array) $docaccesssetupsuser) != "0") {
            if ($docaccesssetupsuser['approved_type'] == "cost_center_id") {
                $allowcostcenter = $getdocaccesssetup['allowcostcenter'];
                $conditionbuild .= " AND po.cost_center_id IN(" . implode(',', $allowcostcenter) . ") ";
            }
            if ($docaccesssetupsuser['opex_cpex'] != "") {
                $conditionbuild .= " AND po.opex_cpex = " . $docaccesssetupsuser['opex_cpex'];
            }
            if ($docaccesssetupsuser['amount'] != "" && $docaccesssetupsuser['amount'] != "0") {
                $conditionbuild .= " AND po.total_amount <= " . $docaccesssetupsuser['amount'];
            }
            $item_categorylist = json_decode($docaccesssetupsuser['item_category']);
            if (count((array) $item_categorylist) != "0") {
                $conditionbuild .= " AND poitm.item_id in (SELECT id FROM items itm WHERE category_id IN(" . implode(',', (array) $item_categorylist) . "))";
            }
            $transaction_type = json_decode($docaccesssetupsuser['transaction_type']);
            if (count((array) $transaction_type) != "0") {
                $conditionbuild .= " AND poitm.type IN(" . implode(',', (array) $transaction_type) . "))";
            }
        }
        ///////////////////////End quotations Validation/////////////////////////
        $vendor_id = $post['vendor_id'] != '' ? $post['vendor_id'] : 'NULL';
        $cost_center_id = $post['cost_center_id'] != '' ? $post['cost_center_id'] : 'NULL';
        $category_id = 'NULL';
        $opex_cpex = $post['opex_cpex'] != '' ? $post['opex_cpex'] : 'NULL';
        $from = '';
        $to = '';
        if ($post['from'] != "") {
            $from = str_replace('/"', '-', $post['from']);
            $from = date('Y-m-d', strtotime($from));
        }
        if ($post['to'] != "") {
            $to = str_replace('/"', '-', $post['to']);
            $to = date('Y-m-d', strtotime($to));
        }
        if ($from == "") {
            $from = "'1900-01-10'";
        }
        $current = date('Y-m-d');
        if ($to == "") {
            $to = "'" . $current . "'";
        }
        if ($post['table'] == 'goods_receipt_note') {
            $query = "select distinct po.id, po.party_id, (SELECT display_name FROM vendors WHERE vendors.id = po.party_id) vendor_name,po.transaction_number, po.transaction_date, po.total_amount From goods_receipt_notes po,grn_items poitm WHERE po.company_id = poitm.company_id AND po.id = poitm.transaction_id AND po.party_id = IFNULL(" . $vendor_id . self::USER_LIT_PO_PARTY_ID_AND_PO_COST_CENTER . $cost_center_id . self::USER_LIT_PO_COST_CENTER_ID_AND_POITM_IT . $category_id . self::USER_LIT_ITM_CATEGORY_ID_AND_PO_TRANSAC . $from . self::USER_LIT_1900_01_10_AND_PO_TRANSACTION_ . $to . "','" . $current . "' )) AND poitm.pending_qty >0 AND po.current_status = '" . ST_APPROVED . "'  ORDER BY vendor_name, po.transaction_date asc";
        } elseif ($post['table'] == 'stock_request') {
            $query = "select distinct po.id, po.party_id, po.transaction_number, po.transaction_date, po.total_amount, po.transfer_location_id From stock_requests po,strq_items poitm WHERE po.company_id = poitm.company_id AND po.id = poitm.transaction_id AND po.transfer_location_id = IFNULL(" . $vendor_id . ", po.transfer_location_id) AND po.cost_center_id = IFNULL(" . $cost_center_id . self::USER_LIT_PO_COST_CENTER_ID_AND_POITM_IT . $category_id . self::USER_LIT_ITM_CATEGORY_ID_AND_PO_TRANSAC . $from . self::USER_LIT_1900_01_10_AND_PO_TRANSACTION_ . $to . "','" . $current . "' )) AND po.current_status = '" . ST_APPROVED . "' ORDER BY po.transaction_date asc";
        } elseif ($post['table'] == 'stock_transfer') {
            $query = "select distinct po.id, po.party_id, po.transaction_number, po.transaction_date, po.total_amount, po.transfer_location_id From stock_transfers po,sttr_items poitm WHERE po.company_id = poitm.company_id AND po.id = poitm.transaction_id AND po.transfer_location_id = IFNULL(" . $vendor_id . ", po.transfer_location_id) AND po.cost_center_id = IFNULL(" . $cost_center_id . self::USER_LIT_PO_COST_CENTER_ID_AND_POITM_IT . $category_id . self::USER_LIT_ITM_CATEGORY_ID_AND_PO_TRANSAC . $from . self::USER_LIT_1900_01_10_AND_PO_TRANSACTION_ . $to . "','" . $current . "' )) AND po.current_status = '" . ST_APPROVED . "' ORDER BY po.transaction_date asc";
        } elseif ($post['table'] == 'purchase_orders') {
            $category_id = $post['category_id'] != '' ? $post['category_id'] : 'NULL';
            $query = "select distinct po.id, po.party_id, (SELECT display_name FROM vendors WHERE vendors.id = po.party_id) vendor_name,po.transaction_number, po.transaction_date, po.total_amount From purchase_orders po,po_items poitm WHERE po.company_id = poitm.company_id AND po.id = poitm.transaction_id AND po.party_id = IFNULL(" . $vendor_id . self::USER_LIT_PO_PARTY_ID_AND_PO_COST_CENTER . $cost_center_id . self::USER_LIT_PO_COST_CENTER_ID_AND_POITM_IT . $category_id . ", itm.category_id) ) AND (po.transaction_date >= IFNULL('" . $from . "', '1900-01-10') AND po.transaction_date <= IFNULL('" . $to . "','" . $current . "')) AND po.current_status = '" . ST_APPROVED . "' ORDER BY vendor_name, po.transaction_date asc";
        } else {
            $dmtsql = self::USER_SQL_SELECT_ID_PAGE_TITLE_APPLICATI_1 . $post['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $post['get_table'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $dmtres = $callConfig->getRow($dmtsql);



            $query = "select po.id, po.party_id,po.cost_center_id,po.opex_cpex, GROUP_CONCAT(poitm.id SEPARATOR ',') AS itemtb_id, (SELECT display_name FROM " . $post['get_display_table'] . " as vendors WHERE vendors.id = po.party_id) vendor_name,po.transaction_number, po.transaction_date, po.total_amount,po.current_status From " . $dmtres->application_table_name . " po," . $dmtres->item_table . " poitm WHERE po.company_id = '" . $post['company_id'] . "' AND po.company_id = poitm.company_id AND po.id = poitm.transaction_id AND po.opex_cpex = IFNULL(" . $opex_cpex . ", po.opex_cpex) AND po.party_id = IFNULL(" . $vendor_id . self::USER_LIT_PO_PARTY_ID_AND_PO_COST_CENTER . $cost_center_id . ", po.cost_center_id) AND (po.transaction_date >= IFNULL('" . $from . "', '1900-01-10') AND po.transaction_date <= IFNULL('" . $to . "','" . $current . "' )) AND po.is_active = 0 AND po.current_status = '" . ST_APPROVED . "' " . $conditionbuild . " GROUP BY po.id, po.party_id,po.cost_center_id,po.opex_cpex,po.transaction_number, po.transaction_date, po.total_amount,po.current_status ORDER BY vendor_name, po.transaction_date asc";

        }
        $return['query'] = $query;
        $data = $callConfig->getAllRows($query);
        $return['transaction_details_sql'] = $query;
        $approvedtransid = array();
        foreach ($data as $data1) {
            $approvedtransid[] = $data1->id;
        }
        if (count((array) $document_access_setupsres) != "0") {
            if (count((array) $docaccesssetupsuser) != 0) {
                $return['transaction_details'] = $data;
            }
        } else {
            $return['transaction_details'] = $data;
        }
        $cost_centersql = "SELECT id,cost_center_name FROM " . TBL_COST_CENTERS . self::USER_SQL_WHERE_COMPANY_ID . $post['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $cost_centerres = $callConfig->getAllRows($cost_centersql);
        $costcenterres = $cost_centerres;
        if ($docaccesssetupsuser['approved_type'] == "cost_center_id") {
            $costcenterres = array();
            $allowcostcenter = $getdocaccesssetup['allowcostcenter'];
            foreach ($cost_centerres as $ccvalue) {
                if (in_array($ccvalue->id, (array) $allowcostcenter)) {
                    $costcenterres[] = $ccvalue;
                }
            }
        }
        $return['cost_centers'] = $costcenterres;

        $lolcationssql = "SELECT id, location_name FROM " . TBL_LOCATIONS . self::USER_SQL_WHERE_COMPANY_ID . $post['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $lolcationsres = $callConfig->getAllRows($lolcationssql);
        $return['locations'] = $lolcationsres;

        $vendorssql = "SELECT id, display_name FROM " . TBL_VENDOR . self::USER_SQL_WHERE_COMPANY_ID . $post['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $vendorsres = $callConfig->getAllRows($vendorssql);
        $return['vendors'] = $vendorsres;

        $capexopexsql = "SELECT id, genc_detail_name, genc_detail_code FROM general_code_details WHERE company_id = '" . $post['company_id'] . "' AND genc_code = 'OPEXCAPEX' AND is_active = 0";
        $capexopexres = $callConfig->getAllRows($capexopexsql);
        $capexopexresult = $capexopexres;
        ///////////////////////////////////////////////////
        if ($docaccesssetupsuser['opex_cpex'] != "") {
            $capexopexresult = array();
            foreach ($capexopexres as $capexopexre) {
                if ($docaccesssetupsuser['opex_cpex'] == $capexopexre->genc_detail_code) {
                    $capexopexresult[] = $capexopexre;
                }
            }
        }
        //////////////////////////////////////
        $return['capexopex'] = $capexopexresult;

        $display_attributessql = "SELECT * FROM display_attributes WHERE company_id = '" . $post['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $post['get_table'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $display_attributesres = $callConfig->getRow($display_attributessql);

        $return['display_attributes'] = $display_attributesres;
        $post['table'] = $post['get_table'];
        $status_progress = $this->getStatusProgressList($post);
        foreach ($status_progress as $statusprogress) {
            $return['status_progress'][$statusprogress->status] = $statusprogress;
        }
        $return['approvedtransid'] = $approvedtransid;
        if ($post['get_table'] == "requisitions" || $post['get_table'] == "quotations") {
            if (count((array) $approvedtransid) != '0') {
                $listapproved = implode(",", (array) $approvedtransid);
                $quotationssql = "SELECT id,ref_id,transaction_number FROM quotations WHERE company_id = '" . $post['company_id'] . self::USER_LIT_AND_REF_ID_IN . $listapproved . self::USER_LIT_AND_REF_TYPE_1 . $post['get_table'] . self::USER_LIT_AND_IS_ACTIVE_0_6;
                $quotationsres = $callConfig->getAllRows($quotationssql);
                $return['quotationssql'] = $quotationssql;
                foreach ($quotationsres as $qtres) {
                    $return['quotations'][$qtres->ref_id][] = $qtres;
                }
                $purchase_orderssql = "SELECT id,ref_id,transaction_number FROM purchase_orders WHERE company_id = '" . $post['company_id'] . self::USER_LIT_AND_REF_ID_IN . $listapproved . self::USER_LIT_AND_REF_TYPE_1 . $post['get_table'] . self::USER_LIT_AND_IS_ACTIVE_0;
                $purchase_ordersres = $callConfig->getAllRows($purchase_orderssql);
                foreach ($purchase_ordersres as $potres) {
                    $return['purchase_orders'][$potres->ref_id][] = $potres;
                }
            }
        } else {
            if (count((array) $approvedtransid) != '0') {
                $listapproved = implode(",", (array) $approvedtransid);
                $already_trasnactionsql = "SELECT id,ref_id,transaction_number FROM " . $post['clone_table'] . self::USER_SQL_WHERE_COMPANY_ID . $post['company_id'] . self::USER_LIT_AND_REF_ID_IN . $listapproved . self::USER_LIT_AND_REF_TYPE_1 . $post['get_table'] . self::USER_LIT_AND_IS_ACTIVE_0;
                $already_trasnactionres = $callConfig->getAllRows($already_trasnactionsql);
                foreach ($already_trasnactionres as $potres1) {
