                }
            }
        }
        return $return;
    }
    public function getDyanamicAutoSelectData($table_name, $filed_name, $words)
    {
        global $callConfig;
        $whr = "application_table_name= '" . $table_name . self::USER_LIT_AND_FIELD_NAME . $filed_name . "'";
        $query = $callConfig->selectQuery(TBL_DISPLAYATTRIBUTES_TYPE, '*', $whr, '', '', '');
        $data = $callConfig->getRow($query);
        $display = $data->display_field;
        $value = $data->value_field;
        $array['type'] = $data->attribute_type;
        $array1 = array();
        if ($data->attribute_type == 'custom_sql') {
            $qquery = urldecode($data->content);
            if (strpos($qquery, 'WHERE')) {
                $cwhr = self::USER_SQL_AND_COMPANY_ID_3 . $data->company_id . self::USER_SQL_AND . $display . self::USER_LIT_LIKE . $words . "%'  ORDER BY";
            } else {
                $cwhr = self::USER_SQL_WHERE_COMPANY_ID_6 . $data->company_id . self::USER_SQL_AND . $display . self::USER_LIT_LIKE . $words . "%' ORDER BY";
            }
            $qquery = str_replace(self::USER_SQL_ORDER_BY_1, $cwhr, $qquery);
            $qquery .= " limit 20";
            $custom_sql = $callConfig->getAllRows($qquery);
            foreach ($custom_sql as $custom) {
                $array1[] = array('id' => $custom->$value, 'full_name' => $custom->$display);
            }
        } else {
            $array1['res'] = json_decode($data->content, 1);
        }
        return $array1;
    }
    public function getcitydatasautotype($data)
    {
        global $callConfig;
        if ($data['extracat'] != "") {
            $attchsql = ", " . $data['extracat'];
        }
        if ($data['transaction_date'] != "" && $data['table'] == 'items') {
            $extraconditon = " AND (from_date <='" . $this->dateconvertdbformat($data['transaction_date']) . "' AND to_date >= '" . $this->dateconvertdbformat($data['transaction_date']) . "' OR from_date IS NULL)";
        }
        if ($data['table'] == 'chart_of_accounts') {
            $extraconditon = " AND allow_posting = 0 ";
        }
        if (isset($data['selectvalue'])) {
            if ($data['table'] == 'items') {
                $sql = "SELECT id, " . $data['selectfiled'] . $attchsql . ", sku FROM " . $data['table'] . self::USER_SQL_WHERE_COMPANY_ID . $data['company_id'] . self::USER_LIT_AND_5 . $data['selectfiled'] . self::USER_LIT_LIKE . $data['namewords'] . "%' OR sku like '%" . $data['namewords'] . "%') and id NOT IN (" . $data['selectvalue'] . ") " . $extraconditon . " AND is_active = 0 LIMIT 10";
            } else {
                $sql = "SELECT id, " . $data['selectfiled'] . $attchsql . self::USER_SQL_FROM . $data['table'] . self::USER_SQL_WHERE_COMPANY_ID . $data['company_id'] . self::USER_LIT_AND_1 . $data['selectfiled'] . self::USER_LIT_LIKE . $data['namewords'] . "%' and id NOT IN (" . $data['selectvalue'] . ") " . $extraconditon . " AND is_active = 0 LIMIT 10";

            }
        } else {
            if ($data['table'] == 'items') {
                $sql = self::USER_SQL_SELECT_ID . $data['selectfiled'] . $attchsql . ", sku FROM " . $data['table'] . self::USER_SQL_WHERE_COMPANY_ID . $data['company_id'] . self::USER_LIT_AND_5 . $data['selectfiled'] . self::USER_LIT_LIKE . $data['namewords'] . "%' OR sku like '%" . $data['namewords'] . "%') " . $extraconditon . self::USER_SQL_AND_IS_ACTIVE_0_LIMIT_10;
            } elseif ($data['table'] == 'chart_of_accounts') {
                $sql = "SELECT account_code,account_name FROM chart_of_accounts WHERE company_id = '" . $data['company_id'] . "' AND (account_code like '%" . $data['namewords'] . "%' OR account_name like '%" . $data['namewords'] . "%') " . $extraconditon . self::USER_SQL_AND_IS_ACTIVE_0_LIMIT_10;
            } elseif ($data['table'] == 'hsn_and_sac_codes') {
                $sql = "SELECT code as id, code, code_description, gst FROM hsn_and_sac_codes WHERE company_id = '" . $data['company_id'] . "' AND (code like '%" . $data['namewords'] . "%' OR code_description like '%" . $data['namewords'] . "%') " . $extraconditon . self::USER_SQL_AND_IS_ACTIVE_0_LIMIT_10;
            } else {
                $sql = self::USER_SQL_SELECT_ID . $data['selectfiled'] . $attchsql . self::USER_SQL_FROM . $data['table'] . self::USER_SQL_WHERE_COMPANY_ID . $data['company_id'] . self::USER_LIT_AND_1 . $data['selectfiled'] . self::USER_LIT_LIKE . $data['namewords'] . "%' " . $extraconditon . self::USER_SQL_AND_IS_ACTIVE_0_LIMIT_10;
            }
        }
        return $callConfig->getAllRows($sql);
    }
    public function gettrackingdynamic($get)
    {
        global $callConfig;
        $data['ref_table'] = $get['table'];
        $data['ref_trn_id'] = $get['transaction_id'];
        $sql = "SELECT id,reference_table FROM dynamic_reference_tables WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $referencedocuments = array();
        $referencetableres = $callConfig->getAllRows($sql);

        foreach ($referencetableres as $reftable) {
            $sql1 = "SELECT id,transaction_number,transaction_date,originator FROM " . $reftable->reference_table . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . self::USER_LIT_AND_REF_TYPE . $get['table'] . self::USER_LIT_AND_REF_ID . $get['transaction_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $transactiondetails = $callConfig->getAllRows($sql1);
            foreach ($transactiondetails as $transd) {
                $referencedocuments[$reftable->reference_table][$transd->id] = $transd;
            }
        }


        return $referencedocuments;
    }
    public function toreusetracking($table, $trn)
    {
        global $callConfig;
        $query = self::USER_SQL_SELECT_FROM_1 . $table . self::USER_SQL_WHERE_ID_1 . $trn;
        $row = $callConfig->getRow($query);
        if ($table == "bill_payments") {
            $return['table'] = $table;
            $return['trn_no'] = $row->id;
            $return['trn_id'] = $trn;
            $return['trn_date'] = $row->payment_date;
            $return['ref_table'] = "bills";
            $return['ref_trn_no'] = "";
            $return['ref_trn_id'] = $row->bill_id;
            $return['ref_trn_date'] = "";
            $return['user_id'] = $row->created_by;
        } else {
            $return['table'] = $table;
            $return['trn_no'] = $row->transaction_number;
            $return['trn_id'] = $trn;
            $return['trn_date'] = $row->transaction_date;
            $return['ref_table'] = $row->ref_type;
            $return['ref_trn_no'] = $row->ref_no;
            $return['ref_trn_id'] = $row->ref_id;
            $return['ref_trn_date'] = $row->ref_date;
            $return['user_id'] = $row->created_by;
        }
        return $return;
    }
