    public function resetNewPassword($data)
    {
        global $callConfig;

        $old_password = $callConfig->passwordEncrypt($data['old_password']);
        $confirm_password = $callConfig->passwordEncrypt($data['confirm_password']);
        $sql1 = "SELECT id,company_id, display_name, user_email, user_mobile FROM `application_users` where user_password = '" . $old_password . self::USER_LIT_AND_ID_1 . $data['Rid'] . "'";
