            $qquery = urldecode($data->content);
            if (strpos($qquery, 'WHERE')) {
                $cwhr = self::USER_SQL_AND_COMPANY_ID_3 . $data->company_id . self::USER_SQL_ORDER_BY;
            } else {
                $cwhr = self::USER_SQL_WHERE_COMPANY_ID_6 . $data->company_id . self::USER_SQL_ORDER_BY;
            }
            $qquery = str_replace(self::USER_SQL_ORDER_BY_1, $cwhr, $qquery);
