trait UserPurchaseOrdersAndInvoicesTrait
{

    public function checkWhoShouldApproves($data)
    {

        global $callConfig;
        $checkcriteria = $this->checkCriteria($data);

        if (isset($checkcriteria['workflow_configuration'])) {

            $step = "";
            if ($checkcriteria['workflow_configuration']->approval_type == 'manager') {
                $sql = self::USER_SQL_SELECT_REPORTS_TO_FROM_APPLICA . $data['company_id'] . self::USER_LIT_AND_ID_2 . $data['user_id'] . "'";
                $rowd = $callConfig->getRow($sql); //reports_to
                $row['reports_to'] = $rowd->reports_to;
                $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);

            } elseif ($checkcriteria['workflow_configuration']->approval_type == 'Managers_Manager') {
                $sql = self::USER_SQL_SELECT_REPORTS_TO_FROM_APPLICA . $data['company_id'] . self::USER_LIT_AND_ID_2 . $data['user_id'] . "'";
                $rows = $callConfig->getRow($sql); //manager
                $sql1 = self::USER_SQL_SELECT_REPORTS_TO_FROM_APPLICA . $data['company_id'] . self::USER_LIT_AND_ID_2 . $rows->reports_to . "'";
                $row1 = $callConfig->getRow($sql1); //managers manager
                $row['reports_to'] = $row1->reports_to;
                $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
            } elseif ($checkcriteria['workflow_configuration']->approval_type == 'user') {
                $row['reports_to'] = $checkcriteria['workflow_configuration']->sub_approve_type;
                $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
            } elseif ($checkcriteria['workflow_configuration']->approval_type == 'custom_process') {
                $conjson = json_decode($checkcriteria['workflow_configuration']->sub_approve_type, 1);
                $m = 1;
                $step = 1;
                foreach ($conjson as $ro) {
                    $row['reports_to'] = $ro['step_' . $m];
                    if ($step == '1' && $m == 1) {  //seqquencial
                        $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
                    }
                    if ($step == "") {   //pareler
                        $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
                    }
                    $m++;
                }
            } elseif ($checkcriteria['workflow_configuration']->approval_type == 'access_levels') {
                $like = "'" . '%"' . $checkcriteria['workflow_configuration']->sub_approve_type . '"%' . "'";
                $sql = "SELECT id FROM `application_users` WHERE  is_active = 0 AND company_id = '" . $data['company_id'] . "' AND role_id like " . $like;
                $row = $callConfig->getAllRows($sql);
                $i = 1;
                foreach ($row as $ro) {
                    $row['reports_to'] = $ro->id;
                    if ($step == '1' && $i == 1) {
                        $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
                    }
                    if ($step == "") {
                        $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
                    }
                    $i++;
                }
            } elseif ($checkcriteria['workflow_configuration']->approval_type == 'role_levels') {

                $getuserid = $this->rolelevelworkflow($checkcriteria, $data, 1);
                $row['reports_to'] = $getuserid;
                $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);

            } elseif ($checkcriteria['workflow_configuration']->approval_type == 'user_hierarchical') {
                $reportid = '';
                $step = 1;
                for ($i = 1; $i <= $step; $i++) {
                    if ($i == 1) {
                        $sql = self::USER_SQL_SELECT_REPORTS_TO_FROM_APPLICA . $data['company_id'] . self::USER_LIT_AND_ID_2 . $data['user_id'] . "'";
                        $rows = $callConfig->getRow($sql);
                        $reportid = $rows->reports_to;
                    } else {
                        $sql = self::USER_SQL_SELECT_REPORTS_TO_FROM_APPLICA . $data['company_id'] . self::USER_LIT_AND_ID_2 . $reportid . "'";
                        $rows = $callConfig->getRow($sql);
                        $reportid = $rows->reports_to;
                    }
                    $row['reports_to'] = $reportid;
                    $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
                }
            } elseif ($checkcriteria['workflow_configuration']->approval_type == 'buddy') {
                $row['reports_to'] = $this->findbuddyid($checkcriteria, $data);
                $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
            } elseif ($checkcriteria['workflow_configuration']->approval_type == 'individual_employee_role') {
                $empdata = "select user_id from employees where role_id=" . $checkcriteria['workflow_configuration']->sub_approve_type . " and is_active='0' and company_id = '" . $data['company_id'] . "'";
                $rows = $callConfig->getRow($empdata);
                $row['reports_to'] = $rows->user_id;
                $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
            } elseif ($checkcriteria['workflow_configuration']->approval_type == 'email_groups') {
                $emailgroup = "SELECT e.user_id FROM `email_group_emails` ege left JOIN email e on ege.email_id=e.id WHERE ege.email_groups_id =" . $checkcriteria['workflow_configuration']->sub_approve_type . " and ege.is_active='0' and ege.company_id = '" . $data['company_id'] . "' ";
                $emailgrouprows = $callConfig->getAllRows($emailgroup);
                foreach ($emailgrouprows as $emailgrouprows) {
                    $row['reports_to'] = $emailgrouprows->user_id;
                    $this->checkAlreadyTransactionApprovalLogs($data, $checkcriteria, $row);
                }
            }
            return array("status" => $rows);
        } else {
            return array("status" => "404");
        }
    }


    public function findbuddyid($checkcriteria, $data)
    {
        global $callConfig;
        $buddy_id = 0;
        $employee_id = $data['emp_id'];
        $company_id = $data['company_id'];
        $empdata = "select * from employees where id=" . $employee_id . " and is_active='0' and company_id='" . $company_id . self::USER_LIT_AND_IS_ACTIVE_0_2;
        $edata = $callConfig->getRow($empdata);
        $location_id = $edata->location_id;
        if ($checkcriteria['sub_approve_type'] == "AB") {
            $buddy_id = $edata->admin_buddy;
        } elseif ($checkcriteria['sub_approve_type'] == "FB") {
            $buddy_id = $edata->finance_buddy;
        } elseif ($checkcriteria['sub_approve_type'] == "HB") {
            $buddy_id = $edata->hr_buddy;
        } elseif ($checkcriteria['sub_approve_type'] == "PB") {
            $buddy_id = $edata->project_buddy;
        }
        if ($buddy_id == 0 || $buddy_id == "") {
            $hrconnect_data = self::USER_SQL_SELECT_FROM_LOCATIONS_WHERE_CO . $company_id . self::USER_LIT_AND_IS_ACTIVE_0_AND_ID . $location_id . "'";
            $hrconnect_details = $callConfig->getRow($hrconnect_data);
            if ($checkcriteria['sub_approve_type'] == "AB") {
                $buddy_id = $hrconnect_details->admin_connect;
            } elseif ($checkcriteria['sub_approve_type'] == "FB") {
                $buddy_id = $hrconnect_details->finance_connect;
            } elseif ($checkcriteria['sub_approve_type'] == "HB") {
                $buddy_id = $hrconnect_details->hr_connect;
            } elseif ($checkcriteria['sub_approve_type'] == "PB") {
                $buddy_id = $hrconnect_details->project_connect;
            }
            if ($buddy_id == 0 || $buddy_id == "") {
                $hrconnect_data = "select * from config where company_id='" . $company_id . self::USER_LIT_AND_IS_ACTIVE_0_5;
                $hrconnect_details = $callConfig->getAllRows($hrconnect_data);
                $buddy_id = $hrconnect_details[0]->default_hr;
            }
        }
        return $buddy_id;
    }


    public function emailSendWorkflow($data, $workflow, $type)
    {
        global $callConfig;
        $sendstatus = 1;
        if ($workflow->after_approval_email != "" && $type == "approve") {
            $emailcontain_id = $workflow->after_approval_email;
            $emailtype = $workflow->send_aproval_email_to;
            $sendstatus = 0;
        } elseif ($workflow->after_rejection_email != "" && $type == "reject") {
            $emailcontain_id = $workflow->after_rejection_email;
            $emailtype = $workflow->send_rejection_email_to;
            $sendstatus = 0;
        }
        if ($sendstatus == '0') {
            $insert_id = $data['rid'];
            $emailsql = "select * FROM email_content where id = '" . $emailcontain_id . "'";
            $callConfig->getRow($emailsql);
            $urlpagename = "COM_INSERT_" . ucwords($data['table']);
            $datas = array('company_id' => $data['company_id'], 'transaction_number' => $data['transaction_id'], 'transaction_type' => ucwords(str_replace("_", " ", $data['table'])), 'transaction_date' => date("d-m-Y"), 'action_label' => self::USER_LIT_SUBMIT_FOR_APPROVAL, 'option' => $urlpagename, 'Rid' => $insert_id, 'email_template' => $emailcontain_id, 'email_content_id' => $emailcontain_id, 'status' => $data['status'], 'updated_by' => $data['user_id']);

            $detailsurl = "select * FROM " . $data['table'] . " where id = " . $insert_id;
            $detailsdata = $callConfig->getRow($detailsurl);
            foreach ($detailsdata as $key => $detailsdata) {
                $datas[$data['table'] . "." . $key] = $detailsdata;
            }
            $email_data = '';
            $email = '';
            if ($emailtype == 'everyone_approve') {
                $emaillistevryapprove = self::USER_SQL_SELECT_AU_USER_EMAIL_AS_EMAIL_ . $data['table'] . self::USER_LIT_AND_TAL_TRANSACTION_ID . $data['rid'] . "'  order by tal.id asc";
                $emaillistevryapproved = $callConfig->getAllRows($emaillistevryapprove);
                foreach ($emaillistevryapproved as $drow) {
                    $emails[] = $drow->email;
                }
            } elseif ($emailtype == 'everyone_till_approved') {
                $emaillisttillapprove = self::USER_SQL_SELECT_AU_USER_EMAIL_AS_EMAIL_ . $data['table'] . self::USER_LIT_AND_TAL_TRANSACTION_ID . $data['rid'] . "' AND tal.response_type IS NOT NULL";
                $emaillisttillapproves = $callConfig->getAllRows($emaillisttillapprove);
                foreach ($emaillisttillapproves as $drow) {
                    $emails[] = $drow->email;
                }
            } else {
                $emaillistevryapprove = self::USER_SQL_SELECT_AU_USER_EMAIL_AS_EMAIL_ . $data['table'] . self::USER_LIT_AND_TAL_TRANSACTION_ID . $data['rid'] . "'  order by tal.id asc";
                $emaillistevryapproved = $callConfig->getAllRows($emaillistevryapprove);
                $emails[] = $emaillistevryapproved[0]->email;

            }
            $emails[] = $email_data;
            $email_array = $this->emailtemplate($datas);
            $file_name = 'email' . '_' . time() . uniqid() . '.' . 'html';
            $email_array['content'] = $file_name;
            $email_array['revicer'] = $email;
            $email_array['email_type'] = 1;
            $email = $email_array['mesg'];
            $file_path = self::USER_LIT_UPLOADS_EMAIL . $file_name;
            file_put_contents($file_path, $email);
            $this->sendEmailslist($email_array);
        }
    }

