            }




            $employee_detailsurl = "select id,joining_date FROM employees where is_active='0' and company_id = '" . $data['company_id'] . "'" . $condition;
            $resultreturn['employee_detailsurl'][] = $employee_detailsurl;
            $employee_details = $callConfig->getAllRows($employee_detailsurl);
            $resultreturn['employee_details'][] = $employee_details;
            foreach ($employee_details as $employee_detail) {
                if ($leave_type_levels->before_or_after == "B") {
                    $before_or_after = "-";
                } else {
                    $before_or_after = "+";
                }
                if ($leave_type_levels->action_frequency == 'W') {
                    $startleavetype = "week";
                } elseif ($leave_type_levels->action_frequency == 'M') {
                    $startleavetype = "months";
                } elseif ($leave_type_levels->action_frequency == 'Y') {
                    $startleavetype = "years";
                } else {
                    $startleavetype = "days";
                }
                $leavestart = strtotime($employee_detail->joining_date . ' ' . $before_or_after . ' ' . round($leave_type_levels->action_number) . ' ' . $startleavetype);
                $resultreturn['leave_start_date'][] = $leavestart;
                $todaydates = date('Y-m-d');

                if ($leavestart <= strtotime($todaydates)) {
                    $resultreturn['leave_start_date'][] = "Yes";
                    $emp_leave_balances = "select * FROM emp_leave_balances where is_active='0' and company_id = '" . $data['company_id'] . self::USER_LIT_AND_EMPLOYEE_ID_2 . $employee_detail->id . "' AND leave_type = '" . $leaevtyperesult->id . "'";
                    $resultreturn['emp_leave_balances'][] = $emp_leave_balances;
                    $emp_leave_balancesresults = $callConfig->getRow($emp_leave_balances);
                    $resultreturn['emp_leave_balancesresults'][] = $emp_leave_balancesresults;
                    if (!isset($emp_leave_balancesresults->id)) {
                        $applicable_leaves_balance = $emp_leave_balancesresults->applicable_leaves;
                        $limitleave = $leave_type_levels->max_accured_limit;
                        $resultreturn['limitleave'][] = $limitleave;
                        $transaction_date = "";
                        if ($leave_type_levels->accured_action_based == "W") {
                            $transaction_date = date('Y-m-d', strtotime($leave_type_levels->month_year_weeck, strtotime($todaydates)));
                        } elseif ($leave_type_levels->accured_action_based == "M") {
                            $transaction_date = date("Y-m-" . $leave_type_levels->day);
                            if (strtotime($transaction_date) <= strtotime($todaydates)) {
                                $transaction_date = date("Y-m-d", strtotime(self::USER_LIT_1_MONTH, strtotime($transaction_date)));
                            }
                        } elseif ($leave_type_levels->accured_action_based == "Y") {
                            $transaction_date = date("Y-" . $leave_type_levels->month_year_weeck . "-" . $leave_type_levels->day);
                        }
                        if ($leaevtyperesult->first_accrual == 'P') {
                            $base_onleave = $leave_type_levels->base_on;
                            $addedleave = $applicable_leaves_balance + $base_onleave;
                            $resultreturn['first_accrual'][] = "Prorata";
                        } else {
                            $week = $leave_type_levels->base_on * 52;
                            $month = $leave_type_levels->base_on * 12;
                            $years = $leave_type_levels->base_on * 1; //old value 1 year direct multiple but year days remaining so month count
                            $days = $leave_type_levels->base_on * ((strtotime($todaydate . ' + 1 years') - strtotime($todaydate)) / (60 * 60 * 24));
                            if ($leave_type_levels->accured_action_based == 'W') {
                                $addedleave = $week;
                            } elseif ($leave_type_levels->accured_action_based == 'M') {
                                $addedleave = $month;
                            } elseif ($leave_type_levels->accured_action_based == 'Y') {
                                $addedleave = $years;
                            } else {
                                $addedleave = $days;
                            }
                            $resultreturn['first_accrual'][] = "full";
                        }
                        $resultreturn['addedleave'][] = $addedleave;
                        if ($leaevtyperesult->accruals_happen == 'B') {
                            $addedleaveok = $addedleave;
                        } else {
                            $addedleaveok = '0';
                        }
                        $resultreturn['addedleaveok'][] = $addedleaveok;

                        if ($addedleaveok <= $limitleave) {
                            $fieldnames = array('is_active' => '0', 'company_id' => $data['company_id'], 'employee_id' => $employee_detail->id, 'leave_type' => $leaevtyperesult->id, 'applicable_leaves' => $addedleaveok, 'consumed_leaves' => '0', 'current_status' => '0', 'leave_year' => $year);
                            $callConfig->insertRecord('emp_leave_balances', $fieldnames);
                            $fieldnames['transaction_date'] = $transaction_date;
                            $callConfig->insertRecord('emp_leave_allocations', $fieldnames);
                        } else {
                            $fieldnames = array('is_active' => '0', 'company_id' => $data['company_id'], 'employee_id' => $employee_detail->id, 'leave_type' => $leaevtyperesult->id, 'applicable_leaves' => $limitleave, 'consumed_leaves' => '0', 'current_status' => '0', 'leave_year' => $year);
                            $callConfig->insertRecord('emp_leave_balances', $fieldnames);
                            $fieldnames['transaction_date'] = $transaction_date;
                            $callConfig->insertRecord('emp_leave_allocations', $fieldnames);
                        }
                        $resultreturn['emp_leave_balances_insert'][] = $fieldnames;
                    }
                } else {
                    $resultreturn['leave_start_date'][] = "NO";
                }
            }
            $rettt[] = $resultreturn;
        }
        print_r($rettt);
    }

    public function cronJobLeave($data)
    {
        global $callConfig;
        $this->checkLeaveApplicable($data);
        $todaydate = date('Y-m-d');
        $year = date('Y');
        $monthdate = date('m-d');
        $emp_leave_balancesurl = "select elb.id as elbid,elb.employee_id as employee_id,elb.leave_type as elbleave_type,elb.applicable_leaves,elb.consumed_leaves,elb.leave_year,elb.weekend_leave_consume,elb.holiday_leave_consume,elb.unapproved_leaves,elb.employee_id,elb.status_date as elb_status_date,lt.* FROM emp_leave_balances elb, leave_types lt where elb.company_id = '" . $data['company_id'] . "' AND elb.leave_type = lt.id AND elb.company_id = lt.company_id AND elb.is_active = lt.is_active AND elb.is_active='0'";
        $emp_leave_balances = $callConfig->getAllRows($emp_leave_balancesurl);
        $carry_forward_sql = "SELECT id,leave_carry_forward_date FROM `config` where company_id = '" . $data['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $carry_forwardres = $callConfig->getRow($carry_forward_sql);
        $carry_forwarddate = date('m-d', strtotime($carry_forwardres->leave_carry_forward_date));
        foreach ($emp_leave_balances as $emp_leave_balancess) {
            $returnresultarray = array();
            $lastupdatesql = "SELECT id,transaction_date FROM `emp_leave_allocations` where company_id = '" . $data['company_id'] . "' and employee_id ='" . $emp_leave_balancess->employee_id . "' and  leave_type= '" . $emp_leave_balancess->elbleave_type . "' ORDER BY transaction_date DESC";
            $lastupdateresult = $callConfig->getRow($lastupdatesql);

            $leave_type_levels = self::USER_SQL_SELECT_FROM_LEAVE_TYPE_LEVELS_ . $data['company_id'] . self::USER_LIT_AND_LEAVE_TYPE_ID . $emp_leave_balancess->id . "'";
            $leave_type_levels = $callConfig->getRow($leave_type_levels);

            $employee_detailsurl = "select id,joining_date FROM employees where is_active='0' and company_id = '" . $data['company_id'] . self::USER_LIT_AND_ID_2 . $emp_leave_balancess->employee_id . "'";
            $employee_details = $callConfig->getRow($employee_detailsurl);

            if ($leave_type_levels->before_or_after == "B") {
                $before_or_after = "-";
            } else {
                $before_or_after = "+";
            }
            if ($leave_type_levels->action_frequency == 'W') {
                $startleavetype = "week";
            } elseif ($leave_type_levels->action_frequency == 'M') {
                $startleavetype = "months";
            } elseif ($leave_type_levels->action_frequency == 'Y') {
                $startleavetype = "years";
            } else {
                $startleavetype = "days";
            }
            $leavestart = strtotime($employee_details->joining_date . ' ' . $before_or_after . ' ' . round($leave_type_levels->action_number) . ' ' . $startleavetype);
            // End Accrual Schedule start day to leave
            $returnresultarray['employe_id'] = $emp_leave_balancess->employee_id;
            $returnresultarray['leave_type'] = $emp_leave_balancess->elbleave_type;
            $returnresultarray['leave_start_date'] = date('Y-m-d', $leavestart);

            $returnresultarray['leave_today_date'] = $todaydate;
            if ($leavestart <= strtotime($todaydate)) {
                $returnresultarray['leave_start_date_working'] = "ok";
                if (isset($lastupdateresult->id)) {
                    $lastupdatedate = $lastupdateresult->transaction_date;
                    $returnresultarray['lastupdatedate'] = $lastupdatedate;
                } else {
                    $lastupdatedate = $emp_leave_balancess->elb_status_date;
                    $returnresultarray['lastupdatedate'] = $lastupdatedate;
                }

                if ($leave_type_levels->accured_action_based == 'W') {
                    $accruedaddtype = "week";
                } elseif ($leave_type_levels->accured_action_based == 'M') {
                    $accruedaddtype = "months";
                } elseif ($leave_type_levels->accured_action_based == 'Y') {
                    $accruedaddtype = "years";
                } else {
                    $accruedaddtype = "days";
                }
                $returnresultarray['increment_days'] = $leave_type_levels->base_on;
                $statusupdatedatetodayornot = strtotime($lastupdatedate . ' + 1 ' . $accruedaddtype);  //increment days in date
                $statusupdatedatetodayornots = date('Y-m-d', $statusupdatedatetodayornot);
                $returnresultarray['statusupdatedatetodayornots'] = $statusupdatedatetodayornots;
                $returnresultarray['first_accrual'] = $emp_leave_balancess->first_accrual;
                $returnresultarray['todaydate_same_or_not'] = $statusupdatedatetodayornots . " -- " . $todaydate . "--" . $monthdate . " == " . $carry_forwarddate;


                if ($statusupdatedatetodayornots == $todaydate || $monthdate == $carry_forwarddate) {   //status date Same or Not
                    $returnresultarray['samedate'] = "ok";
                    $applicable_leaves_balance = $emp_leave_balancess->applicable_leaves;
                    $limitleave = $leave_type_levels->max_accured_limit;
                    $returnresultarray['first_accrual'] = $limitleave->first_accrual;
                    if ($emp_leave_balancess->first_accrual == 'P') {
                        $base_onleave = $leave_type_levels->base_on;
                        $addedleave = $applicable_leaves_balance + $base_onleave;
                    } else {
                        $week = $leave_type_levels->base_on * 52;
                        $month = $leave_type_levels->base_on * 12;
                        $years = $leave_type_levels->base_on * 1;
                        $days = $leave_type_levels->base_on * ((strtotime($todaydate . ' + 1 years') - strtotime($todaydate)) / (60 * 60 * 24));
                        if ($leave_type_levels->accured_action_based == 'W') {
                            $addedleave = $week;
                        } elseif ($leave_type_levels->accured_action_based == 'M') {
                            $addedleave = $month;
                        } elseif ($leave_type_levels->accured_action_based == 'Y') {
                            $addedleave = $years;
                        } else {
                            $addedleave = $days;
                        }
                    }
                    $returnresultarray['addedleave'] = $addedleave;

                    $penddingleave = $emp_leave_balancess->applicable_leaves - $emp_leave_balancess->consumed_leaves;

                    $carryovertype = $leave_type_levels->carry_over_limit;
                    $percentagecarryoverleave = ($carryovertype / 100) * $emp_leave_balancess->applicable_leaves;
                    if ($leave_type_levels->carry_over_limit_type == 'P') {
                        $halfdaycalculation = round($percentagecarryoverleave / 5, 1) * 5;
                        $penddingleave = $halfdaycalculation;
                    }
                    $carryoverleave = 0;
                    if ($carryovertype == 'N' || $carryovertype == '') {
                        $carryoverleave = 0;
                    } elseif ($carryovertype == 'U') {
                        $carryoverleave = $penddingleave;
                    } else {
                        if ($penddingleave <= $carryovertype) {
                            $carryoverleave = $penddingleave;
                        } else {
                            $carryoverleave = $carryovertype;
                        }
                    }



                    if ($addedleave <= $limitleave) {
                        $maxleavadded = $addedleave;
                    } else {
                        $maxleavadded = $limitleave;
                    }
                    if ($monthdate == $carry_forwarddate) {  //yearly new entry added emp_leave_balances table

                        $fields = array('is_active' => '1', 'status_date' => date('Y-m-d'));
                        $whrcon = "id='" . $emp_leave_balancess->elbid . "'";
                        $callConfig->updateRecord('emp_leave_balances', $fields, '', '', $whrcon);
                        $fieldnames = array('is_active' => '0', 'company_id' => $data['company_id'], 'employee_id' => $emp_leave_balancess->employee_id, 'leave_type' => $emp_leave_balancess->elbleave_type, 'applicable_leaves' => $carryoverleave, 'unapproved_leaves' => $emp_leave_balancess->unapproved_leaves, 'consumed_leaves' => '0', 'current_status' => '0', 'leave_year' => $year);
                        $callConfig->insertRecord('emp_leave_balances', $fieldnames);
                        $fieldnames['transaction_date'] = $todaydate;
                        $fieldnames['note'] = "Carry Forward Days";
                        $fieldnames['type'] = 0;
                        unset($fieldnames['unapproved_leaves']);
                        $callConfig->insertRecord('emp_leave_allocations', $fieldnames);
                    } else {    //Not yearly Update record emp_leave_balances table
                        $fields = array('leave_year' => $year, 'is_active' => '0', 'applicable_leaves' => $maxleavadded);
                        $whrcon = "id='" . $emp_leave_balancess->elbid . "'";
                        $callConfig->updateRecord('emp_leave_balances', $fields, '', '', $whrcon);
                        $fieldnames = array('is_active' => '0', 'company_id' => $data['company_id'], 'employee_id' => $emp_leave_balancess->employee_id, 'leave_type' => $emp_leave_balancess->elbleave_type, 'applicable_leaves' => $maxleavadded, 'consumed_leaves' => '0', 'current_status' => '0', 'leave_year' => $year);
                        $fieldnames['transaction_date'] = $todaydate;
                        $fieldnames['type'] = 0;
                        unset($fieldnames['unapproved_leaves']);
                        $insertnewbalance = $callConfig->insertRecord('emp_leave_allocations', $fieldnames);
                        $returnresultarray['limitexitempleave'] = $insertnewbalance;
                    }


                } else {
                    $returnresultarray['samedate'] = "NO";
                }
            } else {
                $returnresultarray['leave_start_date_working'] = "NO";
            }
            $rsrrs[] = $returnresultarray;
        }
        echo "<pre>";
        print_r($rsrrs);
    }
    public function checkLeaveBalanceOrHalfDay($data)
    {
        global $callConfig;
        if ($data['leave_year'] == "") {
            $data['leave_year'] = date("Y");
        }
        $halfdaysql = "SELECT eb.id,lt.half_day,eb.applicable_leaves,eb.consumed_leaves,eb.unapproved_leaves,lt.duration_allowed,lt.duration_leave_count FROM emp_leave_balances eb, `leave_types` lt  WHERE  eb.company_id = '" . $data['company_id'] . "' AND eb.company_id =lt.company_id AND eb.leave_type = lt.id  AND eb.employee_id = '" . $data['emp_id'] . "' AND lt.leave_category_id = '" . $data['categorytype'] . "' AND eb.leave_year = '" . $data['leave_year'] . "' AND  eb.is_active =lt.is_active AND eb.is_active='0'";
        $halfdya = $callConfig->getRow($halfdaysql);
        $avlbleave = ($halfdya->applicable_leaves - ($halfdya->unapproved_leaves + $halfdya->consumed_leaves));
        $leavedetails = array("halfday" => $halfdya->half_day, 'consumed_leaves' => $halfdya->consumed_leaves, 'applicable_leaves' => $halfdya->applicable_leaves, 'weekend_leave_consume' => $halfdya->weekend_leave_consume, 'holiday_leave_consume' => $halfdya->holiday_leave_consume, 'id' => $halfdya->id, 'available_leave' => $avlbleave, 'duration_allowed' => $halfdya->duration_allowed, 'duration_leave_count' => $halfdya->duration_leave_count);

        $tempcheckleavesql = "SELECT sum(leave_days) as leave_days FROM `temp_attendance_details` WHERE company_id = '" . $data['company_id'] . "' and is_active = 0 AND MONTH(attendance_date) = '" . $data['month'] . "' AND YEAR(attendance_date) = '" . $data['leave_year'] . "' AND attendance_type = 2 AND leave_type_id = '" . $data['categorytype'] . self::USER_LIT_AND_EMPLOYEE_ID_2 . $data['emp_id'] . "'";
        $callConfig->getRow($tempcheckleavesql);


        $returnarray['leave_details'] = $leavedetails;
        return $returnarray;
    }

    public function insertLeaveRequest($data)
    {

        global $callConfig;
        $returnarray = array();
        $returnarray['post'] = $data;
        $rid = $data['rid'];
        $userid = $data['user_id'];
        unset($data['rid']);
        unset($data['user_id']);
        if ($rid != "") {
            $emp_leavesql = self::USER_SQL_SELECT_LEAVE_DAYS_EMPLOYEE_ID_ . $data['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_AND_ID_1 . $rid . "'";
            $emp_leaveres = $callConfig->getRow($emp_leavesql);
            $returnarray['emp_leaveres'] = $emp_leavesql;
        }
        $newdata = $data;
        $newdata['emp_id'] = $data['employee_id'];
        $newdata['leavetype'] = $data['leave_type_id'];
        $newdata['old_leave_days'] = $emp_leaveres->leave_days != "" ? $emp_leaveres->leave_days : 0;
        $newdata['rid'] = $rid;
        $checkleave = $this->checkEmployeeLeaveAvailableOrNot($newdata);
        $returnarray["leavestatus"] = $checkleave;
        if ($checkleave['leaveaplye'] == '0') {
            $data['unpaid_days'] = $checkleave['unpaid_days'];
            $data['weekend_leave_consume'] = $checkleave['weeckendandnumberdate'];
            $data['holiday_leave_consume'] = $checkleave['holidaysnumberdate'];
            if ($rid != "") {
                $data['created_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
                $data['created_by'] = $userid;
                $res = $callConfig->updateRecord('employee_leaves', $data, 'id', $rid);
                $res['LASTID'] = $rid;
            } else {
                $data['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
                $data['updated_by'] = $userid;
                $res = $callConfig->insertRecord('employee_leaves', $data);
            }

            $updateval = $checkleave['final_appllay_leave_count'] - $emp_leaveres->leave_days; //allways positive value show
            if ($updateval < 0) {
                $sql = "UPDATE `emp_leave_balances` SET `unapproved_leaves`= unapproved_leaves -" . abs($updateval) . ",weekend_leave_consume = weekend_leave_consume+'" . $checkleave['weeckendandnumberdate'] . "',holiday_leave_consume = holiday_leave_consume+'" . $checkleave['holidaysnumberdate'] . "'  WHERE `id`='" . $checkleave['leavebalanceid'] . self::USER_LIT_AND_IS_ACTIVE_0_18;
            } else {
                $sql = "UPDATE `emp_leave_balances` SET `unapproved_leaves`= unapproved_leaves + " . $updateval . ",weekend_leave_consume = weekend_leave_consume+'" . $checkleave['weeckendandnumberdate'] . "',holiday_leave_consume = holiday_leave_consume+'" . $checkleave['holidaysnumberdate'] . "'  WHERE `id`='" . $checkleave['leavebalanceid'] . self::USER_LIT_AND_IS_ACTIVE_0_18;
            }
            $callConfig->executeQueryString($sql);
            $returnarray['emp_leave_balances'] = $sql;
            $returnarray['leaveinsert'] = $res;
        }

        return $returnarray;
    }
    public function rolelevelworkflow($checkcriteria, $data, $looprun)
    {
        if (isset($checkcriteria)) { /* noop */ }
        global $callConfig;
        $returnuserid = "";
        $emplyeesql = "SELECT id,display_name,company_id,user_id,role_id,sub_section_id,section_id,department_id,division_id FROM employees where is_active = 0 and company_id = '" . $data['company_id'] . self::USER_LIT_AND_ID_2 . $data['emp_id'] . "'";
        $employeerow = $callConfig->getRow($emplyeesql);
        $tepstorereprtid = 0;
        for ($jk = 1; $jk <= $looprun; $jk++) {
            if ($jk == 1) {
                $emplyeerolsql = "SELECT id,reports_to_role FROM employment_roles where is_active = 0 and company_id = '" . $data['company_id'] . self::USER_LIT_AND_ID_2 . $employeerow->role_id . "'";
                $employeerolrow = $callConfig->getRow($emplyeerolsql);
                $tepstorereprtid = $employeerolrow->reports_to_role;
            } else {
                $emplyeerolsql = "SELECT id,reports_to_role FROM employment_roles where is_active = 0 and company_id = '" . $data['company_id'] . self::USER_LIT_AND_ID_2 . $tepstorereprtid . "'";
                $employeerolrow = $callConfig->getRow($emplyeerolsql);
                $tepstorereprtid = $employeerolrow->reports_to_role;
            }
        }
        if ($tepstorereprtid != "") {
            $subsectionsql = self::USER_SQL_SELECT_USER_ID_FROM_EMPLOYEES_ . $data['company_id'] . "' and sub_section_id='" . $employeerow->sub_section_id . self::USER_LIT_AND_ROLE_ID_1 . $tepstorereprtid . "'";
            $subsectionrow = $callConfig->getRow($subsectionsql);
            if (isset($subsectionrow->user_id)) {
                $returnuserid = $subsectionrow->user_id;
            } else {
                $sectionsql = self::USER_SQL_SELECT_USER_ID_FROM_EMPLOYEES_ . $data['company_id'] . "' and section_id='" . $employeerow->section_id . self::USER_LIT_AND_ROLE_ID_1 . $tepstorereprtid . "'";
                $sectionrow = $callConfig->getRow($sectionsql);
                if (isset($sectionrow->user_id)) {   //section match
                    $returnuserid = $sectionrow->user_id;
                } else {
                    $departmentsql = self::USER_SQL_SELECT_USER_ID_FROM_EMPLOYEES_ . $data['company_id'] . "' and department_id='" . $employeerow->department_id . self::USER_LIT_AND_ROLE_ID_1 . $tepstorereprtid . "'";
                    $departmebtrow = $callConfig->getRow($departmentsql);
                    if (isset($departmebtrow->user_id)) {  ////department match
                        $returnuserid = $departmebtrow->user_id;
                    } else {
                        $divisionsql = self::USER_SQL_SELECT_USER_ID_FROM_EMPLOYEES_ . $data['company_id'] . "' and division_id='" . $employeerow->division_id . self::USER_LIT_AND_ROLE_ID_1 . $tepstorereprtid . "'";
                        $divisionrow = $callConfig->getRow($divisionsql);
                        if (isset($divisionrow->user_id)) { //division match
                            $returnuserid = $divisionrow->user_id;
                        } else {
                            $comanysql = "SELECT hr_connect FROM companies where is_active = 0 and id ='" . $employeerow->company_id . "'";
                            $companyrow = $callConfig->getRow($comanysql);
                            $returnuserid = $companyrow->hr_connect;
                        }
                    }
                }
            }
        } else {
            $returnuserid = "-1";
        }
        return $returnuserid;
    }
    public function workflowsendnotifiction($checkcriteria, $data, $userarray, $fianlapprove = "")
    {
        global $callConfig;
        if ($checkcriteria->after_approve_call_function != "") {
            $dynamic_status = $data['status'];
            $dynamic_post = $data;
            $functions = $checkcriteria->after_approve_call_function;
            $returnarry['dddd'][] = $this->$functions($dynamic_status, $dynamic_post);
        }
        if ($data['pagename'] != "") {
            $option = $data['pagename'];
        } else {
            $option = "COM_INSERT_" . strtoupper($data['table']);
        }
        $data['tablename'] = $data['table'];
        $rid = $data['rid'];
        if ($userarray != "") {
            $workf['workflow_configuration'] = $checkcriteria;
            $msg = $this->workFlowSendNotificatin($data, $workf, 'approve_message'); //approve_message,reject_message,sendback_message,completed_workflow_message,employee_message
            $user_ids = array($userarray);
            $usernotdataa = array('company_id' => $data['company_id'], 'notification_message' => $msg, 'id' => $rid, 'application_table_name' => $data['table'], 'type' => 'ACTION', 'notification_users' => $user_ids, 'option' => $option);
            $this->tosendnotifiations($usernotdataa);
        } else {

            $cretedby = self::USER_SQL_SELECT_CREATED_BY_FROM . $data['table'] . self::USER_SQL_WHERE_COMPANY_ID_5 . $data['company_id'] . self::USER_LIT_AND_ID_2 . $rid . "'";
            $cretedbyid = $callConfig->getRow($cretedby);
            $workf['workflow_configuration'] = $checkcriteria;
            if ($fianlapprove == "ap") {
                $msg1 = $this->workFlowSendNotificatin($data, $workf, 'completed_workflow_message'); //approve_message,reject_message,sendback_message,completed_workflow_message,employee_message
            } else {
                $msg1 = $this->workFlowSendNotificatin($data, $workf, 'employee_message'); //approve_message,reject_message,sendback_message,completed_workflow_message,employee_message
            }
            $user_ids1 = array($cretedbyid->created_by);
            $crfeatebynotdataa = array('company_id' => $data['company_id'], 'notification_message' => $msg1, 'id' => $rid, 'application_table_name' => $data['table'], 'type' => 'INFORMATION', 'notification_users' => $user_ids1, 'option' => $option);
            $this->tosendnotifiations($crfeatebynotdataa);
        } //new notification this time comment part
        return $msg . "----" . $msg1;

    }
