    public function updatedynamicapprovallognew($data)
    {
        global $callConfig;
        $fields1 = array('response_type' => $data['status'], 'response_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'comments' => $data['comment']);
        $whrcon1 = "id='" . $data['transaction_id'] . self::USER_LIT_AND_SEND_BACK_FLAG_0;
        $callConfig->updateRecord('transaction_approval_logs', $fields1, '', '', $whrcon1);
        $workflowsql = "select * from workflow_configuration where is_active='0' and company_id = '" . $data['company_id'] . self::USER_LIT_AND_ID_1 . $data['workflow_id'] . "'";
        $resutlworkflow = $callConfig->getRow($workflowsql);
        $status = json_decode($resutlworkflow->approve_update_status, 1);
        if ($data['status'] == ST_SEND_BACK) {
            $workf['workflow_configuration'] = $resutlworkflow;
            $returnarray = $this->setSendBack($data, $workf);
        } else {

            if ($data['type'] == "approve") {
                if ($resutlworkflow->approval_type == 'email_groups' || $resutlworkflow->approval_type == 'access_levels' || $resutlworkflow->approval_type == 'individual_employee_role') {
                    $samestatusrescntsql = self::USER_SQL_SELECT_COUNT_ID_AS_CNT_FROM_TR . $data['table'] . self::USER_LIT_AND_TRANSACTION_ID_1 . $data['rid'] . "' AND response_type = '" . $data['status'] . self::USER_LIT_AND_SEND_BACK_FLAG_0;
