                    $callConfig->executeQuery($updatequery);
                    if ($data['status'] == ST_APPROVED) {
                        $this->workflowsendnotifiction($resutlworkflow, $data, '', 'ap');
                    } else {
                        $this->workflowsendnotifiction($resutlworkflow, $data, '');
                    }
                }
                if ($resutlworkflow->approval_type != 'email_groups' || $resutlworkflow->approval_type != 'access_levels' || $resutlworkflow->approval_type != 'individual_employee_role') {
                    $getstatus = '0';
