                                $datareportid->reports_to = $getfiledid[$status[$incrementkey - 1]['work_flow_field']];
                            } else {
                                $hrurl = "SELECT reports_to FROM application_users WHERE id = '" . $data['user_id'] . "'";
                                $datareportid = $callConfig->getRow($hrurl);
                            }
                            $inserttransactionapprovelog = array('company_id' => $data['company_id'], 'module_setup_id' => $callConfig->module_id, 'transaction_table' => $data['table'], 'transaction_id' => $data['rid'], 'response_type' => '', 'user_id' => $datareportid->reports_to, 'request_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'workflow_id' => $data['workflow_id'], 'ref_field' => $data['rid']);
