                            if ($datareportid->reports_to != "") {
                                $callConfig->insertRecord("transaction_approval_logs", $inserttransactionapprovelog);
                            }
                            $returnarray['workflowsendnotifiction'] = $this->workflowsendnotifiction($resutlworkflow, $data, $datareportid->reports_to);
                        }
                    } else {
                        $returnarray['next_user'] = "approved";
                    }
                }



            } else {
                $returnarray = array();
                if ($resutlworkflow->approval_type == 'email_groups' || $resutlworkflow->approval_type == 'access_levels' || $resutlworkflow->approval_type == 'individual_employee_role') {

