            $retrunarry['log'][] = $aprlog;
            $insertlogandnotification = $this->insertTransactionApprovalLogs($aprlog, $data, $details);
            $retrunarry['nofiti'][] = $insertlogandnotification;
        } else {
            $retrunarry['error'] = "404";
        }
        return $retrunarry;
    }
    public function setSendBack($data, $workflowdetails)
    {
        global $callConfig;
        $updatequery = self::USER_SQL_UPDATE . $data['table'] . self::USER_LIT_SET_CURRENT_STATUS . ST_SEND_BACK . self::USER_SQL_WHERE_ID_IN . $data['rid'] . ")";
