    public function employeeadvancepaymntsamountwithupdate($data)
    {
        global $callConfig;
        $query = "SELECT SUM(amount) as adv_amount FROM emp_salary_advance WHERE salary_applicable=0 AND transaction_date >= '" . $data['date1'] . "' AND transaction_date <= '" . $data['date2'] . self::USER_LIT_AND_EMP_ID . $data['emp_id'];
        $row = $callConfig->getRow($query);
        if ($row->adv_amount != "") {
            $updatequery = "UPDATE emp_salary_advance SET salary_applicable=1,pay_month='" . $data['pay_month'] . "',pay_year='" . $data['pay_year'] . "' WHERE salary_applicable=0 AND  transaction_date >= '" . $data['date1'] . "' AND transaction_date <= '" . $data['date2'] . self::USER_LIT_AND_EMP_ID . $data['emp_id'];
            $callConfig->executeQuery($updatequery);
        }
        return $row;
    }
    public function toinsertpayrnsummarynew($post, $get)
