    public function getheadcountreportEmployeFilter11($get)
    {
        global $callConfig;
        $returnarray = array();
        $year = $get['year'];
        $monthNo = $get['month'];
        $prev_year = $year - 1;
        $appendcondtion = '';
        $filterdata = urldecode($get['filterby']);
        $filters = json_decode($filterdata, 1);
        $curentyear_totalheadcount = 0;
        $prevyear_totalheadcount = 0;
        if ($filters != '') {
            $appendcondtion = self::USER_SQL_AND_1;
            foreach ($filters as $filterkey => $filtervalue) {
                $appendcondtion .= $filterkey . self::USER_LIT_IN;
                $appendcondtion .= implode(',', array_keys((array) $filtervalue));
                $appendcondtion .= self::USER_LIT_AND_2;
            }
            $appendcondtion = substr($appendcondtion, 0, -4);
        }
        for ($i = 1; $i <= 12; $i++) {
            $ldate = $prev_year . "-" . sprintf('%02s', $i) . "-31";
            $query = self::USER_SQL_SELECT_COUNT_ID_AS_HEADCOUNT_F . $ldate . "') as date_of_leaving  FROM `employees`) as td ";
            $returnarray['headcount'][] = $query;
            $empdatas = $callConfig->getRow($query);
            $query_emp = "SELECT id,display_name,designation_id,department_id,joining_date,employment_category_id,location_id  FROM `employees`  WHERE company_id='" . $get['company_id'] . "' AND employee_type =1 AND is_active =0  " . $appendcondtion;
            $returnarray['employee'][] = $query_emp;
            $emp_id_query = $callConfig->getAllRows($query_emp);
            foreach ($emp_id_query as $eidvalue) {
                $selected_employees[$eidvalue->id] = $eidvalue;
            }
            $prevyear_monthwise_headcount[$i] = $empdatas->headcount;
        }
        for ($i = 1; $i <= 12; $i++) {
            if ($i > $monthNo) {
                $curyear_monthwise_headcount[$i] = 0;
            } else {
                $ldate = $year . "-" . sprintf('%02s', $i) . "-31";
                $query = self::USER_SQL_SELECT_COUNT_ID_AS_HEADCOUNT_F . $ldate . "') as date_of_leaving  FROM `employees`) as td ";
                $empdatas = $callConfig->getRow($query);
                $returnarray['headcount2'][] = $query;
                $query_emp = "SELECT id,display_name,designation_id,department_id,joining_date,employment_category_id,location_id  FROM `employees` WHERE company_id='" . $get['company_id'] . "' AND employee_type =1 AND is_active =0 " . $appendcondtion;
                $returnarray['employee2'][] = $query_emp;
                $emp_id_query = $callConfig->getAllRows($query_emp);
                foreach ($emp_id_query as $eidvalue) {
                    $selected_employees[$eidvalue->id] = $eidvalue;
                }
                $curyear_monthwise_headcount[$i] = $empdatas->headcount;
            }
        }
        $details['years'] = array($year, $prev_year);
        $details['curyear_monthwise_headcount'] = $curyear_monthwise_headcount;
        $details['prevyear_monthwise_headcount'] = $prevyear_monthwise_headcount;
        $details['Total_Head_Count'] = $curentyear_totalheadcount + $prevyear_totalheadcount;
        $details['Total_Head_Count_CurrentYear'] = $curentyear_totalheadcount - $prevyear_totalheadcount;
        $details['Total_Head_Count_PrevYear'] = $prevyear_totalheadcount;
        $details['selected_employees'] = $selected_employees;
        $query_1 = "SELECT *  FROM `employment_categories` WHERE company_id='" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
        $empdatas1 = $callConfig->getAllRows($query_1);
        foreach ($empdatas1 as $value1) {
            $query1 = "SELECT count(id) as headcount  FROM `employees` WHERE employment_category_id=" . $value1->id . self::USER_SQL_AND_COMPANY_ID_2 . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
            $empresult = $callConfig->getRow($query1);
            $empcategorywise_headcount[$value1->category_name] = $empresult->headcount;
            $employment_category[$value1->id] = $value1->category_name;
        }
        $details['empcategorywise_headcount'] = $empcategorywise_headcount;
        $query_2 = "SELECT *  FROM `divisions` WHERE company_id='" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
        $empdatas2 = $callConfig->getAllRows($query_2);
        foreach ($empdatas2 as $valuediv) {
            $divisions[$valuediv->id] = $valuediv->division_name;
            $query_dept = self::USER_SQL_SELECT_FROM_DEPARTMENTS_WHERE_ . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
            $deparmentsql = $callConfig->getAllRows($query_dept);
            foreach ($deparmentsql as $value2) {
                $query2 = self::USER_SQL_SELECT_COUNT_ID_AS_HEADCOUNT_F_1 . $value2->id . self::USER_SQL_AND_COMPANY_ID_2 . $get['company_id'] . "' and is_active =0 and department_id in (select id from departments where division_id=" . $valuediv->id . ")";
                $empresult = $callConfig->getRow($query2);
                $divisionwise_headcount[$valuediv->id][$value2->department_name] = $empresult->headcount;
            }
        }
        $details['division_list'] = $divisions;
        $details['divisionwise_headcount'] = $divisionwise_headcount;
        $query_3 = "SELECT *  FROM `locations` WHERE company_id='" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
        $empdatas3 = $callConfig->getAllRows($query_3);
        foreach ($empdatas3 as $value3) {
            $query3 = "SELECT count(id) as headcount  FROM `employees` WHERE location_id=" . $value3->id . self::USER_SQL_AND_COMPANY_ID_2 . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
            $empresult = $callConfig->getRow($query3);
            $locationwise_headcount[$value3->location_name] = $empresult->headcount;
            $location[$value3->id] = $value3->location_name;
        }
        $details['locationwise_headcount'] = $locationwise_headcount;
        $quer_4 = self::USER_SQL_SELECT_FROM_DEPARTMENTS_WHERE_ . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
        $empdatas4 = $callConfig->getAllRows($quer_4);
        foreach ($empdatas4 as $value4) {
            $query4 = self::USER_SQL_SELECT_COUNT_ID_AS_HEADCOUNT_F_1 . $value4->id . self::USER_SQL_AND_COMPANY_ID_2 . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
            $empresult = $callConfig->getRow($query4);
            $departmentwise_headcount[$value4->department_name] = $empresult->headcount;
            $department[$value4->id] = $value4->department_name;
        }
        $details['departmentwise_headcount'] = $departmentwise_headcount;
        $details['locations'] = $location;
        $details['departments'] = $department;
        $quer_5 = self::USER_SQL_SELECT_FROM_DESIGNATIONS_WHERE . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
        $empdatas5 = $callConfig->getAllRows($quer_5);
        foreach ($empdatas5 as $value5) {
            $designation[$value5->id] = $value5->designation_name;
        }
        $quer_6 = "SELECT *  FROM `job_titles` WHERE company_id='" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
        $empdatas6 = $callConfig->getAllRows($quer_6);
        foreach ($empdatas6 as $value6) {
            $jobtitles[$value6->id] = $value6->job_title;
        }

        $quer_7 = "SELECT *  FROM `cost_centers` WHERE company_id='" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_2;
        $empdatas7 = $callConfig->getAllRows($quer_7);
        foreach ($empdatas7 as $value7) {
            $costcenter[$value7->id] = $value7->cost_center_name;
        }

        if (isset($get['fromdatetimesheet'])) {
            $quer_8 = self::USER_SQL_SELECT_COUNT_DISTINCT_TIMESHEE . $get['fromdatetimesheet'] . self::USER_LIT_AND_TIMESHEET_DATE . $get['todatetimesheet'] . self::USER_LIT_AND_IS_ACTIVE_0_GROUP_BY_EMP_I;
        } else {
            $startdate = date("Y-m-d", strtotime(self::USER_LIT_MONDAY_THIS_WEEK, strtotime(date('Y-m-d'))));
            $enddate = date("Y-m-d", strtotime(self::USER_LIT_SUNDAY_THIS_WEEK, strtotime(date('Y-m-d'))));
            $quer_8 = self::USER_SQL_SELECT_COUNT_DISTINCT_TIMESHEE . $startdate . self::USER_LIT_AND_TIMESHEET_DATE . $enddate . self::USER_LIT_AND_IS_ACTIVE_0_GROUP_BY_EMP_I;
        }
        $empdatas8 = $callConfig->getAllRows($quer_8);
        foreach ($empdatas8 as $value8) {
            $projecttimesheets[$value8->emp_id] = $value8->cnt;
        }
        $details['designations'] = $designation;
        $details['employment_categories'] = $employment_category;
        $details['job_titles'] = $jobtitles;
        $details['costcenter'] = $costcenter;
        $details['project_timesheets'] = $projecttimesheets;

        return $details;
    }
    public function getLitsAttendancesApi($get)
    {
        global $callConfig;
        $empidlist = array($get['emp_id'] => $get['emp_id']);
        $month = $get['month'];
        $year = $get['year'];
        $attstc = "SELECT * FROM attendance_settings WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_IS_ACTIVE_0_1;
        $atsdata = $callConfig->getRow($attstc);
        $workingdays = json_decode($atsdata->working_days, 1);

        $shiftkeys = "SELECT * FROM attendance_key_types WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_IS_ACTIVE_0_1;
        $shiftkeysdata = $callConfig->getAllRows($shiftkeys); // working //absent
        foreach ($shiftkeysdata as $svalue) {
            $shift[$svalue->key_short_code] = (array) $svalue;
        }

        $attendancesql = "SELECT *  FROM `employee_daily_attendances` WHERE company_id=" . $get['company_id'] . " AND employee_id='" . $get['emp_id'] . "' AND  (attendace_date >= concat('" . $year . "-" . $month . "-01') AND attendace_date <= last_day(concat('" . $year . "-" . $month . "-01'))) AND is_active=0";
        $attendanceres = $callConfig->getAllRows($attendancesql); // working //absent
        foreach ($attendanceres as $attendancere) {
            $attendacnearray[$attendancere->employee_id][$attendancere->attendace_date] = $attendancere;
        }
        $leavessql = "select employee_id,leave_from,leave_to,leave_type_id,start_half_day,end_half_day,datelist
    from employee_leaves,
    (select adddate('1970-01-01',t4.i*10000 + t3.i*1000 + t2.i*100 + t1.i*10 + t0.i) datelist from
    (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t0,
    (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t1,
    (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t2,
    (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t3,
    (select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t4) as v
    where datelist>=leave_from and datelist <=leave_to AND employee_id = '" . $get['emp_id'] . "' AND ((MONTH(leave_from) = '" . $month . "' AND YEAR(leave_from) = '" . $year . "') OR (MONTH(leave_to) = '" . $month . "' AND YEAR(leave_to) = '" . $year . "') )";
        $leavesdetails = $callConfig->getAllRows($leavessql); // working //absent
        foreach ($leavesdetails as $leavesdetail) {
            $leavesdetailsarray[$leavesdetail->employee_id][$leavesdetail->datelist] = array('type' => $leavesdetail->leave_type_id, 'start_half_day' => $leavesdetail->start_half_day, 'end_half_day' => $leavesdetail->end_half_day);
        }
        $holidays = "SELECT holiday_date FROM holidays WHERE company_id=" . $get['company_id'] . " AND MONTH(holiday_date) = '" . $month . "' AND YEAR(holiday_date) = '" . $year . "' AND is_active=0 ";
        $holidaysdata = $callConfig->getAllRows($holidays); //holidays
        foreach ($holidaysdata as $hvalue) {
            $holidaysdatas[] = $hvalue->holiday_date;
        }
        $enterdate = date("Y-m-d");
        if ($get['reprt_type'] == "W") {
            $startdate = date("Y-m-d", strtotime(self::USER_LIT_MONDAY_THIS_WEEK, strtotime($enterdate)));
            $enddate = date("Y-m-d", strtotime(self::USER_LIT_SUNDAY_THIS_WEEK, strtotime($enterdate)));
        } elseif ($get['reprt_type'] == "M") {
            $startdate = date("Y-m" . "-01", strtotime($enterdate));
            $enddate = date("Y-m-t", strtotime($enterdate));
        } else {
            $startdate = $enterdate;
            $enddate = $enterdate;
        }
        $i = 0;
        foreach ($empidlist as $ky => $emp) {
            $monthworkingdays = 0;
            $actualworkingdays = 0;
            $start = new DateTime($startdate);
            $end = new DateTime($enddate);
            $dates = array();
            $timeshettempoyee = array();
            $tempdetailary = array();
            $retrunarray['valuedisplaytype'] = "update";
            while ($start <= $end) {
                $date = $start->format('Y-m-d');
                $dy = $start->format('l');
                if (in_array($date, (array) $holidaysdatas)) {
                    $dates[$date] = array('day' => 'H', 'date' => $date, 'billable_hrs' => $timeshettempoyee[$date]['billable_hrs'], 'timesheetid' => $timeshettempoyee[$date]['id'], 'color_code' => $shift['H']['color_code'], 'display_value' => $shift['H']['display_value'], 'key_name' => $shift['H']['key_name'], 'key_bgcolor' => $shift['H']['key_bgcolor']);
                } elseif (!in_array($dy, (array) $workingdays)) {
                    $dates[$date] = array('day' => 'O', 'date' => $date, 'billable_hrs' => $timeshettempoyee[$date]['billable_hrs'], 'timesheetid' => $timeshettempoyee[$date]['id'], 'color_code' => $shift['O']['color_code'], 'display_value' => $shift['O']['display_value'], 'key_name' => $shift['O']['key_name'], 'key_bgcolor' => $shift['O']['key_bgcolor']);
                } elseif (isset($attendacnearray[$ky][$date]) && isset($leavesdetailsarray[$ky][$date])) {
                    $dates[$date] = array('day' => 'V', 'date' => $date, 'billable_hrs' => $timeshettempoyee[$date]['billable_hrs'], 'timesheetid' => $timeshettempoyee[$date]['id'], 'color_code' => $shift['V']['color_code'], 'display_value' => $shift['V']['display_value'], 'strthalfday' => $tempdetailary[$ky][$date]['start_half_day'], 'endthalfday' => $tempdetailary[$ky][$date]['end_half_day'], 'working_color' => $shift['W']['color_code'], 'key_name' => $shift['V']['key_name'], 'key_bgcolor' => $shift['V']['key_bgcolor']);
                    $discrepancy[$ky] = $emp;
                    $monthworkingdays++;
                    $actualworkingdays++;
                } elseif (isset($attendacnearray[$ky][$date])) {
                    $monthworkingdays++;
                    $actualworkingdays++;
                    $dates[$date] = array('day' => 'W', 'date' => $date, 'billable_hrs' => $timeshettempoyee[$date]['billable_hrs'], 'timesheetid' => $timeshettempoyee[$date]['id'], 'color_code' => $shift['W']['color_code'], 'display_value' => $shift['W']['display_value'], 'start' => $attendacnearray[$ky][$date]->clock_in, 'end' => $attendacnearray[$ky][$date]->clock_out, 'key_name' => $shift['W']['key_name'], 'key_bgcolor' => $shift['W']['key_bgcolor']);
                } else {
                    if (isset($leavesdetailsarray[$ky][$date])) {
                        $monthworkingdays++;
                        $actualworkingdays++;
                        if ($leavesdetailsarray[$ky][$date]['type'] == '6') {
                            $dates[$date] = array('day' => 'S', 'date' => $date, 'billable_hrs' => $timeshettempoyee[$date]['billable_hrs'], 'timesheetid' => $timeshettempoyee[$date]['id'], 'color_code' => $shift['S']['color_code'], 'display_value' => $shift['S']['display_value'], 'strthalfday' => $leavesdetailsarray[$ky][$date]['start_half_day'], 'endthalfday' => $leavesdetailsarray[$ky][$date]['end_half_day'], 'working_color' => $shift['W']['color_code'], 'key_name' => $shift['W']['key_name'], 'key_bgcolor' => $shift['W']['key_bgcolor']);
                            $discrepancy[$ky] = $emp;
                        } else {
                            $dates[$date] = array('day' => 'V', 'date' => $date, 'billable_hrs' => $timeshettempoyee[$date]['billable_hrs'], 'timesheetid' => $timeshettempoyee[$date]['id'], 'color_code' => $shift['V']['color_code'], 'display_value' => $shift['V']['display_value'], 'strthalfday' => $tempdetailary[$ky][$date]['start_half_day'], 'endthalfday' => $tempdetailary[$ky][$date]['end_half_day'], 'working_color' => $shift['W']['color_code'], 'key_name' => $shift['W']['key_name'], 'key_bgcolor' => $shift['W']['key_bgcolor']);
                            $discrepancy[$ky] = $emp;
                        }
                    } else {
                        $monthworkingdays++;
                        $dates[$date] = array('day' => 'A', 'date' => $date, 'billable_hrs' => $timeshettempoyee[$date]['billable_hrs'], 'timesheetid' => $timeshettempoyee[$date]['id'], 'color_code' => $shift['A']['color_code'], 'display_value' => $shift['A']['display_value'], 'key_name' => $shift['A']['key_name'], 'key_bgcolor' => $shift['A']['key_bgcolor']);
                        $discrepancy[$ky] = $emp;
                    }
                }
                if ($i == '0') {
                    $alldate[] = $date;
                }
                $start->modify(self::USER_LIT_1_DAYS);
            }
        }
        $retrunarray['timesheet'] = $dates;
        $retrunarray['emplist'] = $empidlist;
        return $retrunarray;
    }


    public function getLeaveWithStatus($data)
    {
        global $callConfig;
        $return = array();
        $emp_listtsql = "SELECT emp.id,emp.emp_code,emp.display_name,emp.image,( SELECT department_name FROM `departments` dep WHERE dep.is_active=emp.is_active AND dep.company_id = emp.company_id AND dep.id = emp.department_id ) department_name,( SELECT designation_name FROM `designations` des WHERE des.is_active=emp.is_active AND des.company_id = emp.company_id AND des.id = emp.designation_id ) designation_name  FROM `employees` emp where emp.is_active='0' AND  emp.company_id = '" . $data['company_id'] . "'";
        $emp_listtlist = $callConfig->getAllRows($emp_listtsql);
        foreach ($emp_listtlist as $emp_listtlist) {
            $emp_list[$emp_listtlist->id] = $emp_listtlist;
        }
        if ($data['emp_id'] != "") {
            $condition = " AND employee_id = '" . $data['emp_id'] . "'";
