            $condition = " AND ID IN(SELECT transaction_id FROM `transaction_approval_logs` WHERE transaction_table = 'employee_leavesself::USER_SQL_AND_USER_ID" . $data['user_id'] . "' AND response_type='0')";

        }



        $sql = "SELECT * FROM `employee_leaves` WHERE is_active='0' AND  company_id = '" . $data['company_id'] . "' " . $condition;
