            if ($data['user_id'] != $created_by) {
                $str = '9002 - createby';
            }
        }
        if (count((array) $lists) == 0) {
            $str = '9003';
        }
        $pass_data['view_status'] = $str;
        return $pass_data;
    }
    public function insertFeeds($post)
    {
        global $callConfig;
        $post['year'] = date("Y");
        $sql = "SELECT id FROM `feeds` WHERE sending_emp_id='" . $post['sending_emp_id'] . self::USER_LIT_AND_RECEIVING_EMP_ID . $post['receiving_emp_id'] . "' AND birthday_anniversary_type = '" . $post['birthday_anniversary_type'] . self::USER_LIT_AND_IS_ACTIVE_0_AND_COMPANY_ID_2 . $post['company_id'] . "'";
        $feedlist = $callConfig->getRow($sql);
        $returnarray["sql"] = $sql;
        if (isset($feedlist->id)) {
            $post['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
            $post['is_active'] = '0';
            $post['current_status'] = '0';
            $post['updated_by'] = $post['user_id'];
            unset($post['user_id']);
            $res = $callConfig->updateRecord('feeds', $post, 'id', $feedlist->id);
            $returnarray["status"] = "old";
            $returnarray["respons"] = $res;
        } else {
            $post['created_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
            $post['is_active'] = '0';
            $post['current_status'] = '0';
            $post['created_by'] = $post['user_id'];
            unset($post['user_id']);
            $res = $callConfig->insertRecord('feeds', $post);
            $returnarray["status"] = "new";
            $returnarray["respons"] = $res;
        }
        $commentsql = "SELECT count(id) as cnt FROM `feeds` WHERE msg_type='1' AND birthday_anniversary_type = '" . $post['birthday_anniversary_type'] . self::USER_LIT_AND_RECEIVING_EMP_ID . $post['receiving_emp_id'] . "' AND year='" . $post['year'] . self::USER_LIT_AND_IS_ACTIVE_0_AND_COMPANY_ID_2 . $post['company_id'] . "'";
        $commentsum = $callConfig->getRow($commentsql);
        $returnarray["sum_comments"] = $commentsum->cnt;
        $likesql = "SELECT count(id) as cnt FROM `feeds` WHERE like_type='1' AND birthday_anniversary_type = '" . $post['birthday_anniversary_type'] . self::USER_LIT_AND_RECEIVING_EMP_ID . $post['receiving_emp_id'] . "' AND year='" . $post['year'] . self::USER_LIT_AND_IS_ACTIVE_0_AND_COMPANY_ID_2 . $post['company_id'] . "'";
        $likesum = $callConfig->getRow($likesql);
        $returnarray["sum_like"] = $likesum->cnt;
        $returnarray["post"] = $post;
        return $returnarray;
    }

