    public function getStockTakes($data)
    {
        global $callConfig;
        $stocktakes = "SELECT * FROM stocktakes WHERE is_active =0 AND company_id = '" . $data['company_id'] . self::USER_LIT_AND_ID_5 . $data['Rid'] . "'";
