            $insert_array = array('company_id' => $data['company_id'], 'stocktake_id' => $data['stocktake_id'], 'item_id' => $data['item_id'], 'uom_details' => $data['uom_details'], 'location_id' => $data['location_id']);
            if (isset($check_i->id)) {
                $insert_array['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
                $insert_array['updated_by'] = $data['user_id'];
                $where = self::USER_LIT_ID . $check_i->id . "'";
                $res = $callConfig->updateRecord("stocktake_items", $insert_array, "", "", $where);
                $returnresult['update'] = $res;
            } else {
                $insert_array['is_active'] = '0';
                $insert_array['created_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
                $insert_array['created_by'] = $data['user_id'];
                $insert_array['current_status'] = '0';
                $res = $callConfig->insertRecord('stocktake_items', $insert_array);
                $returnresult['insert'] = $res;
            }
        } else {
            if ($data['status'] != '3') {
                foreach ($data['item_id'] as $item_key => $item_value) {
                    $inserts_task['status'] = $data['status'];
                    $callConfig->updateRecord('stocktakes', $inserts_task, 'id', $data['stocktake_id']);
                    if ($data['count_qty'][$item_key] != "") {
                        $check_isql = self::USER_SQL_SELECT_ID_FROM_STOCKTAKE_ITEMS . $data['company_id'] . self::USER_LIT_AND_STOCKTAKE_ID . $data['stocktake_id'] . self::USER_LIT_AND_ITEM_ID_4 . $item_value . self::USER_LIT_AND_LOCATION_ID . $data['location_id'][$item_key] . "'";
                        $check_i = $callConfig->getRow($check_isql);
                        $insert_array = array('company_id' => $data['company_id'], 'stocktake_id' => $data['stocktake_id'], 'item_id' => $item_value, 'uom_details' => $data['uom_details'][$item_key], 'count_qty' => $data['count_qty'][$item_key], 'location_id' => $data['location_id'][$item_key]);

                        if (isset($check_i->id)) {
                            $insert_array['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
                            $insert_array['updated_by'] = $data['user_id'];
                            $where = self::USER_LIT_ID . $check_i->id . "'";
                            $res = $callConfig->updateRecord("stocktake_items", $insert_array, "", "", $where);
                            $returnresult['update'] = $res;
                        } else {
                            $insert_array['is_active'] = '0';
                            $insert_array['created_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
                            $insert_array['created_by'] = $data['user_id'];
                            $insert_array['current_status'] = '0';
                            $res = $callConfig->insertRecord('stocktake_items', $insert_array);
                            $returnresult['insert'] = $res;
                        }
                    }
                }
            } else {
                $returnresult['completed'][] = $this->getStockTakeAdjustments($data);
            }
        }
        return $returnresult;
    }
