    public function getStockTakeAdjustments($data)
    {
        global $callConfig;
        $inserts_task['status'] = '3';
        $inserts_task['completed_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
        $callConfig->updateRecord('stocktakes', $inserts_task, 'id', $data['stocktake_id']);
        $ddf = array();
        $insert_id = $data['stocktake_id'];
        $document_ref_no = $data['transaction_number'];
        $table = 'stocktakes';
        foreach ($data['item_id'] as $item_key => $item_value) {
            $insert_array = array('system_qty' => $data['system_qty'][$item_key], 'variance' => $data['available_qty'][$item_key], 'updated_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'updated_by' => $data['user_id']);
            $mainitem = $this->togetitemvalues($item_value);
            $day_rate = $this->togetitemwadayrate($item_value, $data['company_id']);
            if ($data['available_qty'][$item_key] != "0" && $data['substoktakecheck'][$item_key] == "0") {
                $sale_price = $data['sale_price'][$item_key];
                $purchase_price = $data['purchase_price'][$item_key];
                $sale_value = $sale_price * abs($data['available_qty'][$item_key]);
                $len = array('company_id' => $data['company_id'], 'location_id' => $data['location_id'][$item_key], 'transaction_date' => date('Y-m-d'), 'item_id' => $item_value, 'document_no' => $insert_id, 'document_type' => $table, 'document_ref_no' => $document_ref_no, 'item_in_value' => $mainitem->purchase_price * abs($data['available_qty'][$item_key]), 'sale_price' => $sale_price, 'sale_value' => $sale_value, 'item_wa_cost' => $day_rate, 'item_st_cost' => $mainitem->purchase_price);
                if ($data['available_qty'][$item_key] < 0) {
                    $len['out_qty'] = abs($data['available_qty'][$item_key]);
                    $len['out_value'] = $sale_price;
                    $len['reason_id'] = '1';
                } else {
                    $len['in_qty'] = abs($data['available_qty'][$item_key]);
                    $len['in_value'] = $purchase_price;
                    $len['reason_id'] = '0';
                }
                $insert_array['update_balance'] = "Y";
            }
            $check_isql = self::USER_SQL_SELECT_ID_FROM_STOCKTAKE_ITEMS . $data['company_id'] . self::USER_LIT_AND_STOCKTAKE_ID . $data['stocktake_id'] . self::USER_LIT_AND_ITEM_ID_4 . $item_value . self::USER_LIT_AND_LOCATION_ID . $data['location_id'][$item_key] . "'";
            $check_i = $callConfig->getRow($check_isql);
            $where = self::USER_LIT_ID . $check_i->id . "'";
            $callConfig->updateRecord("stocktake_items", $insert_array, "", "", $where);
        }
        return $ddf;
    }
    public function getStockTakeLocations($data)
    {
        global $callConfig;
        $location = "SELECT DISTINCT iloc.location_id, (SELECT loc.location_name FROM locations loc WHERE iloc.is_active = loc.is_active AND iloc.company_id = loc.company_id AND iloc.location_id = loc.id) as location_name  FROM  item_locations iloc  WHERE iloc.item_id IN(" . $data['selectitems'] . ") AND  is_active =0 AND company_id = '" . $data['company_id'] . "'";
        return $callConfig->getAllRows($location);
    }
    public function softDeletedRecord($data)
    {
        global $callConfig;
        $insert_array = array('is_active' => null);
        $where = self::USER_LIT_ID . $data['id'] . "'";
        $res = $callConfig->updateRecord($data['table'], $insert_array, "", "", $where);
        if ($data['table'] == 'building_floors') {
            $removeequipment_allocations = "UPDATE `equipment_allocations` SET is_active = null WHERE company_id = '" . $data['company_id'] . "' AND building_floor_space_id IN(SELECT id FROM `building_floor_spaces` WHERE company_id = '" . $data['company_id'] . "' AND building_floor_id = '" . $data['id'] . "' AND is_active = 0) AND is_active = 0";
            $callConfig->executeQuery($removeequipment_allocations);

            $removebuilding_floor_spaces = "UPDATE `building_floor_spaces` SET is_active = null WHERE company_id = '" . $data['company_id'] . "' AND building_floor_id = '" . $data['id'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $callConfig->executeQuery($removebuilding_floor_spaces);
        } elseif ($data['table'] == 'building_floor_spaces') {

            $removeequipment_allocations = "UPDATE `equipment_allocations` SET is_active = null WHERE company_id = '" . $data['company_id'] . "' AND building_floor_space_id  = '" . $data['id'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $callConfig->executeQuery($removeequipment_allocations);

        }

        return $res;
    }

    /***********End Stock takes***************/



    public function dateconvertdbformat($date)
    {
        $dateformat = "";
        if ($date != "") {
            $datesplit = str_replace('/"', '-', $date);
            $dateformat = date('Y-m-d', strtotime($datesplit));
        }
        return $dateformat;
    }
    public function getJobPostings($get)
    {
        global $callConfig;
        $returnresult = array();

        // Sanitize inputs
        $company_id = (int) $get['company_id'];
        $rid = (int) $get['rid'];

        // 1. Job Postings
        $job_postingssql = "SELECT * FROM job_postings WHERE is_active = 0 AND company_id = ? AND id = ?";
        $returnresult['job_postings'] = $callConfig->getRowNew($job_postingssql, [$company_id, $rid]);

        // 2. Application Tags
        $application_tagssql = "SELECT * FROM application_tags WHERE company_id = ? AND application_table_name = 'job_postings' AND transaction_id = ?";
        $returnresult['application_tags'] = $callConfig->getAllRowsNew($application_tagssql, [$company_id, $rid]);

        // 3. Job Titles
        $job_titlesql = "SELECT id, job_title, job_description FROM job_titles WHERE is_active = 0 AND company_id = ?";
        $returnresult['job_titles'] = $callConfig->getAllRowsNew($job_titlesql, [$company_id]);

        // 4. Locations
        $locationssql = "SELECT id, location_name FROM locations WHERE is_active = 0 AND company_id = ?";
        $returnresult['locations'] = $callConfig->getAllRowsNew($locationssql, [$company_id]);

        // 5. Application Users
        $application_userssql = "SELECT id, display_name, role_id FROM application_users WHERE is_active = 0 AND company_id = ?";
        $returnresult['application_users'] = $callConfig->getAllRowsNew($application_userssql, [$company_id]);

        // 6. Departments
        $departmentssql = "SELECT id, department_name FROM departments WHERE is_active = 0 AND company_id = ?";
        $returnresult['departments'] = $callConfig->getAllRowsNew($departmentssql, [$company_id]);

        // 7. ESGIN Budget Approvals
        $esgin_budget_approvalssql = "SELECT id, transaction_number FROM esgin_budget_approvals WHERE is_active = 0 AND company_id = ?";
        $returnresult['esgin_budget_approvals'] = $callConfig->getAllRowsNew($esgin_budget_approvalssql, [$company_id]);

        // 8. Job Selection Process
        $job_selection_processsql = "SELECT id, process_name FROM job_selection_process WHERE is_active = 0 AND company_id = ?";
        $returnresult['job_selection_process'] = $callConfig->getAllRowsNew($job_selection_processsql, [$company_id]);

        // 9. Job Grade
        $job_gradesql = "SELECT id, job_grade_name FROM job_grade WHERE is_active = 0 AND company_id = ?";
        $returnresult['job_grade'] = $callConfig->getAllRowsNew($job_gradesql, [$company_id]);

        // 10. Customers
        $customerssql = "SELECT id, display_name FROM customers WHERE is_active = 0 AND company_id = ?";
        $returnresult['customers'] = $callConfig->getAllRowsNew($customerssql, [$company_id]);

        return $returnresult;
    }
