        $logsql = "SELECT user_id,response_type FROM `transaction_approval_logs` WHERE company_id = '" . $get['company_id'] . "' AND  transaction_table = '" . $get['table'] . self::USER_LIT_AND_TRANSACTION_ID . $get['rid'] . "' AND send_back_flag = 0";
        $logres = $callConfig->getAllRows($logsql);
        foreach ($logres as $logres0) {
            $logresar[$logres0->response_type] = $logres0->user_id;
        }

        $workfsql = "SELECT workflow_id,process_type,approve_update_status FROM `workflow_configuration_histories` WHERE company_id = '" . $get['company_id'] . "' AND process_type = '" . $get['table'] . self::USER_LIT_AND_TRANSACTION_ID . $get['rid'] . "'";
        $workfres = $callConfig->getRow($workfsql);
        $statussteps = json_decode($workfres->approve_update_status, 1);
        $returnarray['status'] = $statussteps;
        $returnarray['workflow_id'] = $logdetails->workflow_id;
        $statsu_progressql = "select status,action_label from status_progress where table_name='" . $get['table'] . self::USER_LIT_AND_COMPANY_ID_2 . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_12;
        $statsu_progresres = $callConfig->getAllRows($statsu_progressql);
        $status = array();
        $statustep = array();
        foreach ($statsu_progresres as $statsu_progresre) {
            $status[$statsu_progresre->status] = $statsu_progresre->action_label;
        }
        foreach ($statussteps as $statusstepr) {
            $statusstepr['action_label'] = $status[$statusstepr['status']];
            $statustep[] = $statusstepr;
        }
        return array("steps" => $statustep, "log" => $logresar);
    }
