    public function togettransactionlogempitdeclaration($get)
    {
        global $callConfig;
        $empquery = "SELECT id, emp_code, display_name, email_id FROM employees WHERE company_id =" . $get['company_id'] . " AND id IN ( SELECT employee_id FROM employee_buddies WHERE finance_buddy =" . $get['emp_id'] . ")";
        $emp_data = $callConfig->getAllRows($empquery);
        $query = "SELECT * FROM transaction_approval_logs WHERE company_id =" . $get['company_id'] . " AND  user_id=" . $get['user_id'] . " AND transaction_table = 'emp_it_declaration' ";
        $mydata = $callConfig->getAllRows($query);
        foreach ($mydata as $data) {
            $ids[] = $data->transaction_id;
        }
        $query = "SELECT * FROM emp_it_declaration  WHERE company_id =" . $get['company_id'] . " AND id IN (" . implode(",", (array) $ids) . ") AND is_active=0 ";
        $tabledata = $callConfig->getAllRows($query);
        return array('emp_data' => $emp_data, 'transaction' => $mydata, 'data' => $tabledata);
    }
