    public function getCandidates($get)
    {
        global $callConfig;
        $condition = "";
        $sortby = " ORDER BY display_name ASC";
        $limit = "LIMIT 10";

        if ($get['filter'] == "Y") {
            if ($get['location_id'] != "") {
                $condition .= " AND location_id = '" . $get['location_id'] . "'";
            }
            if ($get['job_tittle_id'] != "" && !empty(json_decode($get['job_tittle_id']))) {
                $decod = json_decode($get['job_tittle_id'], 1);
                $json = implode(',', (array) $decod);
                $condition .= " AND job_tittle_id  IN(" . $json . ")";
            }
            if ($get['gender'] != "" && !empty(json_decode($get['gender']))) {
                $decod = json_decode($get['gender'], 1);
                $json = implode("','", (array) $decod);
                $condition .= " AND gender  IN('" . $json . "')";
            }
            if ($get['job_type'] != "" && !empty(json_decode($get['job_type']))) {
                $decod = json_decode($get['job_type'], 1);
                $json = implode("','", (array) $decod);
                $condition .= " AND job_type  IN('" . $json . "')";
            }
            if ($get['alphabet'] != "") {
                $condition .= " AND display_name like '" . $get['alphabet'] . "%'";
            }

            if ($get['expected_ctc_start'] != "" && $get['expected_ctc_end'] != "") {
                $condition .= " AND expected_ctc >= " . $get['expected_ctc_start'] . " AND expected_ctc <=" . $get['expected_ctc_end'];
            }
            if ($get['total_experiance_start'] != "" && $get['total_experiance_end'] != "") {
                $condition .= " AND total_experiance >= " . $get['total_experiance_start'] . " AND total_experiance <=" . $get['total_experiance_end'];
            }
            if ($get['skill'] != "" && !empty(json_decode($get['skill']))) {
                $decod = json_decode($get['skill'], 1);
                foreach ($decod as $decods) {
                    $condition .= " AND skills LIKE '" . '%"' . $decods . '"%' . "'";
                }
            }
            if ($get['sort_by'] != "") {
                $sortby = " ORDER BY " . $get['sort_by'] . " ASC ";
            }
            if ($get['limit'] != "") {
                $limit = " limit " . $get['limit'];
            }

            if ($get['perfect_match'] != "0") {
                $condition = "";
            }

        }
        $candidatessql = "SELECT * FROM candidates WHERE company_id='" . $get['company_id'] . "' " . $condition . " AND is_active='0' " . $sortby . " " . $limit;
        $candidatesres = $callConfig->getAllRows($candidatessql);
        $return['candidates'] = $candidatesres;
        $return['sql'] = $candidatessql;

        $locationssql = "SELECT id,location_name FROM locations WHERE company_id='" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_4;
