    public function sendNotificationAndEmails($notarry, $emailarray, $actionid)
    {
        global $callConfig;
        if ($actionid != "" && count((array) $emailarray) != 0 && $emailarray != "") {
            if ($emailarray['databasename'] != "") {
                $databasename = $emailarray['databasename'] . ".";
            }

            $default_module_id = $emailarray['default_module_id'] != "" ? $emailarray['default_module_id'] : $callConfig->module_id;
            $query2 = "SELECT ec.template_reference_id,ec.template_type_id, ec.id,ec.email_id_cc,ec.email_id_to,ec.template_reference_id FROM " . $databasename . "email_content ec WHERE ec.company_id = '" . $emailarray['session_company_id'] . "' AND ec.template_reference_id = '" . $actionid . "' AND (ec.application_module = '" . $default_module_id . "' OR module_check = 1) AND ec.is_active = 0 ";
            $actionemailsettings = $callConfig->getRow($query2);
            $emailarray['email_content_ref_id'] = $actionid;
            $emailarray['email_template'] = $actionemailsettings->template_type_id;
            $emailarray['email_content_id'] = $actionemailsettings->template_reference_id;
            $emailarray['email_address_cc'] = $actionemailsettings->email_id_cc;
            $emailarray['email_address_to'] = $actionemailsettings->email_id_to;
            $emailarray['this_year'] = date("Y");
            $emailarray['date'] = date(self::USER_LIT_D_M_Y_1);
            $emailarray['send_email'] = $this->sendEmails($emailarray);

        }
        if (count((array) $notarry) != '0' && $notarry != "") {
            $this->tosendnotifiations($notarry);
        }
        return $emailarray;
    }
    public function sendEmails($emailarray)
    {
        global $callConfig;
        if ($emailarray['databasename'] != "") {
            $databasename = $emailarray['databasename'] . ".";
        }
        $emailarray['super_admin_email_id'] = SUPERADMIN_EMAIL_ID;
        $emailarray['super_admin_company_name'] = SUPERADMIN_COMPNAY_NAME;
        $emailarray['super_admin_display_name'] = SUPERADMIN_DISLAY_NAME;

        if ($callConfig->module_id != "") {
            $msql = "SELECT role_admin_short_code FROM " . $databasename . "module_setup where module_id = '" . $callConfig->module_id . "'";
            $module_setupres = $callConfig->getRow($msql);
        }
        if ($module_setupres->role_admin_short_code != "") {
            $adminsersql = "SELECT au.id, au.display_name, au.user_email, au.user_mobile, comp.name FROM " . $databasename . "application_users au, " . $databasename . "companies comp WHERE au.company_id = '" . $emailarray['session_company_id'] . self::USER_LIT_AND_AU_COMPANY_ID_COMP_ID_AND_ . '%"' . $module_setupres->role_admin_short_code . '"%' . "'";

            $adminserres = $callConfig->getRow($adminsersql);
        } else {
            $adminsersql = "SELECT au.id, au.display_name, au.user_email, au.user_mobile, comp.name FROM " . $databasename . "application_users au, " . $databasename . "companies comp WHERE au.company_id = '" . $emailarray['session_company_id'] . self::USER_LIT_AND_AU_COMPANY_ID_COMP_ID_AND_ . '%"' . ADMIN_ROLES . '"%' . "'";

            $adminserres = $callConfig->getRow($adminsersql);
        }
        $emailarray['admin_email_sql'] = $adminsersql;
        $emailarray['admin_email_id'] = $adminserres->user_email;
        $emailarray['admin_company_name'] = $adminserres->name;
        $emailarray['company_name'] = $adminserres->name;
        $emailarray['admin_display_name'] = $adminserres->display_name;
        $emailarray['admin_phone_number'] = $adminserres->user_mobile;
        if ($emailarray['email_address_to'] != "") {
            $emailarray['email_send_type'] = "TO";
            $email_array = $this->emailtemplate($emailarray);
            $file_name = 'email' . '_' . time() . uniqid() . '.' . 'html';
            $email_array['content'] = $file_name;
            $email_array['revicer'] = array($this->emaildatareplace($emailarray, $emailarray['email_address_to']));

            $email_array['email_type'] = 1;
            $email = $email_array['mesg'];
            $email_array['email_content_ref_id'] = $emailarray['email_content_ref_id'];
            $email_array['created_by'] = $emailarray['user_id'];
            $email_array['databasename'] = $emailarray['databasename'];
            //attachements
            $email_array['attachment'] = $emailarray['attachment'];
            $email_array['attachment_data'] = $emailarray['attachment_data'];
            $email_array['attachment_file_name'] = $emailarray['attachment_file_name'];
            $email_array['attachment_file_path'] = $emailarray['attachment_file_path'];
            $file_path = self::USER_LIT_UPLOADS_EMAIL . $file_name;

            file_put_contents($file_path, $email);

            $lenn = $this->sendEmailslist($email_array);
            $emailarray['sendmail'][] = $lenn;
        }
        if ($emailarray['email_address_cc'] != "") {
            $emailarray['email_send_type'] = "CC";
            $email_array = $this->emailtemplate($emailarray);
            $emailarray['email_template_array'] = $email_array;
            $file_name = 'email' . '_' . time() . uniqid() . '.' . 'html';
            $email_array['content'] = $file_name;
            $email_array['revicer'] = array($this->emaildatareplace($emailarray, $emailarray['email_address_cc']));
            $email_array['email_type'] = 1;
            $email = $email_array['mesg'];
            $email_array['email_content_ref_id'] = $emailarray['email_content_ref_id'];
            $email_array['created_by'] = $emailarray['user_id'];
            $email_array['databasename'] = $emailarray['databasename'];
            //attachements
