    public function updatetransactionactivityschedule($post)
    {
        global $callConfig;
        $alldone = 0;
        if ($post['linkurl'] != "Y") {
            $transaction_activity_schedulesql = "SELECT tas.id, tas.check_list, tas.transaction_table, tas.task_name, tas.transaction_id, tas.assigned_to, tas.approval_user_id, tas.current_status FROM transaction_activity_schedule tas WHERE tas.company_id = '" . $post['company_id'] . "' AND tas.id= '" . $post['rid'] . self::USER_LIT_AND_TAS_IS_ACTIVE_0;
            $tasres = $callConfig->getRow($transaction_activity_schedulesql);
            $check_list = json_decode($tasres->check_list, 1);
            $check_list[$post['aryposition']]['checklist_completed'] = "Y";
            $check_list[$post['aryposition']]['comment'] = $post['comment'];
            $check_list[$post['aryposition']]['attachment_name'] = $post['attachment_file'];
            $check_list[$post['aryposition']]['complition_time'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
            $check_lists = json_encode($check_list);
            $post_array = array("check_list" => $check_lists);
            $post_array['current_status'] = ST_INPROGRESS;
            if ($alldone == '1') {
                $post_array['actual_action_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
            }
            if ($tasres->current_status == ST_SEND_BACK) {
                $post_array['current_status'] = $tasres->current_status;
            }

