    public function emailtemplate4($send_data)
    {
        global $callConfig;
        $temp = "";
        $configsql = "SELECT name,contact_address,application_module,admin_email,display_logo FROM config WHERE id = 1";
        $configres = $callConfig->getRow($configsql);
        $send_data['company_name'] = $configres->name != "" ? $configres->name : SUPERADMIN_COMPNAY_NAME;
        $send_data['contact_address'] = $configres->contact_address != "" ? $configres->contact_address : SUPERADMIN_CONTACT_ADDRESS;
        $configres->display_logo = $configres->display_logo != "" ? $configres->display_logo : SUPERADMIN_LOGO;
        $configres->admin_email = $configres->admin_email != "" ? $configres->admin_email : SUPERADMIN_EMAIL_ID;
        $configres->application_module = $configres->application_module != "" ? $configres->application_module : $send_data['user_module_id'];
        $modulesetupsql = "SELECT module_name FROM module_setup WHERE module_id = '" . $configres->application_module . "'";
        $modulesetupres = $callConfig->getRow($modulesetupsql);
        $send_data['product_name'] = $modulesetupres->module_name;
        if ($send_data['email_send_type'] == "TO") {
            $emailcontentsql = "SELECT email_subject_to as email_subject,email_header_to as email_header,email_content_to as email_content_1,button_label, email_footer  as email_fotter FROM email_content WHERE company_id = '" . $send_data['session_company_id'] . self::USER_LIT_AND_TEMPLATE_REFERENCE_ID . $send_data['email_content_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        } else {
            $emailcontentsql = "SELECT email_subject_cc as email_subject,email_header_cc as email_header,email_content_cc as email_content_1,button_label,email_footer  as email_fotter FROM email_content WHERE company_id = '" . $send_data['session_company_id'] . self::USER_LIT_AND_TEMPLATE_REFERENCE_ID . $send_data['email_content_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        }
        $emailcontentres = $callConfig->getRow($emailcontentsql);


        $subject = $this->emaildatareplace($send_data, $send_data['subject']);
        $temp = '
        <!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">
        <html xmlns="http://www.w3.org/1999/xhtml">

        <head>

        </head>
        <body yahoo bgcolor="#f6f8f1">
        <table width="70%" style="padding:20px;background-color:#f5f5f5;" align="center" cellpadding="0" cellspacing="0" border="0">
        <tr>
        <td style="font-size:24px; letter-spacing:normal; font-stretch:normal; font-weight:bold; line-height:1.79; color:#252424; padding:15px 0px;">
        <img class="fix" src="' . UPLOADIMGURL . '/all/' . $configres->display_logo . '"  border="0" alt="" style="width: 150px;"/>

        </td>
        </tr>
        <tr>
        <td>
        <table width="100%" style="padding:10px;background-color:#FFFFFF;"  >
        <tr>
        <td>
        &nbsp;
        </td>
        <tr>
        <td style="padding-left:33px; font-size:12px; font-stretch:normal; line-height:1.79; letter-spacing:normal; font-weight:normal; color:#5c5b5b;">
        ' . $this->emaildatareplace($send_data, $send_data['email_content']) . '

        </td>
        </tr>

        </table>

        </td>
        </tr>
        <tr>
        <td style="padding:15px 0px; font-size:14px; font-stretch:normal; line-height:1.79; letter-spacing:normal; font-weight:normal; color:#5c5b5b;">
        ' . $this->emaildatareplace($send_data, $emailcontentres->email_fotter) . '

        </td>
        </tr>
        </table>
        </body>
        </html>
        ';
        $return['subject'] = $subject;
        $return['mesg'] = $temp;
        $return['sender'] = $configres->admin_email;
        return $return;
    }


