    public function candidateRequestDocs($post)
    {
        global $callConfig;
        $category_id = $post['category_id'];
        $due_date = "";
        if ($post['reporting_date'] != "") {
            $addminus = "";
            if ($post['before_or_after'] == "AF") {
                $addminus = "+";
            } elseif ($post['before_or_after'] == "BF") {
                $addminus = "-";
            }
            $due_date = date('Y-m-d', strtotime($addminus . $post['day'] . ' day', strtotime($post['reporting_date'])));
        }
        $insert_array = array('company_id' => $post['company_id'], 'candidate_id' => $post['candidate_id'], 'category_id' => $category_id, 'document_list_id' => $post['document_id'], 'due_date' => $due_date, 'is_active' => '0', 'current_status' => ST_INPROGRESS, 'created_by' => $post['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1));
        $callConfig->insertRecord('candidate_documents', $insert_array);
        return $post;
    }



