    public function gettTimeZone($datetimezone = "", $actualtimezone = "", $timezone = "")
    {
        date_default_timezone_set($actualtimezone);
        $returnresult['timezonename'] = $timezone;
        $date_time = new DateTime($datetimezone);
        $date_time->setTimezone(new DateTimeZone($actualtimezone));
        $destination_tz = new DateTimeZone($timezone);
        $date_time->setTimezone($destination_tz);
        $returnresult['timezonedatetime'] = $date_time->format(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
        $returnresult['timezonetime12'] = $date_time->format('h:i A');
        $returnresult['timezonetime24'] = $date_time->format('H:i');
        return $returnresult;
    }

