    public function getAuditTrails($get)
    {
        global $callConfig;
        $return['get'] = $get;
        $decod = json_decode($get['action_type'], 1);
        $user_id = isset($get['user_profie_id']) && $get['user_profie_id'] != '' ? $get['user_profie_id'] : $get['user_id'];
        $return['decod'] = $decod;
        $condition = "";
        if ($get['type'] == "login") {
            if ($get['from_date'] != "" && $get['to_date'] != "") {
                $condition .= " AND login_from between '" . $this->dateconvertdbformat($get['from_date']) . self::USER_LIT_00_00_00_AND . $this->dateconvertdbformat($get['to_date']) . self::USER_LIT_23_59_59;
            }
            $audit_trailssql = "SELECT user_id,login_from, login_to FROM application_user_logins WHERE company_id = '" . $get['company_id'] . "' " . $condition . self::USER_SQL_AND_USER_ID_1 . $user_id . "' ORDER BY DATE(login_from) DESC LIMIT 20";
            $audit_trailsres = $callConfig->getAllRows($audit_trailssql);
            $return['login'] = $audit_trailsres;
            $return['loginsql'] = $audit_trailssql;
        } elseif ($get['type'] == "approval") {
            $json = implode("','", (array) $decod);
            $condition .= self::USER_SQL_AND_TYPE_IN . $json . "')";
            if ($get['from_date'] != "" && $get['to_date'] != "") {
                $condition .= " AND request_date between '" . $this->dateconvertdbformat($get['from_date']) . self::USER_LIT_00_00_00_AND . $this->dateconvertdbformat($get['to_date']) . self::USER_LIT_23_59_59;
            }
            $transaction_approval_logssql = "SELECT transaction_table,transaction_id, response_type,user_id,request_date,response_date FROM transaction_approval_logs WHERE user_id = '" . $user_id . "' ORDER BY DATE(request_date) DESC limit 20";
            $transaction_approval_logsres = $callConfig->getAllRows($transaction_approval_logssql);
            $return['approval'] = $transaction_approval_logsres;
            $return['approvalsql'] = $transaction_approval_logssql;
        } else {
            if ($get['action_type'] != "" && $get['action_type'] != "null") {
                $json = implode("','", (array) $decod);
                $condition .= self::USER_SQL_AND_TYPE_IN . $json . "')";
            } else {
                $condition .= " AND type IN('VIEW')";
            }
            if ($get['from_date'] != "" && $get['to_date'] != "") {
                $condition .= " AND created_date between '" . $this->dateconvertdbformat($get['from_date']) . self::USER_LIT_00_00_00_AND . $this->dateconvertdbformat($get['to_date']) . self::USER_LIT_23_59_59;
            }
            $audit_trailssql = "SELECT * FROM audit_trails WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_USER_ID . $user_id . "' " . $condition . " AND is_active = 0 ORDER BY created_date DESC limit 20";
            $audit_trailsres = $callConfig->getAllRows($audit_trailssql);
            $return['audit_trails'] = $audit_trailsres;
            $return['sql'] = $audit_trailssql;

            $application_pagessql = "SELECT application_table_name FROM application_pages WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $application_pagesres = $callConfig->getAllRows($application_pagessql);
            $return['application_pages'] = $application_pagesres;
        }
        return $return;
    }

    public function updateModuleSelection($post)
    {
        global $callConfig;
        $return = array();
        $post_array1 = array("is_active" => null, "updated_by" => $post['user_id'], "updated_date" => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
        $where = " is_active = 0 AND linking = 1";
        $callConfig->updateRecord('module_setup', $post_array1, '', '', $where);

        $linkingmodulesql = "SELECT id,parent_module_id FROM module_setup_linkings WHERE company_id = '" . $post['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $linkingmoduleres = $callConfig->getAllRows($linkingmodulesql);
        foreach ($linkingmoduleres as $linkingmoduleres) {
            $linkingmodulelist[$linkingmoduleres->parent_module_id] = $linkingmoduleres->parent_module_id;
        }
        $linkmoduleavailbleornot = 1;
        foreach ($post['module_id'] as $moduleid) {
            if (isset($linkingmodulelist[$moduleid])) {
                $linkmoduleavailbleornot = 0;
            }
            $post_array = array("is_active" => '0', "updated_by" => $post['user_id'], "updated_date" => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
            $res = $callConfig->updateRecord('module_setup', $post_array, 'module_id', $moduleid);
            $return['update'][] = $res;
        }
        if ($linkmoduleavailbleornot == 1) {
            $post_array1 = array("is_active" => null, "updated_by" => $post['user_id'], "updated_date" => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
            $where = " is_active = 0 AND linking = 0";
            $callConfig->updateRecord('module_setup', $post_array1, '', '', $where);
        }
        //email send
        $modulesql = "SELECT id,module_name FROM module_setup WHERE company_id = '" . $post['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $moduleres = $callConfig->getAllRows($modulesql);
        $return['modulesql'] = $moduleres;
        $modulenamelist = "";
        $mk = 1;
        foreach ($moduleres as $modulename) {
            $modulenamelist .= "<p>" . $mk . ") " . $modulename->module_name . "</p>";
            $mk++;
        }

        $usersetailsql = "SELECT au.id,au.user_email,au.display_name,au.company_id,dr.default_module_id FROM application_users au, " . MAINDB . ".domain_registrations dr WHERE au.company_id = '" . $post['company_id'] . "' AND au.user_email = dr.user_email AND au.id = '" . $post['user_id'] . self::USER_LIT_AND_AU_IS_ACTIVE_0;
        $usersetailres = $callConfig->getRow($usersetailsql);
        $emailarray['user_email_id'] = $usersetailres->user_email;
        $emailarray['user_display_name'] = $usersetailres->display_name;
        $emailarray['to_company_id'] = $usersetailres->company_id;
        $emailarray['session_company_id'] = $usersetailres->company_id;
        $emailarray['user_module'] = $modulenamelist;
        $emailarray['default_module_id'] = $usersetailres->default_module_id;
        $emailarray['created_by'] = $post['user_id'];
        $return['emailarray'] = $usersetailres;
        $return['email'] = $this->sendNotificationAndEmails($notarry, $emailarray, 22);
        //End email send
        return $return;
    }
    public function getDynamicModuleDashboard($get)
    {
        global $callConfig;
        $return = array();
        $return['get'] = $get;
        $originator = $get['fieldaccess'] != "" ? "party_id" : "originator";
        $checkuserid = $get['fieldaccess'] != "" ? $get['vendor_id'] : $get['user_id'];
        if ($get['admin_type'] != 1 || $get['admin_access_employee'] == 'Y') {
            $condition = " AND pt." . $originator . " = '" . $checkuserid . "'";
        }
        $get['transaction_date_check'] = date('Y-m-d');
        $getdocaccesssetup = $this->getdocumentsAccessSetupsRule($get);
        $return['docpermisions'] = $getdocaccesssetup;
        $allowcostcenter = $getdocaccesssetup['allowcostcenter'];
        $docaccesssetupsuser = $getdocaccesssetup['document_access_setups_user'];
        $item_categorylist = json_decode($docaccesssetupsuser['item_category']);
        $get['table'] = $get['transaction_table'];
        $status_progress = $this->getStatusProgressList($get);
        foreach ($status_progress as $statusprogress) {
            $return['status_progress'][$statusprogress->status] = $statusprogress;
        }
        if ($get['tablerows'] == 'Y') {
            $transactipnlist = json_decode(base64_decode($get['transaction_table']), 1);
            $dynamicsql = $logdynamicsql = self::USER_SQL_SELECT;
            foreach ($transactipnlist as $tablename) {
                $dynamicsql .= "(Select count(pt.id) as cnt FROM " . $tablename . self::USER_LIT_PT_WHERE_PT_COMPANY_ID . $get['company_id'] . "' " . $condition . " AND pt.is_active = 0 limit 1) as " . $tablename . ",";

                $logdynamicsql .= "(SELECT count(id) as cnt FROM transaction_approval_logs WHERE transaction_table = '" . $tablename . "' AND  company_id = '" . $get['company_id'] . self::USER_LIT_AND_USER_ID . $get['user_id'] . "' AND send_back_flag = 0 AND call_back = 1 AND response_type ='0') as " . $tablename . ",";

            }
            $dynamicsql = substr($dynamicsql, 0, -1);
            $tableresult = $callConfig->getRow($dynamicsql);
            foreach ($tableresult as $tablename => $cnt) {
                $return['transaction_table'][$tablename] = $cnt;
            }
            $logdynamicsql = substr($logdynamicsql, 0, -1);
            $logtableresult = $callConfig->getRow($logdynamicsql);
            foreach ($logtableresult as $tablename => $cnt) {
                $return['pendding_action_sql'][$tablename] = $logdynamicsql;
                $return['pendding_action'][$tablename] = $cnt;
            }
        } else {
            $location_id = $_GET['location_id'] != "" ? $_GET['location_id'] : 1;
            $holidayssql = "SELECT id,holiday_date,holiday_name FROM holidays where company_id = '" . $get['company_id'] . "' AND holiday_year ='" . date('Y') . "' AND location_id = " . $location_id . " AND is_active = 0 ORDER BY `holiday_date` ASC";
            $holidaysres = $callConfig->getAllRows($holidayssql);
            $return['holidays'] = $holidaysres;

            $dmtsql = self::USER_SQL_SELECT_ID_PAGE_TITLE_APPLICATI_1 . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $get['transaction_table'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $dmtres = $callConfig->getRow($dmtsql);
            $return['dynamic_mapping_tables'] = $dmtres;
            $itemcatename = "item_categories";
            $itemfieldname = "category_description";
            if (count((array) $item_categorylist) != 0) {
                $conditionitmcat = " AND ic.id IN(" . implode(',', (array) $item_categorylist) . ")";
            }
            $orderby = ", ic.category_description";
            if ($callConfig->module_id == PETTY_CASH_MODULE) {
                $itemcatename = "petty_cash_boxes";
                $itemfieldname = "ic.pc_box_description as category_description";
                $conditionitmcat = "";
            } elseif ($get['transaction_table'] == "debit_notes" || $get['transaction_table'] == "credit_notes" || $get['transaction_table'] == "journal_vouchers" || $get['transaction_table'] == "bank_vouchers" || $get['transaction_table'] == "cash_vouchers") {
                $itemcatename = "account_groups";
                $itemfieldname = "ic.group_name as category_description";
                $conditionitmcat = "";
                $orderby = ", ic.group_name";
            }
            $dmtsql = "SELECT ic.id, " . $itemfieldname . ", af.id as favourite_id FROM " . $itemcatename . " ic LEFT JOIN application_favourites af ON ic.company_id = af.company_id AND ic.id = af.transaction_id AND ic.is_active = af.is_active AND af.user_id = '" . $get['user_id'] . "' AND af.application_table_name = '" . $itemcatename . "' WHERE ic.company_id = '" . $get['company_id'] . "' AND ic.is_active = 0 " . $conditionitmcat . " ORDER BY CASE WHEN af.application_table_name IS NOT NULL THEN 0 ELSE 1 END" . $orderby;
            $dmtres1 = $callConfig->getAllRows($dmtsql);
            $return['item_categoriessql'] = $dmtsql;
            $return['item_categories'] = $dmtres1;
            if ($callConfig->module_id == PETTY_CASH_MODULE) {
                $categorylistsql = "SELECT pt.id, pt.transaction_number, pt.transaction_date, pt.originator, pt.party_id, pt.party_name,  pt.total_amount, ct.item_id as category_id, pt.current_status, pt.pending_amount  FROM " . $dmtres->application_table_name . self::USER_LIT_PT . $dmtres->item_table . " ct WHERE pt.company_id = '" . $get['company_id'] . "' AND pt.company_id = ct.company_id AND pt.id = ct.transaction_id  AND pt.is_active = ct.is_active AND pt.is_active = 0 " . $condition . " group by pt.id";
            } elseif ($get['transaction_table'] == "debit_notes" || $get['transaction_table'] == "credit_notes" || $get['transaction_table'] == "journal_vouchers" || $get['transaction_table'] == "bank_vouchers" || $get['transaction_table'] == "cash_vouchers") {
                $categorylistsql = "SELECT pt.id, pt.transaction_number, pt.transaction_date, pt.originator,pt.party_id, pt.party_name,  pt.total_amount, pt.current_status, IF(pt.current_status != 199,'manual',pt.ref_type) as category_id, 0 as pending_amount FROM " . $dmtres->application_table_name . self::USER_LIT_PT . $dmtres->item_table . " ct WHERE pt.company_id = '" . $get['company_id'] . "' AND pt.company_id = ct.company_id AND pt.id = ct.transaction_id  AND pt.is_active = ct.is_active AND pt.is_active = 0 " . $condition . " group by pt.id";

            } elseif ($get['transaction_table'] == "kittings" || $get['transaction_table'] == "dekittings") {

                $kitnname = $get['transaction_table'] == "kittings" ? "pt.kitting_name" : "pt.dekitting_name";
                $categorylistsql = self::USER_SQL_SELECT_PT_ID . $kitnname . " as transaction_number, pt.transaction_date, pt.originator,  pt.parent_item_total as total_amount, item.category_id, pt.current_status, pt.suspense_total as pending_amount FROM " . $get['transaction_table'] . " pt, items item WHERE pt.company_id = '" . $get['company_id'] . "' AND pt.company_id = item.company_id AND pt.parent_item_id = item.id AND pt.is_active = item.is_active AND pt.is_active = 0 " . $condition . " group by pt.id,item.category_id";

            } else {
