                    $conditionpopup .= " AND pt.current_status NOT IN('" . ST_ACTIVE . "','" . ST_DRAFT . "','" . ST_APPROVED . "')";
                } else {
                    $conditionpopup .= " AND pt.current_status = '" . $get['type'] . "'";
                }
            }
            if ($get['admin_type'] != 1 || $get['admin_access_employee'] == 'Y') {
                $conditionpopup .= " AND pt." . $originator . " = '" . $checkuserid . "'";
            }
            $dtablesql = "SELECT pt.id, pt.transaction_number, pt.transaction_date, pt.originator,pt.party_id ,pt.party_name, pt.total_amount, pt.cost_center_id, pt.current_status, pt.pending_amount FROM " . $dmtres->application_table_name . self::USER_LIT_PT_WHERE_PT_COMPANY_ID . $get['company_id'] . "' " . $conditionpopup . "  AND pt.is_active = 0";
            if ($dmtres->application_table_name == 'sales_invoices') {
                $dtablesql = "SELECT pt.id, pt.transaction_number, pt.transaction_date, pt.originator,pt.party_id , cu.display_name as party_name, pt.total_amount, pt.cost_center_id, pt.current_status, pt.pending_amount FROM " . $dmtres->application_table_name . " pt,  customers cu  WHERE pt.company_id = '" . $get['company_id'] . "' " . $conditionpopup . " AND cu.company_id = pt.company_id AND pt.party_id = cu.id  AND pt.is_active = 0";
            } elseif ($get['transaction_table'] == "kittings" || $get['transaction_table'] == "dekittings") {
                $kitnname = $get['transaction_table'] == "kittings" ? "pt.kitting_name" : "pt.dekitting_name";
                $dtablesql = self::USER_SQL_SELECT_PT_ID . $kitnname . " as transaction_number, pt.transaction_date, pt.originator, pt.parent_item_total as total_amount, pt.current_status, pt.suspense_total as pending_amount FROM " . $get['transaction_table'] . self::USER_LIT_PT_WHERE_PT_COMPANY_ID . $get['company_id'] . "' " . $conditionpopup . "  AND pt.is_active = 0";
            }


            $dtableres = $callConfig->getAllRows($dtablesql);
            $return['status_table_list'] = $dtableres;
            $return['status_table_list_sql'] = $dtablesql;
            if ($get['transaction_table'] == "debit_notes" || $get['transaction_table'] == "credit_notes" || $get['transaction_table'] == "journal_vouchers" || $get['transaction_table'] == "bank_vouchers" || $get['transaction_table'] == "cash_vouchers") {
                $lastestdtablesql = "SELECT pt.id, pt.transaction_number, pt.transaction_date, pt.originator, pt.party_name, pt.total_amount, pt.cost_center_id, pt.current_status FROM " . $dmtres->application_table_name . self::USER_LIT_PT_WHERE_PT_COMPANY_ID . $get['company_id'] . "' " . $conditionpopup . self::USER_SQL_AND_PT_IS_ACTIVE_0_ORDER_BY_UP;

            } elseif ($get['transaction_table'] == "kittings" || $get['transaction_table'] == "dekittings") {
                $kitnname = $get['transaction_table'] == "kittings" ? "pt.kitting_name" : "pt.dekitting_name";
                $lastestdtablesql = self::USER_SQL_SELECT_PT_ID . $kitnname . " as transaction_number, pt.transaction_date, pt.originator,  pt.parent_item_total as total_amount, pt.current_status, pt.suspense_total as pending_amount FROM " . $get['transaction_table'] . self::USER_LIT_PT_WHERE_PT_COMPANY_ID . $get['company_id'] . "' " . $conditionpopup . self::USER_SQL_AND_PT_IS_ACTIVE_0_ORDER_BY_UP;

            } else {
                $lastestdtablesql = "SELECT pt.id, pt.transaction_number, pt.transaction_date, pt.originator, pt.party_name, pt.total_amount, pt.cost_center_id, pt.current_status, pt.pending_amount FROM " . $dmtres->application_table_name . self::USER_LIT_PT_WHERE_PT_COMPANY_ID . $get['company_id'] . "' " . $conditionpopup . self::USER_SQL_AND_PT_IS_ACTIVE_0_ORDER_BY_UP;

            }

            $lastestdtableres = $callConfig->getAllRows($lastestdtablesql);
            $return['latest_table_list'] = $lastestdtableres;
            $return['latest_table_list_sql'] = $dtablesql;
            if ($get['transaction_table'] == "kittings" || $get['transaction_table'] == "dekittings") {
                $kitnname = $get['transaction_table'] == "kittings" ? "transtable.kitting_name" : "transtable.dekitting_name";
                $talsql = "SELECT tal.id, tal.transaction_id, tal.request_date, tal.response_type, tal.send_back_flag, tal.call_back, " . $kitnname . " as transaction_number, transtable.transaction_date as transaction_date, transtable.originator, transtable.parent_item_total as total_amount, transtable.current_status FROM transaction_approval_logs tal, " . $get['transaction_table'] . " transtable WHERE tal.transaction_table = '" . $get['transaction_table'] . "' AND tal.transaction_id = transtable.id AND  tal.company_id = '" . $get['company_id'] . "' AND tal.company_id = transtable.company_id AND tal.user_id = '" . $get['user_id'] . "' ORDER BY tal.request_date DESC";
            } else {
                $talsql = "SELECT tal.id, tal.transaction_id, tal.request_date, tal.response_type, tal.send_back_flag, tal.call_back, transtable.transaction_number, transtable.transaction_date, transtable.originator, transtable.party_name, transtable.total_amount, transtable.cost_center_id, transtable.current_status, transtable.pending_amount FROM transaction_approval_logs tal, " . $dmtres->application_table_name . " transtable WHERE tal.transaction_table = '" . $dmtres->application_table_name . "' AND tal.transaction_id = transtable.id AND  tal.company_id = '" . $get['company_id'] . "' AND tal.company_id = transtable.company_id AND tal.user_id = '" . $get['user_id'] . "' ORDER BY tal.request_date DESC";
            }
            $talres = $callConfig->getAllRows($talsql);
            $return['transaction_approval_logs'] = $talres;
            $return['transaction_approval_logs_sql'] = $talsql;





            $dmtsql1 = "SELECT id, page_title, application_table_name, display_table, item_table, tax_table FROM dynamic_mapping_tables WHERE company_id = '" . $get['company_id'] . "' AND application_table_name IN(SELECT transaction_table FROM `dynamic_reference_tables` WHERE company_id = '" . $get['company_id'] . "' AND reference_table = '" . $get['transaction_table'] . "' AND is_active = 0) AND genrate_next_level = 0 AND item_table !='' AND tax_table !='' AND is_active = 0";
            $return['generatesql'] = $dmtsql1;
            $dmtres1 = $callConfig->getAllRows($dmtsql1);
            foreach ($dmtres1 as $dmtress) {
                $conditionbuild = "";
                $get['transaction_date_check'] = date('Y-m-d');
                $getdocaccesssetup = $this->getdocumentsAccessSetupsRule($get);
                $docaccesssetupsuser = $getdocaccesssetup['document_access_setups_user'];
                if (count((array) $docaccesssetupsuser) != "0") {
                    if ($docaccesssetupsuser['approved_type'] == "cost_center_id") {
                        $allowcostcenter = $getdocaccesssetup['allowcostcenter'];
                        $conditionbuild .= " AND po.cost_center_id IN(" . implode(',', (array) $allowcostcenter) . ") ";
                    }
                    if ($docaccesssetupsuser['opex_cpex'] != "") {
                        $conditionbuild .= " AND po.opex_cpex = " . $docaccesssetupsuser['opex_cpex'];
                    }
                    if ($docaccesssetupsuser['amount'] != "" && $docaccesssetupsuser['amount'] != "0") {
                        $conditionbuild .= " AND po.total_amount <= " . $docaccesssetupsuser['amount'];
                    }
                    $item_categorylist = json_decode($docaccesssetupsuser['item_category']);
                    if (count((array) $item_categorylist) != "0") {
                        $conditionbuild .= " AND poitm.item_id in (SELECT id FROM items itm WHERE category_id IN(" . implode(',', (array) $item_categorylist) . "))";
                    }
                }
                $query = "select po.id, po.transaction_number, po.transaction_date, po.originator, po.party_name, GROUP_CONCAT(poitm.id SEPARATOR ',') AS itemtb_id, po.total_amount, po.pending_amount From " . $dmtress->application_table_name . " po," . $dmtress->item_table . " poitm WHERE po.company_id = '" . $get['company_id'] . "' AND po.company_id = poitm.company_id AND po.id = poitm.transaction_id AND po.is_active = 0 AND po.current_status = '" . ST_APPROVED . "' " . $conditionbuild . " GROUP BY po.id,po.party_id,po.cost_center_id,po.opex_cpex,po.transaction_number,po.transaction_date,po.total_amount,po.current_status ORDER BY po.transaction_date asc";
                $return['generatessql'][] = $query;
                $results = $callConfig->getAllRows($query);
                $return['generate'][$dmtress->application_table_name] = $results;

            }
            //genarate new docs



        }

        return $return;
    }
    public function togetemployeeageprofile($post, $get)
    {
        global $callConfig;
        $return['menu_data'] = $this->toreportempdropdown($get);
        $whr = "";
        $whrarry = array('department_id' => 'departments', 'designation_id' => 'designations', 'location_id' => 'locations', 'employee_type' => 'employment_statuses', 'division_id' => 'divisions');
        foreach ($whrarry as $wrkey => $whra) {
            if (count((array) $post[$whra]) > 0) {
                $whr .= " AND emp." . $wrkey . " IN(" . implode(",", (array) $post[$whra]) . ") ";
            }
        }
        $query = "SELECT
        emp.id,
        emp.emp_code,
        emp.display_name,
        emp.image,
        CONCAT( FLOOR( DATEDIFF(NOW(), emp.date_of_birth)/ 365)) age,
        (
        SELECT
        department_name
        FROM
        `departments` dep
        WHERE
        dep.company_id = emp.company_id
        AND dep.id = emp.department_id
        AND dep.is_active = emp.is_active
        ) department_name,
        (
        SELECT
        designation_name
        FROM
        `designations` des
        WHERE
        des.is_active = emp.is_active
        AND des.company_id = emp.company_id
        AND des.id = emp.designation_id
        ) designation_name,
        (
        SELECT
        job_title
        FROM
        `job_titles` jbt
        WHERE
        jbt.company_id = emp.company_id
        AND jbt.id = emp.job_title_id
        AND jbt.is_active = emp.is_active
        ) job_title,
        (
        SELECT
        lc.location_name
        FROM
        locations lc
        WHERE
        lc.company_id = emp.company_id
        AND lc.id = emp.location_id
        AND lc.is_active = emp.is_active
        ) location_name,
        (
        SELECT
        es.employment_status_name
        FROM
        employment_statuses es
        WHERE
        es.company_id = emp.company_id
        AND es.id = emp.employee_type
        AND es.is_active = emp.is_active
        ) employment_status_name,
        (
        SELECT
        divi.division_name
        FROM
        divisions divi
        WHERE
        divi.company_id = emp.company_id
        AND divi.id = emp.division_id
        AND divi.is_active = emp.is_active
        ) division_name
        FROM
        employees emp
        where
        emp.company_id = " . $get['company_id'] . "
        AND (
        CASE WHEN (
        emp.date_of_leaving IS NOT NULL
        AND emp.date_of_leaving >= now()
        ) THEN 1 WHEN (
        emp.date_of_leaving IS NULL
        AND emp.is_active = 0
        ) THEN 1 ELSE 2 END
        )= 1 " . $whr . "
        AND emp.is_active = '0'

        order by
        emp.display_name ASC";
        echo $query;
        exit;
        $return['emp_query'] = $query;
        $return['emp_data'] = $callConfig->getAllRows($query);
        $query = "SELECT  CONCAT( FLOOR( DATEDIFF(NOW(), emp.date_of_birth)/ 365 / 5 )* 5 + 1, '-', FLOOR( DATEDIFF(NOW(), emp.date_of_birth)/ 365 / 5 )* 5 + 5 ) AS age_range, COUNT(*) AS employee_count FROM employees emp WHERE emp.company_id = " . $get['company_id'] . " AND emp.date_of_birth <= DATE_SUB(NOW(), INTERVAL 20 YEAR)  AND ( CASE WHEN ( emp.date_of_leaving IS NOT NULL AND emp.date_of_leaving >= now() ) THEN 1 WHEN ( emp.date_of_leaving IS NULL AND emp.is_active = 0 ) THEN 1 ELSE 2 END )= 1 " . $whr . "  GROUP BY FLOOR( DATEDIFF(NOW(), emp.date_of_birth)/ 365 / 5 ) HAVING age_range <= '60' ORDER BY age_range ASC";
        $return['age_range'] = $callConfig->getAllRows($query);
        return $return;
    }
    public function toreportempdropdown($get)
    {
        global $callConfig;
        $menudata['divisions'] = array('table_name' => 'divisions', 'name' => 'Divisions', 'field' => 'division_name', 'data' => '');
        $menudata['departments'] = array('table_name' => 'departments', 'name' => 'Departments', 'field' => 'department_name', 'data' => '');
        $menudata['locations'] = array('table_name' => 'locations', 'name' => 'Location', 'field' => 'location_name', 'data' => '');
        $menudata['designations'] = array('table_name' => 'designations', 'name' => 'Designations', 'field' => 'designation_name', 'data' => '');
        $menudata['employment_statuses'] = array('table_name' => 'employment_statuses', 'name' => 'Employment Statuses', 'field' => 'employment_status_name', 'data' => '');

        foreach ($menudata as $menuda) {
            $query = self::USER_SQL_SELECT_ID . $menuda['field'] . self::USER_SQL_FROM . $menuda['table_name'] . self::USER_SQL_WHERE_COMPANY_ID_3 . $get['company_id'] . self::USER_SQL_AND_IS_ACTIVE_0;
            $menudetails = $callConfig->getAllRows($query);
            $edata = array();
            foreach ($menudetails as $menudeta) {
                $filed = $menuda['field'];
                $edata[$menudeta->id] = $menudeta->$filed;
            }
            $menudata[$menuda['table_name']]['data'] = $edata;
        }
        return $menudata;
    }
    public function payRollDashboard($get)
    {
        global $callConfig;
        $payrollenddate = $get['pay_year'] . "-" . $get['pay_month'] . "-" . $get['default_payroll_day'];
        $payrollstartdate = date('Y-m-d', strtotime('-1 month', strtotime($payrollenddate)));
        $payrollsixmonthstartdate = date('Y-m-d', strtotime('-5 month', strtotime($payrollenddate)));
        $return = array();
        $sql = "SELECT count(emp.id) as total_emp, sum(if((emp.joining_date  >= '" . $payrollstartdate . self::USER_LIT_AND_EMP_JOINING_DATE . $payrollenddate . "'),1,0)) as this_month_join, sum(if((emp.date_of_leaving  >= '" . $payrollstartdate . self::USER_LIT_AND_EMP_DATE_OF_LEAVING . $payrollenddate . "'),1,0)) as this_month_leaving FROM employees emp where emp.company_id=" . $get['company_id'] . " AND emp.is_active=0";
        $res = $callConfig->getRow($sql);
        $return['payrollempcnt'] = $res;

        $exclusionsql = "SELECT sum(if((category_id = 1),1,0)) as exclusion_cnt, sum(if((category_id = 2),1,0)) as hold_salary_cnt, sum(if((category_id = 4),1,0)) as settlement_cnt, sum(if((category_id = 6),1,0)) as revised_cnt FROM payroll_exclusions WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_PAY_YEAR . $get['pay_year'] . self::USER_LIT_AND_PAY_MONTH . $get['pay_month'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
        $exclusionres = $callConfig->getRow($exclusionsql);
        $return['payroll_exclusions'] = $exclusionres;

        $payrollstepssql = "SELECT category_id,pay_area_id FROM payroll_steps WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_PAY_YEAR . $get['pay_year'] . self::USER_LIT_AND_PAY_MONTH . $get['pay_month'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
        $payrollstepsres = $callConfig->getAllRows($payrollstepssql);
        $return['payroll_steps'] = $payrollstepsres;

        $statutorysql = "SELECT menu_label,page_name FROM `application_menu` WHERE company_id=" . $get['company_id'] . " AND parent_menu = 770 AND menu_location = 'TN' AND is_active=0 ORDER BY display_priority ASC";
        $statutoryres = $callConfig->getAllRows($statutorysql);
        $return['statutory'] = $statutoryres;
        foreach ($statutoryres as $statutoryval) {
            $statutorroptions[] = $statutoryval->page_name;
        }
        $options = implode("','", (array) $statutorroptions);
        $audit_trailssql = "SELECT page_option, max(created_date) as created_date FROM `audit_trails` WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_USER_ID_1 . $get['user_id'] . "' AND page_option IN ('" . $options . "') AND is_active=0 group BY page_option ORDER BY created_date DESC";
        $audit_trailsres = $callConfig->getAllRows($audit_trailssql);
        $return['audit_trails'] = $audit_trailsres;

        $payrollsql = "SELECT id FROM `payroll` WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_PAY_YEAR . $get['pay_year'] . self::USER_LIT_AND_PAY_MONTH . $get['pay_month'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
        $payrollres = $callConfig->getRow($payrollsql);
        $return['payroll'] = $payrollres;
        $startmonth = new DateTime($payrollsixmonthstartdate);
        $endmonth = new DateTime($payrollenddate);
        while ($startmonth <= $endmonth) {
            $salarycomponanatsql = "SELECT sum(if((component_id = " . GROSS_SALARY . "),salary_component_actual,0)) as gross_salary, sum(if((component_id = " . EMPLOYEER_PF_CONTRIBUTION . self::USER_LIT_OR_COMPONENT_ID . EMPLOYEER_ESI_CONTRIBUTION . "),salary_component_actual,0)) as pf_salary, sum(if((component_id = " . REIMBURSEMENT_COMPONENT . "),salary_component_actual,0)) as reimbursement  FROM `pay_run_summary_components` WHERE company_id =  " . $get['company_id'] . self::USER_SQL_AND_PAY_YEAR . $startmonth->format('Y') . self::USER_LIT_AND_PAY_MONTH . $startmonth->format('m') . "' AND (component_id = " . GROSS_SALARY . self::USER_LIT_OR_COMPONENT_ID . EMPLOYEER_ESI_CONTRIBUTION . self::USER_LIT_OR_COMPONENT_ID . EMPLOYEER_PF_CONTRIBUTION . self::USER_LIT_OR_COMPONENT_ID . REIMBURSEMENT_COMPONENT . self::USER_LIT_AND_IS_ACTIVE_0_7;
            $salarycomponanatres = $callConfig->getRow($salarycomponanatsql);
            $return['pay_run_summary_components'][$startmonth->format('M-Y')] = $salarycomponanatres;
            $startmonth->modify(self::USER_LIT_1_MONTH);
        }
        return $return;
    }
    public function getDynamicWorkFlowSteps($get)
    {
        global $callConfig;
        $return = array();
        $transaction_no = $get['transaction_no'];
        $transaction_table = $get['transaction_table'];
        $current_status = $get['current_status'];
        $get['table'] = $get['transaction_table'];
        $status_progress = $this->getStatusProgressList($get);
        foreach ($status_progress as $statusprogress) {
            $return['status_progress'][$statusprogress->status] = $statusprogress;
        }
        $aurolesql = "SELECT aumr.user_id, ar.display_name FROM application_user_module_roles aumr, application_roles ar WHERE aumr.company_id = '" . $get['company_id'] . "' AND aumr.company_id = ar.company_id AND aumr.role_id = ar.id AND aumr.is_active = ar.is_active AND aumr.is_active = 0";
        $auroleres = $callConfig->getAllRows($aurolesql);
        foreach ($auroleres as $aurole) {
            $return['application_user_module_roles'][$aurole->user_id] = $aurole->display_name;
        }

        if ($transaction_table != "") {
            $transactionsql = self::USER_SQL_SELECT_FROM . $transaction_table . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . self::USER_LIT_AND_ID . $transaction_no . self::USER_LIT_AND_IS_ACTIVE_0;
            $transactionres = $callConfig->getRow($transactionsql);
            $return['transaction_details'] = $transactionres;

            $workflowsql = "SELECT id, process_name,document_type_id, process_description, workflow_trigger_status, doa,doa_trigger_field, transaction_owner_field, workflow_level, criteria, approval_process,work_level_type, notification_message, transaction_owner_type, breadcrumb_view_field_type FROM workflow_configurations_new WHERE company_id = '" . $get['company_id'] . "' AND process_name = '" . $transaction_table . self::USER_LIT_AND_IS_ACTIVE_0;
            if ($transaction_table == TBL_DOCUMENT_MANAGEMENT && $transactionres->document_type_id != '') {
                $workflowsql .= " AND document_type_id = '" . $transactionres->document_type_id . "'";
            }
            $workflowres = $callConfig->getRow($workflowsql);
        }

        if (isset($workflowres->id)) {
            $return['workflow_details'] = $workflowres;
            $approval_process = json_decode($workflowres->approval_process, 1);
            $flowstatus[$workflowres->workflow_trigger_status] = $workflowres->workflow_trigger_status;
            $transactionownerfield = $workflowres->transaction_owner_field;
            $transaction_owner_field = $temp_owner_id = $transactionres->$transactionownerfield;
            if ($workflowres->transaction_owner_type != "" && $workflowres->transaction_owner_type != "AU") {
                $uidsql = self::USER_SQL_SELECT_USER_ID_FROM . $workflowres->transaction_owner_type . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . self::USER_LIT_AND_ID_4 . $transaction_owner_field . self::USER_SQL_AND_IS_ACTIVE_0;
                $uidres = $callConfig->getRow($uidsql);
                $transaction_owner_field = $uidres->user_id;
            }
            $return['transaction_owner_id'] = $transaction_owner_field;
            foreach ($approval_process as $approvalprocess) {
                $flowstatus[$approvalprocess['workflow_level_status']] = $approvalprocess['workflow_level_status'];
                $approvalprocesssetp[$approvalprocess['workflow_level_status']] = $approvalprocess;
            }



            $transactionallstatus = $flowstatus;
            $transactionallstatus[ST_APPROVED] = ST_APPROVED;
            $transactionallstatus[ST_CALLBACK] = ST_CALLBACK;
            $transactionallstatus[ST_CANCEL] = ST_CANCEL;
            $transactionallstatus[ST_REJECTED] = ST_REJECTED;
            $transactionallstatus[ST_SEND_BACK] = ST_SEND_BACK;
            $validatestatusarry = array();
            //check current stutus workflow start ,applicable or not
            if ($workflowres->workflow_trigger_status == $current_status || in_array($current_status, (array) $transactionallstatus)) {
                $workflowdetailsql = "SELECT id, approval_level_criteria, doa_amount, final_approval FROM workflow_configuration_details WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_WORKFLOW_ID . $workflowres->id . self::USER_LIT_AND_IS_ACTIVE_0;
                $workflowdetailres = $callConfig->getAllRows($workflowdetailsql);
                $cntworkflowdetailres = count((array) $workflowdetailres);
                $nextstepkeyvalue = $this->keyArrayNextStep($flowstatus);//workflow status level conevrt
                $tranaprrlogsql = "SELECT id, previous_status,user_id, send_back_flag, call_back, response_type FROM transaction_approval_logs WHERE company_id = '" . $get['company_id'] . "' AND transaction_table= '" . $transaction_table . "' AND transaction_id= '" . $transaction_no . "'";
                $tranaprrlogres = $callConfig->getAllRows($tranaprrlogsql);
                foreach ($tranaprrlogres as $tranaprrlog) {
                    if ($tranaprrlog->send_back_flag == '0' && $tranaprrlog->call_back == '1' && $tranaprrlog->response_type == '0') {
                        $return['transaction_approval_logs'][$tranaprrlog->user_id] = $tranaprrlog;
                    }
                    if ($tranaprrlog->response_type != '0') {
                        $return['transaction_approval_logs_approved'][$tranaprrlog->user_id] = $tranaprrlog;
                    }

                }
                if ($workflowres->doa == '0') {
                    foreach ($nextstepkeyvalue as $current_status => $nextstepkey) {
                        if ($nextstepkey != "") {
                            $nextstepvalue = $approvalprocesssetp[$nextstepkey]; //get next level values
                            //match direct 0 pass
                            $checkcondition = 0;
                            if ($cntworkflowdetailres == 0) {
                                $workflowdetailres = (object) ['approval_level_criteria' => '', 'doa_amount' => ''];
                            }
                            foreach ($workflowdetailres as $workflowdetailre) {
                                $loopcheckcondition = 0;
                                $approval_level_criteria = json_decode($workflowdetailre->approval_level_criteria, 1);
                                if ($approval_level_criteria['criteria'] != 'no') {
                                    foreach ($approval_level_criteria as $keyfield => $approvallevelcriteravalue) { //check approval level criteria
                                        if ($transactionres->$keyfield != $approvallevelcriteravalue) { //not match
                                            $loopcheckcondition++;
                                        }
                                    }
                                }
                                if ($loopcheckcondition == 0) {
                                    if ($workflowres->doa == 0) {
                                        $doa_amount = json_decode($workflowdetailre->doa_amount, 1);
                                        $step_amount = $doa_amount[$nextstepvalue['workflow_level_seq']];
                                        $limit_amount = end($doa_amount);//workflow limit Aomunt
                                        $trigerfield = $workflowres->doa_trigger_field; //DOA Field Name
                                        $transaction_amount = $transactionres->$trigerfield; //Get Transaction Amount
                                    }
                                    if ($limit_amount['end_doa'] >= $transaction_amount) {    /// out side or inside amount checked
                                        if (($step_amount['end_doa'] <= $transaction_amount && $step_amount['end_doa'] != "") || $workflowres->doa == 1) {
                                            $passarray = array("get" => $get, "transactionres" => $transactionres, "workflowres" => $workflowres, "nextstepvalue" => $nextstepvalue, "transaction_owner_field" => $transaction_owner_field, 'temp_owner_id' => $temp_owner_id);
                                            $steps = $this->workFlowCheckSteps($passarray);
                                            $steps['workflow_level_status'] = $nextstepvalue['workflow_level_status'];
                                            $steps['current_status'] = $current_status;
                                            $steps['approval_type'] = $nextstepvalue['approval_type'];
                                            $steps['sub_approve_type'] = $nextstepvalue['sub_approve_type'];
                                            $steps['minimum'] = $nextstepvalue['minimum'];
                                            $steps['approval_user_type'] = $nextstepvalue['approval_user_type'];
                                            $steps['updatebtn'] = $nextstepvalue['updatebtn'];
                                            $return['workflowsteps'][$current_status] = $steps;
                                            $return['breadcrumb'][$nextstepvalue['workflow_level_status']] = $steps;
                                            $validatestatusarry[$current_status] = $nextstepkey;
                                            $validatestatusarry[$nextstepkey] = '';
                                        }
                                    } else {
                                        $return['error'] = "9063"; //out side limit
                                    }
                                    $checkcondition++;
                                    break; //stop loop to check conditions
                                }
                            } // loop end
                        }
                    }
                    if ($checkcondition == 0) {
                        $return['error'] = "9062"; //"Criteria Not Set"
                    }
                    //direct approve
                    if (count((array) $validatestatusarry) == '0') {
                        $steps['workflow_level_status'] = ST_APPROVED;
                        $steps['current_status'] = ST_ACTIVE;
                        $steps['approval_type'] = '';
                        $steps['sub_approve_type'] = '';
                        $steps['minimum'] = '';
                        $steps['approval_user_type'] = '';
                        $steps['updatebtn'] = 1;
                        $return['workflowsteps'][ST_ACTIVE] = $steps;
                        $return['breadcrumb'][ST_APPROVED] = $steps;
                        $validatestatusarry[ST_ACTIVE] = ST_APPROVED;
                        $validatestatusarry[ST_APPROVED] = ST_APPROVED;
                    }





                } else {

                    foreach ($nextstepkeyvalue as $current_status => $nextstepkey) {
                        if ($nextstepkey != "") {
                            $nextstepvalue = $approvalprocesssetp[$nextstepkey];
                            $checkcondition = 0;
                            if ($cntworkflowdetailres == 0) {
                                $workflowdetailres = (object) ['approval_level_criteria' => '', 'doa_amount' => ''];
                            }
                            foreach ($workflowdetailres as $workflowdetailre) {
                                $loopcheckcondition = 0;
                                $approval_level_criteria = json_decode($workflowdetailre->approval_level_criteria, 1);
                                if ($approval_level_criteria['criteria'] != 'no') {
                                    foreach ($approval_level_criteria as $keyfield => $approvallevelcriteravalue) { //check approval level criteria
                                        if ($transactionres->$keyfield != $approvallevelcriteravalue) { //not match
                                            $loopcheckcondition++;
                                        }
                                    }
                                }

                                if ($loopcheckcondition == 0) {
                                    $passarray = array("get" => $get, "transactionres" => $transactionres, "workflowres" => $workflowres, "nextstepvalue" => $nextstepvalue, "transaction_owner_field" => $transaction_owner_field, 'temp_owner_id' => $temp_owner_id);

                                    $steps = $this->workflowchecksteps($passarray);
                                    $steps['workflow_level_status'] = $nextstepvalue['workflow_level_status'];
                                    $steps['current_status'] = $current_status;
                                    $steps['approval_type'] = $nextstepvalue['approval_type'];
                                    $steps['sub_approve_type'] = $nextstepvalue['sub_approve_type'];
                                    $steps['minimum'] = $nextstepvalue['minimum'];
                                    $steps['approval_user_type'] = $nextstepvalue['approval_user_type'];
                                    $steps['updatebtn'] = $nextstepvalue['updatebtn'];
                                    $return['workflowsteps'][$current_status] = $steps;
                                    $return['breadcrumb'][$nextstepvalue['workflow_level_status']] = $steps;
                                    $validatestatusarry[$current_status] = $nextstepkey;
                                    $validatestatusarry[$nextstepkey] = '';
                                    $checkcondition++;
                                    break; //stop loop to check conditions
                                }
                            }
                        }
                    }
                    if ($checkcondition == 0) {
                        $return['error'] = "9062"; //"Criteria Not Set"
                    }
                }
                $allsteps = $validatestatusarry;
                $allsteps[key(array_slice($allsteps, -1, 1, true))] = ST_APPROVED;
                $return['nextstepkeyvalue'] = $allsteps;
            } else {
                $return['error'] = "9061"; //Workflow not start
            }
        } else {
            $return['error'] = "9060"; //Workflow not defind
        }
        return $return;
    }
    public function workFlowCheckSteps($passarray)
    {
        global $callConfig;
        $get = $passarray['get'];
        $transaction_table = $get['transaction_table'];
        $transaction_owner_field = $passarray['transaction_owner_field'];
        $transactionres = $passarray['transactionres'];
        $workflowres = $passarray['workflowres'];
        $nextstepvalue = $passarray['nextstepvalue'];
        $temp_owner_id = $passarray['temp_owner_id'];
        $transactionflow = array();
        if ($workflowres->work_level_type == 'custom_process') {
            if ($nextstepvalue['approval_type'] == 'manager') {
                $sql = self::USER_SQL_SELECT_AU_REPORTS_TO_AU2_DISPL . $get['company_id'] . "' AND au.company_id = au2.company_id AND au.reports_to = au2.id AND au.is_active = au2.is_active AND au.id  = '" . $transaction_owner_field . self::USER_LIT_AND_AU_IS_ACTIVE_0;
                $rows = $callConfig->getRow($sql);
                $detailsusers = array("user_id" => $rows->reports_to, "display_name" => $rows->display_name, "user_email" => $rows->user_email);
                $transactionflow['aproval_user'][] = $detailsusers;

            } elseif ($nextstepvalue['approval_type'] == 'Managers_Manager') {

                $sql = self::USER_SQL_SELECT_AU_REPORTS_TO_AU2_DISPL . $get['company_id'] . "' AND au.company_id = au2.company_id AND au.reports_to = au2.id AND au.is_active = au2.is_active AND au.id  = (SELECT au3.reports_to FROM application_users au3 WHERE au3.id = '" . $transaction_owner_field . "' AND au.company_id = au3.company_id AND au.is_active = au3.is_active) AND au.is_active = 0";
                $rows = $callConfig->getRow($sql); //manager
                $detailsusers = array("user_id" => $rows->reports_to, "display_name" => $rows->display_name, "user_email" => $rows->user_email);
                $transactionflow['aproval_user'][] = $detailsusers;

            } elseif ($nextstepvalue['approval_type'] == "user") {

                $sql = "select id,display_name,user_email from application_users where company_id = '" . $get['company_id'] . "' AND  id='" . $nextstepvalue['sub_approve_type'] . self::USER_LIT_AND_IS_ACTIVE_0;
                $rows = $callConfig->getRow($sql);
                $detailsusers = array("user_id" => $rows->id, "display_name" => $rows->display_name, "user_email" => $rows->user_email);
                $transactionflow['aproval_user'][] = $detailsusers;

            } elseif ($nextstepvalue['approval_type'] == 'access_levels') {

                $like = "'" . '%"' . $nextstepvalue['sub_approve_type'] . '"%' . "'";
                $sql = self::USER_SQL_SELECT_ID_DISPLAY_NAME_USER_EM . $get['company_id'] . "' AND is_active = 0  AND role_id like " . $like;
                $rows = $callConfig->getAllRows($sql);
                foreach ($rows as $row) {
                    $detailsusers = array("user_id" => $row->id, "display_name" => $row->display_name, "user_email" => $row->user_email);
                    $transactionflow['aproval_user'][] = $detailsusers;
                }

            } elseif ($nextstepvalue['approval_type'] == 'buddy') {

                $get['emp_id'] = $temp_owner_id;
                $buddies = $this->findbuddyid($nextstepvalue, $get);
                $sql = "select au.id,au.display_name, au.user_email from application_users au, employees emp where au.company_id = '" . $get['company_id'] . "' AND au.company_id = emp.company_id  AND au.id = emp.user_id AND au.is_active = 0 AND emp.id='" . $buddies . "'";
                $rows = $callConfig->getRow($sql);
                $detailsusers = array("user_id" => $rows->id, "display_name" => $rows->display_name, "user_email" => $rows->user_email);
                $transactionflow['aproval_user'][] = $detailsusers;
            } elseif ($nextstepvalue['approval_type'] == 'allbuddy') {

                $get['emp_id'] = $temp_owner_id;
                $sql = "SELECT emp.id, (SELECT emp1.user_id FROM employees emp1 WHERE emp1.company_id = emp.company_id AND emp1.id = emp.hr_buddy) as hr_buddy, (SELECT emp2.user_id FROM employees emp2 WHERE emp2.company_id = emp.company_id AND emp2.id = emp.finance_buddy) as finance_buddy, (SELECT emp3.user_id FROM employees emp3 WHERE emp3.company_id = emp.company_id AND emp3.id = emp.admin_buddy) as admin_buddy, (SELECT emp4.user_id FROM employees emp4 WHERE emp4.company_id = emp.company_id AND emp4.id = emp.loc_buddy) as loc_buddy FROM employees emp where emp.company_id = '" . $get['company_id'] . "' AND  emp.id= " . $temp_owner_id . " AND emp.is_active = 0";
                $rows = $callConfig->getRow($sql);
                $allbuddyuser = array();
                if ($rows->hr_buddy != "") {
                    $allbuddyuser[$rows->hr_buddy] = $rows->hr_buddy;
                }
                if ($rows->finance_buddy != "") {
                    $allbuddyuser[$rows->finance_buddy] = $rows->finance_buddy;
                }
                if ($rows->admin_buddy != "") {
                    $allbuddyuser[$rows->admin_buddy] = $rows->admin_buddy;
                }
                if ($rows->loc_buddy != "") {
                    $allbuddyuser[$rows->loc_buddy] = $rows->loc_buddy;
                }
                if (count((array) $allbuddyuser) != 0) {
                    $sql1 = "select au.id,au.display_name, au.user_email from application_users au WHERE au.company_id = '" . $get['company_id'] . "' AND au.id IN(" . implode(',', (array) $allbuddyuser) . ") AND au.is_active = 0";
                    $rows1 = $callConfig->getAllRows($sql1);
                    foreach ($rows1 as $rowss) {
                        $detailsusers = array("user_id" => $rowss->id, "display_name" => $rowss->display_name, "user_email" => $rowss->user_email);
                        $transactionflow['aproval_user'][] = $detailsusers;
                    }
                } else {
                    $detailsusers = array("user_id" => 0, "display_name" => self::USER_LIT_NO_AVAILABLE, "user_email" => "");
                    $transactionflow['aproval_user'][] = $detailsusers;
                }
            } elseif ($nextstepvalue['approval_type'] == 'individual_employee_role') {
                $empsql = "select id,department_id from employees where company_id = '" . $get['company_id'] . "' AND is_active = 0 AND user_id='" . $transaction_owner_field . "'";
                $empres = $callConfig->getRow($empsql);
                $empdata = "select user_id,display_name,email_id from employees where role_id=" . $nextstepvalue['sub_approve_type'] . " AND department_id= '" . $empres->department_id . self::USER_LIT_AND_COMPANY_ID . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_4;
                $rows = $callConfig->getAllRows($empdata);
                foreach ($rows as $row) {
                    $detailsusers = array("user_id" => $row->user_id, "display_name" => $row->display_name, "user_email" => $row->email_id);
                    $transactionflow['aproval_user'][] = $detailsusers;
                }
            } elseif ($nextstepvalue['approval_type'] == 'email_groups') {
                $sql = "SELECT e.user_id,e.name,e.email FROM `email_group_emails` ege, email e WHERE ege.company_id = '" . $get['company_id'] . "' AND ege.email_id=e.id AND ege.email_groups_id =" . $nextstepvalue['sub_approve_type'] . " AND ege.is_active='0'";
                $rows = $callConfig->getAllRows($sql);
                foreach ($rows as $row) {
                    $detailsusers = array("user_id" => $row->user_id, "display_name" => $row->name, "user_email" => $row->email);
                    $transactionflow['aproval_user'][] = $detailsusers;
                }
            } elseif ($nextstepvalue['approval_type'] == 'custom_field') {
                $dynfield = $nextstepvalue['sub_approve_type'];
                $approvaluid = $transactionres->$dynfield;
                $sql = self::USER_SQL_SELECT_ID_DISPLAY_NAME_USER_EM . $get['company_id'] . self::USER_LIT_AND_ID . $approvaluid . self::USER_LIT_AND_IS_ACTIVE_0;
                $rows = $callConfig->getRow($sql);
                $detailsusers = array("user_id" => $rows->id, "display_name" => $rows->display_name, "user_email" => $rows->user_email);
                $transactionflow['aproval_user'][] = $detailsusers;
            } elseif ($nextstepvalue['approval_type'] == 'location_wise') {
                $dynfield = $nextstepvalue['sub_approve_field'];
                $location_id = '';
                if ($dynfield != '') {
                    $location_id = $transactionres->$dynfield;
                }
                $userIds = array();
                if (count((array) $nextstepvalue['location_approvers']) > 0) {
                    foreach ($nextstepvalue['location_approvers'] as $locRow) {
                        if ($locRow['location_id'] == $location_id) {
                            if (count((array) $locRow['user_ids']) > 0) {
                                foreach ($locRow['user_ids'] as $uid) {
                                    if ($uid != '') {
                                        $userIds[$uid] = $uid;
                                    }
                                }
                            }
                            break;
                        }
                    }
                }
                if (count((array) $userIds) > 0) {
                    $sql = "SELECT id, display_name, user_email FROM application_users WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_ID_IN . implode(',', (array) $userIds) . self::USER_LIT_AND_IS_ACTIVE_0_7;
                    $rows = $callConfig->getAllRows($sql);
                    if (count((array) $rows) > 0) {
                        foreach ($rows as $row) {
                            $detailsusers = array("user_id" => $row->id, "display_name" => $row->display_name, "user_email" => $row->user_email);
                            $transactionflow['aproval_user'][] = $detailsusers;
                        }
                    } else {
                        $detailsusers = array("user_id" => 0, "display_name" => self::USER_LIT_NO_AVAILABLE, "user_email" => "");
                        $transactionflow['aproval_user'][] = $detailsusers;
                    }
                } else {
                    $detailsusers = array("user_id" => 0, "display_name" => self::USER_LIT_NO_AVAILABLE, "user_email" => "");
                    $transactionflow['aproval_user'][] = $detailsusers;
                }
            }
        } elseif ($workflowres->work_level_type == 'user_hierarchical') {
            $reportid = '';
            for ($i = 1; $i <= $nextstepvalue['workflow_level_seq']; $i++) {
                if ($i == 1) {
                    $sql = self::USER_SQL_SELECT_AU_REPORTS_TO_AU2_DISPL . $get['company_id'] . "' AND au.company_id = au2.company_id AND au.reports_to = au2.id AND au.id='" . $transaction_owner_field . "' AND au.is_active = au2.is_active AND au.is_active = 0";
                    $row = $callConfig->getRow($sql);
                    $reportid = $row->reports_to;
                } else {
                    $sql = self::USER_SQL_SELECT_AU_REPORTS_TO_AU2_DISPL . $get['company_id'] . "' AND au.company_id = au2.company_id AND au.reports_to = au2.id AND au.id='" . $reportid . "' AND au.is_active = au2.is_active AND au.is_active = 0";
                    $row = $callConfig->getRow($sql);
                    $reportid = $row->reports_to;
                }
            }
            $detailsusers = array("user_id" => $row->reports_to, "display_name" => $row->display_name, "user_email" => $row->user_email);
            $transactionflow['aproval_user'][] = $detailsusers;
        }
        $transactionflow = $this->checkAllApprovalUserPagePermisions($get, $transactionflow, $transaction_table);
        return $transactionflow;
    }
    public function checkAllApprovalUserPagePermisions($get, $transactionflow, $transaction_table)
    {
        global $callConfig;
        $returnarray = array();
        $sql = "SELECT tapu.user_id FROM transaction_access_permission tap, transaction_access_permission_users tapu WHERE tap.company_id = '" . $get['company_id'] . "' AND tap.company_id =tapu.company_id AND tap.id =tapu.transaction_access_permission_id AND tap.transaction_table = '" . $transaction_table . "' AND (tapu.permission_view = 0 OR tapu.permission_insert = 0 OR tapu.permission_update = 0 OR tapu.permission_approval = 0) AND tap.is_active =tapu.is_active AND tap.is_active = 0";
        $row = $callConfig->getAllRows($sql);
        foreach ($row as $permissiontype) {
            $userlist[$permissiontype->user_id] = $permissiontype->user_id;
        }
        foreach ($transactionflow['aproval_user'] as $userdetail) {
            if (isset($userlist[$userdetail['user_id']])) {
                $userdetail['permision'] = "Y";
            } else {
                $userdetail['permision'] = "N";
            }
            $returnarray['aproval_user'][] = $userdetail;
        }
        return $returnarray;
    }



    public function keyArrayNextStep($array)
    {
        $keys = array_keys($array);
        $wfnextstatus = [];
        $totalKeys = count($keys);
        for ($i = 0; $i < $totalKeys; $i++) {
            $current_key = current($keys);
            $next_key = next($keys); // for php version >= 7.0
            $wfnextstatus[$current_key] = $next_key;
        }
        return $wfnextstatus;
    }


    public function getUserConnectWithEmpIdWorkflow($get)
    {
        global $callConfig;
        $user_id = $get['user_id'];
        $company_id = $get['company_id'];
        $query_sal = "SELECT emp1.location_id,(SELECT user_id FROM employees emp2 WHERE emp2.company_id = emp1.company_id  AND emp2.id  = emp1.hr_buddy) as hr_buddy,(SELECT user_id FROM employees emp3 WHERE emp3.company_id = emp1.company_id  AND emp3.id  = emp1.finance_buddy) as finance_buddy,(SELECT user_id FROM employees emp4 WHERE emp4.company_id = emp1.company_id  AND emp4.id  = emp1.admin_buddy) as admin_buddy,(SELECT user_id FROM employees emp5 WHERE emp5.company_id = emp1.company_id  AND emp5.id  = emp1.project_buddy) as project_buddy,(SELECT user_id FROM employees emp6 WHERE emp6.company_id = emp1.company_id  AND emp6.id  = emp1.loc_buddy) as loc_buddy,(SELECT au.reports_to FROM application_users au WHERE au.company_id = emp1.company_id  AND au.id  = emp1.user_id) as report_to FROM employees emp1  WHERE emp1.company_id = '" . $company_id . "' AND emp1.user_id = '" . $user_id . self::USER_LIT_AND_EMP1_IS_ACTIVE_0;
        $res = $callConfig->getRow($query_sal);
        $location_id = $res->location_id;
        $location_sql = "select hr_connect, admin_connect, finance_connect from locations where company_id='" . $company_id . self::USER_LIT_AND_IS_ACTIVE_0_AND_ID . $location_id . "'";
        $location_details = $callConfig->getRow($location_sql);

