    public function extraFunctionCall($get)
    {
        if ($get['next_status'] == ST_APPROVED) {
            if ($get['transaction_table'] == "petty_cash_box_topup_requests") {
                $pettycashObj = new pettyCashUserClass();
                $pettycash = $pettycashObj->insertPettyCashTopUpBalances($get, '+');
                $return = $pettycash;
            }
            if ($get['transaction_table'] == "petty_cash") {
                $pettycashObj = new pettyCashUserClass();
                $pettycash = $pettycashObj->insertPettyCashBalances($get, '-');
                $return = $pettycash;
            }
            if ($get['transaction_table'] == "transaction_activity_schedule") {
                $pettycash = $this->updateTransactionActivitySchedule1($get);
                $return = $pettycash;
            }
            if ($get['transaction_table'] == "sales_invoices" || $get['transaction_table'] == "delivery_challans") {
                $siinv = $this->salesInvoiceThroughDeliveryOrderCreated($get);
                $return = $siinv;
            }
            if ($get['transaction_table'] == "purchase_invoices") {
                $siinv = $this->purchaseInvoiceThroughgoodsreceiptnotesCreated($get);
                $return = $siinv;
            }
            if ($get['transaction_table'] == "csr_contractor_registations") {

                $siinv = $this->createUserCSRContractorRegistations($get['transaction_no'], $get);
                $return = $siinv;
            }
        } elseif ($get['next_status'] == ST_APPROVED1) {
            if ($get['transaction_table'] == "transaction_activity_schedule") {
                $pettycash = $this->updateTransactionActivitySchedule1($get);
                $return = $pettycash;
            }
        } elseif ($get['next_status'] == ST_REJECTED || $get['next_status'] == ST_SEND_BACK || $get['next_status'] == ST_CALLBACK) {
            if ($get['transaction_table'] == "petty_cash") {
                $pettycashObj = new pettyCashUserClass();
                $pettycash = $pettycashObj->insertPettyCashBalances($get, '+');
                $return = $pettycash;
            }
        }



        return $return;
    }

