    public function documentGenerationNextProcess($get, $transaction, $nexttransaction)
    {
        global $callConfig;
        $return = array();
        $return['get'] = $get;
        $return['transaction'] = $transaction;
        $get['transaction_table'] = $nexttransaction;
        $get['transaction_date_check'] = $transaction->transaction_date;
        $transaction_owner_id = $get['transaction_owner_id'];
        $getdocaccesssetup = $this->getdocumentsAccessSetupsRule($get);
        $allowdivisionusers = $allowdepartmentusers = $allowcostcenterusers = $allowlocationusers = array();
        if (count((array) $getdocaccesssetup['document_access_setupsres']) != 0 && $getdocaccesssetup['document_access_setupsres'] != "") {
            $return['getdocaccesssetup'] = $getdocaccesssetup;
            $nextlevelcreationuser = $getdocaccesssetup['user_document_access_setups'];
            $table_name = $get['table_name'];
            $dmtsql = "SELECT id, page_title, application_table_name,display_table,item_table,tax_table, option_url FROM `dynamic_mapping_tables` WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $table_name . self::USER_LIT_AND_IS_ACTIVE_0;
            $dmtres = $callConfig->getRow($dmtsql);
            $pitemsql = "SELECT pitem.id, pitem.item_id, item.category_id FROM " . $dmtres->item_table . " pitem, items item WHERE pitem.company_id = '" . $get['company_id'] . "' AND pitem.company_id = item.company_id AND pitem.item_id = item.id AND pitem.transaction_id ='" . $transaction->id . "' AND pitem.is_active = item.is_active AND pitem.is_active = 0";
            $pitemres = $callConfig->getAllRows($pitemsql);
            $catgoryarr = array();
            foreach ($pitemres as $pitemre) {
                $catgoryarr[] = $pitemre->category_id;
            }
            $userwithrolepermision = $getdocaccesssetup['document_access_setupsres']->create_access_users;
            if (count((array) $userwithrolepermision) != 0 && $userwithrolepermision != "") {

                foreach ($userwithrolepermision as $keyuid => $uidper) {
                    $alluserid[$keyuid] = $keyuid;
                }
                $divsql = "SELECT ucc1.id, ucc1.division_id, ucc1.user_id FROM user_divisions ucc1, user_divisions ucc2 WHERE ucc1.company_id = '" . $get['company_id'] . self::USER_LIT_AND_UCC1_USER_ID_IN . implode(",", (array) $alluserid) . self::USER_LIT_AND_UCC2_USER_ID . $transaction_owner_id . " AND ucc1.is_active = 0 AND ucc1.division_id = ucc2.division_id AND ucc1.company_id = ucc2.company_id AND ucc1.is_active = ucc2.is_active";
                $divres = $callConfig->getAllRows($divsql);
                foreach ($divres as $divress) {
                    $allowdivisionusers[$divress->user_id] = $divress->user_id;
                }
                $dipartmentsql = "SELECT ucc1.id, ucc1.department_id, ucc1.user_id FROM user_departments ucc1, user_departments ucc2 WHERE ucc1.company_id = '" . $get['company_id'] . self::USER_LIT_AND_UCC1_USER_ID_IN . implode(",", (array) $alluserid) . self::USER_LIT_AND_UCC2_USER_ID . $transaction_owner_id . " AND ucc1.is_active = 0 AND ucc1.department_id = ucc2.department_id AND ucc1.company_id = ucc2.company_id AND ucc1.is_active = ucc2.is_active";
                $dipartmentres = $callConfig->getAllRows($dipartmentsql);
                foreach ($dipartmentres as $divress) {
                    $allowdepartmentusers[$divress->user_id] = $divress->user_id;
                }
                $userccsql = "SELECT ucc1.id, ucc1.cost_center_id, ucc1.user_id FROM user_cost_centers ucc1, user_cost_centers ucc2 WHERE ucc1.company_id = '" . $get['company_id'] . self::USER_LIT_AND_UCC1_USER_ID_IN . implode(",", (array) $alluserid) . self::USER_LIT_AND_UCC2_USER_ID . $transaction_owner_id . " AND ucc1.is_active = 0 AND ucc1.cost_center_id = ucc2.cost_center_id AND ucc1.company_id = ucc2.company_id AND ucc1.is_active = ucc2.is_active";
                $userccres = $callConfig->getAllRows($userccsql);
                foreach ($userccres as $userccress) {
                    $allowcostcenterusers[$userccress->user_id] = $userccress->user_id;
                }
                $locationusersql = "SELECT ucc1.id, ucc1.location_id, ucc1.user_id FROM user_locations ucc1, user_locations ucc2 WHERE ucc1.company_id = '" . $get['company_id'] . self::USER_LIT_AND_UCC1_USER_ID_IN . implode(",", (array) $alluserid) . self::USER_LIT_AND_UCC2_USER_ID . $transaction_owner_id . " AND ucc1.is_active = 0 AND ucc1.location_id = ucc2.location_id AND ucc1.company_id = ucc2.company_id AND ucc1.is_active = ucc2.is_active";
                $locationuserres = $callConfig->getAllRows($locationusersql);
                foreach ($locationuserres as $locationress) {
                    $allowlocationusers[$locationress->user_id] = $locationress->user_id;
                }
            }
            $infouser_ids = array();
            foreach ($nextlevelcreationuser as $userid => $values) {
                $docaccesssetupsuser = $values;
                $nomatch = 0;
                if (count((array) $docaccesssetupsuser) != "0") {
                    if ($docaccesssetupsuser['approved_type'] != "") {
                        if ($docaccesssetupsuser['approved_type'] == "DIV") {
                            if (!isset($allowdivisionusers[$userid])) {
                                $nomatch++;
                            }
                        } elseif ($docaccesssetupsuser['approved_type'] == "D") {
                            if (!isset($allowdepartmentusers[$userid])) {
                                $nomatch++;
                            }
                        } elseif ($docaccesssetupsuser['approved_type'] == "cost_center_id") {
                            if (!isset($allowcostcenterusers[$userid])) {
                                $nomatch++;
                            }
                        } elseif ($docaccesssetupsuser['approved_type'] == "L") {
                            if (!isset($allowlocationusers[$userid])) {
                                $nomatch++;
                            }
                        }
                    }
                    if ($docaccesssetupsuser['opex_cpex'] != "" && $transaction->opex_cpex != $docaccesssetupsuser['opex_cpex']) {
                        $nomatch++;
                    }
                    if ($docaccesssetupsuser['amount'] != "" && $docaccesssetupsuser['amount'] != "0" && $transaction->total_amount > $docaccesssetupsuser['amount']) {
                        $nomatch++;
                    }
                    $item_categorylist = json_decode($docaccesssetupsuser['item_category']);
                    if (count((array) $item_categorylist) != "0") {
                        $matchornot = array_intersect((array) $catgoryarr, (array) $item_categorylist);
                        if (count((array) $matchornot) <= 0) {
                            $nomatch++;
                        }
                    }
                    $transaction_type = json_decode($docaccesssetupsuser['transaction_type']);
                    if (count((array) $transaction_type) != "0" && !in_array($transaction->opex_cpex, (array) $transaction_type)) {
                        $nomatch++;
                    }
                    if ($nomatch == 0) {
                        $infouser_ids[$userid] = $userid;
                    }
                }
            }
            if (count((array) $infouser_ids) != "0") {
                $msg = "Next Proceess Documents Is -" . $transaction->transaction_number;
                $notarry = array('company_id' => $get['company_id'], 'notification_message' => $msg, 'id' => $transaction->id, 'application_table_name' => $get['transaction_table'], 'type' => 'ACTION', 'notification_users' => $infouser_ids, 'option' => $dmtres->option_url, 'assigner_id' => $get['user_id']);
                $return['nextlevel_assigner_doumnets'] = $this->sendNotificationAndEmails($notarry, '', 23);
            } else {
                $msg = "Next Proceess Not Set -" . $transaction->transaction_number;
                $notarry = array('company_id' => $get['company_id'], 'notification_message' => $msg, 'id' => $transaction->id, 'application_table_name' => $get['transaction_table'], 'type' => 'ACTION', 'notification_users' => array($transaction_owner_id), 'option' => $dmtres->option_url, 'assigner_id' => $get['user_id']);
                $return['nextlevel_assigner_doumnets'] = $this->sendNotificationAndEmails($notarry, '', 23);
            }
        }
        return $return;

    }

    public function insertESOPVestingSchedule($transaction_details, $get)
    {
        global $callConfig;

        $vesting_schedule = json_decode($transaction_details->vesting_schedule, 1);
        foreach ($vesting_schedule as $vs) {
            $total_amount = $transaction_details->expected_option_benefit * $transaction_details->option_granted;
            $distributamount = round(($vs['vesting_percentage'] / 100) * $total_amount, 2);
            $distributshare = round(($vs['vesting_percentage'] / 100) * $transaction_details->option_granted, 2);
            $inservs = array('company_id' => $get['company_id'], 'esop_allocation_id' => $transaction_details->id, 'allocation_date' => $this->dateconvertdbformat($vs['vesting_date']), 'till_date' => $this->dateconvertdbformat($vs['till_date']), 'Percentage' => $vs['vesting_percentage'], 'total_amount' => $distributamount, 'allocation_share' => $distributshare, 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
            $callConfig->insertRecord('esop_vesting_schedule', $inservs);
        }
    }











































    public function workFlowSendNotificatinMsg($get, $transaction_owner_id, $workflow_details, $transaction_details)
    {
        global $callConfig;
        $returnarray = array();
        $process = array("process_name" => $workflow_details->process_name);


        $transaction_employee_sql = self::USER_SQL_SELECT_FROM_EMPLOYEES_WHERE_CO . $get['company_id'] . self::USER_LIT_AND_USER_ID_1 . $transaction_owner_id . self::USER_LIT_AND_IS_ACTIVE_0;
        $transaction_employee_detals = $callConfig->getRow($transaction_employee_sql);

        $transaction_user_sql = self::USER_SQL_SELECT_FROM_APPLICATION_USERS__1 . $get['company_id'] . self::USER_LIT_AND_ID_1 . $transaction_owner_id . self::USER_LIT_AND_IS_ACTIVE_0;
        $transaction_user_details = $callConfig->getRow($transaction_user_sql);

        $sessionuser_sql = self::USER_SQL_SELECT_FROM_APPLICATION_USERS__1 . $get['company_id'] . self::USER_LIT_AND_ID_1 . $get['user_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $sessionuser_details = $callConfig->getRow($sessionuser_sql);

        $sessionemployee_sql = self::USER_SQL_SELECT_FROM_EMPLOYEES_WHERE_CO . $get['company_id'] . self::USER_LIT_AND_USER_ID_1 . $get['user_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $sessionemployee_details = $callConfig->getRow($sessionemployee_sql);

        $statussql = "SELECT name FROM status_progress where company_id = '" . $get['company_id'] . "' and status='" . $get['next_status'] . self::USER_LIT_AND_TABLE_NAME . $get['transaction_table'] . "'";
        $statusres = $callConfig->getRow($statussql);
        if ($statusres->name != "") {
            $statusres->transaction_status = $statusres->name;
        } else {
            $statusres->transaction_status = "Not Found";
        }
        $notification_message_array = array('approve_message', 'approve_message_information', 'reject_message', 'sendback_message', 'completed_workflow_message', 'callback', 'employee_message');
        foreach ($notification_message_array as $msg_type) {
            $notification_message = json_decode($workflow_details->notification_message, 1);
            $msg = $notification_message[$msg_type];
            $msg = $this->replacestringwithpreview($get['transaction_table'], $process, $msg);
            $msg = $this->replacestringwithpreview($get['transaction_table'], $transaction_details, $msg);
            $msg = $this->replacestringwithpreview('employees', $transaction_employee_detals, $msg);
            $msg = $this->replacestringwithpreview('application_users', $transaction_user_details, $msg);
            $msg = $this->replacestringwithpreview('session_user', $sessionuser_details, $msg);
            $msg = $this->replacestringwithpreview('session_employee', $sessionemployee_details, $msg);
            $msg = $this->replacestringwithpreview($get['transaction_table'], $statusres, $msg);
            $returnarray[$msg_type] = $msg;
        }
        return $returnarray;
    }
    public function getDynamicQuotationDetails($get)
    {
        global $callConfig;
        $application_userssql = "SELECT id,display_name FROM application_users where company_id = '" . $get['company_id'] . "'";
