    public function getTopUpdetails($get)
    {
        global $callConfig;
        $application_table = $get['transaction_table'];
        $getnew = $get;
        $getnew['transaction_date_check'] = $get['transaction_date_check'];
        $returnres = $this->getdocumentsAccessSetupsRule($getnew);
        $displayattributessql = "SELECT id,application_table_name,help_text,list_attributes,empty_table_message,insert_page_type, help_text, file_upload FROM display_attributes WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $application_table . self::USER_LIT_AND_IS_ACTIVE_0;
        $displayattributesres = $callConfig->getRow($displayattributessql);
        $returnres['display_attributes'] = $displayattributesres;


        $lists = json_decode($displayattributesres->list_attributes, 1);
        $type_array = array('select', 'multi_select', 'disable_select', 'radio', 'checkbox', 'color_pick', 'image');
        foreach ($lists as $key => $value) {
            if (in_array($value['type'], (array) $type_array)) {
                $tablefield = $this->getDyanamicSelectData($application_table, $key);
                if ($tablefield['type'] != 'function') {
                    $field[$key] = $tablefield['res'];
                } else {
                    $field[$key] = $tablefield;
                }
            }
        }
        $returnres['field_result'] = $field;

        $displayattributestypesql = "SELECT content_details,field_name FROM display_attribute_types WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $application_table . "'";
        $returnres['displayattributestypesql'] = $displayattributestypesql;
        $displayattributestyperes = $callConfig->getAllRows($displayattributestypesql);
        foreach ($displayattributestyperes as $fieldtype) {
            $fieldtype->content_details_decode = json_decode(urldecode($fieldtype->content_details), 1);
            $returnres['display_attributes_type'][$fieldtype->field_name] = $fieldtype;
        }

        return $returnres;
    }

    public function dynamicCheckQtyValidation($get)
    {
        global $callConfig;
        if ($get['ref_table'] != "") {

            $dmtsql = self::USER_SQL_SELECT_ID_PAGE_TITLE_APPLICATI_1 . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $get['ref_table'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $dmtres = $callConfig->getRow($dmtsql);
            if (($get['ref_table'] == 'enquiries' || $get['ref_table'] == 'estimates' || $get['ref_table'] == 'sales_orders') && ($get['table_name'] == 'requisitions' || $get['table_name'] == 'quotations' || $get['table_name'] == 'purchase_orders')) {
                $select_pending_qty = ", pending_order_qty as pending_qty";
            } elseif (($get['table_name'] == "purchase_invoices" || $get['table_name'] == "sales_invoices") && ($get['ref_table'] == "purchase_orders" || $get['ref_table'] == "sales_orders")) {
                $select_pending_qty = ", ref_pending_qty_1 as pending_qty";
            } else {
                $select_pending_qty = ", pending_qty";
            }
            if ($get['ref_id'] != "") {
                $talsql = "SELECT id " . $select_pending_qty . self::USER_SQL_FROM . $dmtres->item_table . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . self::USER_LIT_AND_TRANSACTION_ID . $get['ref_id'] . self::USER_LIT_AND_ID . $get['ref_transaction_item_table_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
            } else {
                $talsql = "SELECT id " . $select_pending_qty . self::USER_SQL_FROM . $dmtres->item_table . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . self::USER_LIT_AND_ID . $get['ref_transaction_item_table_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
            }
            $talres = $callConfig->getRow($talsql);
            $return['talres_Sql'] = $talsql;
            $return['talres'] = $talres;
        } elseif ($get['table_name'] != "") {
            $trnsactioncheckmaxlimit = array('supplier_bills', 'purchase_invoices');
            $trnsactioncheckminlimit = array('sales_orders', 'sales_invoices');
            if (in_array($get['table_name'], (array) $trnsactioncheckmaxlimit)) {
                $res = $this->togetitemvalues($get['item_id']);
                $return['res'] = $res;
                if ($res->quantity_check == '1') {
                    $stock_in_hand = $res->stock_in_hand != "" ? $res->stock_in_hand : 0;
                    $purchase_order_qty = $res->purchase_order_qty != "" ? $res->purchase_order_qty : 0;
                    $maximum_capacity = $res->maximum_capacity != "" ? $res->maximum_capacity : 0;
                    $pending_qty = (($purchase_order_qty + $stock_in_hand) - $maximum_capacity);

                    $pending_qtys = $pending_qty != "" ? $pending_qty : 0;
                    $talres['pending_qty'] = round($pending_qtys, 2);
                }
                $return['talres'] = $talres;
            } elseif (in_array($get['table_name'], (array) $trnsactioncheckminlimit)) {
                $res = $this->togetitemvalues($get['item_id']);
                $return['res'] = $res;
                if ($res->quantity_check == '1') {
                    $stock_in_hand = $res->stock_in_hand != "" ? $res->stock_in_hand : 0;
                    $sales_order_qty = $res->sales_order_qty != "" ? $res->sales_order_qty : 0;
                    $minimum_level = $res->minimum_level != "" ? $res->minimum_level : 0;
                    $pending_qty = ($stock_in_hand - ($sales_order_qty + $minimum_level));
                    $pending_qtys = $pending_qty != "" ? $pending_qty : 0;
                    $talres['pending_qty'] = round($pending_qtys, 2);
                }
                $return['talres'] = $talres;
            }
        } else {
            $talres['pending_qty'] = round(99999999, 2);
        }
        return $talres;
    }



    public function updateTransactionItemsQty($get, $transaction, $operation = "")
    {
        global $callConfig;




        $out_array = array('grn_returns', 'stock_transfers', 'delivery_orders', 'stock_issues', 'rgp_delivery_orders', 'nrgp_delivery_orders', 'stock_transfer_returns', 'subcontract_work_order_transfers', 'sample_orders');
        $in_array = array('goods_receipt_notes', 'sales_returns', 'rgp_sales_returns', 'stock_transfer_receipts', 'subcontract_work_order_receipts');
        $reason_array = array('stock_adjustments', 'stock_take');

        $purchaseuomtables = array('goods_receipt_notes', 'grn_returns');
        $salesuomtables = array('delivery_orders', 'sales_returns', 'rgp_delivery_orders', 'nrgp_delivery_orders', 'rgp_sales_returns', 'stock_transfers', 'sample_orders');

        $parentdmtsql = self::USER_SQL_SELECT_ID_DISPLAY_TABLE_ITEM_T . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $get['transaction_table'] . self::USER_LIT_AND_ITEM_TABLE_AND_IS_ACTIVE_0;
        $parentdmtres = $callConfig->getRow($parentdmtsql);

        $itemressql = self::USER_SQL_SELECT_FROM . $parentdmtres->item_table . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . self::USER_LIT_AND_TRANSACTION_ID . $transaction->id . self::USER_LIT_AND_IS_ACTIVE_0;
        $itemresult = $callConfig->getAllRows($itemressql);
        $stock_adjustment_reasons = array();
        if (in_array($get['transaction_table'], (array) $reason_array)) {
            $sadjresonssql = "SELECT id, upordown FROM stock_adjustment_reasons WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $sadjresonsres = $callConfig->getAllRows($sadjresonssql);
            foreach ($sadjresonsres as $sadjres) {
                $stock_adjustment_reasons[$sadjres->id] = $sadjres->upordown; //1:ADD,0:MINS
            }
        }
        foreach ($itemresult as $itemres) {
            $mainitem = $this->togetitemvalues($itemres->item_id);
            $day_rate = $this->togetitemwadayrate($itemres->item_id, $get['company_id']);


            $transaction_warehouse_id = $transaction->transaction_warehouse_id;
            $request_warehouse_id = $transaction->request_warehouse_id;

            $len = array('company_id' => $itemres->company_id, 'location_id' => $transaction->transaction_location_id, 'transaction_warehouse_id' => $transaction_warehouse_id, 'transaction_date' => $transaction->transaction_date, 'item_id' => $itemres->item_id, 'document_no' => $transaction->id, 'document_type' => $get['transaction_table'], 'document_ref_no' => $transaction->transaction_number, 'in_qty' => $itemres->item_quantity, 'in_value' => $itemres->total_amount, 'item_in_value' => $itemres->item_amount, 'reason_id' => $itemres->reason_id, 'out_qty' => $itemres->item_quantity, 'out_value' => $itemres->total_amount, 'sale_price' => $itemres->item_price, 'sale_value' => $itemres->total_amount, 'item_wa_cost' => $day_rate, 'item_st_cost' => $mainitem->purchase_price, 'is_active' => '0', 'current_status' => '0', 'sales_qty' => 0, 'purchase_qty' => 0, 'request_warehouse_id' => $request_warehouse_id);


            if (in_array($get['transaction_table'], (array) $purchaseuomtables)) {
                $len['purchase_uom'] = $itemres->purchase_uom;
                $len['purchase_qty'] = $itemres->item_quantity;
                $len['purchase_base_uom'] = $itemres->base_uom;
                $parent_uom_id = $itemres->purchase_uom;
                $child_uom_id = $mainitem->base_uom;

            } elseif (in_array($get['transaction_table'], (array) $salesuomtables)) {
                $len['sales_uom'] = $itemres->purchase_uom;
                $len['sales_qty'] = $itemres->item_quantity;
                $len['sale_base_uom'] = $itemres->base_uom;
                $parent_uom_id = $itemres->purchase_uom;
                $child_uom_id = $mainitem->base_uom;
            }


            $convsql = "SELECT id,conversion_ratio FROM uom_conversions WHERE company_id = '" . $get['company_id'] . "' AND ((parent_uom_id = '" . $parent_uom_id . self::USER_LIT_AND_CHILD_UOM_ID . $child_uom_id . "') OR (parent_uom_id = '" . $child_uom_id . self::USER_LIT_AND_CHILD_UOM_ID . $parent_uom_id . "')) AND is_active = 0";
            $convresd = $callConfig->getRow($convsql);
            if ($convresd->id != "") {
                //ok coneversion
                if ($convresd->conversion_ratio != "0" && $convresd->conversion_ratio != "") {
                    $len['in_qty'] = $itemres->item_quantity * $convresd->conversion_ratio;
                    $len['in_value'] = $itemres->item_amount * $convresd->conversion_ratio;
                }
            } else {
                //reverse coneversion
                $convsql = "SELECT id,conversion_ratio FROM uom_conversions WHERE company_id = '" . $get['company_id'] . "' AND  ((parent_uom_id = '" . $parent_uom_id . self::USER_LIT_AND_CHILD_UOM_ID . $child_uom_id . "') OR (parent_uom_id = '" . $child_uom_id . self::USER_LIT_AND_CHILD_UOM_ID . $parent_uom_id . "'))  AND is_active = 0";
                $convresd = $callConfig->getRow($convsql);
                if ($convresd->id != "" && $convresd->conversion_ratio != "0" && $convresd->conversion_ratio != "") {
                    $len['in_qty'] = $itemres->item_quantity / $convresd->conversion_ratio;
                    $len['in_value'] = $itemres->item_amount / $convresd->conversion_ratio;
                }
            }

            if (in_array($get['transaction_table'], (array) $in_array)) {
                $len['out_qty'] = '0';
                $len['out_value'] = '0';
            } elseif (in_array($get['transaction_table'], (array) $out_array)) {
                $len['in_qty'] = '0';
                $len['in_value'] = '0';
            } elseif (in_array($get['transaction_table'], (array) $reason_array)) {
                $stockadjres = $stock_adjustment_reasons[$itemres->reason_id];
                if ($stockadjres == 1) { //1:ADD,0:MINS
                    $len['out_qty'] = '0';
                    $len['out_value'] = '0';
                } else {
                    $len['in_qty'] = '0';
                    $len['in_value'] = '0';
                }
                $len['item_wa_cost'] = $itemres->item_price;
                $len['day_rate'] = $itemres->item_price;
            } else {
                $len = array();
            }
            if (count((array) $len) != 0) {
                $this->invoiceUpdates($get['transaction_table'], $len);
            }
        }
        //stock In And Out Code End

        //pendding Qty Update Start
        if ($transaction->ref_type != "" && $operation != "") {
            $parentdmtsql = self::USER_SQL_SELECT_ID_DISPLAY_TABLE_ITEM_T . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $get['transaction_table'] . self::USER_LIT_AND_ITEM_TABLE_AND_IS_ACTIVE_0;
            $parentdmtres = $callConfig->getRow($parentdmtsql);

            $childdmtsql = self::USER_SQL_SELECT_ID_DISPLAY_TABLE_ITEM_T . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $transaction->ref_type . self::USER_LIT_AND_ITEM_TABLE_AND_IS_ACTIVE_0;
            $childdmtres = $callConfig->getRow($childdmtsql);




            if (($get['transaction_table'] == 'purchase_invoices' || $get['transaction_table'] == 'sales_invoices') && $transaction->ref_type != 'subcontract_work_order_receipts') {
                $pending_qty_condition = "rq_i.pending_order_qty = (rq_i.pending_order_qty " . $operation . " po_i.item_quantity)";
            } else {
                $pending_qty_condition = "rq_i.pending_qty = (rq_i.pending_qty " . $operation . " po_i.item_quantity)";
            }
            $updatesql = self::USER_SQL_UPDATE . $childdmtres->item_table . self::USER_LIT_RQ_I . $parentdmtres->item_table . " po_i SET " . $pending_qty_condition . " WHERE rq_i.company_id ='" . $get['company_id'] . "' AND rq_i.company_id = po_i.company_id AND rq_i.item_id = po_i.item_id AND po_i.transaction_id = '" . $transaction->id . self::USER_LIT_AND_RQ_I_ID_PO_I_REF_TRANSACTI;


            $return['updatesql'][] = $callConfig->executeQuery($updatesql);

            if ($get['transaction_table'] == 'grn_returns') {

                $qtsql = "SELECT id,ref_id,ref_type FROM goods_receipt_notes WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_ID . $transaction->ref_id . self::USER_LIT_AND_IS_ACTIVE_0;
                $extrapernttransaction = $callConfig->getRow($qtsql);

                $childdmtsql = self::USER_SQL_SELECT_ID_DISPLAY_TABLE_ITEM_T . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $extrapernttransaction->ref_type . self::USER_LIT_AND_IS_ACTIVE_0;
                $childdmtres = $callConfig->getRow($childdmtsql);
                //End Ref item Table deatils
                $updatesql = self::USER_SQL_UPDATE . $childdmtres->item_table . self::USER_LIT_RQ_I . $parentdmtres->item_table . " po_i SET rq_i.pending_qty = (rq_i.pending_qty + po_i.item_quantity) WHERE rq_i.company_id ='" . $get['company_id'] . "' AND rq_i.company_id = po_i.company_id AND rq_i.item_id = po_i.item_id AND po_i.transaction_id = '" . $transaction->id . self::USER_LIT_AND_RQ_I_ID_PO_I_REF_TRANSACTI;


                $return['updatesql'][] = $callConfig->executeQuery($updatesql);


            } elseif ($get['transaction_table'] == 'sales_returns') {

                $qtsql = "SELECT id,ref_id,ref_type FROM delivery_orders WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_ID . $transaction->ref_id . self::USER_LIT_AND_IS_ACTIVE_0;
                $extrapernttransaction = $callConfig->getRow($qtsql);

                $childdmtsql = self::USER_SQL_SELECT_ID_DISPLAY_TABLE_ITEM_T . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $extrapernttransaction->ref_type . self::USER_LIT_AND_IS_ACTIVE_0;
                $childdmtres = $callConfig->getRow($childdmtsql);
                //End Ref item Table deatils
                $updatesql = self::USER_SQL_UPDATE . $childdmtres->item_table . self::USER_LIT_RQ_I . $parentdmtres->item_table . " po_i SET rq_i.pending_qty = (rq_i.pending_qty + po_i.item_quantity) WHERE rq_i.company_id ='" . $get['company_id'] . "' AND rq_i.company_id = po_i.company_id  AND rq_i.item_id = po_i.item_id  AND po_i.transaction_id = '" . $transaction->id . self::USER_LIT_AND_RQ_I_ID_PO_I_REF_TRANSACTI;


                $return['updatesql'][] = $callConfig->executeQuery($updatesql);
            }
        }
        //pendding Qty Update End



        return $return;
    }

    public function getDynamicTransactionInvoices($get)
    {
        global $callConfig;
        $return = array();
        $return['get'] = $get;
        $originator = $get['fieldaccess'] != "" ? "party_id" : "originator";
        $checkuserid = $get['fieldaccess'] != "" ? $get['vendor_id'] : $get['user_id'];

        if ($get['admin_type'] != 1) {
            $condition = " AND transa." . $originator . " = '" . $checkuserid . "'";
        }

        $get['table'] = $get['transaction_table'];
        $status_progress = $this->getStatusProgressList($get);
        foreach ($status_progress as $statusprogress) {
            $return['status_progress'][$statusprogress->status] = $statusprogress;
        }

        $dmtsql = self::USER_SQL_SELECT_ID_PAGE_TITLE_APPLICATI . $get['company_id'] . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $get['transaction_table'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $dmtres = $callConfig->getRow($dmtsql);
        $return['dynamic_mapping_tables'] = $dmtres;

        if ($get['refrance_res'] == "Y") {
            $condition = " AND transa.ref_type = '" . $get['ref_table'] . "' AND transa.ref_id = '" . $get['ref_id'] . "'";
        }
        $listsql = "SELECT transa.id, transa.transaction_number, transa.transaction_date, transa.originator, transa.party_id, transa.party_name,transa.amount, transa.discount_amount, transa.tax_amount,transa.total_amount, itemtb.item_id, itemtb.item_name, itemtb.item_quantity, itemtb.pending_qty, itemtb.item_amount as atm_item_amount , itemtb.tax_amount as itm_tax_amount ,itemtb.total_amount as atm_total_amount, transa.current_status, transa.ref_type, transa.ref_no FROM " . $dmtres->application_table_name . " transa, " . $dmtres->item_table . " itemtb WHERE transa.company_id = '" . $get['company_id'] . "' AND transa.company_id = itemtb.company_id AND transa.id = itemtb.transaction_id AND transa.is_active = itemtb.is_active AND transa.is_active = 0 " . $condition;
        $listres = $callConfig->getAllRows($listsql);

        $list = array();
        foreach ($listres as $listre) {
            $list[$listre->id][] = $listre;
        }
        $return['transaction_list'] = $list;
        $return['sql'] = $listsql;
        return $return;

    }
}

