        $candidatesres = $callConfig->getRow($candidatessql);
        $return['candidates'] = $candidatesres;

        $document_listssql = "SELECT id, document_name FROM document_lists WHERE company_id = '" . $get['company_id'] . "' AND  category_id = '" . $get['category_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $document_listsres = $callConfig->getAllRows($document_listssql);
        $return['document_lists'] = $document_listsres;

        $esgin_budget_approvalssql = "SELECT id, document_name FROM esgin_budget_approvals WHERE company_id = '" . $get['company_id'] . "' AND  customer_id = '" . $candidatesres->vendor_id . self::USER_LIT_AND_IS_ACTIVE_0;
        $esgin_budget_approvalsres = $callConfig->getAllRows($esgin_budget_approvalssql);
        $return['esgin_budget_approvals'] = $esgin_budget_approvalsres;

        $employeessql = "SELECT id, display_name, emp_code, `hr_buddy`, `finance_buddy`, `admin_buddy`, `project_buddy`, `loc_buddy` FROM employees WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $employeesres = $callConfig->getAllRows($employeessql);
        $return['employees'] = $employeesres;

        $pendtaskcntsql = "SELECT assigned_to, approval_user_id, count(*) as total_task_cnt, SUM(if(current_status=" . ST_COMPLETE . ",1,0)) as review_cnt, SUM(if(current_status=" . ST_INPROGRESS . ",1,0)) as inprogress_cnt, SUM(if(current_status=" . ST_ACTIVE . ",1,0)) as yet_to_start_cnt FROM `transaction_activity_schedule` WHERE company_id = '" . $get['company_id'] . "' AND transaction_table = 'candidates' AND transaction_id = '" . $get['candidate_id'] . "' AND current_status != '" . ST_APPROVED . "' AND is_active = 0 GROUP By assigned_to";
        $pendtaskcntres = $callConfig->getAllRows($pendtaskcntsql);
        $return['pending_task'] = $pendtaskcntres;
        $return['pending_task_cnt_sql'] = $pendtaskcntsql;

        return $return;
    }
    public function getEmployeeOnboardingTask($get)
    {
        global $callConfig;
        $return = array();
        $return['get'] = $get;
        if (trim($get['taskassign']) == "Y") {
            $taslarraylist = array();
            $employeesquery = $callConfig->selectQuery('employees', '*', 'id=' . $get['employee_id'], '', '', '');
            $employees = $callConfig->getRow($employeesquery);
            $return['employees'] = $employees;
            $connectdetails = $this->getempconnectwithempid(array('employee_id' => $get['employee_id'], 'company_id' => $get['company_id']));
            $return['connectdetails'] = $connectdetails;
            $whr1 = self::USER_LIT_COMPANY_ID_1 . $get['company_id'] . "' AND assigned_to = 'EMP' AND process_type='I' AND is_active = 0";
            $task_query = $callConfig->selectQuery('process_task_settings', '*', $whr1, '', '', '');
            $task_data = $callConfig->getAllRows($task_query);
            $return['process_task_settings'] = $task_data;
            foreach ($task_data as $tasks1) {
                $taskid[$tasks1->id] = $tasks1->id;
            }
            $taskfilterary = array();
            if (count((array) $taskid) != 0) {
                $taskfiltersql = "SELECT * FROM filter_tables WHERE company_id = '" . $get['company_id'] . "' AND transaction_id IN(" . implode(',', $taskid) . self::USER_LIT_AND_IS_ACTIVE_0_7;
                $taskfilterres = $callConfig->getAllRows($taskfiltersql);
                foreach ($taskfilterres as $tasks2) {
                    $taskfilterary[$tasks2->transaction_id] = $tasks2;
                }
            }
            foreach ($task_data as $tasks) {
                $task_array = array();
                // Start check employee validate or Not For this Task
                $filterres = $taskfilterary[$tasks->id];
                $assignempchek = 0;
                if ($filterres->id != "" || $filterres->content != "") {
                    $show_filter_cond = $filterres->filter_condition;
                    $show_filter_cond = explode('&', $show_filter_cond);
                    foreach ($show_filter_cond as $show_filter_co) {
                        $fieldname = explode("=", $show_filter_co);
                        if ($fieldname['0'] != "check" && $fieldname['0'] != "table") {
                            $show_filter_condion[$fieldname['0']] = $fieldname['1'];
                        }
                    }
                    foreach ($show_filter_condion as $keys => $vale) {
                        if ($vale != "") {
                            $convertary = explode(",", $vale);
                            if (!in_array($employees->$keys, $convertary)) {
                                $assignempchek = 1;
                            }
                        }
                    }
                }
                // End check employee validate or Not For this Task
                if ($assignempchek == 0) {
                    $days_ago = $employees->joining_date;
                    $approval_id = "";
                    if ($tasks->approval_type == 'AB') {
                        $approval_id = $connectdetails['admin_connect'];
                    } elseif ($tasks->approval_type == 'FB') {
                        $approval_id = $connectdetails['finance_connect'];
                    } elseif ($tasks->approval_type == 'PB') {
                        $approval_id = $connectdetails['project_connect'];
                    } elseif ($tasks->approval_type == 'OB') {
                        $approval_id = $tasks->approval_other_id;
                    } else {
                        $approval_id = $connectdetails['hr_connect'];
                    }
                    if ($tasks->on_the_day != 1) {
                        if ($tasks->action_frequency == 'DY') {
                            $day = $tasks->on_the_day;
                        }
                        if ($tasks->action_frequency == 'WK') {
                            $day = 7;
                        }
                        if ($tasks->action_frequency == 'MON') {
                            $day = 30;
                        }
                        if ($tasks->before_or_after == 'BF') {
                            $day = "-" . $day;
                        } else {
                            $day = "+" . $day;
                        }
                        $days_ago = date('Y-m-d', strtotime($day . self::USER_LIT_DAYS, strtotime($employees->joining_date)));
                    }
                    $task_array = array('company_id' => $get['company_id'], 'transaction_table' => 'employees', 'transaction_id' => $get['employee_id'], 'task_id' => $tasks->id, 'assigned_to' => $employees->user_id, 'action_date' => $days_ago, 'action_flag' => '0', 'check_list' => $tasks->check_list, 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id'], 'approval_user_id' => $approval_id, 'task_name' => $tasks->task_name);
                    if ($get['submit'] != 'Y') {
                        $task_array['process_id'] = $tasks->process_id; ///extrea
                    }
                    $taslarraylist[] = $task_array;
                    if ($get['submit'] == 'Y') {
                        unset($task_array['task_name']);
                        $res = $callConfig->insertRecord('transaction_activity_schedule', $task_array);
                        $return['transaction_activity_schedule_insert'] = $res;
                    }
                }
            }
            $return['assign_task_list'] = $taslarraylist;
            if ($get['submit'] == 'Y') {
                $notiarray = array('notification_message' => 'All Schedule Task Assign ' . $employees->display_name, 'notification_users' => array('0' => $get['user_id'], '1' => $employees->user_id), 'id' => $employees->id, 'application_table_name' => 'transaction_activity_schedule', 'company_id' => $get['company_id'], 'option' => 'COM_VIEW_ONBOARDING_EMPLOYEE_DASHBOARDS', 'notification_datetime' => $days_ago, 'type' => 'INFORMATION');
                $this->tosendnotifiations($notiarray);
            }
        } elseif ($get['dashboard_type'] != "HR") {
            if ($get['admin_type'] != '1') {
                $comdition = " AND tas.assigned_to = '" . $get['user_id'] . "'";
            }
            $taskactivitysql = "SELECT tas.id,tas.action_date,tas.revised_action_date, tas.actual_action_date, tas.action_flag, tas.check_list, tas.current_status, tas.process_id, tas.task_name FROM transaction_activity_schedule tas WHERE tas.company_id = '" . $get['company_id'] . "' AND tas.transaction_table = 'employees'  AND transaction_id= '" . $get['employee_id'] . "' " . $comdition . self::USER_SQL_AND_TAS_IS_ACTIVE_0;
            $taskactivityres = $callConfig->getAllRows($taskactivitysql);
            $return['sql'] = $taskactivitysql;
            $return['transaction_activity_schedule'] = $taskactivityres;
            $tasks_cntssql = "SELECT count(*) as total_task_cnt, sum(if(current_status=" . ST_APPROVED . self::USER_LIT_1_0_AS_APPROVE_CNT_SUM_IF_CURR . ST_COMPLETE . self::USER_LIT_1_0_AS_REVIEW_CNT_SUM_IF_CURRE . ST_INPROGRESS . self::USER_LIT_1_0_AS_INPROGRESS_CNT_SUM_IF_C . ST_ACTIVE . ",1,0)) as yet_to_start_cnt FROM transaction_activity_schedule tas WHERE  tas.company_id = '" . $get['company_id'] . "' AND tas.transaction_table = 'employees'  AND transaction_id= '" . $get['employee_id'] . "' " . $comdition . self::USER_SQL_AND_TAS_IS_ACTIVE_0;
            $tasks_cntsres = $callConfig->getRow($tasks_cntssql);
            $return['task_cnt'] = $tasks_cntsres;
            $employeesql = "SELECT * FROM employees WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_ID_6 . $get['employee_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $employeeres = $callConfig->getRow($employeesql);
            $return['employees'] = $employeeres;
        } else {
            $employeesql = "SELECT emp.id, au.id as user_id, emp.emp_code,  emp.display_name, emp.email_id, emp.joining_date FROM application_users au, employees emp WHERE au.company_id = emp.company_id AND au.company_id = '" . $get['company_id'] . "' AND au.role_id LIKE '" . '%"' . EMPLOYEE_ONBOARDING . '"%' . "' AND au.id = emp.user_id AND au.is_active = emp.is_active AND au.is_active = 0";
            $employeeres = $callConfig->getAllRows($employeesql);
            $onboarduserid = array();
            $onboardempid = array();
            foreach ($employeeres as $empres) {
                $onboarduserid[$empres->user_id] = $empres->user_id;
                $onboardempid[$empres->id] = $empres->id;
            }
            $employeecntsql = "SELECT MONTHNAME(emp.joining_date) as month, count(emp.id) as cnt FROM application_users au, employees emp WHERE au.company_id = emp.company_id AND au.company_id = '" . $get['company_id'] . "' AND au.role_id LIKE '" . '%"' . EMPLOYEE_ONBOARDING . '"%' . "' AND emp.joining_date >='" . $get['startdate'] . self::USER_LIT_AND_EMP_JOINING_DATE . $get['enddate'] . "' AND au.id = emp.user_id AND au.is_active = emp.is_active AND au.is_active = 0 group by month(emp.joining_date)";
            $employeecntres = $callConfig->getAllRows($employeecntsql);
            foreach ($employeecntres as $cntn) {
                $employeecnt[$cntn->month] = $cntn->cnt;
            }
            $return['monthlycnt'] = $employeecnt;
            $tasks_cntssql = "SELECT assigned_to, transaction_id, count(*) as total_task_cnt, sum(if(current_status=" . ST_APPROVED . self::USER_LIT_1_0_AS_APPROVE_CNT_SUM_IF_CURR . ST_COMPLETE . self::USER_LIT_1_0_AS_REVIEW_CNT_SUM_IF_CURRE . ST_INPROGRESS . self::USER_LIT_1_0_AS_INPROGRESS_CNT_SUM_IF_C . ST_ACTIVE . ",1,0)) as yet_to_start_cnt, sum(if(action_date < completion_date,1,0)) as delayed_cnt FROM transaction_activity_schedule tas WHERE  tas.company_id = '" . $get['company_id'] . "' AND tas.transaction_table = 'employees'  AND transaction_id IN(" . implode(',', $onboardempid) . ") AND tas.assigned_to IN(" . implode(',', $onboarduserid) . ") AND tas.is_active = 0 GROUP BY tas.assigned_to";
            $tasks_cntsres = $callConfig->getAllRows($tasks_cntssql);
            $return['tasks_cntssql'] = $tasks_cntssql;
            $return['tasks_result'] = $tasks_cntsres;
            $return['onboarduserid'] = $onboarduserid;
            $return['onboard_employees'] = $employeeres;

        }
        $tasks_categoriessql = self::USER_SQL_SELECT_ID_CATEGORY_NAME_FROM_T . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $tasks_categoriesres = $callConfig->getAllRows($tasks_categoriessql);
        $return['tasks_categories'] = $tasks_categoriesres;
        return $return;
    }
    public function updateOnBoardingTaskStatus($post)
    {
        global $callConfig;
        $return = array();
        $return['get'] = $post;
        $taskactivitysql = "SELECT tas.task_name, tas.assigned_to, tas.transaction_id, tas.approval_user_id, tas.transaction_table FROM transaction_activity_schedule tas WHERE tas.company_id = '" . $post['company_id'] . "' AND tas.transaction_table = '" . $post['transaction_action_table'] . "' AND tas.id= '" . $post['transaction_id'] . self::USER_LIT_AND_TAS_IS_ACTIVE_0;
        $taskactivityres = $callConfig->getRow($taskactivitysql);
        $return['taskactivityres'] = $taskactivitysql;
        $updatearray = array('current_status' => $post['status'], 'comments' => $post['comment']);
        if ($post['status'] == ST_APPROVED) {
            $updatearray['approval_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
        }
        $return['res'] = $callConfig->updateRecord('transaction_activity_schedule', $updatearray, 'id', $post['transaction_id']);
        if ($post['status'] == ST_APPROVED) {
            $approvalmsg = $taskactivityres->task_name . ' Task Successfully Approved';
        } else {
            $approvalmsg = $taskactivityres->task_name . ' Task Is Rejetced';
        }
        $notiarray = array('notification_message' => $approvalmsg, 'notification_users' => array('0' => $taskactivityres->approval_user_id), 'id' => $taskactivityres->transaction_id, 'application_table_name' => 'transaction_activity_schedule', 'company_id' => $post['company_id'], 'option' => 'COM_VIEW_ONBOARDING_EMPLOYEE_DASHBOARDS', 'notification_datetime' => date('Y-m-d H:i'), 'type' => 'INFORMATION');
        if ($taskactivityres->transaction_table == "vendor_registers") {
            $notiarray['option'] = 'COM_INSERT_VENDORS&VTYPE=VR';
        }
        $return['notiarray'] = $notiarray;
        $this->tosendnotifiations($notiarray);

        if (isset($taskactivityres->assigned_to)) {
            $notiarray['notification_users'] = array("0" => $taskactivityres->assigned_to);
            $notiarray['type'] = "ACTION";
            $this->tosendnotifiations($notiarray);
        }

        return $return;
    }

