        $jvary = array('company_id' => $post['company_id'], 'transaction_location_id' => $user->location_id, 'transaction_id' => '', 'transaction_item_id' => '', 'item_id' => '', 'particulars' => $perticularnote, 'item_name' => $perticularnote, 'description' => $perticularnote, 'purchase_uom' => '', 'item_quantity' => 0, 'item_price' => 0, 'item_amount' => 0, 'tax_amount' => 0, 'discount_amount' => 0, 'total_amount' => 0, 'name_type' => 'C', 'doc_ref_no' => '', 'doc_ref_date' => '', 'req_date' => $paymentsres->payment_date, 'approved_quantity' => 0, 'transaction_type' => '', 'transaction_qty' => 0, 'pending_qty' => 0, 'is_active' => '0', 'current_status' => '0', 'created_by' => $itemrow['created_by'], 'account_code' => $debitaccount, 'debit_amount' => $debitamount, 'credit_amount' => $creaditamount);
        $itemref[$debitaccount][] = $jvary;
        // bank or Cash row

        // Vendor or customer acccount
        foreach ($partywithamount as $prt_id => $invamount) {
            $vendorssql = "SELECT * " . $selectfield . self::USER_SQL_FROM . $party_table . self::USER_SQL_WHERE_COMPANY_ID . $post['company_id'] . self::USER_LIT_AND_ID . $prt_id . self::USER_LIT_AND_IS_ACTIVE_0_1;
            $vendorsres = $callConfig->getRow($vendorssql);
            $return['vendors'] = $vendorsres;

            if ($paymentsres->transaction_type == "customers") {
                $partycreditamount = $invamount['total_paid_amount'];
            } elseif ($paymentsres->transaction_type == "employees") {
                $partydebitamount = $invamount['total_paid_amount'];
            } else {
                $partydebitamount = $invamount['total_paid_amount'];
            }
            if ($vendorsres->account_code != "") {
                $partyyaccount = $vendorsres->account_code;
            } else {
                $partyyaccount = $suspense_account;
            }
            if ($chartofaccount[$partyyaccount] == "" || $partyyaccount == "") { // chart Of Account Not Found Suspens Account Enter data
                $partyyaccount = $suspense_account;
            }


            $witemlist[] = array('company_id' => $post['company_id'], 'transaction_location_id' => $user->location_id, 'department_id' => $user->department_id, 'cost_center_id' => $user->cost_center, 'transaction_id' => $transaction_id, 'account_code' => $partyyaccount, 'particulars' => '', 'debit_amount' => $partydebitamount, 'credit_amount' => $partycreditamount, 'is_active' => '0', 'current_status' => '0', 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'created_by' => $paymentsres->originator, 'particulars' => 'Party');

            $jvary = array('company_id' => $post['company_id'], 'transaction_location_id' => $user->location_id, 'transaction_id' => '', 'transaction_item_id' => '', 'item_id' => '', 'particulars' => 'Party', 'item_name' => $vendorsres->display_name, 'description' => $vendorsres->display_name, 'purchase_uom' => '', 'item_quantity' => 0, 'item_price' => 0, 'item_amount' => 0, 'tax_amount' => 0, 'discount_amount' => 0, 'total_amount' => 0, 'name_type' => 'C', 'doc_ref_no' => '', 'doc_ref_date' => '', 'req_date' => $paymentsres->payment_date, 'approved_quantity' => 0, 'transaction_type' => '', 'transaction_qty' => 0, 'pending_qty' => 0, 'is_active' => '0', 'current_status' => '0', 'created_by' => $itemrow['created_by'], 'account_code' => $partyyaccount, 'debit_amount' => $partydebitamount, 'credit_amount' => $partycreditamount);
            $itemref[$partyyaccount][] = $jvary;
        }
        // Vendor or customer acccount


        //Start Suspense Account One Entry Added
        $suspense_account = $partyyaccount; // direct party account added
        $suspensearry = array('company_id' => $post['company_id'], 'transaction_location_id' => $user->location_id, 'department_id' => $user->department_id, 'cost_center_id' => $user->cost_center, 'transaction_id' => $transaction_id, 'account_code' => $suspense_account, 'particulars' => 'Suspense', 'is_active' => '0', 'current_status' => '0', 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'created_by' => $paymentsres->originator, 'particulars' => 'Suspense');

        $jvary = array('company_id' => $post['company_id'], 'transaction_location_id' => $user->location_id, 'transaction_id' => '', 'transaction_item_id' => '', 'item_id' => '', 'particulars' => 'Suspense', 'item_name' => 'Suspense', 'description' => 'Suspense', 'purchase_uom' => '', 'item_quantity' => 0, 'item_price' => 0, 'item_amount' => 0, 'tax_amount' => 0, 'discount_amount' => 0, 'total_amount' => 0, 'name_type' => 'C', 'doc_ref_no' => '', 'doc_ref_date' => '', 'req_date' => $paymentsres->payment_date, 'approved_quantity' => 0, 'transaction_type' => '', 'transaction_qty' => 0, 'pending_qty' => 0, 'is_active' => '0', 'current_status' => '0', 'created_by' => $itemrow['created_by'], 'account_code' => $suspense_account);

        if ($paymentsres->amount > $paymentsres->allocated_amount) {
            $suspensearry['credit_amount'] = $paymentsres->unallocated_amount;
            $jvary['credit_amount'] = $paymentsres->unallocated_amount;
            $itemref[$suspense_account][] = $jvary;
            $witemlist[] = $suspensearry;
        } elseif ($paymentsres->amount < $paymentsres->allocated_amount) {
            $suspensearry['debit_amount'] = $paymentsres->unallocated_amount;
            $jvary['debit_amount'] = $paymentsres->unallocated_amount;
            $itemref[$suspense_account][] = $jvary;
            $witemlist[] = $suspensearry;
        } else {
            $suspensearry = array();
            $jvary = array();
        }
        //End suspense Account One Entry Added

        $postdata = array('main' => $senddata, 'items' => $witemlist, 'itemref' => $itemref, 'update_id' => '', 'company_id' => $post['company_id']);
        $return['postdata'] = $postdata;
        $return['addjournalvouchers'] = $this->addjournalvouchers($postdata, $transaction_table, $type, $insertjvtable);
        return $return;
    }
}

