    public function togethremployeedetails($get)
    {
        global $callConfig;
        $query = "SELECT id, display_name, image FROM employees WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_ID_3 . $get['emp_id'] . self::USER_SQL_AND_IS_ACTIVE_0_1;
        $return['employee'] = $callConfig->getRow($query);
        $query = "SELECT id,leave_type_name,leave_category_id FROM leave_types WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_IS_ACTIVE_0_1;
        $return['leave_type'] = $callConfig->getAllRows($query);
        $query = "SELECT id,leave_type_id,leave_from,leave_to FROM employee_leaves WHERE company_id=" . $get['company_id'] . " AND employee_id=" . $get['emp_id'] . " AND is_active=0 AND YEAR(leave_from) = '" . date('Y') . "'";
        $return['leave'] = $callConfig->getAllRows($query);
        $query = "SELECT id,recognition_type,badge_id,recognition_from, recognition_to, comments, created_date FROM employee_recognitions WHERE company_id=" . $get['company_id'] . " AND  is_active=0 ORDER BY id DESC LIMIT 0,10 ";
