        $query = "SELECT `id`, `company_id`, `event_category_id`, `user_id`, `event_name`, `event_short_name`, `event_description`, `reoccurring_events`, `reoccurring_type`, `auto_manual`, `start_date`, `end_date`, `start_time`, `end_time`, `event_duration`, `remarks`, `event_url` FROM employee_events WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_USER_ID_3 . $get['user_id'] . self::USER_SQL_AND_IS_ACTIVE_0_4;
