        $month_holidays = $callConfig->getAllRows($query);
        foreach ($month_holidays as $mholiday) {
            $mnholiday[] = $mholiday->attendace_date;
        }
        $return['month_holidays'] = $mnholiday;

        $query = "SELECT id,attendace_date FROM employee_daily_attendances WHERE company_id=" . $get['company_id'] . "  AND employee_id=" . $get['emp_id'] . " AND  YEAR(attendace_date)=" . date('Y') . " AND MONTH(attendace_date)= " . date('m') . "  AND  is_active=0 ";
        $return['attedance'] = $callConfig->getAllRows($query);
        $query = "SELECT wfh.id,wfh.effective_from_date,wfh.effective_to_date, wfh.emp_id, emp.display_name, emp.image FROM request_work_from_home wfh, employees emp WHERE wfh.company_id=" . $get['company_id'] . " AND wfh.emp_id= emp.id AND wfh.emp_id =" . $get['emp_id'] . " AND wfh.is_active=0 ORDER By wfh.id DESC";
        $return['wfh'] = $callConfig->getAllRows($query);
        $query = "SELECT id,working_days FROM attendance_settings WHERE company_id=" . $get['company_id'] . "  AND is_active=0 ORDER By id DESC LIMIT 0,1";
        $return['weekatt'] = $callConfig->getRow($query);
        return $return;
    }
