    {
        global $callConfig;
        $return = array();
        $return['get'] = $get;
        if ($get['option'] != "") {
            $condition = " AND page_option = '" . $get['option'] . "'";
        } else {
            $condition = " AND module_setup_id = '" . $get['module_id'] . "'";
        }
        $aetsql = "SELECT  id, transaction_tables FROM application_missing_data_check WHERE company_id = '" . $get['company_id'] . "' " . $condition . self::USER_SQL_AND_IS_ACTIVE_0_1;
        $return['aetsql'] = $aetsql;
        $aetres = $callConfig->getRow($aetsql);
        $return['application_empty_transactions_sql'] = $aetsql;
        $return['application_empty_transactions'] = $aetres;
        $transaction_tables = json_decode($aetres->transaction_tables, 1);
        $empty_array = array();

        $application_pagessaql = "SELECT application_table_name, list_page_name, insert_page_name FROM application_pages WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
        $return['application_pagessaql'] = $application_pagessaql;
        $application_pagessres = $callConfig->getAllRows($application_pagessaql);
        foreach ($application_pagessres as $ap) {
            $application_pages[$ap->application_table_name]['list_page_name'] = $ap->list_page_name;
            $application_pages[$ap->application_table_name]['insert_page_name'] = $ap->insert_page_name;
        }
        $dynamicsql = self::USER_SQL_SELECT;
        $transactiondetails = array();
        foreach ($transaction_tables as $values) {
            $transactiondetails[$values['transaction_table']] = $values;
            $transactiondetails[$values['transaction_table']]['option'] = $application_pages[$values['transaction_table']][$values['option_type']];
            $dynamicsql .= "(Select count(id) as cnt FROM " . $values['transaction_table'] . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . "' AND is_active = 0 limit 1) as " . $values['transaction_table'] . ",";
        }
        $dynamicsql = substr($dynamicsql, 0, -1);
        $tableresult = $callConfig->getRow($dynamicsql);
        foreach ($tableresult as $tablename => $cnt) {
            $valuesary = $transactiondetails[$tablename];
            $valuesary['cnt'] = $cnt != "" ? $cnt : 0;

            $empty_array[] = $valuesary;
        }

        $return['empty_transaction'] = $empty_array;
        $return['empty_transaction_sql'] = $dynamicsql;
        return $return;
    }
    public function getApplicationEmptyTransactions($get)
