                $insertary = array('company_id' => $company_id, 'task_type' => '2', 'assigen_id' => $transactionres->originator, 'task_name' => EMAIL_TASK['message'], 'planned_start' => $task_date, 'transaction_table' => $transaction_table, 'transaction_id' => $transaction_id, 'ref_table' => 'follow_up_levels', 'ref_id' => $ful->id, 'follow_up_type' => EMAIL_TASK['type'], 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
                $return[] = $callConfig->insertRecord('project_task_details', $insertary);
            }
            if ($ful->send_sms == '0') {
                $insertary = array('company_id' => $company_id, 'task_type' => '2', 'assigen_id' => $transactionres->originator, 'task_name' => SMS_TASK['message'], 'planned_start' => $task_date, 'transaction_table' => $transaction_table, 'transaction_id' => $transaction_id, 'ref_table' => 'follow_up_levels', 'ref_id' => $ful->id, 'follow_up_type' => EMAIL_TASK['type'], 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
                $return[] = $callConfig->insertRecord('project_task_details', $insertary);
            }
            if ($ful->follow_up_call == '0') {
                $insertary = array('company_id' => $company_id, 'task_type' => '2', 'assigen_id' => $transactionres->originator, 'task_name' => CALL_TASK['message'], 'planned_start' => $task_date, 'transaction_table' => $transaction_table, 'transaction_id' => $transaction_id, 'ref_table' => 'follow_up_levels', 'ref_id' => $ful->id, 'follow_up_type' => EMAIL_TASK['type'], 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
                $return[] = $callConfig->insertRecord('project_task_details', $insertary);
            }
        }
        $return['follow_up_levels'] = $follow_up_levelsres;
        return $return;
