        $template_reference_id = $get['template_reference_id'];

        $rental_invoicessql = self::USER_SQL_SELECT_FROM . $transaction_table . self::USER_SQL_WHERE_COMPANY_ID . $get['company_id'] . self::USER_LIT_AND_ID . $transaction_id . self::USER_LIT_AND_IS_ACTIVE_0_11;
