        $emailarray['user_email_id'] = $rental_invoicesres->party_email;
        $emailarray['transaction_table'] = $transaction_table;
        $emailarray['transaction_id'] = $transaction_id;
        $emailarray['transaction_number'] = $rental_invoicesres->transaction_number;
        $emailarray['transaction_date'] = $rental_invoicesres->transaction_date;
        $emailarray['transaction_name'] = ucwords(str_replace('_', ' ', $transaction_table));
        $emailarray['total_amount'] = $rental_invoicesres->total_amount;
        $emailarray['created_by'] = $get['user_id'];
        $emailarray['transaction_due_date'] = $rental_invoicesres->due_date;
        $emailarray['transaction_originater_name'] = $originatersres->display_name;
        $emailarray['transaction_originater_email_id'] = $originatersres->user_email;

        $emailarray['reference_transaction_table'] = $get['reference_transaction_table'];
        $emailarray['reference_transaction_id'] = $get['reference_transaction_id'];
        if ($emailarray['attach_invoice_or_not'] == '0' || $emailarray['attach_invoice_or_not'] == "") {
            $emailarray['attachment'] = "Y";
            $emailarray['attachment_file_name'] = $attachment_file_name;
            $emailarray['attachment_file_path'] = $attachment_file_path;
        }
        $notarry = array();
        $email = $this->sendNotificationAndEmails($notarry, $emailarray, $template_reference_id);
        $retrun['email'] = $email;
        return $return;
    }
    public function generateDynamicInvoicePDF($get, $rid = "")
    {
        if (isset($rid)) { /* noop */ }
        global $callConfig;
        $return = array();
        $transaction_id = $get['transaction_id'];
        $transaction_table = $get['transaction_table'];
        $get['rid'] = $transaction_id;
        $postarray = $this->getDynamicInvoicePrint($get);
        $postarray['callapi'] = 'Y';
        $api_url = SITEURL . 'views/custom_qo_print.php';
        $postdata = http_build_query($postarray);
        $opts = array(
            'http' => array(
                'method' => 'POST',
                'header' => "Content-type: application/x-www-form-urlencoded\r\n",
                'content' => $postdata
            )
        );
        $context = stream_context_create($opts);
        $content = file_get_contents($api_url, false, $context);
        $options = new Options();
        $options->set('chroot', realpath(''));
        $options->set('isHtml5ParserEnabled', true);
        $options->set('isPhpEnabled', true);
        $dompdf = new Dompdf($options);
        $dompdf->set_option('margin-top', '10mm');
        $dompdf->set_option('margin-right', '10mm');
        $dompdf->set_option('margin-bottom', '10mm');
        $dompdf->set_option('margin-left', '10mm');
        $dompdf->loadHtml($content);
        $dompdf->setPaper('A4', 'portrait');
        $dompdf->render();
        $filename = $transaction_table . "_" . $transaction_id . "_" . time() . '.pdf';
        $sFilePath = SITEROOT . self::USER_LIT_UPLOADS_INVOICES . $filename;
        $output = $dompdf->output();
        file_put_contents($sFilePath, $output);
        $return['pdf_filename'] = $filename;
        $updateary = array('pdf_name' => $filename, 'updated_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
        $callConfig->updateRecord($transaction_table, $updateary, 'id', $transaction_id);
        return $filename;
    }
