    public function tocreateprocesstaskintotaskdatail($get)
    {
        global $callConfig;
        $query = "SELECT * FROM process_task_settings WHERE company_id = " . $get['company_id'] . "  AND process_type = '" . $get['process_type'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $return['process_query'] = $query;
        $tasks = $callConfig->getAllRows($query);
        $return['process_data'] = $tasks;
        $user_array = array('hr_connect', 'finance_connect', 'admin_connect', 'project_connect', 'location_connect', 'esop_connect', 'legal_connect');
        if (count((array) $tasks) > 0) {

            $module_query = "SELECT module_name,module_description FROM module_setup WHERE module_id = " . $callConfig->module_id;
            $module = $callConfig->getRow($module_query);
            $return['module_query'] = $module_query;
            $return['module_data'] = $module;
            $work_spqusery = "SELECT id FROM project_work_spaces WHERE company_id = '" . $get['company_id'] . "' AND  name = '" . $module->module_name . self::USER_LIT_AND_IS_ACTIVE_0;
            $work_spaces = $callConfig->getRow($work_spqusery);
            $return['work_spaces_query'] = $work_spqusery;
            $return['work_spaces_data'] = $work_spaces;
            if ($work_spaces->id != "") {
                $work_spaces_id = $work_spaces->id;
            } else {
                $insert_array = array('company_id' => $get['company_id'], 'name' => $module->module_name, 'is_active' => 0, 'current_status' => 0, 'created_by' => $get['user_id']);
                $work_res = $callConfig->insertRecord('project_work_spaces', $insert_array);
                $work_spaces_id = $work_res['LASTID'];
            }
            $return['work_spaces_id'] = $work_spaces_id;
            foreach ($tasks as $task) {
                $project_query = "SELECT id FROM projects WHERE company_id = '" . $get['company_id'] . "' AND project_work_space_id = " . $work_spaces_id . " AND  project_name = '" . $task->task_name . self::USER_LIT_AND_IS_ACTIVE_0;
                $pdata = $callConfig->getRow($project_query);
                $return['project_query'] = $project_query;
                $return['project_data'] = $pdata;
                if ($pdata->id != "") {
                    $project_id = $work_spaces->id;
                } else {
                    $insert_array = array('company_id' => $get['company_id'], 'project_work_space_id' => $work_spaces_id, 'assigner_id' => $get['user_id'], 'project_name' => $task->task_name, 'project_type' => 2, 'planned_start' => date('Y-m-d'), 'is_active' => 0, 'current_status' => 0, 'created_by' => $get['user_id']);
                    $project_res = $callConfig->insertRecord('projects', $insert_array);
                    $project_id = $project_res['LASTID'];
                }
                $status = array('0' => 'To DO', '101' => 'Doing', '5' => 'On Hold', '199' => 'Completed');
                $k = 10;
                foreach ($status as $skey => $sta) {
                    $insert_array = array('company_id' => $get['company_id'], 'project_id' => $project_id, 'table_name' => 'project_task_details', 'name' => $sta, 'status' => $skey, 'action_label' => $sta, 'display_priority' => $k, 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id']);
                    $kresult['insert'][] = $insert_array;
                    $kresult['res'][] = $callConfig->insertRecord('project_task_status', $insert_array);
                    $k = $k + 10;
                }

                $return['project_id'] = $project_id;
                $team_query = "SELECT id, user_id FROM project_teams WHERE company_id = '" . $get['company_id'] . "' AND project_id = " . $project_id . self::USER_SQL_AND_IS_ACTIVE_0;
                $listteams = $callConfig->getAllRows($team_query);
                $teams = array();
                if (count($listteams) > 0) {
                    foreach ((array) $listteams as $listteam) {
                        $teams[] = $listteam->user_id;
                    }
                }
                $return['project_old_team'] = $teams;
                $userquery = self::USER_SQL_SELECT_FROM_APPLICATION_USERS_ . $get['company_id'] . self::USER_LIT_AND_ID_4 . $get['transaction_id'] . self::USER_SQL_AND_IS_ACTIVE_0;
                $userdata = $callConfig->getRow($userquery);
                $new_teams = array();
                foreach ((array) $user_array as $user_filed) {
                    $userlist_members[$user_filed] = $userdata->$user_filed;
                    if ($userdata->$user_filed != "" && !in_array($userdata->$user_filed, (array) $teams)) {
                        $new_teams[] = $userdata->$user_filed;
                    }
                }
                $return['project_new_team'] = $new_teams;
                if (count((array) $new_teams) > 0) {
                    foreach ((array) $new_teams as $new_team) {
                        $insert_array = array('company_id' => $get['company_id'], 'project_id' => $project_id, 'role_id' => 2, 'user_id' => $new_team, 'is_active' => 0, 'current_status' => 0, 'created_by' => $get['user_id']);
                        $callConfig->insertRecord('project_teams', $insert_array);
                    }
                }
                $taskdata = $get;
                $taskdata['project_id'] = $project_id;
                $taskdata['task_name'] = $task->task_name . " - " . $userdata->display_name;
                $taskdata['user_name'] = $userdata->display_name;
                $taskdata['assigner'] = $get['user_id'];
                $taskdata['assigen_id'] = $get['user_id'];
                $taskdata['checklist'] = $task->check_list;
                $taskdata['checkuser'] = $userlist_members;
                $planned_start = date('Y-m-d');
