            }
        }
        $callConfig->getRow("SELECT display_name FROM application_users WHERE id=" . $get['user_id']);
        $notuser1[] = $get['user_id'];
        $notuser1[] = $get['assigen_id'];
        if (!isset($get['activity_type'])) {
            $project = $callConfig->getRow("SELECT project_name,assigner_id FROM projects WHERE id=" . $get['project_id']);
            $callConfig->getRow("SELECT display_name FROM application_users WHERE id=" . $get['assigen_id']);
            $insert_arr = array('company_id' => $get['company_id'], 'project_id' => $get['project_id'], 'project_task_id' => $task_id, 'project_role_id' => 2, 'user_id' => $get['transaction_id'], 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id']);
            $callConfig->insertRecord('project_task_teams', $insert_arr);
            $insert_arr['project_role_id'] = 1;
            $insert_arr['user_id'] = $project->assigner_id;
            $callConfig->insertRecord('project_task_teams', $insert_arr);
            $query = "SELECT user_id FROM project_teams WHERE company_id =" . $get['company_id'] . " AND role_id !=2 AND project_id = " . $get['project_id'] . self::USER_SQL_AND_IS_ACTIVE_0_6;
            $lists = $callConfig->getAllRows($query);
            foreach ($lists as $list) {
                $notuser2[] = $list->user_id;
            }
        }


        return $return;
    }



    public function vendorRegistartionTaskAssigne($get)
    {
        global $callConfig;
        echo "<pre>";
        $transaction_date = date('Y-m-d');

        $ausql = "SELECT * FROM `application_users` WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_ID . $get['transaction_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $aures = $callConfig->getRow($ausql);
        $return['aures'] = $aures;

        $tasquery = self::USER_SQL_SELECT_TASK_ID_ASSIGNED_TO_FRO . $get['company_id'] . "' AND transaction_table = 'vendor_registers' AND transaction_id = '" . $get['transaction_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
        $tasres = $callConfig->getAllRows($tasquery);
        $alreadytaskid = array();
        foreach ($tasres as $roleres) {
            $alreadytaskid[$roleres->task_id][$roleres->assigned_to] = "Y";
        }
        $return['tasquery'] = $tasquery;
        $return['alreadytaskid'] = $alreadytaskid;
        $whr1 = self::USER_LIT_COMPANY_ID_1 . $get['company_id'] . "' AND is_active = 0 AND process_type='VR'";
        $task_query = $callConfig->selectQuery('process_task_settings', '*', $whr1, '', '', '');
        $task_data = $callConfig->getAllRows($task_query);
        $return['task_query'] = $task_query;
        $return['task_data'] = $task_data;
        foreach ($task_data as $tasks) {
            if ($tasks->action_no == '1') {
                if ($tasks->action_frequency == 'DY') {
                    /* unused */
                } elseif ($tasks->action_frequency == 'WK') {
                    $day = 7;
                } elseif ($tasks->action_frequency == 'MON') {
                    $day = 30;
                }
                if ($tasks->before_or_after == 'BF') {
                    $day = "-" . $day;
                } else {
                    $day = "+" . $day;
                }
                $days_ago = date('Y-m-d', strtotime($day . self::USER_LIT_DAYS, strtotime($transaction_date)));
            } else {
                $days_ago = $transaction_date;
            }
            if ($tasks->assigned_to == "HB") {
                $assigned_to = $aures->hr_connect;
            } elseif ($tasks->assigned_to == "AB") {
                $assigned_to = $aures->admin_connect;
            } elseif ($tasks->assigned_to == "FB") {
                $assigned_to = $aures->finance_connect;
            } elseif ($tasks->assigned_to == "PB") {
                $assigned_to = $aures->project_connect;
            } elseif ($tasks->assigned_to == "LB") {
                $assigned_to = $aures->location_connect;
            } elseif ($tasks->assigned_to == "ESOP") {
                $assigned_to = $aures->esop_connect;
            } elseif ($tasks->assigned_to == "LEGAL_BUDDY") {
                $assigned_to = $aures->legal_connect;
            } else {
                $assigned_to = $aures->id;
            }
            if (!isset($alreadytaskid[$tasks->id][$assigned_to])) {
                if ($tasks->approval_type == "HB") {
                    $approval_user_id = $aures->hr_connect;
                } elseif ($tasks->approval_type == "AB") {
                    $approval_user_id = $aures->admin_connect;
                } elseif ($tasks->approval_type == "FB") {
                    $approval_user_id = $aures->finance_connect;
                } elseif ($tasks->approval_type == "PB") {
                    $approval_user_id = $aures->project_connect;
                } elseif ($tasks->approval_type == "LB") {
                    $approval_user_id = $aures->location_connect;
                } elseif ($tasks->approval_type == "ESOP") {
                    $approval_user_id = $aures->esop_connect;
                } elseif ($tasks->approval_type == "LEGAL_BUDDY") {
                    $approval_user_id = $aures->legal_connect;
                } else {
                    $approval_user_id = $aures->id;
                }

                $task_array = array('company_id' => $get['company_id'], 'transaction_table' => 'vendor_registers', 'transaction_id' => $aures->id, 'task_id' => $tasks->id, 'assigned_to' => $assigned_to, 'approval_user_id' => $approval_user_id, 'action_date' => $days_ago, 'revised_action_date' => $days_ago, 'actual_action_date' => $days_ago, 'check_list' => $tasks->check_list, 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id']);
                $res = $callConfig->insertRecord('transaction_activity_schedule', $task_array);
                $return['transaction_activity_schedule'][] = $task_array;
                $return['transaction_activity_schedule_insert'][] = $res;
            }
        }



    }
    public function getVendorAdminDashboard($get)
    {
        global $callConfig;
        if ($get['vendorcreate'] == 'Y') {
            $return['registervendors'] = $this->registervendors($get['vendor_id'], $get);
        } else {
            $getvrid = "(SELECT vr.id FROM vendor_registers vr  WHERE vr.company_id =  '" . $get['company_id'] . "' AND ven.id = vr.vendor_id  AND vr.is_active = 0 limit 1) as vr_id";
            $vendorsql = "SELECT id,user_id,display_name,created_date,image,email,created_by,company, " . $getvrid . " FROM vendors ven WHERE company_id =  '" . $get['company_id'] . self::USER_LIT_AND_HR_CONNECT . $get['user_id'] . self::USER_LIT_OR_FINANCE_CONNECT . $get['user_id'] . self::USER_LIT_OR_PURCHASE_CONNECT . $get['user_id'] . self::USER_LIT_OR_ADMIN_CONNECT . $get['user_id'] . self::USER_LIT_OR_PROJECT_CONNECT . $get['user_id'] . self::USER_LIT_OR_LOCATION_CONNECT . $get['user_id'] . self::USER_LIT_OR_LEGAL_CONNECT . $get['user_id'] . self::USER_LIT_OR_CREATED_BY . $get['user_id'] . self::USER_LIT_OR . $get['admin_type'] . "'='1' ) AND is_active = 0";
            $vendorres = $callConfig->getAllRows($vendorsql);
            $return['vendors'] = $vendorres;
            $return['total_vendors'] = count((array) $vendorres);

            $vendorregisterssql = "SELECT id,user_id,display_name,created_date,image,email,created_by,company, verification_profile_users FROM `vendor_registers` WHERE company_id =  '" . $get['company_id'] . self::USER_LIT_AND_HR_CONNECT . $get['user_id'] . self::USER_LIT_OR_FINANCE_CONNECT . $get['user_id'] . self::USER_LIT_OR_PURCHASE_CONNECT . $get['user_id'] . self::USER_LIT_OR_ADMIN_CONNECT . $get['user_id'] . self::USER_LIT_OR_PROJECT_CONNECT . $get['user_id'] . self::USER_LIT_OR_LOCATION_CONNECT . $get['user_id'] . self::USER_LIT_OR_LEGAL_CONNECT . $get['user_id'] . self::USER_LIT_OR_CREATED_BY . $get['user_id'] . self::USER_LIT_OR . $get['admin_type'] . "'='1' ) AND vendor_id IS NULL AND is_active = 0";
            $vendorregistersres = $callConfig->getAllRows($vendorregisterssql);
            $return['vendor_registers'] = $vendorregistersres;
            $vendoruserid = $registervid = array();
            foreach ($vendorregistersres as $venre) {
                $vendoruserid[$venre->user_id] = $venre->user_id;
                $registervid[$venre->id] = $venre->id;
            }
            $return['onboarduserid'] = $registervid;
            $thismonthsql = "SELECT count(id) as cnt FROM vendor_registers WHERE company_id = '" . $get['company_id'] . "' AND created_date >='" . $get['startdate'] . "' AND created_date <= '" . $get['enddate'] . self::USER_LIT_AND_HR_CONNECT . $get['user_id'] . self::USER_LIT_OR_FINANCE_CONNECT . $get['user_id'] . self::USER_LIT_OR_PURCHASE_CONNECT . $get['user_id'] . self::USER_LIT_OR_ADMIN_CONNECT . $get['user_id'] . self::USER_LIT_OR_PROJECT_CONNECT . $get['user_id'] . self::USER_LIT_OR_LOCATION_CONNECT . $get['user_id'] . self::USER_LIT_OR_LEGAL_CONNECT . $get['user_id'] . self::USER_LIT_OR_CREATED_BY . $get['user_id'] . self::USER_LIT_OR . $get['admin_type'] . "'='1') AND is_active = 0";
            $thismonthsres = $callConfig->getRow($thismonthsql);
            $return['this_month_invite_cnt'] = $thismonthsres->cnt;

            $totalvrsql = "SELECT count(id) as cnt FROM vendor_registers WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_HR_CONNECT . $get['user_id'] . self::USER_LIT_OR_FINANCE_CONNECT . $get['user_id'] . self::USER_LIT_OR_PURCHASE_CONNECT . $get['user_id'] . self::USER_LIT_OR_ADMIN_CONNECT . $get['user_id'] . self::USER_LIT_OR_PROJECT_CONNECT . $get['user_id'] . self::USER_LIT_OR_LOCATION_CONNECT . $get['user_id'] . self::USER_LIT_OR_LEGAL_CONNECT . $get['user_id'] . self::USER_LIT_OR_CREATED_BY . $get['user_id'] . self::USER_LIT_OR . $get['admin_type'] . "'='1') AND is_active = 0";
            $totalvrres = $callConfig->getRow($totalvrsql);
            $return['total_registration_vendors'] = $totalvrres->cnt;

            if ($get['admin_type'] != '1') {
                $condition_task = self::USER_SQL_AND_TAS_ASSIGNED_TO . $get['user_id'] . self::USER_LIT_OR_TAS_APPROVAL_USER_ID . $get['user_id'] . "')";
            }
            $transaction_activity_schedulesql = "SELECT tas.assigned_to, tas.transaction_id, count(*) as total_task_cnt, sum(if(tas.current_status=" . ST_APPROVED . ",1,0)) as approve_cnt, sum(if(tas.current_status=" . ST_APPROVED1 . ",1,0)) as review_cnt, sum(if(tas.current_status=" . ST_INPROGRESS . ",1,0)) as inprogress_cnt, sum(if(tas.current_status=" . ST_ACTIVE . ",1,0)) as yet_to_start_cnt, sum(if(tas.action_date < tas.completion_date,1,0)) as delayed_cnt FROM transaction_activity_schedule tas WHERE  tas.company_id = '" . $get['company_id'] . "' AND tas.transaction_table = 'vendor_registers' AND tas.transaction_id IN(" . implode(',', $registervid) . ")  AND tas.is_active = 0  " . $condition_task . " GROUP BY tas.assigned_to,tas.transaction_id";
            $transaction_activity_scheduleres = $callConfig->getAllRows($transaction_activity_schedulesql);
            $return['transaction_activity_scheduleres_sql'] = $transaction_activity_schedulesql;
            $return['transaction_activity_scheduleres'] = $transaction_activity_scheduleres;

            $tasks_categoriessql = self::USER_SQL_SELECT_ID_CATEGORY_NAME_FROM_T . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0;
            $tasks_categoriesres = $callConfig->getAllRows($tasks_categoriessql);
            $return['tasks_categories'] = $tasks_categoriesres;


            $action_transaction_activity_schedulesql = "SELECT tas.id, tas.transaction_table, tas.transaction_id, tas.task_id, tas.assigned_to, tas.approval_user_id, tas.action_date, tas.revised_action_date, tas.actual_action_date, tas.completion_date, tas.approval_date, tas.action_flag, tas.comments, tas.note, tas.check_list, tas.finish_date, tas.current_status, tas.task_name, tas.process_id, tal.request_date, tal.response_date, tal.comments, tal.response_type FROM transaction_activity_schedule tas, transaction_approval_logs tal WHERE tas.company_id = '" . $get['company_id'] . "' AND tas.company_id = tal.company_id AND tas.transaction_table = 'vendor_registers' AND tas.transaction_id IN(" . implode(',', $registervid) . ") AND tas.id = tal.transaction_id AND tal.transaction_table ='transaction_activity_schedule' AND tal.user_id = '" . $get['user_id'] . "' AND tal.response_type ='0' AND tal.call_back ='1' AND tas.is_active = 0";
            $action_transaction_activity_scheduleres = $callConfig->getAllRows($action_transaction_activity_schedulesql);
            $return['action_transaction_activity_schedule'] = $action_transaction_activity_scheduleres;


            $vendor_registration_requestssql = "SELECT id, company_name, display_name, user_email, share_pdf, request_datetime FROM vendor_registration_requests WHERE company_id = '" . $get['company_id'] . "' AND (`originator` = '" . $get['user_id'] . "' OR ('" . $get['admin_type'] . "'='1' AND  `share_pdf` = 'Y')) AND id NOT In(SELECT vendor_registration_request_id FROM `vendor_registers` WHERE company_id = '" . $get['company_id'] . "' AND vendor_registration_request_id IS NOT NULL AND is_active = 0) AND is_active = 0";
            $vendor_registration_requestsres = $callConfig->getAllRows($vendor_registration_requestssql);
            $return['vendor_registration_requests'] = $vendor_registration_requestsres;
        }
        return $return;
    }
    public function getApplicationUsers($get)
    {
        global $callConfig;
        $rid = $get['rid'];
        $ausql = "SELECT au.*, (SELECT loc.location_name FROM locations loc WHERE loc.company_id = au.company_id AND loc.id = au.location_id AND loc.is_active = au.is_active  limit 1) as location_name,(SELECT cc.cost_center_name FROM cost_centers cc WHERE cc.company_id = au.company_id AND cc.id = au.cost_center AND cc.is_active = au.is_active limit 1) as cost_center_name, (SELECT ware.warehouse_name FROM warehouses ware WHERE ware.company_id = au.company_id AND ware.id = au.default_warehouse_id AND ware.is_active = au.is_active limit 1) as warehouse_name, (SELECT stat.state_name FROM states stat WHERE stat.company_id = au.company_id AND stat.id = au.default_state_id AND stat.is_active = au.is_active limit 1) as state_name,(SELECT count.country_name FROM countries count WHERE count.company_id = au.company_id AND count.id = au.country_id AND count.is_active = au.is_active limit 1) as country_name, (SELECT curr.currency_name FROM currencies curr WHERE curr.company_id = au.company_id AND curr.id = au.default_currency_id AND curr.is_active = au.is_active limit 1) as currency_name FROM application_users au WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_ID . $rid . self::USER_LIT_AND_IS_ACTIVE_0;
