        $user_locationsres = $callConfig->getAllRows($user_locationssql);
        $return['user_locations'] = $user_locationsres;

        $user_warehousesql = "SELECT ucc.id, cc.warehouse_name FROM user_warehouse ucc, warehouses cc WHERE ucc.company_id = '" . $get['company_id'] . self::USER_LIT_AND_UCC_USER_ID . $rid . "' AND ucc.company_id = cc.company_id AND ucc.ware_house_id = cc.id AND ucc.is_active = cc.is_active AND ucc.is_active = 0";
        $user_warehouseres = $callConfig->getAllRows($user_warehousesql);
