        $user_assetssql = "SELECT ucc.id, ucc.start_date, ucc.end_date, cc.asset_description FROM user_assets ucc, assets cc WHERE ucc.company_id = '" . $get['company_id'] . self::USER_LIT_AND_UCC_USER_ID . $rid . "' AND ucc.company_id = cc.company_id AND ucc.asset_id = cc.id AND ucc.is_active = cc.is_active AND ucc.is_active = 0";
