    public function getPartyDetails($get)
    {
        global $callConfig;
        $return['get'] = $get;
        $sql = "SELECT *,(SELECT pt.payment_term_name FROM payment_terms pt where pt.company_id = ven.company_id AND pt.id=ven.payment_terms AND pt.is_active = ven.is_active) as payment_term_name FROM " . $get['part_table'] . " ven WHERE ven.company_id = '" . $get['company_id'] . "' AND ven.id = '" . $get['party_id'] . "' AND ven.is_active = 0";
        $res = $callConfig->getRow($sql);
        $return['party_detail'] = $res;
        if ($get['part_table'] == "vendors") {
            $invsql = "SELECT (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Indentings') FROM requisitions WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . "' AND is_active = 0) as req_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Quotations') FROM quotations WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . "' AND is_active = 0) as quo_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Purchase Orders') FROM purchase_orders WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . "' AND is_active = 0) as po_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||',IFNULL(SUM(pending_amount),'0'),'||','Purchase Invoices') FROM purchase_invoices WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CANCEL_INVOICE_N_AND_CURRE . ST_APPROVED . "' AND is_active = 0) as pi_cnt";
            $invres = $callConfig->getRow($invsql);
            $return['invoice_detail_sql'] = $invsql;
            $return['invoice_detail'] = $invres;

            $transsql = "SELECT id, transaction_number, transaction_date, originator, amount, tax_amount, discount_amount, total_amount, shipping_amount, shipping_tax_amount, cancel_invoice, current_status FROM purchase_invoices WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . self::USER_LIT_AND_IS_ACTIVE_0;
            $transres = $callConfig->getAllRows($transsql);
            $return['all_transactions'] = $transres;

            $transsql = "SELECT id, transaction_number, transaction_date, originator, amount, tax_amount, discount_amount, total_amount, shipping_amount, shipping_tax_amount, cancel_invoice, pending_amount, due_date,  current_status FROM purchase_invoices WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . "' AND cancel_invoice = 'N' AND is_active = 0 AND pending_amount > 0";
            $transres = $callConfig->getAllRows($transsql);
            $return['pending_amt_transactions'] = $transres;

            $transsql = "SELECT pt.item_id, pt.item_name, SUM(pt.item_quantity) as item_quantity, SUM(pt.item_price) as item_price, SUM(pt.item_amount) as item_amount , SUM(pt.tax_amount) as tax_amount, SUM(pt.total_amount) as total_amount FROM purchase_invoices pi, pi_items pt WHERE pi.company_id = '" . $get['company_id'] . "'  AND pi.company_id = pt.company_id AND pi.id = pt.transaction_id AND pi.party_id = '" . $get['party_id'] . "' AND pi.current_status ='" . ST_APPROVED . "' AND pi.is_active = pt.is_active AND pi.is_active = 0 GROUP BY pt.item_id, pt.item_name";
            $transres = $callConfig->getAllRows($transsql);
            $return['transaction_items'] = $transres;


            $query = "SELECT id, payment_terms, total_amount, party_id, party_name, due_date, payment_term_history FROM purchase_invoices WHERE company_id = " . $get['company_id'] . " AND (pending_amount IS NULL OR  pending_amount !=0) AND party_id = '" . $get['party_id'] . self::USER_LIT_AND_CANCEL_INVOICE_N_AND_CURRE . ST_APPROVED . self::USER_LIT_AND_IS_ACTIVE_0;
            $return['bills_sql'] = $query;
            $return['bills'] = $callConfig->getAllRows($query);

        } else {

            $invsql = "SELECT (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Indentings') FROM requisitions WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . "' AND is_active = 5) as req_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Sales Orders') FROM sales_orders WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . "' AND is_active = 0) as quo_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Sales Returns') FROM sales_returns WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . "' AND is_active = 0) as po_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||',IFNULL(SUM(pending_amount),'0'),'||','Sales Invoices') FROM sales_invoices WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CANCEL_INVOICE_N_AND_CURRE . ST_APPROVED . "' AND is_active = 0) as pi_cnt";
            $invres = $callConfig->getRow($invsql);
            $return['invoice_detail_sql'] = $invsql;
            $return['invoice_detail'] = $invres;

            $transsql = "SELECT id, transaction_number, transaction_date, originator, amount, tax_amount, discount_amount, total_amount, shipping_amount, shipping_tax_amount, cancel_invoice, current_status FROM sales_invoices WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . self::USER_LIT_AND_IS_ACTIVE_0;
            $transres = $callConfig->getAllRows($transsql);
            $return['all_transactions'] = $transres;

            $transsql = "SELECT id, transaction_number, transaction_date, originator, amount, tax_amount, discount_amount, total_amount, shipping_amount, shipping_tax_amount, cancel_invoice, pending_amount, due_date,  current_status FROM sales_invoices WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $get['party_id'] . self::USER_LIT_AND_CURRENT_STATUS . ST_APPROVED . "' AND cancel_invoice = 'N' AND is_active = 0 AND pending_amount > 0";
            $transres = $callConfig->getAllRows($transsql);
            $return['pending_amt_transactions'] = $transres;

            $transsql = "SELECT pt.item_id, pt.item_name, SUM(pt.item_quantity) as item_quantity, SUM(pt.item_price) as item_price, SUM(pt.item_amount) as item_amount , SUM(pt.tax_amount) as tax_amount, SUM(pt.total_amount) as total_amount FROM sales_invoices pi, si_items pt WHERE pi.company_id = '" . $get['company_id'] . "'  AND pi.company_id = pt.company_id AND pi.id = pt.transaction_id AND pi.party_id = '" . $get['party_id'] . "' AND pi.current_status ='" . ST_APPROVED . "' AND pi.is_active = pt.is_active AND pi.is_active = 0 GROUP BY pt.item_id, pt.item_name";
            $transres = $callConfig->getAllRows($transsql);
            $return['transaction_items'] = $transres;


            $query = "SELECT id, payment_terms, total_amount, party_id, party_name, due_date, payment_term_history FROM sales_invoices WHERE company_id = " . $get['company_id'] . " AND (pending_amount IS NULL OR  pending_amount !=0) AND party_id = '" . $get['party_id'] . self::USER_LIT_AND_CANCEL_INVOICE_N_AND_CURRE . ST_APPROVED . self::USER_LIT_AND_IS_ACTIVE_0;
            $return['bills_sql'] = $query;
            $return['bills'] = $callConfig->getAllRows($query);

        }

        return $return;

    }
