trait UserDocumentsAndPrintingTrait
{
    public function updateApplicationFavourites($post)
    {
        global $callConfig;
        $return['post'] = $post;
        if ($post['type'] == "F") {
            $insertary = array('company_id' => $post['company_id'], 'application_table_name' => $post['application_table_name'], 'transaction_id' => $post['transaction_id'], 'user_id' => $post['user_id'], 'created_by' => $post['user_id'], 'is_active' => 0, 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
            $tapres = $callConfig->insertRecord('application_favourites', $insertary);
            $return['result'] = $tapres;
        } else {
