    public function updateTransactionTDS($get)
    {
        $talres = array();
        global $callConfig;
        $transaction_table = $get['transaction_table'];
        $transaction_no = $get['transaction_no'];
        $company_id = $get['company_id'];
        $vendortable = array('purchase_orders', 'supplier_bills', 'purchase_invoices');
        $customertable = array('sales_invoices');
        $total_tds = 0;

        $sql = self::USER_SQL_SELECT_FROM . $transaction_table . self::USER_SQL_WHERE_COMPANY_ID . $company_id . self::USER_LIT_AND_ID_3 . $transaction_no . self::USER_LIT_AND_IS_ACTIVE_0;
        $partyinvoice = $callConfig->getRow($sql);
        $tds_details = array();
        // TDS PArt Updatetions
        if (in_array($transaction_table, (array) $vendortable)) {
            $party_transaction_table = "vendors";
            $partyinvoiceitem_total = 0;
            if ($partyinvoice->party_id != "") {
                $pasrtysql = self::USER_SQL_SELECT_FROM_VENDORS_WHERE_COMP . $company_id . self::USER_LIT_AND_ID_3 . $partyinvoice->party_id . self::USER_LIT_AND_IS_ACTIVE_0;
                $party_detail = $callConfig->getRow($pasrtysql);
            }
            if ($partyinvoice->transaction_date != "") {
                $taxdetailsql = "SELECT * FROM tax_deducted_sources WHERE company_id = '" . $company_id . "' AND financial_year_start <= '" . $partyinvoice->transaction_date . "' AND financial_year_end >= '" . $partyinvoice->transaction_date . self::USER_LIT_AND_IS_ACTIVE_0;
                $taxdetailres = $callConfig->getAllRows($taxdetailsql);
                foreach ($taxdetailres as $tx) {
                    $tds_details[$tx->id] = $tx;
                }
            }
            $mappingtabsql = self::USER_SQL_SELECT_ID_DISPLAY_TABLE_ITEM_T . $company_id . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $transaction_table . self::USER_LIT_AND_ITEM_TABLE_AND_IS_ACTIVE_0;
            $mappingtabres = $callConfig->getRow($mappingtabsql);
            if ($mappingtabres->item_table != "" && $partyinvoice->party_id != "") {
                $sbsql = "SELECT SUM(item_amount) as total_payments FROM " . $transaction_table . " sb, " . $mappingtabres->item_table . " sbi WHERE sb.company_id ='" . $company_id . "' AND sb.company_id = sbi.company_id  AND sb.id = sbi.transaction_id AND sb.party_id = '" . $partyinvoice->party_id . "' AND sb.is_active = sbi.is_active AND sb.current_status = '" . ST_APPROVED . "' AND sb.is_active = 0 ";
                $sbres = $callConfig->getRow($sbsql);
                if ($sbres->total_payments != "" && isset($sbres->total_payments)) {
                    $total_payments = $sbres->total_payments + $partyinvoiceitem_total;
                }
            }
            if ($mappingtabres->item_table != "" && $partyinvoice->id != "") {
                $partyinvoiceitemsql = "SELECT iv.*, it.item_name, it.category_id, ic.category_description, ic.tax_deducted_source_id, ic.tax_collected_source_id FROM " . $mappingtabres->item_table . " iv, items it ,item_categories ic WHERE iv.company_id = '" . $company_id . self::USER_LIT_AND_IV_COMPANY_ID_IT_COMPANY_I . $partyinvoice->id . self::USER_LIT_AND_IV_IS_ACTIVE_IT_IS_ACTIVE_;
                $partyinvoiceitemres = $callConfig->getAllRows($partyinvoiceitemsql);

                $partinvoiceitemid = array();
                foreach ($partyinvoiceitemres as $itemres) {
                    $partinvoiceitemid[$itemres->item_id] = $itemres->item_id;
                    $partyinvoiceitem_total += $itemres->item_amount;
                }
                $total_tds = 0;
                foreach ($partyinvoiceitemres as $itemres) {
                    if (isset($tds_details[$itemres->tax_deducted_source_id])) {
                        $applaytds = $tds_details[$itemres->tax_deducted_source_id];
                        if ($party_detail->tds_type == "I") {
                            $applay_percentage = $applaytds->individual_percentage;
                        } elseif ($party_detail->tds_type == "H") {
                            $applay_percentage = $applaytds->huf_percentage;
                        } elseif ($party_detail->tds_type == "O") {
                            $applay_percentage = $applaytds->other_percentage;
                        }
                        $vendoritem_amount = $total_payments;
                        $tds_threshold = $applaytds->threshold;
                        if ($tds_threshold <= $vendoritem_amount && $tds_threshold != "" && $vendoritem_amount != "") {
                            $tdsitempayment = ($itemres->item_amount * $applay_percentage) / 100;
                            $total_tds += $tdsitempayment;
                            $updatedata['tds_amount'] = $tdsitempayment;
                            $updatedata['tax_deducted_source_id'] = $applaytds->id;
                            $updatedata['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
                            $updatedata['updated_by'] = $get['user_id'];
                            $callConfig->updateRecord($mappingtabres->item_table, $updatedata, 'id', $itemres->id);
                            $insertapplicationtdstcs = array('company_id' => $company_id, 'transaction_table' => $transaction_table, 'transaction_id' => $transaction_no, 'transaction_number' => $partyinvoice->transaction_number, 'party_transaction_table' => $party_transaction_table, 'party_id' => $partyinvoice->party_id, 'transaction_item_table' => $mappingtabres->item_table, 'transaction_item_table_id' => $itemres->id, 'item_id' => $itemres->item_id, 'item_amount' => $itemres->item_amount, 'tax_amount' => $itemres->tax_amount, 'total_amount' => $itemres->total_amount, 'tds_tcs_id' => $applaytds->id, 'tds_tcs_amount' => $tdsitempayment, 'tds_tcs_details' => urlencode(json_encode((array) $applaytds)), 'transaction_table_details' => urlencode(json_encode((array) $partyinvoice)), 'party_transaction_table_details' => urlencode(json_encode((array) $party_detail)), 'transaction_item_table_details' => urlencode(json_encode((array) $itemres)), 'is_active' => 0, 'current_status' => 0, 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'created_by' => $get['user_id']);
                            $callConfig->insertRecord('application_tds_tcs_transactions', $insertapplicationtdstcs);
                        }
                    }
                }
            }
            $mainupdate['total_tds_amount'] = $total_tds;
            $mainupdate['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
            $mainupdate['updated_by'] = $get['user_id'];
            $callConfig->updateRecord($transaction_table, $mainupdate, 'id', $transaction_no);


            // TDS PArt Updatetions

        } elseif (in_array($transaction_table, $customertable)) {

            $party_transaction_table = "customers";
            $pasrtysql = "SELECT * FROM customers WHERE company_id = '" . $company_id . self::USER_LIT_AND_ID_3 . $partyinvoice->party_id . self::USER_LIT_AND_IS_ACTIVE_0;
            $party_detail = $callConfig->getRow($pasrtysql);

            $partyinvoiceitemsql = "SELECT iv.*, it.item_name, it.category_id, ic.category_description, ic.tax_deducted_source_id, ic.tax_collected_source_id FROM si_items iv, items it ,item_categories ic WHERE iv.company_id = '" . $company_id . self::USER_LIT_AND_IV_COMPANY_ID_IT_COMPANY_I . $partyinvoice->id . self::USER_LIT_AND_IV_IS_ACTIVE_IT_IS_ACTIVE_;
            $partyinvoiceitemres = $callConfig->getAllRows($partyinvoiceitemsql);
            foreach ($partyinvoiceitemres as $itemres) {
                if ($itemres->tax_collected_source_id != "" && $itemres->tax_collected_source_id != "0") {
                    $tdsitempayment = $itemres->tds_amount;
                    $total_tds += $itemres->tds_amount;
                    $insertapplicationtdstcs = array('company_id' => $company_id, 'transaction_table' => $transaction_table, 'transaction_id' => $transaction_no, 'transaction_number' => $partyinvoice->transaction_number, 'party_transaction_table' => $party_transaction_table, 'party_id' => $partyinvoice->party_id, 'transaction_item_table' => 'si_items', 'transaction_item_table_id' => $itemres->id, 'item_id' => $itemres->item_id, 'item_amount' => $itemres->item_amount, 'tax_amount' => $itemres->tax_amount, 'total_amount' => $itemres->total_amount, 'tds_tcs_id' => $itemres->tax_collected_source_id, 'tds_tcs_amount' => $tdsitempayment, 'tds_tcs_details' => urlencode(json_encode((array) $itemres)), 'transaction_table_details' => urlencode(json_encode((array) $partyinvoice)), 'party_transaction_table_details' => urlencode(json_encode((array) $party_detail)), 'transaction_item_table_details' => urlencode(json_encode((array) $itemres)), 'is_active' => 0, 'current_status' => 0, 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'created_by' => $get['user_id']);
                    $callConfig->insertRecord('application_tds_tcs_transactions', $insertapplicationtdstcs);
                }

            }
        }
        $payment_term_history = json_decode($partyinvoice->payment_term_history, 1);
        if (count((array) $payment_term_history) != "0") {
            $pth_cnt = count((array) $payment_term_history);
            $mk = 1;
            foreach ($payment_term_history as $key => $pterh) {
                if ($pth_cnt == $key && in_array($transaction_table, $customertable)) {
                    $pterh['amount'] = $pterh['amount'] + $total_tds;
                }
                $insertdata = array('company_id' => $company_id, 'transaction_table' => $transaction_table, 'transaction_id' => $transaction_no, 'transaction_number' => $partyinvoice->transaction_number, 'party_id' => $partyinvoice->party_id, 'due_date' => $this->dateconvertdbformat($pterh['due_date']), 'due_amount' => $pterh['amount'], 'advance_offer_date' => $this->dateconvertdbformat($pterh['extra_date']), 'advance_offer_amount' => $pterh['extra_amt'], 'pending_amount' => $pterh['amount'], 'is_active' => '0', 'current_status' => '0', 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'created_by' => $get['user_id'], 'amount' => $pterh['without_tax_amount'], 'tax_amount' => $pterh['tax_amount'], 'percentage' => $pterh['percentage'], 'without_tax_pending_amount' => $pterh['without_tax_amount'], 'tax_pending_amount' => $pterh['tax_amount']);
                $callConfig->insertRecord('payment_term_transactions', $insertdata);
                $mk++;
            }
        }



        return $talres;
    }
    public function gerReferanceTableDetails($get)
    {
        global $callConfig;
        $retrun = array();
        $transaction_table = $get['transaction_table'];
        $ref_id = $get['ref_id'];
        if ($transaction_table == 'goods_receipt_notes') {
            $sbcondition = "";
            if ($get['rid'] != "") {
                $sbcondition = self::USER_SQL_AND_ID_4 . $get['rid'] . "'";
            }
            $sql = "SELECT * FROM goods_receipt_notes grn WHERE grn.company_id = '" . $get['company_id'] . self::USER_LIT_AND_REF_ID . $ref_id . "' AND grn.id NOT IN(SELECT ref_no FROM purchase_invoices sb WHERE sb.company_id = grn.company_id AND sb.ref_no = grn.id AND sb.is_active = grn.is_active " . $sbcondition . " AND sb.cancel_invoice = 'N' AND sb.current_status != '" . ST_REJECTED . "') AND grn.current_status = '" . ST_APPROVED . "' AND grn.is_active = 0";
            $grnres = $callConfig->getAllRows($sql);
            $retrun['sql'] = $sql;
