    public function toinsertmonthlypayrnsummarybaseemployeeutype($post, $emps, $version, $pay_area_id)
    {
        global $callConfig;


        $datess = $this->payrollfromtodates($post);
        $date1 = $datess['date1'];
        $date2 = $datess['date2'];
        $cfquery = $callConfig->selectQuery('config', 'default_payroll_day,show_leave_member,shift_mode,professional_tax_type,default_professional_tax_location_id', 'id=1', '', '', '');
        $cfdata = $callConfig->getRow($cfquery);

        $whr = self::USER_LIT_COMPANY_ID_2 . $post['company_id'] . self::USER_LIT_AND_ID_4 . $pay_area_id . " AND  is_active=0";
        $payareaquery = $callConfig->selectQuery('pay_areas', '*', $whr, '', '', '');
        $callConfig->getRow($payareaquery);

        $whr = self::USER_LIT_COMPANY_ID_2 . $post['company_id'] . "'  AND  is_active=0";
        $ccquery = $callConfig->selectQuery('contract_employee_pay_config', '*', $whr, '', '', '');
        $cc_data = $callConfig->getRow($ccquery);
        $cc_data = (array) $cc_data;

        foreach ($emps as $emp) {
            $allemps[] = $emp->id;
        }
        $conctor_query = "SELECT * FROM contract_employee_pay WHERE company_id =" . $post['company_id'] . " AND employee_id IN (" . implode(",", $allemps) . self::USER_LIT_AND_IS_ACTIVE_0_16;
        $conctor_data = $callConfig->getAllRows($conctor_query);
        foreach ($conctor_data as $con_data) {
            $cdata[$con_data->employee_id] = (array) $con_data;
        }
        $newtotalworkingdays = $this->togetnewwithoutworkindays($date1, $date2);
        foreach ($emps as $emp) {
            if (isset($cdata[$emp->id])) {

                $mndata = $cdata[$emp->id];
                $emp_termination_query = self::USER_SQL_SELECT_FROM_EMPLOYEE_TERMINATI . $date1 . self::USER_LIT_AND_RELEIVE_DATE . $date2 . self::USER_LIT_AND_CURRENT_STATUS_1 . ST_APPROVED . self::USER_SQL_AND_EMP_ID . $emp->id;
                $emp_termination_data = $callConfig->getRow($emp_termination_query);
                $leavec = array('shift_mode' => $cfdata->shift_mode, 'emp_id' => $emp->id, 'date1' => $date1, 'date2' => $date2);
                if ($emp_termination_data->id != "" && $emp->joining_date > $date1) {
                    $leaves = $this->togetemployeeleavecalucateutype($emp->id, $emp->joining_date, $emp_termination_data->releive_date, $leavec);
                } elseif ($emp->joining_date > $date1) {
                    $leaves = $this->togetemployeeleavecalucateutype($emp->id, $emp->joining_date, $date2, $leavec);
                } elseif ($emp_termination_data->id != "") {
                    $leaves = $this->togetemployeeleavecalucateutype($emp->id, $date1, $emp_termination_data->releive_date, $leavec);
                } else {
                    if ($cfdata->show_leave_member == 1) {
                        $leaves = $this->togetemployeeleavecalucateutype($emp->id, $date1, $date2, $leavec);
                        $total_no_of_leaves = $leaves['total_no_of_leaves'];
                    } else {
                        $total_no_of_leaves = 0;
                    }
                }

                $total_month_working_days = $leaves['work_withholi_days'] != "" ? $leaves['work_withholi_days'] : 22;
                $work_leave_days = $leaves['work_leave_days'] != "" ? $leaves['work_leave_days'] : 0;
                $date_of_leaving = $emp->date_of_leaving != "" ? $emp->date_of_leaving : $emp_termination_data->releive_date;

                $last_query = "SELECT SUM(`salary_actual_amount`) AS total_amount FROM contract_pay_summary WHERE  company_id =" . $post['company_id'] . " AND  (`pay_year` = 2024 AND `pay_month` >= 4) OR (`pay_year` = 2025 AND `pay_month` <= 3) AND is_active = 0";
                $callConfig->getRow($last_query);

                $recoquery = "SELECT *  FROM employee_other_earnings WHERE employee_id=" . $emp->id . self::USER_SQL_AND_PAY_YEAR . $post['pay_year'] . self::USER_LIT_AND_PAY_MONTH . $post['pay_month'] . self::USER_LIT_AND_IS_ACTIVE_0;
                $recoqq = $callConfig->getRow($recoquery);

                $one_time_amount = 0;
                $salary_actual_amount = 0;
                $gst_amount = 0;
                if (count((array) $recoqq) > 0) {
                    $one_time_amount = $recoqq->approved_amount;
                }

                $wkdays = $total_month_working_days - $work_leave_days;

                $salary_actual_amount = ($mndata['pay_rate'] / $newtotalworkingdays) * $wkdays;
                if ($mndata['gst_type'] == 0) {
                    $gst_amount = ($cc_data['gst_percentage'] / 100) * ($salary_actual_amount + $one_time_amount);
                }
                $base_tax = ($salary_actual_amount + $one_time_amount) * ($cc_data['tax_percentage'] / 100);
                $insert_array = array('company_id' => $post['company_id'], 'revision_no' => $version, 'pay_area_id' => $pay_area_id, 'pay_year' => $post['pay_year'], 'pay_month' => $post['pay_month'], 'location_id' => $emp->location_id, 'employee_id' => $emp->id, 'designation_id' => $emp->designation_id, 'father_name' => $emp->father_name, 'date_of_birth' => $emp->date_of_birth, 'date_of_leaving' => $date_of_leaving, 'date_of_joining' => $emp->joining_date, 'contact_details' => $emp->phone, 'bank_id' => $emp->bank_id, 'bank_link' => $emp->bank_link, 'bank_account_no' => $emp->bank_account_no, 'cover_under_pf' => $emp->cover_under_pf, 'cover_under_esi' => $emp->cover_under_esi, 'total_no_of_leaves' => $total_no_of_leaves, 'total_no_of_days' => $newtotalworkingdays, 'total_lop_days' => $work_leave_days, 'total_no_of_working_days' => $total_month_working_days, 'is_active' => '0', 'current_status' => '0', 'created_by' => $post['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1), 'salary_standard_amount' => $mndata['ctc_monthly'], 'salary_actual_amount' => $salary_actual_amount, 'one_time_amount' => $one_time_amount, 'gst_type' => $mndata['gst_type'], 'gst_percentage' => $cc_data['gst_percentage'], 'gst_amount' => $gst_amount, 'tds_amount' => $base_tax, 'gst_no' => $cdata['gst_no']);
                $insert[] = $callConfig->insertRecord('contract_pay_summary', $insert_array);

            }
        }
        return $insert;
    }
}

trait UserReportsAndAnalyticsTrait
{
    public function togetnewwithoutworkindays($from, $to)
    {
        global $callConfig;
        $attstc = "SELECT * FROM attendance_settings WHERE company_id= 1 AND is_active=0";
        $atsdata = $callConfig->getRow($attstc);
        $workingdays = $atsdata->working_days;
        $working_days = json_decode($workingdays, 1);
        $datediff = strtotime($to) - strtotime($from);
        $datediff = floor($datediff / (60 * 60 * 24));
        $resday = 0;
        for ($i = 0; $i < $datediff + 1; $i++) {
            $valday = ucwords(date("l", strtotime($from . ' + ' . $i . 'day')));
            if (in_array($valday, (array) $working_days)) {
                $resday = $resday + 1;
            }
        }
        return $resday;
    }
    public function updateTransactionTCS($transaction_table, $transaction_no, $get)
    {
        global $callConfig;
        $return = array();
        $company_id = $get['company_id'];
        $sql = self::USER_SQL_SELECT_FROM . $transaction_table . self::USER_SQL_WHERE_COMPANY_ID . $company_id . self::USER_LIT_AND_ID_3 . $transaction_no . self::USER_LIT_AND_IS_ACTIVE_0;
        $partyinvoice = $callConfig->getRow($sql);
        $total_tds = 0;
        $party_transaction_table = "customers";
        $pasrtysql = self::USER_SQL_SELECT_FROM . $party_transaction_table . self::USER_SQL_WHERE_COMPANY_ID . $company_id . self::USER_LIT_AND_ID_3 . $partyinvoice->party_id . self::USER_LIT_AND_IS_ACTIVE_0;
        $callConfig->getRow($pasrtysql);

        $taxdetailsql = "SELECT * FROM tax_collected_sources WHERE company_id = '" . $company_id . self::USER_LIT_AND_IS_ACTIVE_0;
        $taxdetailres = $callConfig->getAllRows($taxdetailsql);
        foreach ($taxdetailres as $tx) {
            $tds_details[$tx->id] = $tx;
        }
        $mappingtabsql = self::USER_SQL_SELECT_ID_DISPLAY_TABLE_ITEM_T . $company_id . self::USER_LIT_AND_APPLICATION_TABLE_NAME . $transaction_table . self::USER_LIT_AND_ITEM_TABLE_AND_IS_ACTIVE_0;
        $mappingtabres = $callConfig->getRow($mappingtabsql);
        $partyinvoiceitemsql = "SELECT iv.*, it.item_name, it.category_id, ic.category_description, ic.tax_deducted_source_id, ic.tax_collected_source_id FROM " . $mappingtabres->item_table . " iv, items it ,item_categories ic WHERE iv.company_id = '" . $company_id . self::USER_LIT_AND_IV_COMPANY_ID_IT_COMPANY_I . $partyinvoice->id . self::USER_LIT_AND_IV_IS_ACTIVE_IT_IS_ACTIVE_;
        $partyinvoiceitemres = $callConfig->getAllRows($partyinvoiceitemsql);
        foreach ($partyinvoiceitemres as $itemres) {
            $applaytds = $tds_details[$itemres->tax_collected_source_id];
            $applay_percentage = 0;
            if ($applaytds->id != "") {
                $applay_percentage = $applaytds->percentage;
                $tdsitempayment = ($itemres->item_amount * $applay_percentage) / 100;
                $total_tds += $tdsitempayment;
                $updatedata['tds_amount'] = $tdsitempayment;
                $updatedata['tax_deducted_source_id'] = $applaytds->id;
                $updatedata['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
                $updatedata['updated_by'] = $get['user_id'];
                $return['childupdate'][] = $updatedata;
                $res = $callConfig->updateRecord('si_items', $updatedata, 'id', $itemres->id);
                $return['childupdate_res'][] = $res;
            }
        }
        $mainupdate['total_amount'] = $partyinvoice->total_amount + $total_tds;
        $mainupdate['pending_amount'] = $partyinvoice->pending_amount + $total_tds;
        $mainupdate['total_tds_amount'] = $total_tds;
        $mainupdate['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);


        $return['payment_term_history11'] = $partyinvoice->payment_term_history;
        $payment_term_history = json_decode($partyinvoice->payment_term_history, 1);
        $payment_term_history11 = array();
        if (count((array) $payment_term_history) != "0") {
            $pth_cnt = count((array) $payment_term_history);
            $return['pth_cnt'] = $pth_cnt;
            foreach ($payment_term_history as $kk => $pterh) {
                if ($pth_cnt == $kk) {
                    $pterh['amount'] = $pterh['amount'] + $total_tds;
                }
                $payment_term_history11[$kk] = $pterh;
            }
        }
        $mainupdate['payment_term_history'] = json_encode($payment_term_history11);
        $callConfig->updateRecord($transaction_table, $mainupdate, 'id', $transaction_no);
        $return['mainupdate'] = $mainupdate;
        return $return;
    }

