    public function generateOTP($length = 4)
    {
        $otp = '';
        for ($i = 0; $i < $length; $i++) {
            $otp .= random_int(1, 9);
        }
        if (strlen($otp) != $length) {
            $otp = $this->generateOTP($length);
        }
        return $otp;
    }
