                }
                if ($get['category_id'] != "") {
                    $dynamiccondition .= " AND category_id = '" . $get['category_id'] . "'";
                }
                if ($get['location_id'] != "") {
                    $dynamiccondition .= " AND id IN(SELECT item_id FROM item_locations il WHERE il.company_id = '" . $get['company_id'] . "' AND il.location_id = '" . $get['location_id'] . self::USER_LIT_AND_IL_IS_ACTIVE_0;
                }
                if ($get['warehouse_id'] != "") {
                    $dynamiccondition .= " AND id IN(SELECT item_id FROM item_locations il WHERE il.company_id = '" . $get['company_id'] . "' AND il.warehouse_id = '" . $get['warehouse_id'] . self::USER_LIT_AND_IL_IS_ACTIVE_0;
                }
                if ($get['vendor_id'] != "") {
                    $dynamiccondition .= " AND id IN(SELECT item_id FROM vendor_items il WHERE il.company_id = '" . $get['company_id'] . "' AND il.vendor_id = '" . $get['vendor_id'] . self::USER_LIT_AND_IL_IS_ACTIVE_0;
                }
                if ($get['customer_id'] != "") {
                    $dynamiccondition .= " AND id IN(SELECT item_id FROM customer_items il WHERE il.company_id = '" . $get['company_id'] . "' AND il.customer_id = '" . $get['customer_id'] . self::USER_LIT_AND_IL_IS_ACTIVE_0;
                }

                $itemssql = self::USER_SQL_SELECT_FROM_ITEMS_WHERE_COMPAN_1 . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_1 . $dynamiccondition;
                $itemsres = $callConfig->getAllRows($itemssql);
                $return['items'] = $itemsres;
                $return['itemssql'] = $itemssql;
            }
            $itemtypes_sql = self::USER_SQL_SELECT_ID_ITEM_TYPE_NAME_FROM_ . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
            $itemtypes_res = $callConfig->getAllRows($itemtypes_sql);
            $return['item_types'] = $itemtypes_res;

            $category_sql = "SELECT id, category_description, parent_item_category_id  FROM  item_categories WHERE company_id = '" . $get['company_id'] . "' AND is_active ='0'  ORDER BY category_description ASC";
            $category_res = $callConfig->getAllRows($category_sql);
            $return['item_categories'] = $category_res;

            $customers_sql = "SELECT id,display_name,company FROM  customers WHERE  company_id = '" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_ORDER_BY_DISPL;
            $customers_res = $callConfig->getAllRows($customers_sql);
            $return['customers'] = $customers_res;

            $vendors_sql = "SELECT id,display_name,company FROM vendors WHERE  company_id = '" . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_ORDER_BY_DISPL;
            $vendors_res = $callConfig->getAllRows($vendors_sql);
            $return['vendors'] = $vendors_res;

            $locationssql = self::USER_SQL_SELECT_ID_LOCATION_NAME_FROM_L . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_14;
            $locationssres = $callConfig->getAllRows($locationssql);
            $return['locations'] = $locationssres;

            $warehousessql = self::USER_SQL_SELECT_ID_LOCATION_ID_WAREHOUS . $get['company_id'] . self::USER_LIT_AND_IS_ACTIVE_0_14;
            $warehousesres = $callConfig->getAllRows($warehousessql);
            $return['warehouses'] = $warehousesres;
        }
        return $return;
    }
    public function insertImportExcelData($post)
    {
        global $callConfig;
        $returnaray['post'] = $post;
        if ($post['recordupdate'] == "N") {
            $importdata = $post['csvdata'];
            $header = $data = array();
            foreach ($importdata[1] as $idata) {
                $header[] = $idata;
            }
            unset($importdata[0]);
            unset($importdata[1]);
            foreach ($importdata as $idata) {
                if ($idata[0] != "") {  //id possition
                    $data[] = $idata;
                }
            }
            $returnaray['post'] = $post;
            $jsonheader = json_encode($header);
            $jsondata = json_encode($data);
            $insertuserarray1 = array('company_id' => $post['company_id'], 'file_name' => $post['file_name'], 'header' => $jsonheader, 'data' => $jsondata, 'system_start_date' => $this->dateconvertdbformat($post['system_start_date']), 'is_active' => '0', 'current_status' => '0', 'created_by' => $post['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
            $tapres = $callConfig->insertRecord('import_excel_data', $insertuserarray1);
            $returnaray['respons'] = $tapres;

        } elseif ($post['recordupdate'] == "Y") {
            $itemssql = self::USER_SQL_SELECT_FROM_IMPORT_EXCEL_DATA_ . $post['company_id'] . "' AND file_name ='" . $post['FIN'] . self::USER_LIT_AND_IS_ACTIVE_0_1;
            $itemsres = $callConfig->getRow($itemssql);
            $returnaray['import_excel_data'] = $itemsres;
            $importdata = json_decode($itemsres->data, 1);
            $system_start_date = $this->dateconvertdbformat($itemsres->system_start_date);
            $items = array();
            $itemssql = "SELECT id, opening_quantity FROM items WHERE  company_id = '" . $post['company_id'] . "' AND opening_quantity IS NOT NULL AND opening_quantity !='0' AND is_active=0";
            $itemsres11 = $callConfig->getAllRows($itemssql);
            $returnaray['itemsres11'] = $itemsres11;
            foreach ($itemsres11 as $ires) {
                $items[$ires->id] = $ires->id;
            }
            foreach ($importdata as $idata) {
                if ($idata[0] != "") {  //id possition
                    if ($idata[5] != "" && $idata[5] != "0" && !in_array($idata[0], (array) $items)) { // already update open qty
                        $postupd['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S);
                        $postupd['updated_by'] = $post['user_id'];
                        $postupd['opening_quantity'] = $idata[5];
                        $postupd['opening_quantity_date'] = $system_start_date;
                        $postupd['warehouse_id'] = 1;
                        $returnaray['items_update_ary'][] = $postupd;
                        $res = $callConfig->updateRecord('items', $postupd, 'id', $idata[0]);
                        $returnaray['items_update'][] = $res;
                        $mainitem = $this->togetitemvalues($idata[0]);
                        $day_rate = $this->togetitemwadayrate($idata[0], $post['company_id']);
                        $len = array('company_id' => $post['company_id'], 'location_id' => 1, 'transaction_warehouse_id' => 1, 'transaction_date' => $system_start_date, 'item_id' => $idata[0], 'document_no' => $idata[0], 'document_type' => 'items', 'document_ref_no' => '', 'in_qty' => $idata[5], 'in_value' => 0, 'item_in_value' => 0, 'reason_id' => '', 'out_qty' => 0, 'out_value' => 0, 'sale_price' => 0, 'sale_value' => 0, 'item_wa_cost' => $day_rate, 'item_st_cost' => $mainitem->purchase_price, 'is_active' => '0', 'current_status' => '0', 'sales_qty' => 0, 'purchase_qty' => 0);
                        $this->invoiceUpdates('items', $len);
                        $returnaray['items_ledger'][] = null;
                    }
                    $returnaray['array'] = $idata;
                }
            }
        }
        return $returnaray;
    }
