    public function tocallmobilenotificationmob($get)
    {
        global $callConfig;
        if (!isset($get['re_val'])) {
            $get['re_val'] = 0;
        }
        $query = "SELECT * FROM user_mobile_details WHERE company_id =" . $get['company_id'] . self::USER_SQL_AND_USER_ID . $get['user_id'] . self::USER_SQL_AND_IS_ACTIVE_0;
        $data = $callConfig->getRow($query);

        $return['response'] = "FCM token is empty";

        if ($data->fcm_token != "") {
            $query = "SELECT * FROM mobile_firebase_authentications WHERE company_id =" . $get['company_id'] . self::USER_SQL_AND_IS_ACTIVE_0_6;
            $res_data = $callConfig->getRow($query);
            $auth_token = $res_data->authentication_key;
            $mesg = $get['message'] != "" ? $get['message'] : "Test Notificaiton body For mobile  to API Test3";
            $title = $get['title'] != "" ? $get['title'] : "Test Notificaiton title For mobile  to API Test3";
            $messageary['token'] = $data->fcm_token;
            $messageary['notification'] = array("body" => $mesg, "title" => $title);
            if (isset($get['data'])) {
                $messageary['data'] = $get['data'];
            }

            $request['message'] = $messageary;

            $send_req = json_encode($request);

            $curl = curl_init();
            curl_setopt_array($curl, array(
                CURLOPT_URL => 'https://fcm.googleapis.com/v1/projects/infistaq/messages:send',
                //https://fcm.googleapis.com/v1/projects/infistaq/messages:send
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_ENCODING => '',
                CURLOPT_MAXREDIRS => 10,
                CURLOPT_TIMEOUT => 0,
                CURLOPT_FOLLOWLOCATION => true,
                CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                CURLOPT_CUSTOMREQUEST => 'POST',
                CURLOPT_POSTFIELDS => $send_req,
                CURLOPT_HTTPHEADER => array(
                    'Content-Type: application/json',
                    'Authorization: Bearer ' . $auth_token
                ),
            ));
            $response = curl_exec($curl);
            $res = json_decode($response, 1);
            if (isset($res['name']) && $res['name'] != "") {
                $return['response'] = $res;
            } else {
                $accessToken = $this->togenratefirebaseheaderauthentication($get);
                $upquery = "UPDATE mobile_firebase_authentications SET is_active=1 WHERE company_id=" . $get['company_id'] . self::USER_SQL_AND_IS_ACTIVE_0_2;
                $callConfig->executeQuery($upquery);
                $insert_array = array('company_id' => $get['company_id'], 'authentication_key' => $accessToken, 'is_active' => '0', 'current_status' => '0', 'created_by' => $get['user_id']);
                $callConfig->insertRecord('mobile_firebase_authentications', $insert_array);
                $get['re_val'] = $get['re_val'] + 1;
                if ($get['re_val'] < 3) {
                    $this->tocallmobilenotificationmob($get);
                }
            }
        }
        return $return;
    }
    public function togenratefirebaseheaderauthentication($get)
    {
        if (isset($get)) { /* noop */ }
        $url = SITEURL . "/cfa_token.php";
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_HEADER, false);
        return curl_exec($ch);

    }
    public function toGetApplicationFinanceYearSerialNumbers($table_name, $trandate = "")
    {
        global $callConfig;
        $get = array();
        $transdate = $trandate != "" ? $trandate : date('Y-m-d');

        $finyaer = date("m", strtotime($transdate)) >= 4 ? date("Y", strtotime($transdate)) . '-' . (date("y", strtotime($transdate)) + 1) : (date("Y", strtotime($transdate)) - 1) . '-' . date("y", strtotime($transdate));
        $query = "SELECT * FROM `application_finance_year_serial_numbers` WHERE application_table_name = '" . $table_name . "' AND start_date <= '" . $this->dateconvertdbformat($transdate) . "' AND end_date >= '" . $this->dateconvertdbformat($transdate) . self::USER_LIT_AND_IS_ACTIVE_0_3;
        $return['query_1'] = $query;
        $res = $callConfig->getRow($query);
        $return['query_1_res'] = $res;
        if ($res->id != "") {
            $res = $callConfig->getRow($query);
            $le = $res->doc_no_length;
            $var = "%0" . $le . "d";
            $data = $res->pre_fix . '/' . $res->post_fix . '/' . $finyaer . '/' . sprintf($var, $res->serial_number + 1);
            if (isset($res->id)) {
                $callConfig->updateRecord('application_finance_year_serial_numbers', array('serial_number' => $res->serial_number + 1), 'id', $res->id);
            }
        } else {
            $query = "SELECT * FROM `application_finance_year_serial_numbers` WHERE application_table_name = '" . $table_name . self::USER_LIT_AND_IS_ACTIVE_0_3;
            $res = $callConfig->getRow($query);
            $return['query_2_res'] = $res;
            if (isset($res->doc_no_length)) {
                $le = $res->doc_no_length;
                $var = "%0" . $le . "d";
                $data = $res->pre_fix . '/' . $res->post_fix . '/' . $finyaer . '/' . sprintf($var, 1);
                if (date("m", strtotime($transdate)) >= 4) {
                    $startyear = date("Y", strtotime($transdate));
                    $endyear = (date("Y", strtotime($transdate)) + 1);
                    $startdate = $startyear . self::USER_LIT_04_01;
                    $enddate = $endyear . self::USER_LIT_03_31;
                } else {
                    $startyear = (date("Y", strtotime($transdate)) - 1);
                    $endyear = date("Y", strtotime($transdate));
                    $startdate = $startyear . self::USER_LIT_04_01;
                    $enddate = $endyear . self::USER_LIT_03_31;
                }
                if ($res->doc_no_length != "" && $res->serial_number_type != "" && $table_name != "") {
                    $insertary = array('company_id' => $res->company_id, 'application_table_name' => $table_name, 'serial_number' => '1', 'pre_fix' => $res->pre_fix, 'post_fix' => $res->post_fix, 'doc_no_length' => $res->doc_no_length, 'serial_number_type' => $res->serial_number_type, 'start_date' => $startdate, 'end_date' => $enddate, 'is_active' => 0, 'current_status' => 0, 'created_by' => $get['user_id'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S));
                    $return['res_item_insertary'] = $insertary;
                    $res1 = $callConfig->insertRecord('application_finance_year_serial_numbers', $insertary);
                    $return['res_item'] = $res1;
                }
            } else {
                $data = 1;
            }
        }

        return trim($data);
    }
