    public function getDynamicInviceParty($get)
    {
        global $callConfig;
        $return = array();
        $party_id = $get['party_id'];
        if ($get['transaction_table'] == "vendors") {
            $sql = self::USER_SQL_SELECT_FROM_VENDORS_WHERE_COMP . $get['company_id'] . self::USER_LIT_AND_ID . $party_id . self::USER_LIT_LIMIT_1;
            $res = $callConfig->getRow($sql);
            $res->pending_amount = 0;
            $return['party'] = $res;

            $sql1 = "SELECT * FROM customer_vendor_gst_billing_details WHERE company_id = '" . $get['company_id'] . "' AND transaction_table = 'vendors' AND customer_vendor_id = '" . $party_id . "'";
            $res1 = $callConfig->getAllRows($sql1);
            $return['customer_vendor_gst_billing_details'] = $res1;


            $sql2 = "SELECT war.id, war.warehouse_name, vw.default_warehouse FROM vendor_warehouse vw, warehouses war WHERE vw.company_id = '" . $get['company_id'] . "' AND vw.company_id = vw.company_id AND vw.ware_house_id = war.id AND vw.vendor_id = '" . $party_id . "' AND vw.is_active = war.is_active AND vw.is_active = 0";
            $res2 = $callConfig->getAllRows($sql2);
            $return['vendor_warehouse'] = $res2;


        } elseif ($get['transaction_table'] == "customers") {
            $sql = "SELECT * FROM customers WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_ID . $party_id . self::USER_LIT_LIMIT_1;
            $res = $callConfig->getRow($sql);

            $sql1 = "SELECT SUM(pending_amount) as pending_amount FROM sales_invoices WHERE company_id = '" . $get['company_id'] . self::USER_LIT_AND_PARTY_ID . $party_id . "' AND is_active = 0 AND cancel_invoice !='Y'";
            $res1 = $callConfig->getRow($sql1);
            $res->pending_amount = $res1->pending_amount != "" ? $res1->pending_amount : 0;
            $return['party'] = $res;

            $sql1 = "SELECT * FROM customer_vendor_gst_billing_details WHERE company_id = '" . $get['company_id'] . "' AND transaction_table = 'customers' AND customer_vendor_id = '" . $party_id . "'";
            $res1 = $callConfig->getAllRows($sql1);
            $return['customer_vendor_gst_billing_details'] = $res1;


        }
        return $return;
    }
}

