                $return['vendor_or_customer_list'] = $partyres;

                $fieldnames['party_id'] = $party_id;
                $fieldnames['party_name'] = $partyres->company;
                $fieldnames['party_email'] = $partyres->email;
                $fieldnames['party_phone'] = $partyres->phone;
                $fieldnames['party_address'] = $partyres->billing_address;
                $fieldnames['party_ship_adderss'] = $partyres->shipping_address;
                $fieldnames['place_of_supply'] = $partyres->cvgstbill_id;
                $fieldnames['payment_terms'] = $partyres->payment_terms;
            }
