                $fieldnames['updated_by'] = $post['updated_by'];
                $insert_data = $callConfig->updateRecord($document_type, $fieldnames, 'id', $post['multi_ref_transaction_id']);
                $return['insert_data'] = $insert_data;
                //start added records sla_tracking_logs
                $slaarray = $post;
                $slaarray['transaction_table'] = $document_type;
                $slaarray['transaction_id'] = $post['hid'];
                $slaarray['remarks'] = 'UPDATE';
                $slaarray['previous_status'] = $status;
                $this->insertSLATrackingLogs($slaarray);
                //End Added records sla_tracking_logs
                $insert_id = $post['multi_ref_transaction_id'];
                $fieldnames['transaction_type'] = $document_type;
                $return['transaction_id'] = $insert_id;

                // update all items table start
                $updaterecord = array('is_active' => null, 'updated_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1), 'updated_by' => $post['user_id']);
                $callConfig->updateRecord($tres->item_table, $updaterecord, 'transaction_id', $insert_id);
                $callConfig->updateRecord($tres->tax_table, $updaterecord, 'transaction_id', $insert_id);
                // update all items table end

            } else {
                $fieldnames['created_by'] = $post['created_by'];
                $fieldnames['created_date'] = $post['created_date'];
                $fieldnames['is_active'] = '0';


                //start - Serial Number Masters
                $post['transaction_date'] = date("Y-m-d");
                $post['party_id'] = $party_id;
                $post['transaction_type'] = $document_type;
                $transaction_number_details = $this->generatingApplicationSerialNumberMasters($document_type, $post);
                $fieldnames['transaction_number'] = $transaction_number_details['main_transaction_number'];
                $fieldnames['monthly_transaction_number'] = $transaction_number_details['monthly_transaction_number'];
                $fieldnames['yearly_transaction_number'] = $transaction_number_details['yearly_transaction_number'];
                $fieldnames['lifetime_transaction_number'] = $transaction_number_details['lifetime_transaction_number'];
                //End - Serial Number Masters


                $fieldnames['transaction_date'] = date('Y-m-d');
                $fieldnames['multi_reference'] = "Y";
                $insert_data = $callConfig->insertRecord($document_type, $fieldnames);
                $return['insert_data'] = $insert_data;
                $insert_id = $insert_data['LASTID'];
                //start added records sla_tracking_logs
                $slaarray = $post;
                $slaarray['transaction_table'] = $document_type;
                $slaarray['transaction_id'] = $insert_id;
                $slaarray['remarks'] = 'INSERT';
                $slaarray['previous_status'] = $status;
                $this->insertSLATrackingLogs($slaarray);
                //End Added records sla_tracking_logs
                $return['transaction_id'] = $insert_id;
            }


            $transaction_item_id = implode(",", $post['transaction_item_list']);
            $sql1 = "SELECT transtab.transaction_number, transtab.id as ref_transaction_table_id,  trnitm.id, trnitm.transaction_id, trnitm.description, trnitm.purchase_uom, trnitm.account_code,  trnitm.item_id, trnitm.item_name, trnitm.item_quantity, trnitm.item_price, trnitm.tax_amount, trnitm.total_amount, trnitm.pending_qty, trnitmtax.id as tax_tab_id, trnitmtax.tax_name, trnitmtax.tax_value, trnitmtax.tax_id FROM " . $reference_document_type . self::USER_LIT_AS_TRANSTAB . $clon_res->item_table . self::USER_LIT_AS_TRNITM_LEFT_JOIN . $clon_res->tax_table . self::USER_LIT_AS_TRNITMTAX_ON_TRNITM_ID_TRNI . $post['company_id'] . "' AND transtab.company_id = trnitm.company_id  AND transtab.id = trnitm.transaction_id AND trnitm.id IN(" . $transaction_item_id . ") AND trnitm.is_active = trnitm.is_active  AND trnitm.is_active = 0  order BY transtab.transaction_number ASC";
            $drtres1 = $callConfig->getAllRows($sql1);
            $return['transactions_sql'] = $sql1;
            $return['transactions_res'] = $drtres1;


            foreach ($drtres1 as $transdetails) {
                $itemfieldnames = array('company_id' => $post['company_id'], 'transaction_id' => $insert_id, 'item_id' => $transdetails->item_id, 'item_name' => $transdetails->item_name, 'description' => $transdetails->description, 'purchase_uom' => $transdetails->purchase_uom, 'account_code' => $transdetails->account_code, 'item_wa_cost' => 0, 'item_fifo_cost' => 0, 'item_lifo_cost' => 0, 'is_active' => '0', 'ref_transaction_item_table_id' => $transdetails->id, 'ref_transaction_table_id' => $transdetails->ref_transaction_table_id);

                if ($document_type == 'goods_receipt_notes' || $document_type == 'delivery_orders' || $document_type == 'rgp_delivery_orders' || $document_type == 'rgp_sales_returns' || $document_type == 'nrgp_delivery_orders' || $document_type == 'stock_transfers' || $document_type == 'stock_transfer_receipts' || $document_type == 'stock_transfer_returns') {
                    $itemfieldnames['item_quantity'] = $transdetails->item_quantity;
                }

                if ($post['old_transaction_item_table_id'][$transdetails->id] != '') {
                    $itemfieldnames['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1);
                    $itemfieldnames['updated_by'] = $post['user_id'];
                    $res = $callConfig->updateRecord($tres->item_table, $itemfieldnames, 'id', $post['old_transaction_item_table_id'][$transdetails->id]);
                    $return['transaction_items'][] = $res;
                    $transaction_item_row_id = $item_transaction['LASTID'];
                } else {
                    $itemfieldnames['item_quantity'] = 0;
                    $itemfieldnames['item_price'] = $transdetails->item_price;
                    $itemfieldnames['item_amount'] = 0;
                    $itemfieldnames['tax_amount'] = 0;
                    $itemfieldnames['total_amount'] = 0;
                    $itemfieldnames['discount_amount'] = 0;
                    $itemfieldnames['pending_qty'] = 0;
                    $itemfieldnames['created_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1);
