                    $item_transaction = $callConfig->insertRecord($tres->item_table, $itemfieldnames);
                    $return['transaction_items'][] = $item_transaction;
                    $transaction_item_row_id = $item_transaction['LASTID'];
                }

                if ($transdetails->tax_tab_id != "") {
                    $taxfield = array('company_id' => $post['company_id'], 'transaction_id' => $insert_id, 'transaction_item_id' => $transdetails->item_id, 'tax_id' => $transdetails->tax_tab_id, 'tax_name' => $transdetails->tax_name, 'tax_type' => 'S', 'tax_value' => $transdetails->tax_value, 'is_active' => '0', 'current_status' => '0');

                    if ($post['old_transaction_item_tax_table_id'][$transdetails->id] != '') {
                        $taxfield['updated_date'] = date(self::USER_DATE_FORMAT_Y_M_D_H_I_S_1);
                        $taxfield['updated_by'] = $post['user_id'];
