    public function sendotptoverifymobile($get)
    {
        global $callConfig;
        $updatequery = "UPDATE user_otp_authentication SET is_active = NULL WHERE company_id = " . $get['company_id'] . " AND mobile = " . $get['mobile'] . self::USER_SQL_AND_IS_ACTIVE_0_2;
        $callConfig->executeQuery($updatequery);

        $otp = $this->generateOTP(4);
        $insert_array = array('company_id' => $get['company_id'], 'user_id' => $get['user_id'], 'otp_number' => $otp, 'created_by' => $get['user_id'], 'mobile' => $get['mobile'], 'created_date' => date(self::USER_DATE_FORMAT_Y_M_D_H_I_S), 'is_active' => '0', 'current_status' => '0');
        $callConfig->insertRecord('user_otp_authentication', $insert_array);


        $res = array('status' => 'success', 'msg' => 'An OTP has been sent to your registered email ID and is also available on our web portal.');

        $message = 'Your OTP for mobile verification is ' . $otp;
        $array = array('company_id' => $get['company_id'], 'mobile_no' => $get['mobile'], 'message' => $message, 'send_no' => '8179947020', 'recivce_no' => $get['mobile'], 'data_name' => $get['data_name']);
        $res['msg_otp']['mobile'] = $this->tosendmessagetomobile($array);
        $res['msg_otp']['whatsup'] = $this->tosendwhatsappdata($array);
        return $res;
    }

